  const toggleChannelType = (key: "online" | "hall" | "takeout") => {
    setChannelState((prev) => {
      if (key === "online") {
        const nextOnline = !prev.online
        return { ...prev, online: nextOnline, apps: nextOnline ? prev.apps : [] }
      }
      return { ...prev, [key]: !prev[key] }
    })
  }

