  const handleDeleteTenderRule = React.useCallback(async (rule: PosLinkposTenderRule) => {
    const ok = await appConfirm(`규칙을 삭제하시겠습니까?\n[${rule.storeCode}] ${rule.matchKeyword} → ${rule.tenderKey}`)
    if (!ok) return
    try {
