/** 출금 관리 5가지 유형 실행: 매입대금, 경비, 자산취득, 자금이동, 자본거래 */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Content-Type', 'application/json')

  try {
    const body = await request.json()
    const userRole = String(body.userRole || body.user_role || '').toLowerCase()
    const userName = String(body.userName || body.user_name || '').trim()
    const userStore = String(body.userStore || body.user_store || '').trim()
    const isOffice = ['director', 'officer', 'ceo', 'hr'].some((r) => userRole.includes(r))

    if (!isOffice) {
      return NextResponse.json(
        { success: false, message: '본사 권한만 출금 등록할 수 있습니다.' },
        { status: 403, headers }
      )
    }

    const paymentMethod = String(body.paymentMethod || body.payment_method || 'bank').toLowerCase()
    const amount = Math.abs(Number(body.amount || 0))
    const transDate = String(body.transDate || body.trans_date || getBangkokTodayDateString()).slice(0, 10)
    const memo = String(body.memo || '').trim()
    const storeName = String(body.storeName || body.store_name || '').trim()

    const categoryMain = String(body.categoryMain || body.category_main || '').toLowerCase()
    const categorySub = String(body.categorySub || body.category_sub || '').toLowerCase()

    if (amount <= 0) {
      return NextResponse.json({ success: false, message: '금액을 입력해 주세요.' }, { status: 400, headers })
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(transDate)) {
      return NextResponse.json({ success: false, message: '날짜 형식이 올바르지 않습니다.' }, { status: 400, headers })
    }
    if (!['bank', 'petty'].includes(paymentMethod)) {
      return NextResponse.json({ success: false, message: '지급 수단은 bank 또는 petty 입니다.' }, { status: 400, headers })
    }

    const vendorCode = String(body.vendorCode || body.vendor_code || '').trim()
    const accountSubjectId = body.accountSubjectId ?? body.account_subject_id
    const invoiceReceived = body.invoiceReceived ?? body.invoice_received
    const invoiceNo = String(body.invoiceNo || body.invoice_no || '').trim()
    const invoicePhotoUrl = String(body.invoicePhotoUrl || body.invoice_photo_url || '').trim()
    const accountSubjectCode = String(body.accountSubjectCode || '').trim()
    const accountSubjectName = String(body.accountSubjectName || '').trim()
    const transferToAccountId = body.transferToAccountId ?? body.transfer_to_account_id
    const transferToAccountNo = String(body.transferToAccountNo || body.transfer_to_account_no || '').trim()
    const transferBankAccountNo = String(body.transferBankAccountNo || body.transfer_bank_account_no || '').trim()
    const transferBankRecipientName = String(body.transferBankRecipientName || body.transfer_bank_recipient_name || '').trim()
    const transferToType = String(body.transferToType || body.transfer_to_type || 'bank').toLowerCase()
    const transferToPettyStore = String(body.transferToPettyStore || body.transfer_to_petty_store || '').trim()
    const transferToCardAccountId = body.transferToCardAccountId ?? body.transfer_to_card_account_id
    const assetName = String(body.assetName || body.asset_name || '').trim()
    const assetCode = String(body.assetCode || body.asset_code || '').trim()
    const usefulLifeMonths = Math.max(1, Math.min(600, Number(body.usefulLifeMonths || body.useful_life_months) || 60))
    const residualRate = Math.min(100, Math.max(0, Number(body.residualRate || body.residual_rate) || 0))

    let category = mapToWithdrawalCategory(categoryMain, categorySub)
    const paymentIsBankOrCard = paymentMethod === 'bank' || paymentMethod === 'card'
    if (category === 'transfer' && paymentIsBankOrCard && transferToCardAccountId) {
      category = 'transfer_to_card'
    } else if (category === 'transfer' && paymentMethod === 'bank' && transferBankAccountNo && transferBankRecipientName) {
      category = 'transfer_external'
    } else if (category === 'transfer' && paymentMethod === 'petty') {
      category = 'transfer_from_petty'
    }
    if (!category) {
      return NextResponse.json({ success: false, message: '출금 유형을 선택해 주세요.' }, { status: 400, headers })
    }

    if (['purchase_payment', 'purchase_advance'].includes(category) && !vendorCode) {
      return NextResponse.json({ success: false, message: '거래처를 선택해 주세요.' }, { status: 400, headers })
    }
    if (['expense', 'expense_advance'].includes(category) && !accountSubjectId && !accountSubjectCode) {
      return NextResponse.json({ success: false, message: '계정과목을 선택해 주세요.' }, { status: 400, headers })
    }
    if (category === 'transfer_to_card' && !transferToCardAccountId) {
      return NextResponse.json({ success: false, message: '충전할 카드를 선택해 주세요.' }, { status: 400, headers })
    }
    if (category === 'transfer_external' && (!transferBankAccountNo || !transferBankRecipientName)) {
      return NextResponse.json({ success: false, message: '계좌번호와 받는 사람을 입력해 주세요.' }, { status: 400, headers })
    }
    if (category === 'transfer_from_petty' && !transferToAccountId && !transferToAccountNo) {
      return NextResponse.json({ success: false, message: '입금할 통장 계좌를 선택하거나 계좌번호를 입력해 주세요.' }, { status: 400, headers })
    }
    if (category === 'fixed_asset' && !assetName && !memo) {
      return NextResponse.json({ success: false, message: '자산명 또는 적요를 입력해 주세요.' }, { status: 400, headers })
    }

    if (accountSubjectId != null && !isNaN(Number(accountSubjectId))) {
      const hdr = await assertAccountSubjectNotHeader(Number(accountSubjectId))
      if (!hdr.ok) {
        return NextResponse.json({ success: false, message: hdr.message }, { status: hdr.status, headers })
      }
    }

    const store = storeName || '본사'
    let bankTransactionId: number | null = null
    let pettyCashTransactionId: number | null = null
    let fixedAssetId: number | null = null

    if (paymentMethod === 'bank') {
      const accountId = Number(body.accountId || body.account_id || 0)
      if (!accountId) {
        return NextResponse.json({ success: false, message: '통장 출금은 계좌를 선택하세요.' }, { status: 400, headers })
      }

      const bankCategory = mapToBankTransactionCategory(category)
      const row: Record<string, unknown> = {
        account_id: accountId,
        trans_date: transDate,
        trans_type: 'withdraw',
        amount: -amount,
        memo: memo || null,
        note: `withdrawal_category:${category};${INTERNAL_BANK_SOURCE_MARKER}`,
        store: store || null,
        user_name: userName || null,
        category: bankCategory,
        expense_date: transDate,
      }
      if (vendorCode) row.vendor_code = vendorCode
      if (accountSubjectId != null) row.account_subject_id = Number(accountSubjectId)
      if (typeof invoiceReceived === 'boolean') row.invoice_received = invoiceReceived
      if (invoiceNo) row.invoice_no = invoiceNo
      if (invoicePhotoUrl) row.invoice_photo_url = invoicePhotoUrl
      if (category === 'transfer_external') {
        const extMemo = [memo, `받는사람: ${transferBankRecipientName}`, `계좌: ${transferBankAccountNo}`].filter(Boolean).join(' / ')
        row.memo = extMemo
      } else if (transferToAccountId != null && category === 'transfer') {
        row.transfer_to_account_id = Number(transferToAccountId)
      }

      const inserted = (await supabaseInsert('bank_transactions', row)) as { id?: number }[]
      bankTransactionId = Number(inserted?.[0]?.id || 0) || null

      if (category === 'transfer' && transferToAccountId) {
        await supabaseInsert('bank_transactions', {
          account_id: Number(transferToAccountId),
          trans_date: transDate,
          trans_type: 'deposit',
          amount: amount,
          memo: memo ? `이체입금: ${memo.slice(0, 200)}` : '이체입금',
          note: `withdrawal_transfer_from:${accountId};${INTERNAL_BANK_SOURCE_MARKER}`,
          store: store || null,
          user_name: userName || null,
          category: 'correction',
        })
      }
      if (category === 'transfer_to_petty' && transferToPettyStore) {
        await supabaseInsert('petty_cash_transactions', {
          store: transferToPettyStore,
          trans_date: transDate,
          trans_type: 'replenish',
          amount: amount,
          memo: memo ? `통장이체: ${memo.slice(0, 200)}` : '통장이체',
          user_name: userName || null,
        })
      }
      if (category === 'transfer_to_card' && transferToCardAccountId && bankTransactionId) {
        await supabaseInsert('card_transactions', {
          card_account_id: Number(transferToCardAccountId),
          trans_date: transDate,
          trans_type: 'charge',
          amount,
          memo: memo ? `통장이체: ${memo.slice(0, 200)}` : '통장이체',
          bank_transaction_id: bankTransactionId,
        })
      }
      // 매입 대금(통장): payable_transactions에 지급 기록 → 미지급금 차감, 지급 예정 반영
      if (category === 'purchase_payment' && vendorCode && bankTransactionId) {
        await supabaseInsert('payable_transactions', {
          vendor_code: vendorCode,
          amount: -amount,
          ref_type: 'Payment',
          ref_id: null,
          trans_date: transDate,
          memo: memo ? `통장 지급(매입): ${memo.slice(0, 200)}` : `통장 지급(매입): ${vendorCode}`,
          bank_transaction_id: bankTransactionId,
        })
      }

    } else {
      const pettyStore = store || '본사'
      const row: Record<string, unknown> = {
        store: pettyStore,
        trans_date: transDate,
        trans_type: 'expense',
        amount: -amount,
        memo: memo || null,
        user_name: userName || null,
      }
      if (accountSubjectId != null) row.account_subject_id = Number(accountSubjectId)

      const inserted = (await supabaseInsert('petty_cash_transactions', row)) as { id?: number }[]
      pettyCashTransactionId = Number(inserted?.[0]?.id || 0) || null

      if (category === 'transfer_from_petty' && transferToAccountId) {
        await supabaseInsert('bank_transactions', {
          account_id: Number(transferToAccountId),
          trans_date: transDate,
          trans_type: 'deposit',
          amount: amount,
          memo: memo ? `패티이체입금: ${memo.slice(0, 200)}` : '패티이체입금',
          note: `withdrawal_transfer_from_petty:${pettyStore};${INTERNAL_BANK_SOURCE_MARKER}`,
          store: store || null,
          user_name: userName || null,
          category: 'correction',
        })
      }
      if (category === 'transfer_from_petty' && transferToAccountNo && !transferToAccountId) {
        const enhancedMemo = memo ? `${memo} [입금계좌: ${transferToAccountNo}]` : `입금계좌: ${transferToAccountNo}`
        await supabaseUpdate('petty_cash_transactions', Number(inserted?.[0]?.id), { memo: enhancedMemo })
      }

      if (category === 'purchase_payment' && vendorCode && pettyCashTransactionId) {
        await supabaseInsert('payable_transactions', {
          vendor_code: vendorCode,
          amount: -amount,
          ref_type: 'Payment',
          ref_id: null,
          trans_date: transDate,
          memo: memo ? `패티 지급: ${memo.slice(0, 200)}` : '패티 지급',
          petty_cash_transaction_id: pettyCashTransactionId,
        })
      }

      if (category === 'fixed_asset') {
        const faCode = assetCode || `FA-${Date.now()}`
        const faInserted = (await supabaseInsert('fixed_assets', {
          asset_code: faCode,
          name: assetName || memo || '고정자산',
          store_name: store,
          acquisition_date: transDate,
          acquisition_cost: amount,
          residual_rate: residualRate,
          useful_life_months: usefulLifeMonths,
          depreciation_method: 'straight_line',
          status: 'active',
          memo: memo || null,
        })) as { id?: number }[]
        fixedAssetId = Number(faInserted?.[0]?.id || 0) || null
      }
    }

    if (category === 'fixed_asset' && !fixedAssetId) {
      const faCode = assetCode || `FA-${Date.now()}`
      const faInserted = (await supabaseInsert('fixed_assets', {
        asset_code: faCode,
        name: assetName || memo || '고정자산',
        store_name: store,
        acquisition_date: transDate,
        acquisition_cost: amount,
        residual_rate: residualRate,
        useful_life_months: usefulLifeMonths,
        depreciation_method: 'straight_line',
        status: 'active',
        memo: memo || null,
      })) as { id?: number }[]
      fixedAssetId = Number(faInserted?.[0]?.id || 0) || null
      if (fixedAssetId && bankTransactionId) {
        await supabaseUpdate('bank_transactions', bankTransactionId, { fixed_asset_id: fixedAssetId })
      }
    }

    try {
      await postWithdrawalJournal({
        sourceType: paymentMethod === 'bank' ? 'bank_transaction' : 'petty_cash',
        sourceId: paymentMethod === 'bank' ? bankTransactionId : pettyCashTransactionId,
        category,
        accountingDate: transDate,
        amountAbs: amount,
        memo: memo || undefined,
        storeName: store || undefined,
        postedBy: userName || undefined,
        expenseAccountCode: accountSubjectCode || undefined,
        expenseAccountName: accountSubjectName || undefined,
        expenseAccountSubjectId:
          accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : undefined,
        transferToAccountId: category === 'transfer' ? transferToAccountId : undefined,
        transferToPettyStore: category === 'transfer_to_petty' ? transferToPettyStore : undefined,
        transferToCardAccountId: category === 'transfer_to_card' ? transferToCardAccountId : undefined,
        transferFromPettyToAccountId: category === 'transfer_from_petty' ? transferToAccountId : undefined,
        transferExternalRecipientName: category === 'transfer_external' ? transferBankRecipientName : undefined,
      })
    } catch (postingErr) {
      console.error('executeWithdrawal posting:', postingErr)
    }

    return NextResponse.json({
      success: true,
      message: '등록되었습니다.',
      bankTransactionId: bankTransactionId ?? undefined,
      pettyCashTransactionId: pettyCashTransactionId ?? undefined,
      fixedAssetId: fixedAssetId ?? undefined,
    }, { headers })
  } catch (e) {
    console.error('executeWithdrawal:', e)
    return NextResponse.json(
      { success: false, message: '오류: ' + (e instanceof Error ? e.message : String(e)) },
      { status: 500, headers }
    )
  }
}

function mapToWithdrawalCategory(main: string, sub: string): WithdrawalCategory | null {
  const m = main.toLowerCase()
  const s = sub.toLowerCase()
  if (m === 'purchase' || m === '매입') {
    return s === 'advance' || s === '선급' ? 'purchase_advance' : 'purchase_payment'
  }
  if (m === 'expense' || m === '경비') {
    return s === 'advance' || s === '선급' ? 'expense_advance' : 'expense'
  }
  if (m === 'fixed_asset' || m === '자산') return 'fixed_asset'
  if (m === 'transfer' || m === '이체') return 'transfer'
  if (m === 'loan' || m === '대출') {
    return s === 'given' || s === '대여' ? 'loan_given' : 'loan_repayment'
  }
  if (m === 'loan_repayment') return 'loan_repayment'
  if (m === 'loan_given') return 'loan_given'
  if (m === 'tax' || m === '세금') {
    if (s === 'vat' || s === '부가세') return 'tax_vat'
    if (s === 'corporate' || s === '법인세') return 'tax_corporate'
    return 'tax_withholding'
  }
  if (m === 'correction' || m === '정정') return 'correction'
  if (m === 'dividend' || m === '자본') return 'dividend'
  return null
}

function mapToBankTransactionCategory(cat: WithdrawalCategory): string {
  const map: Record<WithdrawalCategory, string> = {
    purchase_payment: 'purchase_payment',
    purchase_advance: 'advance',
    expense: 'expense',
    expense_advance: 'advance',
    fixed_asset: 'expense',
    transfer: 'transfer',
    transfer_external: 'transfer',
    transfer_to_petty: 'transfer',
    transfer_to_card: 'transfer',
    transfer_from_petty: 'transfer',
    loan_repayment: 'loan',
    loan_given: 'advance',
    tax_vat: 'expense',
    tax_withholding: 'expense',
    tax_corporate: 'expense',
    correction: 'correction',
    dividend: 'expense',
  }
  return map[cat] || 'expense'
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter } from '@/lib/supabase-server'
import { ORDERS_ADMIN_LIST_COLS, ORDERS_STORE_NAME_COLS } from '@/lib/postgrest-narrow-select'

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const startStr = String(searchParams.get('startStr') || searchParams.get('startDate') || '').trim()
  const endStr = String(searchParams.get('endStr') || searchParams.get('endDate') || '').trim()
  let storeFilter = String(searchParams.get('store') || searchParams.get('storeFilter') || '').trim()
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = String(searchParams.get('userRole') || '').toLowerCase()
  const isHQ = ['office', '본사', '오피스'].includes(userStore.toLowerCase().trim())
  if (userStore && !isHQ) storeFilter = userStore
  const deliveryStatusFilter = String(searchParams.get('deliveryStatus') || '').trim()
  const statusFilter = String(searchParams.get('status') || searchParams.get('statusFilter') || '').trim()
  const orderIdFilter = String(searchParams.get('orderId') || searchParams.get('search') || '').trim().replace(/^#/, '')

  let s = startStr
  let e = endStr
  if (!s || !e) {
    const now = new Date()
    const first = new Date(now.getFullYear(), now.getMonth(), 1)
    const last = new Date(now.getFullYear(), now.getMonth() + 1, 0)
    s = first.toISOString().slice(0, 10)
    e = last.toISOString().slice(0, 10)
  }

  try {
    const endIso = e + 'T23:59:59.999Z'

    const itemsRows = (await supabaseSelect('items', { order: 'id.asc', limit: 10000, select: 'code,category,spec,vendor,outbound_location' })) as {
      code?: string
      category?: string
      spec?: string
      vendor?: string
      outbound_location?: string
    }[] | null
    const itemSpecMap: Record<string, string> = {}
    const itemCategoryMap: Record<string, string> = {}
    const itemVendorMap: Record<string, string> = {}
    const itemOutboundMap: Record<string, string> = {}
    for (const row of itemsRows || []) {
      const code = String(row.code || '').trim()
      if (code) {
        itemSpecMap[code] = String(row.spec || '').trim()
        itemCategoryMap[code] = String(row.category || '').trim()
        itemVendorMap[code] = String(row.vendor || '').trim()
        itemOutboundMap[code] = String(row.outbound_location || '').trim()
      }
    }

    let filter =
      `order_date=gte.${encodeURIComponent(s)}&order_date=lte.${encodeURIComponent(endIso)}`
    if (storeFilter && storeFilter !== 'All' && storeFilter !== '전체') {
      filter += `&store_name=eq.${encodeURIComponent(storeFilter)}`
    }
    const baseFilter = `order_date=gte.${encodeURIComponent(s)}&order_date=lte.${encodeURIComponent(endIso)}`
    const orderIdNum = orderIdFilter ? parseInt(orderIdFilter, 10) : NaN
    const hasValidOrderId = !Number.isNaN(orderIdNum) && orderIdNum > 0

    const [rows, storeRows, orderByIdRows, empRows] = await Promise.all([
      supabaseSelectFilter('orders', filter, {
        order: 'order_date.desc',
        limit: 5000,
        select: ORDERS_ADMIN_LIST_COLS,
      }),
      supabaseSelectFilter('orders', baseFilter, {
        order: 'order_date.desc',
        limit: 10000,
        select: ORDERS_STORE_NAME_COLS,
      }),
      hasValidOrderId
        ? supabaseSelectFilter('orders', `id=eq.${orderIdNum}`, {
            limit: 1,
            select: ORDERS_ADMIN_LIST_COLS,
          })
        : Promise.resolve(null),
      supabaseSelect('employees', { order: 'id.asc', limit: 2000, select: 'store,name,nick' }),
    ])

    const nameToNick: Record<string, string> = {}
    const nameToNickByUser: Record<string, string> = {}
    const empList = (empRows || []) as { store?: string; name?: string; nick?: string }[]
    for (const e of empList) {
      const storeKey = String(e.store || '').trim()
      const n = String(e.name || '').trim()
      const nickStr = String(e.nick || '').trim()
      const displayVal = nickStr || n
      if (storeKey && n) nameToNick[storeKey + '|' + n] = displayVal
      if (storeKey && nickStr) nameToNick[storeKey + '|' + nickStr] = displayVal
      if (n) nameToNickByUser[n] = displayVal
    }

    const rowsTyped = rows as {
      id: number
      order_date?: string
      store_name?: string
      user_name?: string
      cart_json?: string
      total?: number
      status?: string
      delivery_status?: string
      delivery_date?: string
      delivery_dates_by_outbound?: string
      received_indices?: string
      approved_indices?: string
      approved_original_qty_json?: string
      reject_reason?: string
    }[]

    const orderByIdTyped = (orderByIdRows || []) as typeof rowsTyped
    const existingIds = new Set((rowsTyped || []).map((r) => r.id))
    const combinedRows = [...(rowsTyped || [])]
    for (const o of orderByIdTyped) {
      if (!existingIds.has(o.id)) {
        combinedRows.unshift(o)
        existingIds.add(o.id)
      }
    }

    const list = combinedRows.map((o) => {
      let items: { code?: string; name?: string; spec?: string; qty?: number; price?: number }[] = []
      try {
        items = JSON.parse(o.cart_json || '[]')
      } catch {}
      items = items.map((it) => ({
        ...it,
        spec: it.spec || itemSpecMap[it.code || ''] || '',
        category: (it as { category?: string }).category || itemCategoryMap[it.code || ''] || '',
        vendor: (it as { vendor?: string }).vendor || itemVendorMap[it.code || ''] || '',
        outboundLocation: itemOutboundMap[it.code || ''] || '',
      }))
      let receivedIndices: number[] = []
      try {
        if (o.received_indices) receivedIndices = JSON.parse(o.received_indices)
      } catch {}
      let approvedOriginalQtyMap: Record<string, number> = {}
      try {
        if (o.approved_original_qty_json) approvedOriginalQtyMap = JSON.parse(o.approved_original_qty_json) || {}
      } catch {}
      const itemsWithOriginal = items.map((it, idx) => ({
        ...it,
        originalQty: approvedOriginalQtyMap[String(idx)] ?? it.qty,
      }))
      const summary =
        items.length > 0
          ? (items[0].name || '') + (items.length > 1 ? ` 외 ${items.length - 1}건` : '')
          : '내용 없음'
      const dateVal = o.order_date
      const dateStr = dateVal ? String(dateVal).substring(0, 16).replace('T', ' ') : ''
      const storeKey = String(o.store_name || '').trim()
      const userName = String(o.user_name || '').trim()
      const userNick = (storeKey && userName)
        ? (nameToNick[storeKey + '|' + userName] ?? nameToNickByUser[userName] ?? userName)
        : userName || undefined
      let deliveryDatesByOutbound: Record<string, string> | undefined
      try {
        const raw = (o as { delivery_dates_by_outbound?: string }).delivery_dates_by_outbound
        if (raw && typeof raw === 'string') {
          const parsed = JSON.parse(raw) as Record<string, string>
          if (parsed && typeof parsed === 'object') deliveryDatesByOutbound = parsed
        }
      } catch {}
      const legacyDeliveryDate = String(o.delivery_date || '').trim()
      const firstFromOutbound = deliveryDatesByOutbound && Object.keys(deliveryDatesByOutbound).length > 0
        ? Object.values(deliveryDatesByOutbound)[0]
        : ''
      return {
        row: o.id,
        orderId: o.id,
        date: dateStr,
        store: o.store_name || '',
        userName: userName || undefined,
        userNick: userNick || undefined,
        total: Number(o.total) || 0,
        status: o.status || 'Pending',
        deliveryStatus: (() => {
          const ds = (o.delivery_status || '').trim()
          if (ds === '배송완료' || ds === '배송 완료' || ds === '일부배송완료' || ds === '일부 배송 완료') {
            return ds === '일부 배송 완료' ? '일부배송완료' : (ds === '배송 완료' ? '배송완료' : ds)
          }
          if (o.received_indices && receivedIndices.length > 0) {
            return receivedIndices.length >= items.length ? '배송완료' : '일부배송완료'
          }
          return o.status === 'Approved' ? '배송중' : ''
        })(),
        deliveryDate: legacyDeliveryDate || firstFromOutbound,
        deliveryDatesByOutbound,
        items: itemsWithOriginal,
        summary,
        receivedIndices,
        rejectReason: String(o.reject_reason || '').trim() || undefined,
      }
    })

    let filteredList = list
    if (deliveryStatusFilter && deliveryStatusFilter !== 'All' && deliveryStatusFilter !== '전체') {
      const norm = (s: string) => (s || '').replace(/\s/g, '')
      filteredList = filteredList.filter((o) => norm(o.deliveryStatus || '') === norm(deliveryStatusFilter))
    }
    if (statusFilter && statusFilter !== 'all' && statusFilter !== 'All' && statusFilter !== '전체') {
      const statusMap: Record<string, string> = {
        pending: 'Pending',
        approved: 'Approved',
        rejected: 'Rejected',
        hold: 'Hold',
      }
      const target = statusMap[statusFilter.toLowerCase()] || statusFilter
      filteredList = filteredList.filter((o) => (o.status || '') === target)
    }

    const storesForDropdown = [...new Set((storeRows || []).map((r: { store_name?: string }) => r.store_name || '').filter(Boolean))].sort()
    return NextResponse.json({ list: filteredList, stores: storesForDropdown }, { headers })
  } catch (err) {
    console.error('getAdminOrders:', err)
    return NextResponse.json({ list: [] }, { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter, supabaseRpc } from '@/lib/supabase-server'
import { getVerifiedAuth } from '@/lib/verify-auth'
import { isPosAdditiveOptionItemCategory } from '@/lib/pos-additive-item-category'
import { getStockLocationPatterns } from '@/lib/stock-location-patterns'
import { getBangkokEndOfDayUtcIso } from '@/lib/bangkok-time'

export interface AppItem {
  code: string
  category: string
  name: string
  spec: string
  price: number
  cost: number
  taxType: string
  safeQty: number
  image: string
  description?: string
  purchaseSource?: 'hq' | 'store'
  orderDisabled?: boolean
  /** 재고 기본 단위. 비어 있으면 unit 사용 (하위 호환) */
  stockBaseUnit?: string
  /** 조정/조사 시 선택 단위 (하위 호환) */
  stockUnitOptions?: { unit: string; factor: number }[]
  /** 표준 단위 목록. (totalQuantity) [unit] = 1 규격 → 입력÷totalQuantity = 규격 수 */
  standardUnits?: { unit: string; totalQuantity: number }[]
}

const ITEMS_SELECT_FULL = 'code,category,name,spec,unit,total_quantity,price,cost,tax,image,description,purchase_source,order_disabled,stock_base_unit,stock_unit_options,standard_units'
const ITEMS_SELECT_MINIMAL = 'code,category,name,spec,unit,total_quantity,price,cost,tax,image,description,purchase_source,order_disabled'

function parseStockUnitOptions(val: unknown): { unit: string; factor: number }[] {
  if (!Array.isArray(val)) return []
  return val
    .filter((x): x is { unit?: string; factor?: number } => x != null && typeof x === 'object')
    .map((x) => ({ unit: String(x.unit ?? '').trim(), factor: Number(x.factor) || 1 }))
    .filter((x) => x.unit.length > 0)
}

function parseStandardUnits(val: unknown): { unit: string; totalQuantity: number }[] {
  if (!Array.isArray(val)) return []
  return val
    .filter((x): x is { unit?: string; total_quantity?: number } => x != null && typeof x === 'object')
    .map((x) => ({ unit: String(x.unit ?? '').trim(), totalQuantity: Number(x.total_quantity) || 1 }))
    .filter((x) => x.unit.length > 0 && x.totalQuantity > 0)
}

async function getItems(storeName: string, scope?: string): Promise<AppItem[]> {
  const isOrderScope = String(scope || '').toLowerCase().trim() === 'order'
  type Row = {
    code?: string
    category?: string
    name?: string
    spec?: string
    unit?: string
    total_quantity?: number | null
    price?: number
    cost?: number
    tax?: string
    image?: string
    description?: string
    purchase_source?: string
    order_disabled?: boolean
    stock_base_unit?: string
    stock_unit_options?: unknown
    standard_units?: unknown
  }
  let rows: Row[] | null = null
  let useStockUnits = true
  try {
    if (isOrderScope) {
      rows = (await supabaseSelectFilter(
        'items',
        `or=(purchase_source.eq.hq,purchase_source.is.null)`,
        { order: 'id.asc', select: ITEMS_SELECT_FULL }
      )) as Row[] | null
    } else {
      rows = (await supabaseSelect('items', { order: 'id.asc', select: ITEMS_SELECT_FULL })) as Row[] | null
    }
  } catch {
    useStockUnits = false
    if (isOrderScope) {
      rows = (await supabaseSelectFilter(
        'items',
        `or=(purchase_source.eq.hq,purchase_source.is.null)`,
        { order: 'id.asc', select: ITEMS_SELECT_MINIMAL }
      )) as Row[] | null
    } else {
      rows = (await supabaseSelect('items', { order: 'id.asc', select: ITEMS_SELECT_MINIMAL })) as Row[] | null
    }
  }

  const safeMap: Record<string, number> = {}
  if (storeName) {
    const storeNorm = String(storeName).toLowerCase().trim()
    const settings = (await supabaseSelectFilter(
      'store_settings',
      `store=ilike.${encodeURIComponent(storeNorm)}`
    )) as { code?: string; safe_qty?: number }[] | null
    for (let i = 0; i < (settings || []).length; i++) {
      const c = String(settings![i].code || '')
      if (c) safeMap[c] = Number(settings![i].safe_qty) || 0
    }
  }
  const list: AppItem[] = []
  for (let i = 0; i < (rows || []).length; i++) {
    const row = rows![i]
    if (!row?.code) continue
    // 매장 발주 품목(scope=order)에서 order_disabled=true면 제외
    if (isOrderScope && row.order_disabled === true) continue
    // POS 추가형 옵션용 품목 마스터 — 발주 품목이 아님(판매 단위는 POS 메뉴·옵션)
    if (isOrderScope && isPosAdditiveOptionItemCategory(row.category)) continue
    const taxType = row.tax === '면세' ? '면세' : row.tax === '영세율' ? '영세율' : '과세'
    const ps = String(row.purchase_source || '').trim()
    list.push({
      code: String(row.code),
      category: String(row.category || ''),
      name: String(row.name || ''),
      spec: String(row.spec || ''),
      price: Number(row.price) || 0,
      cost: Number(row.cost) || 0,
      taxType,
      safeQty: safeMap[row.code] || 0,
      image: String(row.image || ''),
      description: row.description ? String(row.description).trim() : undefined,
      purchaseSource: ps === 'store' ? 'store' : 'hq',
      orderDisabled: row.order_disabled === true,
      ...(useStockUnits && row
        ? (() => {
            const parsed = parseStandardUnits((row as Row).standard_units)
            const standardUnits =
              parsed.length > 0
                ? parsed
                : (() => {
                    const u = String((row as Row).unit ?? '').trim()
                    const tq = Number((row as Row).total_quantity)
                    if (u && !isNaN(tq) && tq > 0) return [{ unit: u, totalQuantity: tq }]
                    return []
                  })()
            return {
              stockBaseUnit: String((row as Row).stock_base_unit ?? '').trim(),
              stockUnitOptions: parseStockUnitOptions((row as Row).stock_unit_options),
              standardUnits,
            }
          })()
        : {}),
    })
  }
  return list
}

async function getStoreStock(store: string, asOfDate?: string): Promise<Record<string, number>> {
  try {
    const storeNorm = String(store || '').toLowerCase().trim()
    if (!storeNorm) return {}

    const patterns: string[] = getStockLocationPatterns(store)
    if (patterns.length === 0) return {}

    const asOfTrim = asOfDate?.trim() || ''
    const asOfTimestamp =
      asOfTrim && /^\d{4}-\d{2}-\d{2}$/.test(asOfTrim) ? getBangkokEndOfDayUtcIso(asOfTrim) : null

    try {
      const rows = (await supabaseRpc<{ item_code: string; total_qty: number }[]>(
        'get_store_stock',
        {
          p_location_patterns: patterns,
          p_as_of_date: asOfTimestamp,
        }
      )) as { item_code?: string; total_qty?: number }[] | null

      const m: Record<string, number> = {}
      for (let i = 0; i < (rows || []).length; i++) {
        const code = rows![i].item_code
        if (!code) continue
        m[code] = Number(rows![i].total_qty ?? 0)
      }
      return m
    } catch (rpcErr) {
      // RPC 미배포 시 fallback: 기존 select 방식 (limit 50000)
      const locFilter =
        patterns.length === 1
          ? `location=ilike.${encodeURIComponent(patterns[0])}`
          : `or=(${patterns.map((p) => `location.ilike.${encodeURIComponent(p)}`).join(',')})`
      const dateSuffix = asOfTimestamp
        ? `&log_date=lte.${encodeURIComponent(asOfTimestamp)}`
        : ''
      const rows = (await supabaseSelectFilter(
        'stock_logs',
        `${locFilter}${dateSuffix}`,
        { order: 'id.asc', limit: 50000, select: 'item_code,qty' }
      )) as { item_code?: string; qty?: number }[] | null
      const m: Record<string, number> = {}
      for (let i = 0; i < (rows || []).length; i++) {
        const code = rows![i].item_code
        if (!code) continue
        m[code] = (m[code] || 0) + Number(rows![i].qty || 0)
      }
      return m
    }
  } catch {
    return {}
  }
}

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const storeName = String(searchParams.get('storeName') || searchParams.get('store') || '').trim()
  const asOfDate = String(searchParams.get('asOfDate') || searchParams.get('date') || '').trim()
  const scope = String(searchParams.get('scope') || '').trim()

  const auth = await getVerifiedAuth(request)
  const userRole = (auth?.role || '').toLowerCase()
  const isManager = userRole.includes('manager') || userRole.includes('franchisee')
  const userStore = (auth?.store || '').trim()
  if (isManager && userStore && storeName) {
    const storeNorm = storeName.toLowerCase().trim()
    const userNorm = userStore.toLowerCase().trim()
    const matches = storeNorm === userNorm || userNorm.includes(storeNorm) || storeNorm.includes(userNorm)
    if (!matches) {
      return NextResponse.json({ items: [], stock: {} }, { headers })
    }
  }

  try {
    const [items, stock] = await Promise.all([
      getItems(storeName, scope || undefined),
      getStoreStock(storeName, asOfDate || undefined),
    ])
    return NextResponse.json({ items, stock }, { headers })
  } catch (e) {
    console.error('getAppData:', e)
    return NextResponse.json({ items: [], stock: {} }, { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilterAllPages } from '@/lib/supabase-server'
import { ATTENDANCE_LOG_ADMIN_GRID_COLS } from '@/lib/postgrest-narrow-select'
import {
  bangkokDateRangeToUtc,
  plannedWorkMinutesFromPlans,
  resolveScheduleForAttendanceDay,
  scheduleDateKey,
} from '@/lib/attendance-utils'
import { otMinutesForPayroll } from '@/lib/payroll-utils'
import { normalizeEmployeeNameForGradeMatch } from '@/lib/employee-display-name'

const TZ = 'Asia/Bangkok'

/** log_at(UTC ISO) → 방콕 기준 날짜 YYYY-MM-DD */
function toDateStr(val: string | Date | null | undefined): string {
  if (!val) return ''
  const d = new Date(val)
  return isNaN(d.getTime()) ? '' : d.toLocaleDateString('en-CA', { timeZone: TZ })
}

/** log_at(UTC ISO) → 방콕 기준 시간 HH:mm */
function toTimeStr(iso: string | null | undefined): string {
  if (!iso) return ''
  const d = new Date(iso)
  return isNaN(d.getTime()) ? '' : d.toLocaleTimeString('ko-KR', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false })
}

/** log_at(UTC ISO) → 방콕 기준 시간 HH:mm:ss (출근=퇴근 여부 확인용) */
function toTimeStrWithSec(iso: string | null | undefined): string {
  if (!iso) return ''
  const d = new Date(iso)
  return isNaN(d.getTime()) ? '' : d.toLocaleTimeString('ko-KR', { timeZone: TZ, hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
}

/** 방콕 기준 날짜(YYYY-MM-DD)에서 N일 더한 날짜 */
function addDay(dateStr: string, delta: number): string {
  const d = new Date(dateStr + 'T12:00:00')
  d.setDate(d.getDate() + delta)
  return d.toISOString().slice(0, 10)
}

/** log_at(ISO) → 방콕 기준 시각의 시(hour) 0~23 */
function getBangkokHour(iso: string): number {
  if (!iso) return 12
  const d = new Date(iso)
  const str = d.toLocaleTimeString('en-US', { timeZone: TZ, hour: '2-digit', hour12: false })
  return parseInt(str, 10) || 0
}

/** Mr./Ms./Mrs./Miss 접두어 제거 - 스케줄·근태 이름 매칭용 */
function normalizeNameForSchedule(name: string): string {
  return normalizeEmployeeNameForGradeMatch(name)
}

export interface AttendanceDailyRow {
  date: string
  store: string
  name: string
  employeeId?: number
  employeeCode?: string
  inTimeStr: string
  outTimeStr: string
  breakMin: number
  actualWorkHrs: number
  plannedWorkHrs: number
  diffMin: number
  lateMin: number
  earlyMin?: number
  otMin: number
  status: string
  approval: string
  /** @deprecated use pendingInId/pendingOutId */
  pendingId: number | null
  pendingInId: number | null
  pendingOutId: number | null
  /** 퇴근 로그 id (승인 여부 무관, 조정 반영 시 사용) */
  outLogId: number | null
  inStatus?: string
  /** 파트타임/시급이면 계획 0이어도 빨간 행 표시 안 함 */
  isPartTime?: boolean
}

export const dynamic = 'force-dynamic' // 조정 반영 후 최신 데이터 조회를 위해 캐시 비활성화

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Cache-Control', 'no-store, max-age=0')
  const { searchParams } = new URL(request.url)
  const startDate = String(searchParams.get('startDate') || searchParams.get('start') || '').trim()
  const endDate = String(searchParams.get('endDate') || searchParams.get('end') || '').trim()
  let storeFilter = String(searchParams.get('storeFilter') || searchParams.get('store') || '').trim()
  let employeeFilter = String(searchParams.get('employeeFilter') || searchParams.get('employee') || searchParams.get('name') || '').trim()
  const statusFilter = String(searchParams.get('statusFilter') || searchParams.get('status') || 'all').trim()
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = String(searchParams.get('userRole') || '').toLowerCase()
  if (storeFilter === 'null' || storeFilter === 'undefined') storeFilter = ''
  if (employeeFilter === 'null' || employeeFilter === 'undefined') employeeFilter = ''

  if (!startDate || !endDate) {
    return NextResponse.json([], { headers })
  }

  const startStr = startDate.slice(0, 10)
  const endStr = endDate.slice(0, 10)
  const { startISO, endISOExclusive } = bangkokDateRangeToUtc(startStr, endStr)
  // 자정 넘김 퇴근(익일 00:00~06:59 방콕) 포함: log_at 조회 끝을 익일 07:00 방콕(= 익일 00:00 UTC)까지 연장
  const logEndISOExclusive = addDay(endStr, 1) + 'T00:00:00.000Z'

  const isAllStores = !storeFilter || storeFilter === 'All' || storeFilter.toLowerCase() === 'all' || storeFilter === '전체' || storeFilter === '전체 매장'
  const isAllEmployees = !employeeFilter || employeeFilter === 'All' || employeeFilter === '전체 직원'
  const pendingOnly = statusFilter === 'pending'

  const isManager = userRole === 'manager'
  if (isManager && userStore) storeFilter = userStore

  try {
    type AttRow = {
      id?: number
      log_at?: string
      store_name?: string
      name?: string
      employee_id?: number | null
      log_type?: string
      late_min?: number
      early_min?: number
      ot_min?: number
      break_min?: number
      status?: string
      approved?: string
    }

    // 급여(getPayrollCalc)와 동일 구간의 로그를 모두 수집. limit 2000만 쓰면 log_at.asc 앞쪽 행만 오고
    // 직원 필터는 루프에서 적용되어 말일·특정 직원 행이 누락될 수 있음(지각 공제는 있는데 근태 표에 없음).
    const attLogFilterParts = [
      `log_at=gte.${encodeURIComponent(startISO)}`,
      `log_at=lt.${encodeURIComponent(logEndISOExclusive)}`,
    ]
    if (!isAllStores && storeFilter) {
      attLogFilterParts.unshift(`store_name=ilike.${encodeURIComponent(storeFilter)}`)
    }
    if (!isAllEmployees && employeeFilter) {
      attLogFilterParts.push(`name=eq.${encodeURIComponent(employeeFilter)}`)
    }
    const attLogFilter = attLogFilterParts.join('&')
    const attRows = (await supabaseSelectFilterAllPages('attendance_logs', attLogFilter, {
      order: 'log_at.asc',
      select: ATTENDANCE_LOG_ADMIN_GRID_COLS,
      pageSize: 2500,
      maxRows: 120_000,
    })) as AttRow[]

    /** 파트타임/시급 식별 + 직원코드 맵 */
    const partTimeKeys = new Set<string>()
    const codeByStoreName: Record<string, string> = {}
    const codeByEmployeeId: Record<number, string> = {}
    try {
      const empRows = (await supabaseSelect('employees', {
        select: 'id,store,name,job,sal_type,employee_code',
        limit: 5000,
      })) as {
        id?: number
        store?: string
        name?: string
        job?: string
        sal_type?: string
        employee_code?: string | null
      }[]
      const partTimeSal = /시급|hourly|hour|part-time|part\s*time/i
      const partTimeJob = /part|파트|part-time/i
      for (const e of empRows || []) {
        const store = String(e.store || '').trim()
        const nm = String(e.name || '').trim()
        if (!store || !nm) continue
        const code = String(e.employee_code || '')
          .trim()
          .toUpperCase()
          .replace(/[^A-Z0-9]/g, '')
          .slice(0, 5)
        const eid = e.id != null && Number.isFinite(Number(e.id)) ? Math.floor(Number(e.id)) : 0
        if (code) {
          codeByStoreName[`${store}|${nm}`] = code
          const nmNorm = normalizeNameForSchedule(nm)
          if (nmNorm) codeByStoreName[`${store}|${nmNorm}`] = code
          if (eid > 0) codeByEmployeeId[eid] = code
        }
        const job = String(e.job || '').trim()
        const salType = String(e.sal_type || '').trim()
        const isPart = partTimeSal.test(salType) || partTimeJob.test(job)
        if (isPart) {
          partTimeKeys.add(`${store}|${nm}`)
          partTimeKeys.add(`${store}|${normalizeNameForSchedule(nm)}`)
        }
      }
    } catch (_) { /* ignore */ }

    type SchRow = {
      schedule_date?: string
      store_name?: string
      name?: string
      employee_id?: number | null
      plan_in?: string
      plan_out?: string
      break_start?: string
      break_end?: string
      plan_in_prev_day?: boolean
    }
    const scheduleMap: Record<string, SchRow> = {}
    /** schedules: 고정 limit는 데이터 증가 시 항상 부족 → Range 페이지로 전부 수집. 매장 필터로 트래픽·메모리 절감 */
    const schParts = [`schedule_date=gte.${startStr}`, `schedule_date=lte.${endStr.slice(0, 10)}`]
    if (!isAllStores && storeFilter) {
      schParts.push(`store_name=ilike.${encodeURIComponent(storeFilter)}`)
    }
    const schFilter = schParts.join('&')
    const schRows = (await supabaseSelectFilterAllPages('schedules', schFilter, {
      order: 'schedule_date.asc',
      pageSize: 8000,
      maxRows: 2_000_000,
    })) as SchRow[]
    for (const s of schRows || []) {
      const d = scheduleDateKey(s.schedule_date)
      const store = String(s.store_name || '').trim()
      const nm = String(s.name || '').trim()
      if (d && store && nm) {
        const sid =
          s.employee_id != null && Number.isFinite(Number(s.employee_id))
            ? Math.floor(Number(s.employee_id))
            : 0
        if (sid > 0) scheduleMap[`${d}|${store}|#${sid}`] = s
        scheduleMap[`${d}|${store}|${nm}`] = s
        const nmNorm = normalizeNameForSchedule(nm)
        if (nmNorm !== nm) scheduleMap[`${d}|${store}|${nmNorm}`] = s
      }
    }

    const byKey: Record<
      string,
      {
        date: string
        store: string
        name: string
        employeeId: number
        inTime: string | null
        outTime: string | null
        breakMin: number
        lateMin: number
        /** 퇴근 로그 early_min (NULL=미설정·계산값 사용, 0=조정으로 면제) */
        earlyMinFromDb: number | null
        otMin: number | null // null = DB에 미설정, 계산값 사용
        status: string
        approval: string
        inId: number | null
        outId: number | null
        outLogId: number | null
        outApproved: string
        inStatus: string
      }
    > = {}

    for (const r of attRows || []) {
      const rowDate = toDateStr(r.log_at)
      const type = String(r.log_type || '').trim()
      const logAt = r.log_at || ''
      if (!rowDate || rowDate < startStr) continue
      // 조회 구간 밖 날짜: 익일 새벽 퇴근(자정 넘김)만 허용 → 전날 행에 붙이기 위함
      if (rowDate > endStr) {
        const isOvernightOutForRange = type === '퇴근' && getBangkokHour(logAt) <= 7 && rowDate === addDay(endStr, 1)
        if (!isOvernightOutForRange) continue
      }
      const rowStore = String(r.store_name || '').trim()
      const name = String(r.name || '').trim()
      if (!isAllEmployees && name !== employeeFilter) continue

      const eid =
        r.employee_id != null && Number.isFinite(Number(r.employee_id)) ? Math.floor(Number(r.employee_id)) : 0
      const key = eid > 0 ? `${rowDate}|${rowStore}|#${eid}` : `${rowDate}|${rowStore}|${name}`
      if (!byKey[key]) {
        byKey[key] = {
          date: rowDate,
          store: rowStore,
          name,
          employeeId: eid,
          inTime: null,
          outTime: null,
          breakMin: 0,
          lateMin: 0,
          earlyMinFromDb: null,
          otMin: null,
          status: '',
          approval: '대기',
          inId: null,
          outId: null,
          outLogId: null,
          outApproved: '',
          inStatus: '',
        }
      }
      const rec = byKey[key]
      const approved = String(r.approved || '').trim()
      const st = String(r.status || '').trim()
      const isGpsOrForced = /위치미확인|승인대기|강제퇴근/.test(st)
      const needsInApproval = approved === '대기' && (isGpsOrForced || (Number(r.late_min) || 0) > 0)
      const needsOutApproval = approved === '대기' && (isGpsOrForced || (Number(r.ot_min) || 0) > 0 || (Number(r.early_min) || 0) > 0)

      if (type === '출근') {
        if (!rec.inTime || logAt < (rec.inTime || '')) {
          rec.inTime = logAt
          rec.lateMin = Number(r.late_min) || 0
          if (needsInApproval) {
            rec.inId = r.id ?? null
            rec.inStatus = st || ''
          }
        }
      } else if (type === '퇴근') {
        const bangkokHour = getBangkokHour(logAt)
        const isOvernightOut = bangkokHour < 7
        const prevDayKey = eid > 0 ? `${addDay(rowDate, -1)}|${rowStore}|#${eid}` : `${addDay(rowDate, -1)}|${rowStore}|${name}`
        const prevRec = byKey[prevDayKey]

        if (isOvernightOut && prevRec?.inTime && !prevRec.outTime) {
          prevRec.outTime = logAt
          prevRec.earlyMinFromDb =
            r.early_min != null && Number.isFinite(Number(r.early_min))
              ? Math.round(Number(r.early_min))
              : null
          prevRec.otMin = r.ot_min != null ? Number(r.ot_min) : null
          prevRec.status = st || prevRec.status
          prevRec.outApproved = approved || ''
          if (needsOutApproval) prevRec.outId = r.id ?? null
          prevRec.outLogId = r.id ?? null
        } else if (!isOvernightOut && (!rec.outTime || logAt > (rec.outTime || ''))) {
          rec.outTime = logAt
          rec.earlyMinFromDb =
            r.early_min != null && Number.isFinite(Number(r.early_min))
              ? Math.round(Number(r.early_min))
              : null
          rec.otMin = r.ot_min != null ? Number(r.ot_min) : null
          rec.status = st || rec.status
          rec.outApproved = approved || ''
          if (needsOutApproval) rec.outId = r.id ?? null
          rec.outLogId = r.id ?? null
        }
      } else if (type === '휴식종료') {
        rec.breakMin += Number(r.break_min) || 0
      }
    }

    const result: AttendanceDailyRow[] = []
    for (const rec of Object.values(byKey)) {
      if (!rec.inTime) continue
      const dateForRow = rec.date
      const inTimeForRow = rec.inTime
      let outTimeForRow = rec.outTime
      let breakMinForRow = rec.breakMin
      const lateMinForRow = rec.lateMin
      let earlyMinDb = rec.earlyMinFromDb
      let otMinForRow = rec.otMin
      let statusForRow = rec.status
      let outApprovedForRow = rec.outApproved
      let outIdForRow = rec.outId
      let outLogIdForRow = rec.outLogId
      const inIdForRow = rec.inId
      const inStatusForRow = rec.inStatus || ''

      if (!outTimeForRow) {
        const nextDay = (() => {
          const d = new Date(rec.date + 'T12:00:00')
          d.setDate(d.getDate() + 1)
          return d.toISOString().slice(0, 10)
        })()
        const nextRec = byKey[`${nextDay}|${rec.store}|${rec.name}`]
        if (nextRec && nextRec.outTime && !nextRec.inTime) {
          outTimeForRow = nextRec.outTime
          earlyMinDb = nextRec.earlyMinFromDb
          otMinForRow = nextRec.otMin
          statusForRow = nextRec.status || ''
          outApprovedForRow = nextRec.outApproved
          outIdForRow = nextRec.outId
          outLogIdForRow = nextRec.outLogId
          breakMinForRow += nextRec.breakMin
          // 자정 넘김 근무: 행은 출근한 날(오늘) 기준 유지, 퇴근만 익일 기록 사용
        }
      }

      let actualWorkMin = 0
      if (inTimeForRow && outTimeForRow) {
        const inMs = new Date(inTimeForRow).getTime()
        const outMs = new Date(outTimeForRow).getTime()
        actualWorkMin = Math.max(0, Math.floor((outMs - inMs) / 60000) - breakMinForRow)
      }

      const sch = resolveScheduleForAttendanceDay(
        dateForRow,
        rec.store,
        rec.employeeId > 0 ? `#${rec.employeeId}` : rec.name,
        scheduleMap,
        actualWorkMin,
        'payroll'
      )
      const planIn = sch?.plan_in || ''
      const planOut = sch?.plan_out || ''
      const planBS = sch?.break_start || ''
      const planBE = sch?.break_end || ''
      const planInPrevDay = !!sch?.plan_in_prev_day
      const plannedWorkMin = sch
        ? plannedWorkMinutesFromPlans(planIn, planOut, planBS, planBE, planInPrevDay)
        : 0
      const plannedWorkHrs = Math.round((plannedWorkMin / 60) * 100) / 100
      const actualWorkHrs = actualWorkMin / 60
      const diffMin = Math.round(actualWorkMin - plannedWorkMin)

      const approval = outTimeForRow ? (outApprovedForRow || '대기') : '대기'
      const isPending = inIdForRow != null || outIdForRow != null
      const outAppr = String(outApprovedForRow || '').trim()
      const approvedOut = outAppr === '승인완료' || outAppr === '승인'
      const statusStr = String(statusForRow || '').trim()
      const computedEarlyMin = plannedWorkMin > 0 && diffMin < 0 ? Math.abs(diffMin) : 0
      /** 퇴근 승인 후 DB early_min(NULL이면 자동 산정분). NOT NULL DEFAULT 0 스키마면 과거 데이터가 면제로 보일 수 있음 */
      const useDbEarly =
        approvedOut &&
        statusStr.includes('정상(승인)') &&
        plannedWorkMin > 0 &&
        diffMin < 0 &&
        earlyMinDb != null &&
        Number.isFinite(earlyMinDb)
      const displayEarlyMin = useDbEarly
        ? Math.min(Math.max(0, Math.round(earlyMinDb as number)), computedEarlyMin)
        : computedEarlyMin

      // 실제 근무시간이 0이면 지각 의미 없음. 스케줄 대비 순증 근무(diff>0)면 지각 분 숨김(급여 지각 공제와 동일)
      const rawLateMin = actualWorkMin <= 0 ? 0 : lateMinForRow
      const effectiveLateMin = plannedWorkMin > 0 && diffMin > 0 ? 0 : rawLateMin
      // 연장: 차이가 음수(조퇴)면 OT 없음. 그 외는 DB 조정값 또는 스케줄 차이(급여 집계와 동일)
      const effectiveOtMin =
        actualWorkMin <= 0 || plannedWorkMin <= 0 || diffMin < 0
          ? 0
          : otMinForRow != null
            ? otMinForRow
            : Math.max(0, diffMin)
      const displayOtMin =
        diffMin < 0
          ? 0
          : otMinForRow != null
            ? effectiveOtMin
            : otMinutesForPayroll(Math.max(0, diffMin))

      if (pendingOnly && !isPending) continue

      // 상태 표시: 퇴근 승인·정상(승인)이면 DB 상태 유지(조정 반영 후에도 조퇴로 덮어쓰지 않음). 그 외 차이 음수→조퇴 등
      const displayStatus =
        !outTimeForRow
          ? '퇴근미기록'
          : (statusForRow && String(statusForRow).includes('강제퇴근(승인)'))
            ? statusForRow
            : approvedOut && statusStr.includes('정상(승인)')
              ? statusForRow
              : diffMin < 0
                ? '조퇴'
                : displayOtMin >= 30
                  ? '연장'
                  : statusForRow === '조퇴'
                    ? '정상'
                    : statusForRow

      const isPartTime =
        partTimeKeys.has(`${rec.store}|${rec.name}`) ||
        partTimeKeys.has(`${rec.store}|${normalizeNameForSchedule(rec.name)}`)
      // 출근·퇴근이 동일하게 보이면(같은 분 또는 실제 동일) 초까지 표시해 오입력/앱 버그 확인 가능하도록
      const inStr = toTimeStr(inTimeForRow)
      const outStr = outTimeForRow ? toTimeStr(outTimeForRow) : '-'
      const sameMinute = outTimeForRow && inStr === outStr
      result.push({
        date: dateForRow,
        store: rec.store,
        name: rec.name,
        ...(rec.employeeId > 0 ? { employeeId: rec.employeeId } : {}),
        ...(() => {
          const c0 = rec.employeeId > 0 ? codeByEmployeeId[rec.employeeId] || '' : ''
          const c1 = codeByStoreName[`${rec.store}|${rec.name}`] || ''
          const code = (c0 || c1).trim()
          return code ? { employeeCode: code } : {}
        })(),
        inTimeStr: sameMinute ? toTimeStrWithSec(inTimeForRow) : inStr,
        outTimeStr: outTimeForRow ? (sameMinute ? toTimeStrWithSec(outTimeForRow) : outStr) : '-',
        breakMin: breakMinForRow,
        actualWorkHrs: Math.round(actualWorkHrs * 100) / 100,
        plannedWorkHrs: Math.round(plannedWorkHrs * 100) / 100,
        diffMin,
        lateMin: effectiveLateMin,
        earlyMin: displayEarlyMin,
        otMin: displayOtMin,
        status: displayStatus,
        approval: approval || '대기',
        pendingId: outIdForRow ?? inIdForRow,
        pendingInId: inIdForRow,
        pendingOutId: outIdForRow,
        outLogId: outLogIdForRow ?? null,
        inStatus: inStatusForRow,
        isPartTime,
      })
    }

    result.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1
      if (a.store !== b.store) return a.store.localeCompare(b.store)
      return a.name.localeCompare(b.name)
    })

    return NextResponse.json(result, { headers })
  } catch (e) {
    console.error('getAttendanceRecordsAdmin:', e)
    return NextResponse.json([], { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter } from '@/lib/supabase-server'

const INTERNAL_BANK_SOURCE_MARKER = 'source:expense_internal'

/** 통장 거래 목록 + 잔액 검증용 집계 */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Cache-Control', 'public, s-maxage=30, stale-while-revalidate=120')
  const { searchParams } = new URL(request.url)
  const accountId = String(searchParams.get('accountId') || '').trim()
  const startStr = String(searchParams.get('startStr') || searchParams.get('start') || '').trim()
  const endStr = String(searchParams.get('endStr') || searchParams.get('end') || '').trim()
  const pageSizeParam = Number(searchParams.get('pageSize') || searchParams.get('limit') || 0)
  const cursorIdParam = Number(searchParams.get('cursorId') || 0)
  const sortParam = String(searchParams.get('sort') || 'asc').toLowerCase()
  const isDesc = sortParam === 'desc'
  const hasPagination = Number.isFinite(pageSizeParam) && pageSizeParam > 0
  const pageSize = hasPagination ? Math.min(1000, Math.max(1, Math.floor(pageSizeParam))) : 20000

  if (!accountId) {
    return NextResponse.json({ list: [], summary: null }, { headers })
  }

  try {
    const accountRows = (await supabaseSelectFilter('bank_accounts', `id=eq.${accountId}`, {
      select: 'id,opening_balance,opening_balance_date',
      limit: 1,
    })) as { id?: number; opening_balance?: number; opening_balance_date?: string }[]
    const account = accountRows?.[0]
    const openingBalance = Number(account?.opening_balance) ?? 0
    const openingDate = account?.opening_balance_date ? String(account.opening_balance_date).slice(0, 10) : '1900-01-01'

    if (!startStr || !endStr) {
      return NextResponse.json({
        list: [],
        summary: {
          openingBalance,
          periodDeposits: 0,
          periodWithdrawals: 0,
          calculatedBalance: openingBalance,
          actualBalance: null,
          difference: null,
        },
      }, { headers })
    }

    let filter = `account_id=eq.${accountId}&trans_date=gte.${startStr}&trans_date=lte.${endStr}`
    if (hasPagination && Number.isFinite(cursorIdParam) && cursorIdParam > 0) {
      filter += isDesc ? `&id=lt.${Math.floor(cursorIdParam)}` : `&id=gt.${Math.floor(cursorIdParam)}`
    }
    const rows = (await supabaseSelectFilter('bank_transactions', filter, {
      order: isDesc ? 'id.desc' : 'id.asc',
      limit: pageSize,
    })) as {
      id?: number
      trans_date?: string
      trans_type?: string
      amount?: number
      memo?: string
      note?: string
      category?: string
      account_subject_id?: number
      sales_date?: string
      expense_date?: string
      vendor_code?: string
      store_name?: string
      invoice_received?: boolean
      invoice_no?: string
      invoice_photo_url?: string
      purchase_order_id?: number
    }[]

    const linkedIds = new Set<number>()
    const rowIds = (rows || []).map((r) => Number(r.id)).filter((id) => id && !isNaN(id))
    if (rowIds.length > 0) {
      const idList = rowIds.join(',')
      const ptRows = (await supabaseSelectFilter('payable_transactions', `bank_transaction_id=in.(${idList})`, {
        select: 'bank_transaction_id',
        limit: rowIds.length,
      })) as { bank_transaction_id?: number }[]
      for (const r of ptRows || []) {
        const bid = Number(r.bank_transaction_id)
        if (bid && !isNaN(bid)) linkedIds.add(bid)
      }
    }

    const visibleRows = (rows || []).filter((r) => !String(r.note || '').toLowerCase().includes(INTERNAL_BANK_SOURCE_MARKER))
    const list = visibleRows.map((r) => ({
      id: r.id,
      transDate: String(r.trans_date || '').slice(0, 10),
      transType: String(r.trans_type || 'withdraw').toLowerCase(),
      amount: Number(r.amount) || 0,
      memo: String(r.memo || '').trim(),
      note: String(r.note || '').trim(),
      category: String(r.category || 'expense').toLowerCase(),
      accountSubjectId: r.account_subject_id ?? null,
      salesDate: r.sales_date ? String(r.sales_date).slice(0, 10) : undefined,
      expenseDate: r.expense_date ? String(r.expense_date).slice(0, 10) : undefined,
      vendorCode: r.vendor_code ? String(r.vendor_code).trim() : undefined,
      storeName: r.store_name ? String(r.store_name).trim() : undefined,
      invoiceReceived: Boolean(r.invoice_received),
      invoiceNo: r.invoice_no ? String(r.invoice_no).trim() : undefined,
      invoicePhotoUrl: r.invoice_photo_url ? String(r.invoice_photo_url).trim() : undefined,
      purchaseOrderId: r.purchase_order_id ?? undefined,
      isLinked: linkedIds.has(Number(r.id || 0)),
    }))

    const periodDeposits = list.filter((t) => t.transType === 'deposit').reduce((s, t) => s + t.amount, 0)
    const periodWithdrawals = list.filter((t) => t.transType === 'withdraw').reduce((s, t) => s + Math.abs(t.amount), 0)

    const beforeStartFilter = `account_id=eq.${accountId}&trans_date=lt.${startStr}`
    const beforeRows = (await supabaseSelectFilter('bank_transactions', beforeStartFilter, {
      select: 'trans_type,amount,note',
      limit: 50000,
    })) as { trans_type?: string; amount?: number; note?: string }[]
    const visibleBeforeRows = (beforeRows || []).filter((r) => !String(r.note || '').toLowerCase().includes(INTERNAL_BANK_SOURCE_MARKER))
    const beforeDeposits = visibleBeforeRows.filter((r) => (r.trans_type || '').toLowerCase() === 'deposit').reduce((s, r) => s + Number(r.amount || 0), 0)
    const beforeWithdrawals = visibleBeforeRows.filter((r) => (r.trans_type || '').toLowerCase() === 'withdraw').reduce((s, r) => s + Math.abs(Number(r.amount || 0)), 0)

    const beginningBalance = openingBalance + beforeDeposits - beforeWithdrawals
    const endingBalance = beginningBalance + periodDeposits - periodWithdrawals

    const responseBody: {
      list: typeof list
      summary: {
        openingBalance: number
        beginningBalance: number
        periodDeposits: number
        periodWithdrawals: number
        calculatedBalance: number
        actualBalance: null
        difference: null
      }
      pagination?: { pageSize: number; sort: 'asc' | 'desc'; hasMore: boolean; nextCursorId: number | null }
    } = {
      list,
      summary: {
        openingBalance,
        beginningBalance,
        periodDeposits,
        periodWithdrawals,
        calculatedBalance: endingBalance,
        actualBalance: null,
        difference: null,
      },
    }
    if (hasPagination) {
      const lastId = list.length > 0 ? Number(list[list.length - 1]?.id || 0) : 0
      responseBody.pagination = {
        pageSize,
        sort: isDesc ? 'desc' : 'asc',
        hasMore: list.length === pageSize && lastId > 0,
        nextCursorId: list.length === pageSize && lastId > 0 ? lastId : null,
      }
    }

    return NextResponse.json(responseBody, { headers })
  } catch (e) {
    console.error('getBankTransactions:', e)
    return NextResponse.json({ list: [], summary: null }, { headers })
  }
}

