import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter } from '@/lib/supabase-server'

const OFFICE_STORES = ['입고등록', '본사', 'Office', '오피스', '본점']

function isOfficeStore(s: string): boolean {
  const x = String(s || '').trim()
  return x === '본사' || x === 'Office' || x === '오피스' || x === '본점' || x.toLowerCase().includes('office')
}

/** 통장 출금 입고 연동용 - 거래처별 입고 배치 목록 (vendor_code 또는 vendor_name으로 매칭)
 * vendorCode로 조회 시: vendors 테이블에서 code→name, gps_name 조회 후 입고의 vendor_code/vendor_name과 매칭
 * storeFilter: 선택된 통장 계좌의 매장 - 매장별로 입고 배치가 달라야 함
 */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const { searchParams } = new URL(request.url)
    const vendorCode = String(searchParams.get('vendorCode') || '').trim()
    const vendorName = String(searchParams.get('vendorName') || '').trim()
    const storeFilter = String(searchParams.get('storeFilter') || '').trim()
    if (!vendorCode && !vendorName) {
      return NextResponse.json([], { headers })
    }

    let locationFilter = ''
    if (storeFilter) {
      if (isOfficeStore(storeFilter)) {
        locationFilter = `&location=in.(입고등록,본사,Office,오피스,본점)`
      } else {
        locationFilter = `&location=ilike.${encodeURIComponent(storeFilter)}`
      }
    }

    const rows = (await supabaseSelectFilter('inbound_batches', `id=gt.0${locationFilter}`, {
      order: 'batch_date.desc',
      limit: 100,
      select: 'id,batch_date,vendor_name,vendor_code,total_amount,location',
    })) as {
      id?: number
      batch_date?: string
      vendor_name?: string
      vendor_code?: string
      total_amount?: number
      location?: string
    }[]

    let matchValues: string[] = []
    if (vendorCode) {
      matchValues = [vendorCode]
      try {
        const vendorRows = (await supabaseSelectFilter('vendors', `code=eq.${encodeURIComponent(vendorCode)}`, {
          select: 'code,name,gps_name',
          limit: 1,
        })) as { code?: string; name?: string; gps_name?: string }[]
        if (vendorRows?.[0]) {
          const v = vendorRows[0]
          const vn = String(v.name || '').trim()
          const gn = String(v.gps_name || '').trim()
          if (vn && !matchValues.includes(vn)) matchValues.push(vn)
          if (gn && !matchValues.includes(gn)) matchValues.push(gn)
        }
      } catch (_) {
        /* vendors 없으면 code만 사용 */
      }
    } else if (vendorName) {
      matchValues = [vendorName]
    }

    const filtered = (rows || []).filter((r) => {
      const vc = String(r.vendor_code || '').trim()
      const vn = String(r.vendor_name || '').trim()
      return matchValues.some((m) => vc === m || vn === m)
    })

    return NextResponse.json(
      filtered.map((r) => ({
        id: r.id,
        batchDate: r.batch_date?.slice(0, 10),
        vendorName: r.vendor_name,
        totalAmount: Number(r.total_amount) || 0,
        location: r.location,
      })),
      { headers }
    )
  } catch (e) {
    console.error('getInboundBatchesForLink:', e)
    return NextResponse.json([], { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter } from '@/lib/supabase-server'

function normalizeOutboundKey(s: string): string {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
}

/**
 * 품목의 outbound_location과 발주 화면 출고지 선택값이 같은 창고인지 판별.
 * - 비어 있으면 모든 출고지에 표시(기존 동작)
 * - code·name 불일치, 대소문자/공백, "S&J Global" vs "S&J Global Co., Ltd." 등 완화 매칭
 */
function itemOutboundMatchesSelection(itemOutboundRaw: string, selectedParts: string[]): boolean {
  const itemRaw = String(itemOutboundRaw || '').trim()
  if (!itemRaw) return true
  const candidates = [...new Set(selectedParts.map((x) => String(x || '').trim()).filter(Boolean))]
  if (candidates.length === 0) return true
  const itemNorm = normalizeOutboundKey(itemRaw)
  for (const c of candidates) {
    const cn = normalizeOutboundKey(c)
    if (!cn) continue
    if (itemNorm === cn) return true
    const minLen = Math.min(itemNorm.length, cn.length)
    // 짧은 코드/이름 오매칭 방지: 충분히 긴 문자열끼리만 부분 일치 허용
    if (minLen >= 6 && (itemNorm.includes(cn) || cn.includes(itemNorm))) return true
  }
  return false
}

/** 본사 발주용: vendor 코드 또는 이름으로 품목 목록 조회
 * - items.vendor = code/name (기존) + item_vendors 매핑 (다대다)
 */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const vendorCode = String(searchParams.get('vendorCode') || searchParams.get('vendor') || '').trim()
  const vendorName = String(searchParams.get('vendorName') || '').trim()
  const outboundLocation = String(searchParams.get('outboundLocation') || '').trim()
  const outboundLocationName = String(searchParams.get('outboundLocationName') || '').trim()

  if (!vendorCode && !vendorName) {
    return NextResponse.json([], { headers })
  }

  try {
    type ItemRow = {
      code?: string
      name?: string
      spec?: string
      price?: number
      cost?: number
      category?: string
      image?: string
      outbound_location?: string
      tax?: string
    }
    const codeSet = new Set<string>()
    const rowsMap = new Map<string, ItemRow>()

    const addRow = (r: ItemRow) => {
      const c = String(r.code || '')
      if (c && !codeSet.has(c)) {
        codeSet.add(c)
        rowsMap.set(c, r)
      }
    }

    const selectCols = 'code,name,spec,price,cost,category,image,outbound_location,tax,purchase_source'
    const selectColsMinimal = 'code,name,spec,price,cost,category,image,outbound_location,tax'
    const hqFilter = `or=(purchase_source.eq.hq,purchase_source.is.null,purchase_source.eq.)`
    /** 본사 발주: purchase_source=store 또는 category=매장 전용/Store Only 제외 */
    const isHqItem = (r: ItemRow & { purchase_source?: string }) => {
      const ps = String(r.purchase_source || '').trim().toLowerCase()
      if (ps === 'store') return false
      const cat = String(r.category || '').trim().toLowerCase().replace(/\s+/g, ' ')
      if (cat === '매장 전용' || cat === '매장전용' || cat === 'store only' || cat === 'storeonly') return false
      if (/\bstore\s*only\b/i.test(cat) || /매장\s*전용/.test(cat)) return false
      return ps === '' || ps === 'hq' || !ps
    }
    let rowsByVendor: (ItemRow & { purchase_source?: string })[] | null = []
    const runItemsQuery = async (vendorVal: string, withHq: boolean) => {
      const enc = encodeURIComponent(vendorVal)
      const filter = withHq ? `vendor=ilike.*${enc}*&${hqFilter}` : `vendor=ilike.*${enc}*`
      const select = withHq ? selectCols : selectColsMinimal
      return (await supabaseSelectFilter('items', filter, {
        order: 'code.asc',
        limit: 1000,
        select,
      })) as (ItemRow & { purchase_source?: string })[]
    }
    if (vendorCode) {
      try {
        rowsByVendor = await runItemsQuery(vendorCode, true)
        if (rowsByVendor?.length) rowsByVendor = rowsByVendor.filter((r) => isHqItem(r))
      } catch {
        try {
          rowsByVendor = await runItemsQuery(vendorCode, false)
          if (rowsByVendor?.length) rowsByVendor = rowsByVendor.filter((r) => isHqItem(r))
        } catch {
          rowsByVendor = []
        }
      }
    }
    if ((!rowsByVendor || rowsByVendor.length === 0) && vendorName) {
      try {
        rowsByVendor = await runItemsQuery(vendorName, true)
        if (rowsByVendor?.length) rowsByVendor = rowsByVendor.filter((r) => isHqItem(r))
      } catch {
        try {
          rowsByVendor = await runItemsQuery(vendorName, false)
          if (rowsByVendor?.length) rowsByVendor = rowsByVendor.filter((r) => isHqItem(r))
        } catch {
          rowsByVendor = []
        }
      }
    }
    if ((!rowsByVendor || rowsByVendor.length === 0) && vendorCode) {
      try {
        rowsByVendor = await runItemsQuery(vendorCode, false)
        if (rowsByVendor?.length) rowsByVendor = rowsByVendor.filter((r) => isHqItem(r))
      } catch {
        rowsByVendor = []
      }
    }
    for (const r of rowsByVendor || []) addRow(r)

    try {
      if (vendorCode) {
        const encVc = encodeURIComponent(vendorCode)
        const ivRows = (await supabaseSelectFilter(
          'item_vendors',
          `vendor_code=ilike.*${encVc}*`,
          { select: 'item_code', limit: 1000 }
        )) as { item_code?: string }[] | null
        const itemCodesFromMap = (ivRows || []).map((x) => String(x.item_code || '').trim()).filter(Boolean)
        if (itemCodesFromMap.length > 0) {
          for (const ic of itemCodesFromMap) {
            if (codeSet.has(ic)) continue
            try {
              let itemRows = (await supabaseSelectFilter(
                'items',
                `code=eq.${encodeURIComponent(ic)}&${hqFilter}`,
                { limit: 1, select: selectCols }
              )) as (ItemRow & { purchase_source?: string })[] | null
              if (itemRows?.length && !isHqItem(itemRows[0])) itemRows = []
              if ((!itemRows || itemRows.length === 0) && hqFilter) {
                itemRows = (await supabaseSelectFilter(
                  'items',
                  `code=eq.${encodeURIComponent(ic)}`,
                  { limit: 1, select: selectCols }
                )) as ItemRow[] | null
                if (itemRows?.length && !isHqItem(itemRows[0] as ItemRow & { purchase_source?: string })) itemRows = []
              }
              for (const r of itemRows || []) addRow(r)
            } catch {
              /* skip item */
            }
          }
        }
      }
      if (vendorName && vendorName.trim()) {
        const encVn = encodeURIComponent(vendorName.trim())
        const ivRowsByName = (await supabaseSelectFilter(
          'item_vendors',
          `vendor_code=ilike.*${encVn}*`,
          { select: 'item_code', limit: 1000 }
        )) as { item_code?: string }[] | null
        const codesByName = (ivRowsByName || []).map((x) => String(x.item_code || '').trim()).filter(Boolean)
        for (const ic of codesByName) {
          if (codeSet.has(ic)) continue
          try {
            let itemRows = (await supabaseSelectFilter(
              'items',
              `code=eq.${encodeURIComponent(ic)}&${hqFilter}`,
              { limit: 1, select: selectCols }
            )) as (ItemRow & { purchase_source?: string })[] | null
            if (itemRows?.length && !isHqItem(itemRows[0])) itemRows = []
            if ((!itemRows || itemRows.length === 0) && hqFilter) {
              itemRows = (await supabaseSelectFilter(
                'items',
                `code=eq.${encodeURIComponent(ic)}`,
                { limit: 1, select: selectCols }
              )) as ItemRow[] | null
              if (itemRows?.length && !isHqItem(itemRows[0] as ItemRow & { purchase_source?: string })) itemRows = []
            }
            for (const r of itemRows || []) addRow(r)
          } catch {
            /* skip item */
          }
        }
      }
    } catch (_) {
      // item_vendors 테이블 미존재 시 무시
    }

    let filtered = Array.from(rowsMap.values())
      .filter((r) => isHqItem(r as ItemRow & { purchase_source?: string }))
      .sort((a, b) => String(a.code || '').localeCompare(String(b.code || '')))
    if (outboundLocation || outboundLocationName) {
      const selectedParts = [outboundLocation, outboundLocationName]
      filtered = filtered.filter((r) =>
        itemOutboundMatchesSelection(String(r.outbound_location || ''), selectedParts)
      )
    }

    const list = filtered.map((row) => {
      const tax = String(row.tax || '').trim()
      const taxType = tax === '면세' ? 'exempt' : tax === '영세율' ? 'zero' : 'taxable'
      return {
        code: String(row.code || ''),
        name: String(row.name || ''),
        spec: String(row.spec || ''),
        price: Number(row.price) || 0,
        cost: Number(row.cost) || 0,
        category: String(row.category || ''),
        image: String(row.image || ''),
        outbound_location: String(row.outbound_location || ''),
        taxType,
      }
    })

    return NextResponse.json(list, { headers })
  } catch (e) {
    console.error('getItemsByVendor:', e)
    return NextResponse.json([], { headers })
  }
}

import { NextResponse } from 'next/server'
import { appendFileSync } from 'node:fs'
import { join } from 'node:path'
import { createClient } from '@supabase/supabase-js'

// #region agent log
const _log = (msg: string, data?: Record<string, unknown>) => {
  try {
    const logPath = join(process.cwd(), '..', 'debug-e3767f.log')
    appendFileSync(logPath, JSON.stringify({ sessionId: 'e3767f', location: 'getLoginData/route.ts', message: msg, data: data ?? {}, timestamp: Date.now() }) + '\n')
  } catch (_) {}
}
// #endregion

/** Supabase 응답이 느린 경우 5분 캐시로 반복 요청 부하 감소 */
let _loginDataCache: { data: { users: Record<string, string[]>; vendors: string[] }; until: number } | null = null
const CACHE_TTL_MS = 5 * 60 * 1000

function fetchWithTimeout(
  input: RequestInfo | URL,
  init?: RequestInit,
  timeoutMs = 15_000
): Promise<Response> {
  const controller = new AbortController()
  const t = setTimeout(() => controller.abort(), timeoutMs)
  return fetch(input, { ...init, signal: controller.signal }).finally(() => clearTimeout(t))
}

async function getLoginDataHandler(url: string, key: string) {
  const supabase = createClient(url, key, { global: { fetch: fetchWithTimeout } })
  const empRes = await supabase.from('employees').select('store,name').order('id', { ascending: true })
  if (empRes.error) throw new Error(empRes.error.message)
  const vendorRes = await supabase.from('vendors').select('name,gps_name,type').order('id', { ascending: true })
  if (vendorRes.error) throw new Error(vendorRes.error.message)
  const empList = empRes.data as { store?: string; name?: string }[] | null
  const vendorRows = vendorRes.data as { name?: string; gps_name?: string; type?: string }[] | null
  const userMap: Record<string, string[]> = {}
  for (let i = 0; i < (empList || []).length; i++) {
    const store = String((empList as { store?: string }[])[i].store || '').trim()
    const name = String((empList as { name?: string }[])[i].name || '').trim()
    if (store && name) {
      if (!userMap[store]) userMap[store] = []
      userMap[store].push(name)
    }
  }
  const vendorList: string[] = []
  const vRows = (vendorRows || []) as { name?: string; gps_name?: string; type?: string }[]
  for (let v = 0; v < vRows.length; v++) {
    const row = vRows[v]
    const gpsName = String(row.gps_name || '').trim()
    const fullName = String(row.name || '').trim()
    const t = String(row.type || '').toLowerCase()
    const isSales = t === 'sales' || t === '매출' || t === '매출처' || t === 'both' || t === '둘 다'
    const n = (isSales && gpsName) ? gpsName : fullName
    if (n) vendorList.push(n)
  }
  return { users: userMap, vendors: vendorList }
}

export async function GET() {
  // #region agent log
  _log('GET entry', { hypothesisId: 'H1' })
  // #endregion
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Access-Control-Allow-Methods', 'GET, OPTIONS')
  headers.set('Access-Control-Allow-Headers', 'Content-Type')

  const url = (process.env.SUPABASE_URL || '').trim()
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_ANON_KEY
  // #region agent log
  _log('env check', { hasUrl: !!url, hasKey: !!key, hypothesisId: 'H4' })
  // #endregion
  if (!url || !key) {
    const msg = 'SUPABASE_URL 및 SUPABASE_SERVICE_ROLE_KEY 또는 SUPABASE_ANON_KEY가 없습니다. .env를 확인하고 개발 서버를 재시작하세요.'
    console.error('getLoginData:', msg)
    return NextResponse.json(
      { users: {}, vendors: [], error: msg },
      { status: 503, headers }
    )
  }

  try {
    const now = Date.now()
    if (_loginDataCache && _loginDataCache.until > now) {
      // #region agent log
      _log('cache hit', { hypothesisId: 'H5' })
      // #endregion
      return NextResponse.json(_loginDataCache.data, { headers })
    }
    // #region agent log
    _log('before getLoginDataHandler', { hypothesisId: 'H2' })
    // #endregion
    const data = await getLoginDataHandler(url, key)
    _loginDataCache = { data, until: now + CACHE_TTL_MS }
    // #region agent log
    _log('getLoginDataHandler success', { userCount: Object.keys(data.users ?? {}).length, vendorCount: (data.vendors ?? []).length, hypothesisId: 'H5' })
    // #endregion
    return NextResponse.json(data, { headers })
  } catch (e) {
    const err = e instanceof Error ? e : new Error(String(e))
    const msg = err.message
    // #region agent log
    _log('getLoginDataHandler error', {
      message: msg,
      cause: err.cause ? String(err.cause) : undefined,
      causeCode: (err.cause as { code?: string })?.code,
      name: err.name,
      hypothesisId: 'H2',
    })
    // #endregion
    console.error('getLoginData:', e)
    return NextResponse.json(
      { users: {}, vendors: [], error: msg },
      { status: 503, headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter } from '@/lib/supabase-server'
import { ORDERS_MY_HISTORY_COLS } from '@/lib/postgrest-narrow-select'
import { getDirectSettlementMap } from '@/lib/direct-settlement-server'
import { parseListPagination, slicePage, DEFAULT_LIST_PAGE_SIZE } from '@/lib/pagination-params'

export interface OrderHistoryItem {
  id: number
  orderRowId: number
  date: string
  deliveryDate: string
  /** 출고지별 배송일 */
  deliveryDatesByOutbound?: Record<string, string>
  summary: string
  total: number
  status: string
  deliveryStatus: string
  items: { name?: string; qty?: number; price?: number; receivedQty?: number; originalQty?: number; code?: string; outboundLocation?: string; index?: number; isDirectSettlement?: boolean }[]
  receivedIndices?: number[]
  userName?: string
  userNick?: string
  rejectReason?: string
  /** 강제 출고(출고 입력에서 직접 입력) 여부 - 발주 없이 본사가 직접 출고한 건 */
  isForceOutbound?: boolean
}

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const store = String(searchParams.get('store') || '').trim()
  const startStr = String(searchParams.get('startStr') || searchParams.get('start') || '').trim()
  const endStr = String(searchParams.get('endStr') || searchParams.get('end') || '').trim()
  const { page, pageSize } = parseListPagination(searchParams, null, 20)

  if (!store || !startStr || !endStr) {
    return NextResponse.json(
      { items: [], total: 0, page: 1, pageSize: DEFAULT_LIST_PAGE_SIZE },
      { headers }
    )
  }

  try {
    const startD = new Date(startStr)
    startD.setHours(0, 0, 0, 0)
    const endD = new Date(endStr)
    endD.setHours(23, 59, 59, 999)

    const endIso = endStr + 'T23:59:59.999Z'
    const filter =
      `store_name=eq.${encodeURIComponent(store)}` +
      `&order_date=gte.${encodeURIComponent(startStr)}` +
      `&order_date=lte.${encodeURIComponent(endIso)}`
    const rows = (await supabaseSelectFilter('orders', filter, {
      order: 'order_date.desc',
      limit: 800,
      select: ORDERS_MY_HISTORY_COLS,
    })) as {
      id: number
      order_date?: string
      delivery_date?: string
      delivery_dates_by_outbound?: string
      cart_json?: string
      total?: number
      status?: string
      delivery_status?: string
      received_indices?: string
      received_qty_json?: string
      original_order_qty_json?: string
      user_name?: string
      reject_reason?: string
    }[]

    const itemMap: Record<string, string> = {}
    const priceMap: Record<string, number> = {}
    try {
      const itemRows = (await supabaseSelect('items', {
        select: 'code,outbound_location,price',
        limit: 5000,
      })) as { code?: string; outbound_location?: string; price?: number }[]
      for (const it of itemRows || []) {
        const c = String(it.code || '').trim()
        if (c) {
          itemMap[c] = String(it.outbound_location || '').trim() || '(미지정)'
          priceMap[c] = Number(it.price) || 0
        }
      }
    } catch {}

    const nameToNick: Record<string, string> = {}
    if (store) {
      try {
        const empFilter = `store=eq.${encodeURIComponent(store)}`
        const emps = (await supabaseSelectFilter('employees', empFilter, { select: 'name,nick', limit: 500 })) as { name?: string; nick?: string }[]
        for (const e of emps || []) {
          const n = String(e.name || '').trim()
          if (n) nameToNick[n] = String(e.nick || e.name || '').trim() || n
        }
      } catch {}
    }
    const list: OrderHistoryItem[] = (rows || []).map((o) => {
      let cart: { code?: string; name?: string; qty?: number; price?: number }[] = []
      try {
        cart = JSON.parse(o.cart_json || '[]')
      } catch {}
      let receivedIndices: number[] = []
      try {
        if (o.received_indices) receivedIndices = JSON.parse(o.received_indices)
      } catch {}
      let receivedQtyMap: Record<string, number> = {}
      try {
        if (o.received_qty_json) receivedQtyMap = JSON.parse(o.received_qty_json) || {}
      } catch {}
      let originalOrderQtyMap: Record<string, number> = {}
      try {
        if (o.original_order_qty_json) originalOrderQtyMap = JSON.parse(o.original_order_qty_json) || {}
      } catch {}
      const isFullReceived = o.delivery_status === '배송완료' || o.delivery_status === '배송 완료'
      const items = cart.map((it, idx) => {
        const origFromMap = originalOrderQtyMap[String(idx)]
        const recQty = receivedQtyMap[String(idx)] ?? receivedQtyMap[idx]
        const isReceived = receivedIndices.includes(idx) || isFullReceived
        const effectiveQty = isReceived && typeof recQty === 'number' ? recQty : Number(it.qty || 0)
        const code = String(it.code || '').trim()
        const outboundLocation = code ? (itemMap[code] || '(미지정)') : '(미지정)'
        return {
          ...it,
          code,
          index: idx,
          qty: Number(it.qty || 0),
          receivedQty: isReceived ? effectiveQty : undefined,
          originalQty: isReceived && origFromMap != null ? origFromMap : undefined,
          outboundLocation,
        }
      })
      const summary =
        cart.length > 0
          ? (cart[0].name || '') + (cart.length > 1 ? ` 외 ${cart.length - 1}건` : '')
          : 'Items'
      const orderDate = o.order_date ? new Date(o.order_date) : new Date()
      let deliveryDatesByOutbound: Record<string, string> | undefined
      try {
        const raw = o.delivery_dates_by_outbound
        if (raw && typeof raw === 'string') {
          const parsed = JSON.parse(raw) as Record<string, string>
          if (parsed && typeof parsed === 'object') deliveryDatesByOutbound = parsed
        }
      } catch {}
      return {
        id: o.id,
        orderRowId: o.id,
        date: orderDate.toISOString().slice(0, 10),
        deliveryDate: String(o.delivery_date || '').trim(),
        deliveryDatesByOutbound,
        summary,
        total: Number(o.total) || 0,
        status: o.status || 'Pending',
        deliveryStatus: (() => {
          const ds = o.delivery_status === '일부 배송 완료' ? '일부배송완료' : (o.delivery_status || '').trim()
          if (ds === '배송완료' || ds === '배송 완료' || ds === '일부배송완료') return ds
          if (o.received_indices) {
            const recIdx = Array.isArray(receivedIndices) ? receivedIndices : []
            return recIdx.length >= cart.length ? '배송완료' : '일부배송완료'
          }
          return o.status === 'Approved' ? '배송중' : ''
        })(),
        items,
        receivedIndices,
        userName: String(o.user_name || '').trim() || undefined,
        userNick: nameToNick[String(o.user_name || '').trim()] || undefined,
        rejectReason: String(o.reject_reason || '').trim() || undefined,
      }
    })

    // 강제 출고(ForcePush) 병합: 출고 입력에서 직접 입력한 건 - stock_logs
    try {
      const fpFilter =
        `location=eq.${encodeURIComponent(store)}` +
        `&log_type=eq.ForcePush`
      const forcePushRows = (await supabaseSelectFilter('stock_logs', fpFilter, {
        order: 'log_date.desc',
        limit: 400,
        select: 'log_date,item_code,item_name,qty,delivery_status',
      })) as {
        log_date?: string
        item_code?: string
        item_name?: string
        qty?: number
        delivery_status?: string
      }[]

      const groups = new Map<string, typeof forcePushRows>()
      for (const row of forcePushRows || []) {
        const rowDate = new Date(row.log_date || '')
        if (isNaN(rowDate.getTime()) || rowDate < startD || rowDate > endD) continue
        const key = rowDate.toISOString() + '\t' + (row.delivery_status || '')
        if (!groups.has(key)) groups.set(key, [])
        groups.get(key)!.push(row)
      }

      for (const [, batch] of groups) {
        const first = batch[0]
        const rowDate = new Date(first.log_date || '')
        const items = batch.map((r, idx) => {
          const code = String(r.item_code || '').trim()
          const qty = Math.abs(Number(r.qty) || 0)
          const price = priceMap[code] ?? 0
          return {
            name: String(r.item_name || '').trim(),
            code,
            qty,
            price,
            receivedQty: qty,
            outboundLocation: code ? (itemMap[code] || '(미지정)') : '(미지정)',
            index: idx,
          }
        })
        const total = items.reduce((s, i) => s + (i.price ?? 0) * (i.qty ?? 0), 0)
        const summary =
          items.length > 0
            ? (items[0].name || '') + (items.length > 1 ? ` 외 ${items.length - 1}건` : '')
            : '강제출고'
        const deliveryDate =
          first.delivery_status && /^\d{4}-\d{2}-\d{2}/.test(String(first.delivery_status))
            ? String(first.delivery_status).slice(0, 10)
            : rowDate.toISOString().slice(0, 10)

        list.push({
          id: -Math.abs(rowDate.getTime()),
          orderRowId: 0,
          date: rowDate.toISOString().slice(0, 10),
          deliveryDate,
          summary,
          total,
          status: 'Approved',
          deliveryStatus: '배송완료',
          items,
          receivedIndices: items.map((_, i) => i),
          isForceOutbound: true,
        })
      }
    } catch (fpErr) {
      console.error('getMyOrderHistory ForcePush merge:', fpErr)
    }

    list.sort((a, b) => {
      const da = new Date(a.date + 'T' + (a.deliveryDate || '00:00:00'))
      const db = new Date(b.date + 'T' + (b.deliveryDate || '00:00:00'))
      return db.getTime() - da.getTime()
    })

    const total = list.length
    const items = slicePage(list, page, pageSize)
    return NextResponse.json({ items, total, page, pageSize }, { headers })
  } catch (e) {
    console.error('getMyOrderHistory:', e)
    return NextResponse.json(
      { items: [], total: 0, page, pageSize },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
