/** POS 메뉴 옵션 목록 조회 (menu_id별 필터 가능) */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const menuId = searchParams.get('menuId')?.trim()

  try {
    const selectCols =
      'id,menu_id,name,price_modifier,price_modifier_delivery,price_modifier_packaging,sort_order,option_type,item_code,additive_source_menu_id,quantity,option_step_values,sell_hall,sell_delivery,sell_packaging'
    const colsWithoutSellAndStep =
      'id,menu_id,name,price_modifier,price_modifier_delivery,price_modifier_packaging,sort_order,option_type,item_code,additive_source_menu_id,quantity'
    const colsBaseWithDelivery = 'id,menu_id,name,price_modifier,price_modifier_delivery,price_modifier_packaging,sort_order'
    const colsBaseWithDeliveryOnly = 'id,menu_id,name,price_modifier,price_modifier_delivery,sort_order'
    const minimalCols = 'id,menu_id,name,price_modifier,sort_order'
    let rows: { id?: number; menu_id?: number; name?: string; price_modifier?: number; price_modifier_delivery?: number | null; price_modifier_packaging?: number | null; sort_order?: number; option_type?: string; item_code?: string | null; additive_source_menu_id?: number | null; quantity?: number; option_step_values?: Record<string, string> | null; sell_hall?: boolean; sell_delivery?: boolean; sell_packaging?: boolean }[] | null = null

    const doSelect = async (cols: string) => {
      if (menuId) {
        return (await supabaseSelectFilter('pos_menu_options', `menu_id=eq.${encodeURIComponent(menuId)}`, { order: 'sort_order.asc,name.asc', limit: 200, select: cols })) as typeof rows
      }
      return (await supabaseSelectAllPages('pos_menu_options', {
        order: 'menu_id.asc,sort_order.asc,name.asc',
        pageSize: 3000,
        select: cols,
      })) as typeof rows
    }

    const selectColsLegacy =
      'id,menu_id,name,price_modifier,price_modifier_delivery,price_modifier_packaging,sort_order,option_type,item_code,quantity,option_step_values,sell_hall,sell_delivery,sell_packaging'
    const colsWithoutSellAndStepLegacy =
      'id,menu_id,name,price_modifier,price_modifier_delivery,price_modifier_packaging,sort_order,option_type,item_code,quantity'

    try {
      rows = await doSelect(selectCols)
    } catch {
      try {
        rows = await doSelect(selectColsLegacy)
      } catch {
        try {
          rows = await doSelect(colsWithoutSellAndStep)
        } catch {
          try {
            rows = await doSelect(colsWithoutSellAndStepLegacy)
          } catch {
            try {
              rows = await doSelect(colsBaseWithDelivery)
            } catch {
              try {
                rows = await doSelect(colsBaseWithDeliveryOnly)
              } catch {
                rows = await doSelect(minimalCols)
              }
            }
          }
        }
      }
    }

    const list = (rows || []).map((row) => {
      const stepValues = row.option_step_values
      const sv = stepValues && typeof stepValues === 'object' && !Array.isArray(stepValues) ? stepValues as Record<string, string> : null
      return {
        id: String(row.id ?? ''),
        menuId: String(row.menu_id ?? ''),
        name: String(row.name ?? ''),
        priceModifier: Number(row.price_modifier) ?? 0,
        priceModifierDelivery: row.price_modifier_delivery != null ? Number(row.price_modifier_delivery) : null,
        priceModifierPackaging: row.price_modifier_packaging != null ? Number(row.price_modifier_packaging) : null,
        sortOrder: Number(row.sort_order) ?? 0,
        optionType: (row.option_type || 'substitution') as 'substitution' | 'additive',
        itemCode: row.item_code ? String(row.item_code).trim() : null,
        additiveSourceMenuId:
          row.additive_source_menu_id != null && Number.isFinite(Number(row.additive_source_menu_id))
            ? Number(row.additive_source_menu_id)
            : null,
        quantity: Number(row.quantity) ?? 1,
        optionStepValues: sv || null,
        sellHall: row.sell_hall != null ? !!row.sell_hall : true,
        sellDelivery: row.sell_delivery != null ? !!row.sell_delivery : true,
        sellPackaging: row.sell_packaging != null ? !!row.sell_packaging : true,
      }
    })

    return NextResponse.json(list, { headers })
  } catch (e) {
    console.error('getPosMenuOptions:', e)
    return NextResponse.json([], { headers })
  }
}

/**
 * 미수금 - 출고건(주문) 단위 목록
 * - receivable_transactions (ref_type=Order) + orders 조인
 * - 매장별 주문, 금액, 수령상태(Paid/Wait to pay)
 */
import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseSelect } from '@/lib/supabase-server'

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const storeFilter = String(searchParams.get('storeFilter') || searchParams.get('store') || '').trim()
  const startStr = String(searchParams.get('startStr') || '').trim().slice(0, 10)
  const endStr = String(searchParams.get('endStr') || '').trim().slice(0, 10)
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = String(searchParams.get('userRole') || '').toLowerCase()

  const isManager = userRole.includes('manager') || userRole.includes('franchisee')
  const effectiveStore = isManager && userStore ? userStore : storeFilter

  try {
    let recFilter = `ref_type=eq.Order&ref_id=not.is.null`
    if (effectiveStore) recFilter += `&store_name=ilike.${encodeURIComponent(effectiveStore)}`
    if (startStr) recFilter += `&trans_date=gte.${startStr}`
    if (endStr) recFilter += `&trans_date=lte.${endStr}`

    const recRows = (await supabaseSelectFilter('receivable_transactions', recFilter, {
      select: 'id,store_name,amount,ref_id,trans_date,memo',
      order: 'trans_date.desc',
      limit: 10000,
    })) as { id?: number; store_name?: string; amount?: number; ref_id?: number; trans_date?: string; memo?: string }[]

    if (!recRows?.length) {
      return NextResponse.json({ type: 'receivable_orders', list: [], storeBalances: {} }, { headers })
    }

    const orderIds = [...new Set((recRows || []).map((r) => r.ref_id).filter((id): id is number => id != null))]
    if (orderIds.length === 0) {
      return NextResponse.json({ type: 'receivable_orders', list: [], storeBalances: {} }, { headers })
    }

    const orders = (await supabaseSelectFilter('orders', `id=in.(${orderIds.join(',')})`, {
      select: 'id,order_date,delivery_date,store_name,total,status,delivery_status',
      limit: 10000,
    })) as { id?: number; order_date?: string; delivery_date?: string; store_name?: string; total?: number; status?: string; delivery_status?: string }[]

    const orderMap = new Map<number, (typeof orders)[0]>()
    for (const o of orders || []) {
      if (o.id != null) orderMap.set(o.id, o)
    }

    const list = (recRows || []).map((r) => {
      const order = r.ref_id != null ? orderMap.get(r.ref_id) : null
      const amount = Number(r.amount ?? 0)
      return {
        id: r.id,
        orderId: r.ref_id,
        storeName: r.store_name ?? order?.store_name ?? '',
        amount,
        transDate: r.trans_date ?? '',
        orderDate: order?.order_date ? String(order.order_date).slice(0, 10) : '',
        deliveryDate: order?.delivery_date ?? '',
        total: Number(order?.total ?? 0),
        status: order?.delivery_status ?? order?.status ?? '',
        memo: r.memo ?? '',
      }
    })

    const storeBalances: Record<string, number> = {}
    const storeFilterForBalance = effectiveStore ? `store_name=ilike.${encodeURIComponent(effectiveStore)}` : 'id=gt.0'
    const allRec = (await supabaseSelectFilter('receivable_transactions', storeFilterForBalance, {
      select: 'store_name,amount',
      limit: 20000,
    })) as { store_name?: string; amount?: number }[]
    for (const r of allRec || []) {
      const sn = String(r.store_name ?? '').trim()
      if (!sn) continue
      storeBalances[sn] = (storeBalances[sn] ?? 0) + Number(r.amount ?? 0)
    }

    return NextResponse.json({ type: 'receivable_orders', list, storeBalances }, { headers })
  } catch (e) {
    console.error('getReceivableOrders:', e)
    return NextResponse.json(
      { type: 'receivable_orders', list: [], storeBalances: {}, error: String(e) },
      { status: 500, headers }
    )
  }
}

/**
 * 미수금/미지급금 목록 조회
 * - type: receivable | payable
 * - storeFilter / vendorFilter (선택)
 * - startStr, endStr (trans_date 범위)
 * - receivable: store_name으로 vendors 매칭 → vendorCode, vendorName 포함
 */
import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseSelect } from '@/lib/supabase-server'

async function getStoreToVendorMap(): Promise<Map<string, { code: string; name: string }>> {
  const vendors = (await supabaseSelect('vendors', {
    select: 'code,name,gps_name',
    limit: 5000,
  })) as { code?: string; name?: string; gps_name?: string }[] | null
  const map = new Map<string, { code: string; name: string }>()
  for (const v of vendors || []) {
    const code = String(v.code || '').trim()
    const name = String(v.name || '').trim() || code
    const gpsName = String(v.gps_name || '').trim()
    if (!code) continue
    const entry = { code, name }
    if (gpsName) map.set(gpsName, entry)
    if (name && !map.has(name)) map.set(name, entry)
    if (gpsName && gpsName.startsWith('CM ')) map.set(gpsName.slice(3).trim(), entry)
    if (gpsName && !gpsName.startsWith('CM ')) map.set('CM ' + gpsName, entry)
  }
  return map
}

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const type = String(searchParams.get('type') || 'receivable').trim().toLowerCase()
  let storeFilter = String(searchParams.get('storeFilter') || searchParams.get('store') || '').trim()
  const vendorFilter = searchParams.get('vendorFilter') || searchParams.get('vendor') || ''
  const startStr = String(searchParams.get('startStr') || searchParams.get('start') || '').trim().slice(0, 10)
  const endStr = String(searchParams.get('endStr') || searchParams.get('end') || '').trim().slice(0, 10)
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = String(searchParams.get('userRole') || '').toLowerCase()

  // 본사/회계직원: 매장별 선택 가능. 매니저/가맹점주: receivable만 자기 매장, payable 조회 불가
  const canSelectStores = ['director', 'ceo', 'hr', 'officer'].some((r) => userRole.includes(r))
    || userRole.includes('accounting')
    || userRole.includes('회계')
  const isManager = (userRole.includes('manager') || userRole.includes('franchisee')) && !canSelectStores
  if (type === 'receivable' && isManager && userStore) {
    storeFilter = userStore
  }
  if (type === 'payable' && isManager) {
    return NextResponse.json({ type: 'payable', list: [] }, { headers })
  }

  try {
    if (type === 'payable') {
      const parts: string[] = []
      if (vendorFilter) parts.push(`vendor_code=ilike.${encodeURIComponent(vendorFilter)}`)
      // 잔액/누적 조회 기준: endStr(조회 종료일)까지 누적
      if (endStr) parts.push(`trans_date=lte.${endStr}`)
      const filter = parts.length ? parts.join('&') : 'id=gt.0'
      let rows = (await supabaseSelectFilter(
        'payable_transactions',
        filter,
        { order: 'trans_date.desc', limit: 20000 }
      )) as { id?: number; vendor_code?: string; amount?: number; ref_type?: string; ref_id?: number; trans_date?: string; memo?: string; created_at?: string; bank_transaction_id?: number | null }[]

      // 매장별 필터: 입고(Inbound) 건은 inbound_batches.location으로 필터
      if (storeFilter && (rows || []).length > 0) {
        const inboundIds = (rows || [])
          .filter((r) => r.ref_type === 'Inbound' && r.ref_id != null)
          .map((r) => Number(r.ref_id))
        let batchIdsForStore: number[] = []
        if (inboundIds.length > 0) {
          const batches = (await supabaseSelectFilter(
            'inbound_batches',
            `id=in.(${inboundIds.join(',')})`,
            { select: 'id,location', limit: 10000 }
          )) as { id?: number; location?: string }[] | null
          const storeNorm = storeFilter.trim().toLowerCase()
          batchIdsForStore = (batches || [])
            .filter((b) => {
              const loc = String(b.location || '').trim().toLowerCase()
              return loc === storeNorm || loc.includes(storeNorm) || storeNorm.includes(loc)
            })
            .map((b) => Number(b.id)).filter((id) => !isNaN(id))
        }
        const batchIdSet = new Set(batchIdsForStore)
        rows = (rows || []).filter((r) => {
          if (r.ref_type === 'Inbound' && r.ref_id != null) {
            return batchIdSet.has(Number(r.ref_id))
          }
          // PO, Payment, Opening 등: 매장 정보 없으면 전체 포함 (본사/공통)
          return true
        })
      }

      // 인보이스 여부: Inbound→inbound_batches, PO→purchase_orders, bank_transaction_id→bank_transactions (마이그레이션 미적용 시 스킵)
      const invoiceByInbound: Record<number, { invoice_received?: boolean; invoice_no?: string | null }> = {}
      const invoiceByPo: Record<number, { invoice_received?: boolean; invoice_no?: string | null }> = {}
      const invoiceByBank: Record<number, { invoice_received?: boolean; invoice_no?: string | null }> = {}

      try {
        const inboundIds = [...new Set((rows || []).filter((r) => r.ref_type === 'Inbound' && r.ref_id).map((r) => Number(r.ref_id!)))]
        const poIds = [...new Set((rows || []).filter((r) => r.ref_type === 'PO' && r.ref_id).map((r) => Number(r.ref_id!)))]
        const bankIds = [...new Set((rows || []).filter((r) => r.bank_transaction_id).map((r) => Number(r.bank_transaction_id!)))]

        if (inboundIds.length > 0) {
          const batches = (await supabaseSelectFilter('inbound_batches', `id=in.(${inboundIds.join(',')})`, {
            limit: 5000,
          })) as { id?: number; invoice_received?: boolean; invoice_no?: string | null }[] | null
          for (const b of batches || []) {
            if (b.id) invoiceByInbound[b.id] = { invoice_received: Boolean(b.invoice_received), invoice_no: b.invoice_no }
          }
        }
        if (poIds.length > 0) {
          const pos = (await supabaseSelectFilter('purchase_orders', `id=in.(${poIds.join(',')})`, {
            limit: 5000,
          })) as { id?: number; invoice_received?: boolean; invoice_no?: string | null }[] | null
          for (const p of pos || []) {
            if (p.id) invoiceByPo[p.id] = { invoice_received: Boolean(p.invoice_received), invoice_no: p.invoice_no }
          }
        }
        if (bankIds.length > 0) {
          const banks = (await supabaseSelectFilter('bank_transactions', `id=in.(${bankIds.join(',')})`, {
            limit: 5000,
          })) as { id?: number; invoice_received?: boolean; invoice_no?: string | null }[] | null
          for (const bt of banks || []) {
            if (bt.id) invoiceByBank[bt.id] = { invoice_received: Boolean(bt.invoice_received), invoice_no: bt.invoice_no }
          }
        }
      } catch (_inv) {
        // invoice 컬럼 미존재 등 시 인보이스 정보 없이 진행
      }

      const rowsWithInvoice = (rows || []).map((r) => {
        const base = { ...r }
        if (r.ref_type === 'Inbound' && r.ref_id) {
          const inv = invoiceByInbound[Number(r.ref_id)]
          if (inv) {
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_received = inv.invoice_received
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_no = inv.invoice_no
          }
        } else if (r.ref_type === 'PO' && r.ref_id) {
          const inv = invoiceByPo[Number(r.ref_id)]
          if (inv) {
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_received = inv.invoice_received
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_no = inv.invoice_no
          }
        } else if (r.bank_transaction_id) {
          const inv = invoiceByBank[Number(r.bank_transaction_id)]
          if (inv) {
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_received = inv.invoice_received
            ;(base as { invoice_received?: boolean; invoice_no?: string | null }).invoice_no = inv.invoice_no
          }
        }
        return base
      })

      const byVendor: Record<string, { total: number; items: typeof rowsWithInvoice }> = {}
      for (const r of rowsWithInvoice) {
        const vc = String(r.vendor_code || '').trim()
        if (!vc) continue
        if (!byVendor[vc]) byVendor[vc] = { total: 0, items: [] }
        byVendor[vc].items.push(r)
        byVendor[vc].total += Number(r.amount ?? 0)
      }

      const list = Object.entries(byVendor).map(([vendorCode, v]) => ({
        vendorCode,
        balance: v.total,
        items: v.items.sort((a, b) => (String(b.trans_date || '').localeCompare(String(a.trans_date || '')))),
      }))

      return NextResponse.json({ type: 'payable', list }, { headers })
    }

    // receivable
    const parts: string[] = []
    if (storeFilter) parts.push(`store_name=ilike.${encodeURIComponent(storeFilter)}`)
    // 잔액/누적 조회 기준: endStr(조회 종료일)까지 누적
    if (endStr) parts.push(`trans_date=lte.${endStr}`)
    const filter = parts.length ? parts.join('&') : 'id=gt.0'
    const rows = (await supabaseSelectFilter(
      'receivable_transactions',
      filter,
      { order: 'trans_date.desc', limit: 20000 }
    )) as {
      id?: number
      store_name?: string
      amount?: number
      ref_type?: string
      ref_id?: number
      trans_date?: string
      memo?: string
      invoice_no?: string
      created_at?: string
      receive_checked?: boolean
    }[]

    const byStore: Record<string, { total: number; items: typeof rows }> = {}
    for (const r of rows || []) {
      const sn = String(r.store_name || '').trim()
      if (!sn) continue
      if (!byStore[sn]) byStore[sn] = { total: 0, items: [] }
      byStore[sn].items.push(r)
      byStore[sn].total += Number(r.amount ?? 0)
    }

    const storeToVendor = await getStoreToVendorMap()
    const list = Object.entries(byStore).map(([storeName, v]) => {
      const vendor = storeToVendor.get(storeName)
      return {
        storeName,
        vendorCode: vendor?.code,
        vendorName: vendor?.name,
        balance: v.total,
        items: v.items.sort((a, b) => (String(b.trans_date || '').localeCompare(String(a.trans_date || '')))),
      }
    })

    return NextResponse.json({ type: 'receivable', list }, { headers })
  } catch (e) {
    console.error('getReceivablePayableList:', e)
    return NextResponse.json(
      { error: e instanceof Error ? e.message : 'Failed' },
      { status: 500, headers }
    )
  }
}

/**
 * 미수금/미지급금 잔액 요약
 * - type: receivable | payable
 * - DB RPC로 집계 (limit 없음, store/vendor별 1행만 반환)
 * - receivable: store_name으로 vendors 매칭(gps_name/name) → vendorCode, vendorName 포함
 */
import { NextRequest, NextResponse } from 'next/server'
import { supabaseRpc, supabaseSelectFilter, supabaseSelect } from '@/lib/supabase-server'

async function getStoreToVendorMap(): Promise<Map<string, { code: string; name: string }>> {
  const vendors = (await supabaseSelect('vendors', {
    select: 'code,name,gps_name',
    limit: 10000,
  })) as { code?: string; name?: string; gps_name?: string }[] | null
  const map = new Map<string, { code: string; name: string }>()
  for (const v of vendors || []) {
    const code = String(v.code || '').trim()
    const name = String(v.name || '').trim() || code
    const gpsName = String(v.gps_name || '').trim()
    if (!code) continue
    const entry = { code, name }
    if (gpsName) map.set(gpsName, entry)
    if (name && !map.has(name)) map.set(name, entry)
    if (gpsName && gpsName.startsWith('CM ')) map.set(gpsName.slice(3).trim(), entry)
    if (gpsName && !gpsName.startsWith('CM ')) map.set('CM ' + gpsName, entry)
  }
  return map
}

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const type = String(searchParams.get('type') || 'receivable').trim().toLowerCase()
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = String(searchParams.get('userRole') || '').toLowerCase()
  const endStr = String(searchParams.get('endStr') || searchParams.get('end') || '').trim().slice(0, 10)
  const storeFilter = String(searchParams.get('storeFilter') || searchParams.get('store') || '').trim()
  const vendorFilter = String(searchParams.get('vendorFilter') || searchParams.get('vendor') || '').trim()

  const canSelectStores = ['director', 'ceo', 'hr', 'officer'].some((r) => userRole.includes(r))
    || userRole.includes('accounting')
    || userRole.includes('회계')
  const isManager = (userRole.includes('manager') || userRole.includes('franchisee')) && !canSelectStores
  if (type === 'payable' && isManager) {
    return NextResponse.json({ type: 'payable', list: [] }, { headers })
  }

  try {
    if (type === 'payable') {
      const rows = (await supabaseRpc<{ vendor_code: string; balance: number; item_count: number }[]>(
        'get_payable_summary',
        {
          p_vendor_filter: vendorFilter || null,
          p_end_str: endStr || null,
        }
      )) as { vendor_code?: string; balance?: number; item_count?: number }[] | null

      const list = (rows || [])
        .map((r) => ({
          vendorCode: String(r.vendor_code ?? '').trim(),
          balance: Number(r.balance ?? 0),
          count: Number(r.item_count ?? 0),
        }))
        .filter((x) => x.vendorCode)
        .sort((a, b) => b.balance - a.balance)
      const totalAmount = list.reduce((sum, i) => sum + (i.balance ?? 0), 0)
      return NextResponse.json({ type: 'payable', list, totalAmount }, { headers })
    }

    // receivable
    const storeFilterVal = isManager && userStore ? userStore : storeFilter
    const rows = (await supabaseRpc<{ store_name: string; balance: number; item_count: number }[]>(
      'get_receivable_summary',
      {
        p_store_filter: storeFilterVal || null,
        p_end_str: endStr || null,
      }
    )) as { store_name?: string; balance?: number; item_count?: number }[] | null

    const storeToVendor = await getStoreToVendorMap()
    const list = (rows || [])
      .map((r) => {
        const storeName = String(r.store_name ?? '').trim()
        const vendor = storeToVendor.get(storeName)
        return {
          storeName,
          vendorCode: vendor?.code,
          vendorName: vendor?.name,
          balance: Number(r.balance ?? 0),
          count: Number(r.item_count ?? 0),
        }
      })
      .filter((x) => x.storeName)
      .sort((a, b) => b.balance - a.balance)
    const totalAmount = list.reduce((sum, i) => sum + (i.balance ?? 0), 0)
    return NextResponse.json({ type: 'receivable', list, totalAmount }, { headers })
  } catch (rpcErr) {
    try {
      // RPC 미배포 시 fallback: 기존 select + JS 집계
      const pParts: string[] = []
      if (vendorFilter) pParts.push(`vendor_code=ilike.${encodeURIComponent(vendorFilter)}`)
      if (endStr) pParts.push(`trans_date=lte.${endStr}`)
      const pFilter = pParts.length ? pParts.join('&') : 'id=gt.0'

      const rParts: string[] = []
      if (isManager && userStore) rParts.push(`store_name=ilike.${encodeURIComponent(userStore)}`)
      else if (storeFilter) rParts.push(`store_name=ilike.${encodeURIComponent(storeFilter)}`)
      if (endStr) rParts.push(`trans_date=lte.${endStr}`)
      const rFilter = rParts.length ? rParts.join('&') : 'id=gt.0'

      const rows =
        type === 'payable'
          ? ((await supabaseSelectFilter('payable_transactions', pFilter, {
              order: 'trans_date.desc',
              limit: 20000,
            })) as { vendor_code?: string; amount?: number }[])
          : ((await supabaseSelectFilter('receivable_transactions', rFilter, {
              order: 'trans_date.desc',
              limit: 20000,
            })) as { store_name?: string; amount?: number }[])

      if (type === 'payable') {
        const byVendor: Record<string, { balance: number; count: number }> = {}
        const payableRows = (rows || []) as { vendor_code?: string; amount?: number }[]
        for (const r of payableRows) {
          const vc = String(r.vendor_code || '').trim()
          if (!vc) continue
          if (!byVendor[vc]) byVendor[vc] = { balance: 0, count: 0 }
          byVendor[vc].balance += Number(r.amount ?? 0)
          byVendor[vc].count += 1
        }
        const list = Object.entries(byVendor)
          .map(([vendorCode, v]) => ({ vendorCode, balance: v.balance, count: v.count }))
          .sort((a, b) => b.balance - a.balance)
        const totalAmount = list.reduce((sum, i) => sum + (i.balance ?? 0), 0)
        return NextResponse.json({ type: 'payable', list, totalAmount }, { headers })
      }

      const byStore: Record<string, { balance: number; count: number }> = {}
      const receivableRows = (rows || []) as { store_name?: string; amount?: number }[]
      for (const r of receivableRows) {
        const sn = String(r.store_name || '').trim()
        if (!sn) continue
        if (!byStore[sn]) byStore[sn] = { balance: 0, count: 0 }
        byStore[sn].balance += Number(r.amount ?? 0)
        byStore[sn].count += 1
      }
      const storeToVendor = await getStoreToVendorMap()
      const list = Object.entries(byStore)
        .map(([storeName, v]) => {
          const vendor = storeToVendor.get(storeName)
          return {
            storeName,
            vendorCode: vendor?.code,
            vendorName: vendor?.name,
            balance: v.balance,
            count: v.count,
          }
        })
        .sort((a, b) => b.balance - a.balance)
      const totalAmount = list.reduce((sum, i) => sum + (i.balance ?? 0), 0)
      return NextResponse.json({ type: 'receivable', list, totalAmount }, { headers })
    } catch (e) {
      console.error('getReceivablePayableSummary:', e)
      return NextResponse.json(
        { error: e instanceof Error ? e.message : 'Failed' },
        { status: 500, headers }
      )
    }
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseSelect } from '@/lib/supabase-server'
import { NOTICE_LIST_COLS } from '@/lib/postgrest-narrow-select'
import { parseListPagination, slicePage, DEFAULT_LIST_PAGE_SIZE } from '@/lib/pagination-params'

const SENT_NOTICES_DB_LIMIT = 400

function toDateStr(val: string | Date | null | undefined): string {
  if (!val) return ''
  if (typeof val === 'string') return val.slice(0, 16).replace('T', ' ')
  const d = new Date(val)
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 16).replace('T', ' ')
}

/** 발송한 공지 목록 (sender 기준, 날짜 필터) - readCount/totalCount 포함 */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  const { searchParams } = new URL(request.url)
  const sender = String(searchParams.get('sender') || '').trim()
  const startStr = String(searchParams.get('startDate') || searchParams.get('start') || '').trim()
  const endStr = String(searchParams.get('endDate') || searchParams.get('end') || '').trim()
  const userStore = String(searchParams.get('userStore') || '').trim()
  const userRole = (searchParams.get('userRole') || '').toLowerCase()
  const searchType = String(searchParams.get('searchType') || 'all').toLowerCase() as 'all' | 'notice' | 'order'
  const keyword = String(searchParams.get('keyword') || searchParams.get('q') || '').trim().toLowerCase()
  const { page, pageSize } = parseListPagination(searchParams, null, 15)

  const isAllSenders = sender === '' || sender.toLowerCase() === 'all' || sender === '전체'

  /** 물류관리 관련 (주문승인/반려/보류/강제출고/발주/입고/재고/배송/매장 수령 완료 등) 공지 여부 (admin-notice-history와 동일) */
  const isOrderRelated = (title: string, content: string) => {
    const t = (title || '').toLowerCase()
    const c = (content || '').toLowerCase()
    const text = t + ' ' + c
    if (/주문.*(승인|반려|보류)/.test(t) || /주문\s*#\d+/.test(t)) return true
    if (/강제|출고|발주|입고|재고|배송|물류|수령/.test(text)) return true
    if (/주문.*확인|승인.*화면/.test(c)) return true
    return false
  }

  try {
    let filter = isAllSenders ? '' : `sender=ilike.${encodeURIComponent(sender)}`
    if (startStr) filter += (filter ? '&' : '') + `created_at=gte.${startStr}`
    if (endStr) {
      const endPlus = endStr + 'T23:59:59'
      filter += (filter ? '&' : '') + `created_at=lte.${endPlus}`
    }
    const effectiveFilter = filter || 'id=gte.0'

    const rows = (await supabaseSelectFilter('notices', effectiveFilter, {
      order: 'created_at.desc',
      limit: SENT_NOTICES_DB_LIMIT,
      select: NOTICE_LIST_COLS,
    })) as {
      id: number
      sender?: string
      title?: string
      content?: string
      target_store?: string
      target_role?: string
      target_recipients?: string | null
      created_at?: string
    }[]

    const empList = (await supabaseSelect('employees', { order: 'id.asc', select: 'store,name,job,role,resign_date' })) as {
      store?: string
      name?: string
      job?: string
      role?: string
      resign_date?: string
    }[] || []

    const noticeIds = (rows || []).map((r) => r.id)
    const readCountByNotice: Record<number, number> = {}
    if (noticeIds.length > 0) {
      const allReadRows = (await supabaseSelectFilter(
        'notice_reads',
        `notice_id=in.(${noticeIds.join(',')})`,
        { limit: 5000, select: 'notice_id' }
      )) as { notice_id: number }[] || []
      for (const r of allReadRows) {
        readCountByNotice[r.notice_id] = (readCountByNotice[r.notice_id] || 0) + 1
      }
    }

    const list: {
      id: string
      sender: string
      title: string
      date: string
      recipients: string[]
      preview: string
      content: string
      readCount: number
      totalCount: number
    }[] = []

    for (const row of rows || []) {
      // searchType 필터: 물류관리/공지사항
      if (searchType === 'order') {
        if (!isOrderRelated(row.title || '', row.content || '')) continue
      } else if (searchType === 'notice') {
        if (isOrderRelated(row.title || '', row.content || '')) continue
      }

      const targetStores = String(row.target_store || '전체').trim()
      const targetRoles = String(row.target_role || '전체').trim()
      let targetRecipientsList: string[] = []
      try {
        const raw = row.target_recipients
        if (raw && typeof raw === 'string') {
          const parsed = JSON.parse(raw) as unknown
          if (Array.isArray(parsed) && parsed.length > 0) {
            targetRecipientsList = parsed.filter((x): x is string => typeof x === 'string')
          }
        }
      } catch {
        /* ignore */
      }

      const isSpecificRecipients = targetRecipientsList.length > 0
      let totalCount = 0
      const recipientSet = new Set<string>()

      if (isSpecificRecipients) {
        totalCount = targetRecipientsList.length
        targetRecipientsList.forEach((s) => {
          const [store] = s.split('|')
          if (store?.trim()) recipientSet.add(store.trim())
        })
      } else {
        const isAllStores = targetStores === '전체' || targetStores.trim() === ''
        const isAllRoles = targetRoles === '전체' || targetRoles.trim() === ''
        const roleList = isAllRoles
          ? []
          : targetRoles
              .split(',')
              .map((s) => s.trim().toLowerCase())
              .filter(Boolean)
        for (const e of empList) {
          const eStore = String(e.store || '').trim()
          const eName = String(e.name || '').trim()
          const resignDate = String(e.resign_date || '').trim()
          if (!eName || (resignDate && resignDate !== '')) continue
          if (!eStore || eStore === '매장명' || eStore === 'Store') continue
          const eRole = (String(e.job || e.role || '').trim() || 'Staff').toLowerCase()
          const storeMatch = isAllStores || targetStores.split(',').map((s) => s.trim()).includes(eStore)
          const roleMatch = isAllRoles || roleList.length === 0 || roleList.some((r) => eRole === r || eRole.indexOf(r) >= 0 || r.indexOf(eRole) >= 0)
          if (storeMatch && roleMatch) {
            totalCount += 1
            recipientSet.add(eStore)
          }
        }
      }

      const readCount = readCountByNotice[row.id] || 0

      let recipients: string[]
      if (isSpecificRecipients) {
        recipients = recipientSet.size > 0 ? Array.from(recipientSet).sort() : [`${totalCount}명`]
      } else if (targetStores === '전체' || targetStores.trim() === '') {
        recipients = ['전체']
      } else {
        recipients = Array.from(recipientSet).sort()
        if (recipients.length === 0) {
          recipients = targetStores.split(',').map((s) => s.trim()).filter(Boolean)
        }
        if (recipients.length === 0) recipients = ['전체']
      }

      list.push({
        id: String(row.id),
        sender: String(row.sender || '').trim(),
        title: row.title || '',
        date: toDateStr(row.created_at),
        recipients,
        preview: (row.content || '').slice(0, 100),
        content: row.content || '',
        readCount,
        totalCount,
      })
    }

    let filtered = list
    if (keyword) {
      filtered = list.filter((n) => {
        const t = (n.title || '').toLowerCase()
        const c = (n.content || '').toLowerCase()
        const p = (n.preview || '').toLowerCase()
        return t.includes(keyword) || c.includes(keyword) || p.includes(keyword)
      })
    }

    const total = filtered.length
    const truncated = (rows || []).length >= SENT_NOTICES_DB_LIMIT
    const items = slicePage(filtered, page, pageSize)

    return NextResponse.json({ items, total, page, pageSize, truncated }, { headers })
  } catch (e) {
    console.error('getSentNotices:', e)
    return NextResponse.json(
      { items: [], total: 0, page: 1, pageSize: DEFAULT_LIST_PAGE_SIZE, truncated: false },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseRpc, supabaseSelect } from '@/lib/supabase-server'
import { getVerifiedAuth } from '@/lib/verify-auth'

/** 재고 현황용 매장 목록 - stock_logs location만. 매니저는 자기 매장만 반환 */
export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  const auth = await getVerifiedAuth(request)
  const userRole = (auth?.role || '').toLowerCase()
  const isManager = userRole.includes('manager') || userRole.includes('franchisee')
  const userStore = (auth?.store || '').trim()

  if (isManager && userStore) {
    return NextResponse.json([userStore], { headers })
  }

  try {
    const rows = (await supabaseRpc<{ location: string }[]>('get_distinct_stock_locations', {})) as { location?: string }[] | null
    const list = (rows || [])
      .map((r) => String(r.location || '').trim())
      .filter(Boolean)
      .sort()
    return NextResponse.json(list, { headers })
  } catch (rpcErr) {
    // RPC 미배포 시 fallback: 기존 select 방식
    const logs = (await supabaseSelect('stock_logs', { limit: 50000, select: 'location' })) as { location?: string }[] | null
    const fromLogs = new Set<string>()
    for (const row of logs || []) {
      const loc = String(row.location || '').trim()
      if (loc) fromLogs.add(loc)
    }
    const list = Array.from(fromLogs).filter(Boolean).sort()
    return NextResponse.json(list, { headers })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { supabaseSelect, supabaseSelectFilter } from "@/lib/supabase-server"
import { buildVisitDisplayNameMap, visitDisplayName } from "@/lib/visit-display-name"
import {
  attendanceBusinessDateStrBangkok,
  attendanceBusinessDayBoundsMs,
  segmentOverlapsAttendanceBusinessDay,
  visitInstantMsBangkok,
  addDayBangkok,
} from "@/lib/attendance-utils"

const TZ = "Asia/Bangkok"
const START_TYPES = new Set(["방문시작", "강제 방문시작"])
const END_TYPES = new Set(["방문종료", "강제 방문종료"])

function toIsoBangkok(ms: number): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TZ,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(new Date(ms))
  const get = (t: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === t)?.value ?? "00"
  return `${get("year")}-${get("month")}-${get("day")}T${get("hour")}:${get("minute")}:${get("second")}+07:00`
}

type SnapshotSegment = {
  name: string
  department: string
  store: string
  purpose: string
  startAt: string
  endAt: string | null
  ongoing: boolean
}

type SnapshotActive = {
  name: string
  department: string
  store: string
  purpose: string
  startedAt: string
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const userStore = searchParams.get("userStore")?.trim()
  const userRole = String(searchParams.get("userRole") || "").toLowerCase()

  /** 근태와 동일: 자정~07:59는 전날 근무일. "오늘" 스냅샷 기준일 */
  const businessToday = attendanceBusinessDateStrBangkok(Date.now())
  /** 짝 맞춤용 넉넉한 visit_date 범위 */
  const minD = addDayBangkok(businessToday, -2)
  const maxD = addDayBangkok(businessToday, 2)
  const { startMs: winStart, endMsExclusive: winEndEx } = attendanceBusinessDayBoundsMs(businessToday)
  const nowMs = Date.now()

  try {
    const empList = (await supabaseSelect("employees", { order: "id.asc", select: "store,job,nick,name", limit: 2000 })) as
      | { store?: string; job?: string; nick?: string; name?: string }[]
      | []

    const nameToDept: Record<string, string> = {}
    for (const e of empList || []) {
      const rowDept = String(e.job || "").trim() || "Staff"
      const nick = String(e.nick || "").trim()
      const legal = String(e.name || "").trim()
      if (nick) nameToDept[nick] = rowDept
      if (legal) nameToDept[legal] = rowDept
    }

    const displayMap = buildVisitDisplayNameMap(empList || [])

    const filters = [`visit_date=gte.${minD}`, `visit_date=lte.${maxD}`]
    if (userRole.includes("manager") && userStore) {
      filters.push(`store_name=eq.${encodeURIComponent(userStore)}`)
    }

    const rows = (await supabaseSelectFilter(`store_visits`, filters.join("&"), {
      order: "visit_date.asc,visit_time.asc,created_at.asc",
      limit: 8000,
      select: "visit_date,visit_time,name,store_name,visit_type,purpose,created_at,duration_min",
    })) as {
      visit_date?: string
      visit_time?: string
      name?: string
      store_name?: string
      visit_type?: string
      purpose?: string
      created_at?: string
      duration_min?: number | string
    }[]

    const typed = (rows || []).filter((r) => {
      const vt = String(r.visit_type || "")
      return START_TYPES.has(vt) || END_TYPES.has(vt)
    })

    const byName = new Map<string, typeof typed>()
    for (const r of typed) {
      const n = String(r.name || "").trim()
      if (!n) continue
      if (!byName.has(n)) byName.set(n, [])
      byName.get(n)!.push(r)
    }

    const segmentsOut: SnapshotSegment[] = []
    const activeOut: SnapshotActive[] = []

    type Pending = {
      store: string
      purpose: string
      startMs: number
    }

    for (const name of Array.from(byName.keys()).sort()) {
      const showName = visitDisplayName(name, displayMap)
      const arr = byName.get(name)!
      arr.sort((a, b) => {
        const ma = visitInstantMsBangkok(String(a.visit_date), a.visit_time, a.created_at)
        const mb = visitInstantMsBangkok(String(b.visit_date), b.visit_time, b.created_at)
        if (ma !== mb) return ma - mb
        return String(a.created_at || "").localeCompare(String(b.created_at || ""))
      })

      const pending: Pending[] = []

      for (const row of arr) {
        const vt = String(row.visit_type || "")
        const store = String(row.store_name || "").trim()
        const purpose = String(row.purpose || "").trim() || "기타"

        if (START_TYPES.has(vt)) {
          const startMs = visitInstantMsBangkok(String(row.visit_date), row.visit_time, row.created_at)
          pending.push({ store, purpose, startMs })
          continue
        }

        if (END_TYPES.has(vt)) {
          const endMs = visitInstantMsBangkok(String(row.visit_date), row.visit_time, row.created_at)
          let idx = -1
          for (let i = pending.length - 1; i >= 0; i--) {
            if (pending[i].store === store) {
              idx = i
              break
            }
          }
          if (idx < 0) continue
          const [start] = pending.splice(idx, 1)
          const ongoing = false
          // 방문 시작의 근무일만 스냅샷 일자에 묶음 (예: 22일 02:00 기록 → 근무일 21일 → 22일 당일 탭 제외, 21일 검색에만 표시)
          if (
            attendanceBusinessDateStrBangkok(start.startMs) === businessToday &&
            segmentOverlapsAttendanceBusinessDay(start.startMs, endMs, ongoing, winStart, winEndEx, nowMs)
          ) {
            const dept = nameToDept[name] || "기타"
            segmentsOut.push({
              name: showName,
              department: dept,
              store: start.store,
              purpose: start.purpose,
              startAt: toIsoBangkok(start.startMs),
              endAt: toIsoBangkok(endMs),
              ongoing: false,
            })
          }
        }
      }

      for (const p of pending) {
        const ongoing = true
        if (
          attendanceBusinessDateStrBangkok(p.startMs) === businessToday &&
          segmentOverlapsAttendanceBusinessDay(p.startMs, null, true, winStart, winEndEx, nowMs)
        ) {
          const dept = nameToDept[name] || "기타"
          segmentsOut.push({
            name: showName,
            department: dept,
            store: p.store,
            purpose: p.purpose,
            startAt: toIsoBangkok(p.startMs),
            endAt: null,
            ongoing: true,
          })
          activeOut.push({
            name: showName,
            department: dept,
            store: p.store,
            purpose: p.purpose,
            startedAt: toIsoBangkok(p.startMs),
          })
        }
      }
    }

    activeOut.sort((a, b) => a.name.localeCompare(b.name))
    segmentsOut.sort((a, b) => {
      const ca = a.startAt.localeCompare(b.startAt)
      if (ca !== 0) return ca
      return a.name.localeCompare(b.name)
    })

    const storeKeys = new Set<string>()
    for (const s of segmentsOut) storeKeys.add(s.store)
    for (const a of activeOut) storeKeys.add(a.store)

    const byStore: { store: string; activeCount: number; segmentsTodayCount: number }[] = Array.from(storeKeys)
      .sort()
      .map((store) => ({
        store,
        activeCount: activeOut.filter((a) => a.store === store).length,
        segmentsTodayCount: segmentsOut.filter((s) => s.store === store).length,
      }))

    return NextResponse.json({
      today: businessToday,
      active: activeOut,
      segments: segmentsOut,
      byStore,
    })
  } catch (e) {
    console.error("getStoreVisitTodaySnapshot:", e)
    return NextResponse.json(
      { today: attendanceBusinessDateStrBangkok(Date.now()), active: [], segments: [], byStore: [], error: String(e) },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter } from '@/lib/supabase-server'

const TZ = 'Asia/Bangkok'

export async function GET(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const { searchParams } = new URL(request.url)
  const storeName = String(searchParams.get('storeName') || searchParams.get('store') || '').trim()
  const name = String(searchParams.get('name') || '').trim()
  const employeeIdRaw = String(searchParams.get('employeeId') || '').trim()
  const employeeId =
    employeeIdRaw && Number.isFinite(Number(employeeIdRaw)) ? Math.floor(Number(employeeIdRaw)) : 0

  if (!storeName || !name) {
    return NextResponse.json([], { headers })
  }

  try {
    const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: TZ })
    // store_name: contains 패턴 사용 (예: "Union Mall" → "CM Union Mall" 매칭)
    const storePattern = '*' + String(storeName).replace(/\*/g, '') + '*'
    const rows = (await (async () => {
      const byIdFilter =
        employeeId > 0
          ? `store_name=ilike.${encodeURIComponent(storePattern)}&employee_id=eq.${employeeId}`
          : ''
      if (byIdFilter) {
        try {
          return await supabaseSelectFilter('attendance_logs', byIdFilter, {
            order: 'log_at.desc',
            limit: 50,
            select: 'log_at,log_type',
          })
        } catch (e) {
          const em = e instanceof Error ? e.message : String(e)
          if (!/employee_id|42703|column/i.test(em)) throw e
        }
      }
      return await supabaseSelectFilter(
        'attendance_logs',
        `store_name=ilike.${encodeURIComponent(storePattern)}&name=ilike.${encodeURIComponent(name)}`,
        { order: 'log_at.desc', limit: 50, select: 'log_at,log_type' }
      )
    })()) as { log_at?: string; log_type?: string }[]

    const arr = rows || []

    // 자정 넘어도 미종료 세션(출근 후 퇴근 없음)이 있으면 퇴근 버튼 활성화
    // 가장 최근 퇴근 위치를 찾고, 그 이후에 출근이 있으면 오픈 세션
    let idxOfLastClockOut = -1
    for (let i = 0; i < arr.length; i++) {
      if (String(arr[i].log_type || '').trim() === '퇴근') {
        idxOfLastClockOut = i
        break
      }
    }

    const types: string[] = []

    if (idxOfLastClockOut >= 0) {
      // 퇴근 있음: 퇴근 이후에 출근이 있으면 새 세션(오픈)
      let hasNewSessionAfterClockOut = false
      for (let i = 0; i < idxOfLastClockOut; i++) {
        if (String(arr[i].log_type || '').trim() === '출근') {
          hasNewSessionAfterClockOut = true
          break
        }
      }
      if (!hasNewSessionAfterClockOut) {
        // 마지막 퇴근이 최신 → 당일만 사용 (기존 로직)
        for (const r of arr) {
          const rowDate = r.log_at ? new Date(r.log_at).toLocaleDateString('en-CA', { timeZone: TZ }) : ''
          if (rowDate !== todayStr) continue
          const typ = String(r.log_type || '').trim()
          if (typ && !types.includes(typ)) types.push(typ)
        }
        return NextResponse.json(types, { headers })
      }
    }

    // 오픈 세션: 출근 후 퇴근이 없는 상태 (자정 넘어도 포함)
    // 전날 출근 후 퇴근 누락이면: 출근도 types에 넣어 퇴근 버튼 활성화 (hasClockIn=true)
    for (let i = 0; i < arr.length; i++) {
      const typ = String(arr[i].log_type || '').trim()
      const logAt = arr[i].log_at
      const rowDate = logAt ? new Date(logAt).toLocaleDateString('en-CA', { timeZone: TZ }) : ''
      if (typ === '출근') {
        // 오픈 세션이면 당일/전날 출근 모두 인정 → 퇴근 버튼 활성화
        if (!types.includes(typ)) types.push(typ)
        break
      }
      if (typ && !types.includes(typ)) types.push(typ)
    }

    return NextResponse.json(types, { headers })
  } catch (e) {
    console.error('getTodayAttendanceTypes:', e)
    return NextResponse.json([], { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import {
  supabaseSelect,
  supabaseSelectFilter,
} from '@/lib/supabase-server'

function toDateStr(v: string | Date | null): string {
  if (!v) return ''
  return typeof v === 'string' ? v.slice(0, 10) : String(v).slice(0, 10)
}

export async function GET(req: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const { searchParams } = new URL(req.url)
    const startStr = searchParams.get('startStr') || searchParams.get('start') || ''
    const endStr = searchParams.get('endStr') || searchParams.get('end') || ''
    const dept = searchParams.get('dept') || ''
    const employee = searchParams.get('employee') || ''

    let fullFilter =
      `log_date=gte.${encodeURIComponent(startStr)}&log_date=lte.${encodeURIComponent(endStr)}`
    if (dept && dept !== 'all') fullFilter += `&dept=eq.${encodeURIComponent(dept)}`
    if (employee && employee !== 'all') fullFilter += `&name=eq.${encodeURIComponent(employee)}`

    const rows =
      (await supabaseSelectFilter('work_logs', fullFilter, {
        order: 'log_date.asc',
        limit: 5000,
        select: 'id,log_date,dept,name,content,progress,status,priority,manager_check',
      })) || []

    const empList = ((await supabaseSelect('employees', { order: 'id.asc', select: 'name,nick,job', limit: 2000 })) || []) as { name?: string; nick?: string; job?: string }[]

    const nameToRole: Record<string, string> = {}
    for (const e of empList) {
      const n = e.nick && String(e.nick).trim() ? e.nick : e.name || ''
      if (n) nameToRole[n] = e.job || ''
    }

    const byEmployee: Record<
      string,
      { total: number; completed: number; carried: number; inProgress: number; progressSum: number; count: number }
    > = {}

    for (const r of rows as {
      name: string
      dept?: string
      content?: string
      progress?: number
      status?: string
    }[]) {
      const name = r.name || ''
      if (!name) continue
      if (!byEmployee[name]) {
        byEmployee[name] = {
          total: 0,
          completed: 0,
          carried: 0,
          inProgress: 0,
          progressSum: 0,
          count: 0,
        }
      }
      const p = byEmployee[name]
      p.total++
      p.progressSum += Number(r.progress) || 0
      p.count++
      const st = String(r.status || '')
      if (st === 'Finish' || (Number(r.progress) || 0) >= 100) p.completed++
      else if (st === 'Continue' || st === 'Carry Over') p.carried++
      else p.inProgress++
    }

    const summaries = Object.entries(byEmployee).map(([employee, p]) => ({
      employee,
      role: nameToRole[employee] || '',
      totalTasks: p.total,
      completed: p.completed,
      carried: p.carried,
      inProgress: p.inProgress,
      avgProgress:
        p.count > 0 ? Math.round(p.progressSum / p.count) : 0,
    }))

    const totalTasks = summaries.reduce((a, s) => a + s.totalTasks, 0)
    const totalCompleted = summaries.reduce((a, s) => a + s.completed, 0)
    const totalCarried = summaries.reduce((a, s) => a + s.carried, 0)
    const overallAvg =
      summaries.length > 0
        ? Math.round(
            summaries.reduce((a, s) => a + s.avgProgress, 0) / summaries.length
          )
        : 0

    return NextResponse.json(
      {
        summaries,
        totalTasks,
        totalCompleted,
        totalCarried,
        overallAvg,
      },
      { headers }
    )
  } catch (e) {
    console.error('getWorkLogWeekly:', e)
    return NextResponse.json(
      {
        summaries: [],
        totalTasks: 0,
        totalCompleted: 0,
        totalCarried: 0,
        overallAvg: 0,
      },
      { headers }
    )
  }
}

/**
 * Excel 원가 파일 → items 테이블에 코드가 없는 품목만 추가, 행 순서대로 sort_order 반영
 * POST FormData: file (Excel .xlsx)
 *
 * - 엑셀 행 순서대로 모든 품목(기존+신규)의 sort_order를 설정 → 관리 화면 정렬이 엑셀과 동일
 * - 코드가 DB에 없는 품목만 신규 등록
 */
import { NextRequest, NextResponse } from 'next/server'
import * as XLSX from 'xlsx'
import {
  supabaseSelect,
  supabaseInsertMany,
  supabaseInsert,
  supabaseUpdateByFilter,
} from '@/lib/supabase-server'

/** 헤더에서 컬럼 인덱스 찾기 (한글/영어 모두 지원) */
function findCol(header: string[], ...names: string[]): number {
  const lower = header.map((h) => String(h || '').trim().toLowerCase())
  for (const n of names) {
    const i = lower.findIndex((h) => h === n.toLowerCase() || h.includes(n.toLowerCase()))
    if (i >= 0) return i
  }
  return -1
}

function mapTax(tax: string): string {
  const t = String(tax || '').trim().toLowerCase()
  if (t === '면세' || t === 'exempt') return '면세'
  if (t === '영세율' || t === 'zero') return '영세율'
  return '과세'
}

function parseNum(val: unknown): number {
  if (val == null) return 0
  const s = String(val).replace(/,/g, '').trim()
  const n = parseFloat(s)
  return Number.isNaN(n) ? 0 : n
}

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const form = await request.formData()
    const file = form.get('file') as File | null
    if (!file) {
      return NextResponse.json({ success: false, message: 'file 필드가 없습니다.' }, { headers })
    }

    const buf = Buffer.from(await file.arrayBuffer())
    const wb = XLSX.read(new Uint8Array(buf), { type: 'array' })
    const sheetName = wb.SheetNames[0] || ''
    const ws = wb.Sheets[sheetName]
    const data = XLSX.utils.sheet_to_json(ws, {
      header: 1,
      defval: '',
      raw: false,
    }) as unknown[][]

    if (!data || data.length < 2) {
      return NextResponse.json({ success: false, message: '헤더 외 데이터가 없습니다.' }, { headers })
    }

    const headerRow = data[0] as string[]
    const header = headerRow.map((h) => String(h ?? '').trim())

    const col = {
      code: findCol(header, '코드', 'code', '품목코드', 'item code'),
      name: findCol(header, '품목명', 'name', '품목이름', '품목'),
      category: findCol(header, '카테고리', 'category', '분류'),
      spec: findCol(header, '규격', 'spec'),
      unit: findCol(header, '단위', 'unit'),
      cost: findCol(header, '원가', 'cost'),
      price: findCol(header, '가격', 'price', '판매가'),
      vendor: findCol(header, '거래처', 'vendor'),
      tax: findCol(header, '세금', 'tax', '과세'),
    }

    if (col.code < 0 || col.name < 0) {
      return NextResponse.json(
        { success: false, message: '필수 컬럼이 없습니다. 코드(또는 품목코드), 품목명(또는 name) 필요.' },
        { headers }
      )
    }

    // 엑셀에 나온 카테고리 순서(첫 등장 순) → item_categories.sort_order 반영
    const orderedCategoryNames: string[] = []
    const seenCategories = new Set<string>()
    for (let i = 1; i < data.length; i++) {
      const row = data[i] as unknown[]
      const catRaw = col.category >= 0 ? String(row[col.category] ?? '').trim() : ''
      const cat = !catRaw ? '' : catRaw === '매장 전용' ? 'Store Only' : catRaw
      if (cat && !seenCategories.has(cat)) {
        seenCategories.add(cat)
        orderedCategoryNames.push(cat)
      }
    }
    const existingCats = (await supabaseSelect('item_categories', { select: 'id,name', limit: 500 })) as { id?: number; name?: string }[] | null
    const existingCatNames = new Set((existingCats || []).map((r) => String(r.name || '').trim()).filter(Boolean))
    for (let idx = 0; idx < orderedCategoryNames.length; idx++) {
      const name = orderedCategoryNames[idx]
      const sortOrder = idx
      try {
        if (existingCatNames.has(name)) {
          await supabaseUpdateByFilter('item_categories', `name=eq.${encodeURIComponent(name)}`, { sort_order: sortOrder })
        } else {
          await supabaseInsert('item_categories', { name, sort_order: sortOrder })
          existingCatNames.add(name)
        }
      } catch (_) {
        // 무시
      }
    }

    // 기존 품목 코드 조회
    const existing = (await supabaseSelect('items', {
      select: 'code',
      limit: 10000,
    })) as { code?: string }[] | null
    const existingCodes = new Set((existing || []).map((r) => String(r.code || '').trim()).filter(Boolean))

    const toInsert: Record<string, unknown>[] = []
    let sortOrderUpdated = 0
    for (let i = 1; i < data.length; i++) {
      const row = data[i] as unknown[]
      const code = col.code >= 0 ? String(row[col.code] ?? '').trim() : ''
      const name = col.name >= 0 ? String(row[col.name] ?? '').trim() : ''

      if (!code || !name) continue

      const sortOrder = i
      if (existingCodes.has(code)) {
        try {
          await supabaseUpdateByFilter('items', `code=eq.${encodeURIComponent(code)}`, { sort_order: sortOrder })
          sortOrderUpdated += 1
        } catch (_) {
          // 컬럼 없음 등 무시
        }
        continue
      }

      const category = col.category >= 0 ? String(row[col.category] ?? '').trim() : ''
      const spec = col.spec >= 0 ? String(row[col.spec] ?? '').trim() : ''
      const unit = col.unit >= 0 ? String(row[col.unit] ?? '').trim() : ''
      const cost = col.cost >= 0 ? parseNum(row[col.cost]) : 0
      const price = col.price >= 0 ? parseNum(row[col.price]) : 0
      const vendor = col.vendor >= 0 ? String(row[col.vendor] ?? '').trim() : ''
      const taxRaw = col.tax >= 0 ? String(row[col.tax] ?? '').trim() : ''
      const tax = mapTax(taxRaw)

      toInsert.push({
        code,
        name,
        category: category || null,
        vendor: vendor || '',
        outbound_location: '',
        spec: spec || '',
        unit: unit || '',
        price: price || 0,
        cost: cost || 0,
        image: '',
        description: null,
        tax,
        purchase_source: 'hq',
        sort_order: sortOrder,
      })
      existingCodes.add(code)
    }

    const chunkSize = 100
    for (let j = 0; j < toInsert.length; j += chunkSize) {
      const chunk = toInsert.slice(j, j + chunkSize)
      await supabaseInsertMany('items', chunk)
    }

    const added = toInsert.length
    const msg =
      added > 0 && sortOrderUpdated > 0
        ? `${added}건 신규 등록, 기존 ${sortOrderUpdated}건 정렬 순서 반영 완료`
        : added > 0
          ? `${added}건 신규 등록 완료`
          : sortOrderUpdated > 0
            ? `정렬 순서 ${sortOrderUpdated}건 반영 완료 (신규 없음)`
            : '추가할 신규 품목이 없습니다. (모든 코드가 이미 등록됨)'
    return NextResponse.json(
      { success: true, message: msg, added, sortOrderUpdated },
      { headers }
    )
  } catch (e) {
    console.error('importItemsFromExcel:', e)
    const msg = e instanceof Error ? e.message : String(e)
    return NextResponse.json(
      { success: false, message: msg || '엑셀 가져오기 실패' },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseSelectFilter, supabaseUpdateByFilter } from '@/lib/supabase-server'
import { runHypercomSaleOnRelay } from '@/lib/payments/linkpos-server'
import type { LinkposPaymentSummary } from '@/lib/payments/types'

function classifyAttemptStatus(responseCode: string): string {
  if (responseCode === '00') return 'approved'
  if (responseCode === 'ND') return 'declined'
  if (responseCode === 'NB') return 'failed'
  return 'failed'
}

export async function POST(req: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  try {
    const body = await req.json()
    const amount = Math.max(0, Number(body?.amount ?? 0))
    const bankId = String(body?.bankId ?? '').trim()
    const reference1 = String(body?.reference1 ?? '').trim().slice(0, 20)
    const reference2 = String(body?.reference2 ?? '').trim().slice(0, 20)
    const retryOfLocalTxId = String(body?.retryOfLocalTxId ?? '').trim().slice(0, 20)
    const retryOfAttemptIdRaw = Number(body?.retryOfAttemptId ?? 0)
    const retryOfAttemptId = Number.isFinite(retryOfAttemptIdRaw) && retryOfAttemptIdRaw > 0 ? retryOfAttemptIdRaw : null
    const storeCode = String(body?.storeCode ?? '').trim()
    const requestedAt = new Date().toISOString()

    if (amount <= 0) {
      return NextResponse.json({ success: false, message: 'amount_required' }, { status: 400, headers })
    }
    if (!reference1) {
      return NextResponse.json({ success: false, message: 'reference1_required' }, { status: 400, headers })
    }
    if (retryOfLocalTxId && retryOfLocalTxId === reference1) {
      return NextResponse.json({ success: false, message: 'retry_reference1_must_be_new' }, { status: 400, headers })
    }

    // R1 멱등: 이미 승인된 시도 재호출이면 승인 결과를 재사용
    try {
      const prior = (await supabaseSelectFilter(
        'pos_payment_attempts',
        `local_tx_id=eq.${encodeURIComponent(reference1)}`,
        {
          limit: 1,
          order: 'created_at.desc',
          select:
            'response_code,approval_code,trace_no,terminal_id,merchant_id,bank_id,tx_code,request_amount,approved_amount,created_at',
        }
      )) as {
        response_code?: string
        approval_code?: string
        trace_no?: string
        terminal_id?: string
        merchant_id?: string
        bank_id?: string
        tx_code?: string
        request_amount?: number
        approved_amount?: number
        created_at?: string
      }[]
      const row = prior?.[0]
      if (row && String(row.response_code ?? '') === '00') {
        const payment: LinkposPaymentSummary = {
          provider: 'kbtg_linkpos',
          mode: 'hypercom',
          txCode: '20',
          bankId: String(row.bank_id ?? bankId),
          responseCode: '00',
          approvalCode: String(row.approval_code ?? ''),
          traceNo: String(row.trace_no ?? ''),
          terminalId: String(row.terminal_id ?? ''),
          merchantId: String(row.merchant_id ?? ''),
          reference1,
          requestedAmount: Number(row.request_amount ?? amount),
          approvedAmount: Number(row.approved_amount ?? amount),
          requestedAt: String(row.created_at ?? requestedAt),
          respondedAt: requestedAt,
        }
        if (body?.orderId && Number(body.orderId) > 0) {
          try {
            await supabaseUpdateByFilter('pos_orders', `id=eq.${Number(body.orderId)}`, {
              linkpos_provider: payment.provider,
              linkpos_mode: payment.mode,
              linkpos_tx_code: payment.txCode,
              linkpos_bank_id: payment.bankId,
              linkpos_response_code: payment.responseCode,
              linkpos_approval_code: payment.approvalCode ?? null,
              linkpos_trace_no: payment.traceNo ?? null,
              linkpos_terminal_id: payment.terminalId ?? null,
              linkpos_merchant_id: payment.merchantId ?? null,
              linkpos_reference1: payment.reference1,
              linkpos_requested_amount: payment.requestedAmount,
              linkpos_approved_amount: payment.approvedAmount,
              linkpos_requested_at: payment.requestedAt,
              linkpos_responded_at: payment.respondedAt,
            })
          } catch (e) {
            console.error('linkpos/pay duplicate pos_orders update:', e)
          }
        }
        return NextResponse.json({ success: true, payment, duplicate: true }, { headers })
      }
    } catch (e) {
      console.error('linkpos/pay idempotency check:', e)
    }

    const result = await runHypercomSaleOnRelay({
      amount,
      bankId,
      reference1,
      reference2,
      timeoutMs: Math.max(2000, Number(body?.timeoutMs ?? 12000)),
      mode: 'hypercom',
    })
    const respondedAt = new Date().toISOString()

    try {
      await supabaseInsert('pos_payment_attempts', {
        order_id: body?.orderId ? Number(body.orderId) : null,
        local_tx_id: reference1,
        provider: 'kbtg_linkpos',
        mode: 'hypercom',
        tx_code: result.txCode,
        retry_of_attempt_id: retryOfAttemptId,
        retry_of_local_tx_id: retryOfLocalTxId || null,
        bank_id: bankId || null,
        request_amount: amount,
        approved_amount: result.ok ? amount : 0,
        request_raw: result.rawRequestHex ?? null,
        response_raw: result.rawResponseHex ?? null,
        response_code: result.responseCode || null,
        approval_code: result.approvalCode ?? null,
        trace_no: result.traceNo ?? null,
        terminal_id: result.terminalId ?? null,
        merchant_id: result.merchantId ?? null,
        response_text: result.responseText ?? null,
        status: classifyAttemptStatus(result.responseCode),
        error_reason: result.errorMessage ?? null,
        created_at: requestedAt,
      })
    } catch (e) {
      console.error('linkpos/pay attempt insert:', e)
    }

    if (!result.ok) {
      return NextResponse.json(
        {
          success: false,
          code: result.responseCode || 'ND',
          message: result.errorMessage || result.responseText || 'declined',
          detail: result,
        },
        { status: 422, headers }
      )
    }

    const payment: LinkposPaymentSummary = {
      provider: 'kbtg_linkpos',
      mode: 'hypercom',
      txCode: '20',
      bankId,
      responseCode: result.responseCode || '00',
      approvalCode: result.approvalCode,
      traceNo: result.traceNo,
      refNo: result.refNo,
      terminalId: result.terminalId,
      merchantId: result.merchantId,
      reference1,
      requestedAmount: amount,
      approvedAmount: amount,
      requestedAt,
      respondedAt,
    }

    if (body?.orderId && Number(body.orderId) > 0) {
      try {
        await supabaseUpdateByFilter('pos_orders', `id=eq.${Number(body.orderId)}`, {
          linkpos_provider: payment.provider,
          linkpos_mode: payment.mode,
          linkpos_tx_code: payment.txCode,
          linkpos_bank_id: payment.bankId,
          linkpos_response_code: payment.responseCode,
          linkpos_approval_code: payment.approvalCode ?? null,
          linkpos_trace_no: payment.traceNo ?? null,
          linkpos_ref_no: payment.refNo ?? null,
          linkpos_terminal_id: payment.terminalId ?? null,
          linkpos_merchant_id: payment.merchantId ?? null,
          linkpos_reference1: payment.reference1,
          linkpos_requested_amount: payment.requestedAmount,
          linkpos_approved_amount: payment.approvedAmount,
          linkpos_requested_at: payment.requestedAt,
          linkpos_responded_at: payment.respondedAt,
        })
      } catch (e) {
        console.error('linkpos/pay pos_orders update:', e)
      }
    }

    return NextResponse.json({ success: true, payment }, { headers })
  } catch (e) {
    console.error('linkpos/pay:', e)
    return NextResponse.json({ success: false, message: String(e) }, { status: 503, headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseSelectFilter, supabaseUpdate } from '@/lib/supabase-server'
import { postExpenseAccrualJournal, postPayableSettlementJournal } from '@/lib/accounting-posting'
import { assertAccountSubjectNotHeader } from '@/lib/account-subject-header-guard'

type AccountSubjectRow = { id?: number; code?: string; name?: string; name_en?: string }
type BankTxRow = { id?: number; account_id?: number; trans_date?: string; trans_type?: string; amount?: number }

/** 통장 출금 거래를 지출 발생으로 등록하고 연결 */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Content-Type', 'application/json')

  try {
    const body = await request.json()
    const userRole = String(body.userRole || body.user_role || '').toLowerCase()
    const userName = String(body.userName || body.user_name || '').trim()
    const isOffice = ['director', 'officer', 'ceo', 'hr'].some((r) => userRole.includes(r))
    if (!isOffice) {
      return NextResponse.json({ success: false, message: '본사 권한만 등록할 수 있습니다.' }, { status: 403, headers })
    }

    const bankTransactionId = Number(body.bankTransactionId ?? body.bank_transaction_id ?? 0)
    const payeeCode = String(body.payeeCode || body.payee_code || body.vendorCode || body.vendor_code || '').trim()
    const payeeName = String(body.payeeName || body.payee_name || '').trim() || payeeCode
    const accountSubjectId = body.accountSubjectId ?? body.account_subject_id
    const memo = body.memo != null ? String(body.memo || '').trim().slice(0, 500) || null : null
    const storeName = String(body.storeName || body.store_name || '').trim()

    if (!bankTransactionId || isNaN(bankTransactionId)) {
      return NextResponse.json({ success: false, message: '통장 거래 ID가 필요합니다.' }, { status: 400, headers })
    }
    if (!payeeCode) {
      return NextResponse.json({ success: false, message: '지급처를 입력해 주세요.' }, { status: 400, headers })
    }

    if (accountSubjectId != null && !isNaN(Number(accountSubjectId))) {
      const hdr = await assertAccountSubjectNotHeader(Number(accountSubjectId))
      if (!hdr.ok) {
        return NextResponse.json({ success: false, message: hdr.message }, { status: hdr.status, headers })
      }
    }

    const bankRows = (await supabaseSelectFilter('bank_transactions', `id=eq.${bankTransactionId}`, { limit: 1 })) as BankTxRow[] | null
    const bankRow = bankRows?.[0]
    if (!bankRow?.id) {
      return NextResponse.json({ success: false, message: '통장 거래를 찾을 수 없습니다.' }, { status: 404, headers })
    }
    if (String(bankRow.trans_type || '').toLowerCase() !== 'withdraw') {
      return NextResponse.json({ success: false, message: '출금 거래만 등록할 수 있습니다.' }, { status: 400, headers })
    }

    const updateExisting = Boolean(body.updateExisting ?? body.update_existing)
    const linkedPayable = (await supabaseSelectFilter('payable_transactions', `bank_transaction_id=eq.${bankTransactionId}`, { limit: 1 })) as { id?: number; expense_accrual_id?: number }[] | null

    if (linkedPayable?.length && !updateExisting) {
      return NextResponse.json({ success: false, message: '이미 연결된 통장 거래입니다.' }, { status: 400, headers })
    }
    if (linkedPayable?.length && updateExisting) {
      const accrualId = Number(linkedPayable[0].expense_accrual_id || 0)
      if (!accrualId) {
        return NextResponse.json({ success: false, message: '연결된 지출 정보를 찾을 수 없습니다.' }, { status: 404, headers })
      }
      const amount = Math.abs(Number(bankRow.amount || 0))
      const expenseDate = String(bankRow.trans_date || '').slice(0, 10)
      await supabaseUpdate('expense_accruals', accrualId, {
        payee_code: payeeCode,
        payee_name: payeeName || payeeCode,
        account_subject_id: accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : null,
        memo: memo ?? undefined,
      })
      const allPayables = (await supabaseSelectFilter('payable_transactions', `expense_accrual_id=eq.${accrualId}`, { limit: 10 })) as { id?: number }[]
      for (const p of allPayables || []) {
        if (p.id) await supabaseUpdate('payable_transactions', p.id, { vendor_code: payeeCode })
      }
      await supabaseUpdate('bank_transactions', bankTransactionId, {
        vendor_code: payeeCode,
        account_subject_id: accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : null,
        note: memo,
      })
      return NextResponse.json({ success: true, message: '수정되었습니다.' }, { headers })
    }

    const amount = Math.abs(Number(bankRow.amount || 0))
    const expenseDate = String(bankRow.trans_date || '').slice(0, 10)
    if (!amount || !expenseDate || !/^\d{4}-\d{2}-\d{2}$/.test(expenseDate)) {
      return NextResponse.json({ success: false, message: '통장 거래 정보가 올바르지 않습니다.' }, { status: 400, headers })
    }

    const accrualRow: Record<string, unknown> = {
      payee_code: payeeCode,
      payee_name: payeeName || payeeCode,
      amount,
      expense_date: expenseDate,
      due_date: expenseDate,
      memo: memo || null,
      store_name: storeName || null,
      created_by: userName || null,
      status: 'done',
    }
    let subjectCode = '5520'
    let subjectName = '기타경비'
    if (accountSubjectId != null && !isNaN(Number(accountSubjectId))) {
      const asId = Number(accountSubjectId)
      accrualRow.account_subject_id = asId
      const subject = (await supabaseSelectFilter(
        'account_subjects',
        `id=eq.${asId}`,
        { select: 'id,code,name,name_en', limit: 1 }
      )) as AccountSubjectRow[] | null
      const first = subject?.[0]
      if (first?.code) subjectCode = String(first.code)
      if (first?.name) subjectName = String(first.name)
    }

    const inserted = (await supabaseInsert('expense_accruals', accrualRow)) as { id?: number }[]
    const expenseAccrualId = Number(inserted?.[0]?.id || 0)
    if (!expenseAccrualId) {
      return NextResponse.json({ success: false, message: '지출 발생 등록에 실패했습니다.' }, { status: 500, headers })
    }

    await supabaseInsert('payable_transactions', {
      vendor_code: payeeCode,
      amount: Math.abs(amount),
      ref_type: 'Expense',
      ref_id: null,
      trans_date: expenseDate,
      memo: '지출발생(통장연결)',
      expense_accrual_id: expenseAccrualId,
      account_subject_id: accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : null,
      expense_date: expenseDate,
      due_date: expenseDate,
    })

    await supabaseInsert('payable_transactions', {
      vendor_code: payeeCode,
      amount: -Math.abs(amount),
      ref_type: 'Payment',
      ref_id: null,
      trans_date: expenseDate,
      memo: `통장 지급: ${payeeName || payeeCode}`.slice(0, 240),
      expense_accrual_id: expenseAccrualId,
      bank_transaction_id: bankTransactionId,
      expense_date: expenseDate,
    })

    await supabaseUpdate('bank_transactions', bankTransactionId, {
      note: memo || null,
      category: 'expense',
      vendor_code: payeeCode,
      expense_date: expenseDate,
      store: storeName || null,
      account_subject_id: accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : null,
    })

    try {
      await postExpenseAccrualJournal({
        expenseAccrualId,
        accountingDate: expenseDate,
        amountAbs: amount,
        expenseAccountCode: subjectCode,
        expenseAccountName: subjectName,
        expenseAccountSubjectId:
          accountSubjectId != null && !isNaN(Number(accountSubjectId)) ? Number(accountSubjectId) : null,
        memo: `지출 발생(통장연결) ${payeeName || payeeCode}`,
        storeName: storeName || undefined,
        postedBy: userName || undefined,
      })
      await postPayableSettlementJournal({
        sourceType: 'bank_transaction',
        sourceId: bankTransactionId,
        accountingDate: expenseDate,
        amountAbs: amount,
        memo: `지출 지급 ${payeeName || payeeCode}`,
        storeName: storeName || undefined,
        postedBy: userName || undefined,
      })
    } catch (postingErr) {
      console.error('registerExpenseFromBankTransaction posting:', postingErr)
    }

    return NextResponse.json(
      { success: true, message: '지출 발생으로 등록되었습니다.', id: expenseAccrualId },
      { headers }
    )
  } catch (e) {
    console.error('registerExpenseFromBankTransaction:', e)
    return NextResponse.json(
      { success: false, message: e instanceof Error ? e.message : '처리 실패' },
      { status: 500, headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseInsertMany, supabaseSelectFilter } from '@/lib/supabase-server'

/** 입고 등록 저장 - inbound_batches + stock_logs + payable(입고 건별) */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const body = await request.json()
    const storeName = (typeof body === 'object' && body?.storeName) ? String(body.storeName).trim() : null
    const vendorCode = (typeof body === 'object' && body?.vendorCode) ? String(body.vendorCode).trim() || null : null
    const purchaseOrderId = (typeof body === 'object' && body?.purchaseOrderId) ? Number(body.purchaseOrderId) : null
    const poNo = (typeof body === 'object' && body?.poNo) ? String(body.poNo).trim() || null : null
    const invoiceNo = (typeof body === 'object' && body?.invoiceNo) ? String(body.invoiceNo).trim() || null : null
    const list = Array.isArray(body) ? body : (body?.list || []) as {
      date?: string
      vendor?: string
      code?: string
      name?: string
      spec?: string
      qty?: number | string
      cost?: number | string
    }[]

    if (!list.length) {
      return NextResponse.json(
        { success: false, message: '저장할 목록이 없습니다.' },
        { headers }
      )
    }

    const location = storeName || '입고등록'
    const vendorName = String(list[0]?.vendor || '').trim()
    const batchDate = list[0]?.date ? new Date(list[0].date).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10)

    let totalAmount = 0
    const rows = list.map((item) => {
      const qty = parseFloat(String(item.qty || 0).replace(/,/g, '')) || 0
      const costVal = item.cost != null && item.cost !== '' ? parseFloat(String(item.cost).replace(/,/g, '')) : null
      const cost = costVal != null && !isNaN(costVal) && costVal >= 0 ? costVal : 0
      totalAmount += qty * cost
      const dateObj = item.date ? new Date(item.date) : new Date()
      const row: Record<string, unknown> = {
        location,
        item_code: String(item.code || '').trim(),
        item_name: String(item.name || '').trim(),
        spec: String(item.spec || '').trim() || '-',
        qty,
        log_date: dateObj.toISOString(),
        vendor_target: String(item.vendor || '').trim(),
        log_type: 'Inbound',
      }
      if (costVal != null && !isNaN(costVal) && costVal >= 0) {
        row.unit_cost = costVal
      }
      return row
    })

    const validRows = rows.filter((r) => r.item_code)
    if (!validRows.length) {
      return NextResponse.json(
        { success: false, message: '유효한 품목이 없습니다.' },
        { headers }
      )
    }

    // vendor_name → vendor_code 정규화 (vendors 테이블 기준, 통장 연동 매칭용)
    let effectiveVendorCode = vendorCode
    if (!vendorCode && vendorName) {
      try {
        const vRows = (await supabaseSelectFilter(
          'vendors',
          `name=eq.${encodeURIComponent(vendorName)}`,
          { select: 'code', limit: 1 }
        )) as { code?: string }[]
        if (vRows?.[0]?.code) {
          effectiveVendorCode = String(vRows[0].code).trim()
        } else {
          const gRows = (await supabaseSelectFilter(
            'vendors',
            `gps_name=eq.${encodeURIComponent(vendorName)}`,
            { select: 'code', limit: 1 }
          )) as { code?: string }[]
          if (gRows?.[0]?.code) effectiveVendorCode = String(gRows[0].code).trim()
        }
      } catch (_) {
        /* vendors 조회 실패 시 그대로 vendorName 사용 */
      }
    }

    // 1. inbound_batches 생성
    const batchRow: Record<string, unknown> = {
      location,
      vendor_name: vendorName || '-',
      vendor_code: effectiveVendorCode || vendorCode,
      batch_date: batchDate,
      total_amount: totalAmount,
      purchase_order_id: purchaseOrderId && !isNaN(purchaseOrderId) ? purchaseOrderId : null,
    }
    if (poNo) batchRow.po_no = poNo
    if (invoiceNo) batchRow.invoice_no = invoiceNo
    const batchInserted = (await supabaseInsert('inbound_batches', batchRow)) as { id?: number }[]
    const batchId = Array.isArray(batchInserted) && batchInserted[0]?.id ? batchInserted[0].id : null

    // 2. stock_logs에 inbound_batch_id 포함
    const rowsWithBatch = validRows.map((r) => ({ ...r, inbound_batch_id: batchId }))
    await supabaseInsertMany('stock_logs', rowsWithBatch)

    // 3. 미지급금 생성 (입고 건별, From HQ 제외)
    if (batchId && totalAmount > 0 && vendorName && vendorName !== 'From HQ') {
      const payVendorCode = effectiveVendorCode || vendorCode || vendorName
      await supabaseInsert('payable_transactions', {
        vendor_code: payVendorCode,
        amount: totalAmount,
        ref_type: 'Inbound',
        ref_id: batchId,
        trans_date: batchDate,
        memo: `입고 ${batchDate} ${vendorName}`,
      })
    }
    return NextResponse.json(
      { success: true, message: `✅ ${validRows.length}건 입고 완료!` },
      { headers }
    )
  } catch (e) {
    console.error('registerInboundBatch:', e)
    return NextResponse.json(
      { success: false, message: e instanceof Error ? e.message : '입고 저장 실패' },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseSelectFilter } from '@/lib/supabase-server'
import { parseOr400, requestLeaveSchema } from '@/lib/api-validate'
import { hasOneYearTenureAsOf } from '@/lib/annual-leave'
import {
  bareNameFuzzySameForLeaveStats,
  isAnnualLeaveFamilyType,
  leavePersonKeyForLeaveStats,
  normalizeLeaveMatchKey,
} from '@/lib/leave-request-utils'

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Access-Control-Allow-Methods', 'POST, OPTIONS')
  headers.set('Access-Control-Allow-Headers', 'Content-Type')
  if (request.method === 'OPTIONS') return new NextResponse(null, { status: 204, headers })

  try {
    const body = await request.json()
    const d = body.d || body
    const bodyForValidation = {
      store: d.store || '',
      name: d.name || '',
      type: d.type || '',
      date: (d.date || d.leave_date || '').slice(0, 10),
      reason: d.reason,
      employeeId: d.employeeId ?? d.employee_id,
    }
    const validated = parseOr400(requestLeaveSchema, bodyForValidation, headers)
    if (validated.errorResponse) return validated.errorResponse
    const { store, name, type, date: leaveDate, reason, employeeId } = validated.parsed

    let verifiedEmployeeId: number | undefined
    if (employeeId != null && employeeId > 0) {
      const erows = (await supabaseSelectFilter(
        'employees',
        `id=eq.${employeeId}&store=ilike.${encodeURIComponent(store)}`,
        { limit: 1, select: 'id,store,name,name_title,join_date' }
      )) as {
        id?: number
        store?: string
        name?: string
        name_title?: string | null
        join_date?: string | null
      }[]
      const e = erows?.[0]
      if (!e) {
        return NextResponse.json(
          { success: false, message: '❌ 직원을 확인할 수 없습니다. 다시 로그인 후 시도해 주세요.' },
          { headers }
        )
      }
      if (normalizeLeaveMatchKey(String(e.store || '')) !== normalizeLeaveMatchKey(store)) {
        return NextResponse.json(
          { success: false, message: '❌ 매장 정보가 일치하지 않습니다.' },
          { headers }
        )
      }
      const reqKey = leavePersonKeyForLeaveStats(name, '')
      const empKey = leavePersonKeyForLeaveStats(String(e.name || ''), e.name_title)
      if (reqKey !== empKey && !bareNameFuzzySameForLeaveStats(reqKey, empKey)) {
        return NextResponse.json(
          { success: false, message: '❌ 로그인 이름과 직원 정보가 일치하지 않습니다.' },
          { headers }
        )
      }
      const vid = Math.floor(Number(e.id))
      if (!(vid > 0)) {
        return NextResponse.json(
          { success: false, message: '❌ 직원 식별에 실패했습니다. 다시 로그인해 주세요.' },
          { headers }
        )
      }
      verifiedEmployeeId = vid
    }

    let effectiveType = type.trim()

    if (isAnnualLeaveFamilyType(effectiveType)) {
      let emp: { join_date?: string | null } | null = null
      if (verifiedEmployeeId != null && verifiedEmployeeId > 0) {
        const one = (await supabaseSelectFilter('employees', `id=eq.${verifiedEmployeeId}`, {
          limit: 1,
          select: 'join_date',
        })) as { join_date?: string | null }[]
        emp = one?.[0] ?? null
      } else {
        const empRows = (await supabaseSelectFilter(
          'employees',
          `store=ilike.${encodeURIComponent(store)}&name=ilike.${encodeURIComponent(name)}`,
          { order: 'id.asc', limit: 1, select: 'join_date' }
        )) as { join_date?: string | null }[]
        emp = empRows?.[0] ?? null
      }
      if (!hasOneYearTenureAsOf(emp, leaveDate)) {
        const half = effectiveType.indexOf('반차') !== -1 || /\bhalf\b/i.test(effectiveType)
        effectiveType = half ? '무급휴가(반차)' : '무급휴가'
      }
    }

    const leaveRow: Record<string, unknown> = {
      store,
      name,
      type: effectiveType,
      leave_date: leaveDate,
      reason: String(reason || '').trim(),
      status: '대기',
    }
    if (verifiedEmployeeId != null && verifiedEmployeeId > 0) {
      leaveRow.employee_id = verifiedEmployeeId
    }
    try {
      await supabaseInsert('leave_requests', leaveRow)
    } catch (insErr) {
      const em = insErr instanceof Error ? insErr.message : String(insErr)
      if (/employee_id|42703|column/i.test(em) && 'employee_id' in leaveRow) {
        const { employee_id: _eid, ...withoutEid } = leaveRow
        await supabaseInsert('leave_requests', withoutEid)
      } else {
        throw insErr
      }
    }
    return NextResponse.json(
      { success: true, message: '✅ 신청 완료' },
      { headers }
    )
  } catch (e) {
    console.error('requestLeave:', e)
    return NextResponse.json(
      {
        success: false,
        message: '❌ 신청 실패: ' + (e instanceof Error ? e.message : String(e)),
      },
      { headers }
    )
  }
}

import { NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter, supabaseUpdate } from '@/lib/supabase-server'

/** POST: 모든 배합 원가 재계산 및 cost_per_unit 캐시 업데이트 */
export async function POST() {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const [sauceRows, ingRows, itemRows] = await Promise.all([
      supabaseSelect('sauces', { order: 'sort_order.asc,id.asc', limit: 500 }),
      supabaseSelect('sauce_ingredients', { limit: 5000, select: 'sauce_id,item_code,quantity,loss_rate' }),
      supabaseSelect('items', { limit: 5000, select: 'code,cost,price,total_quantity,unit' }),
    ]) as [
      { id?: number; code?: string; name?: string; overhead_percent?: number; total_quantity?: number | null }[] | null,
      { sauce_id?: number; item_code?: string; quantity?: number; loss_rate?: number }[] | null,
      { code?: string; cost?: number; price?: number; total_quantity?: number; unit?: string }[] | null,
    ]

    const { getItemCostPerUnit } = await import('@/lib/item-cost-util')
    const itemCost: Record<string, number> = {}
    for (const r of itemRows || []) {
      const code = String(r.code ?? '').trim()
      if (code) itemCost[code] = getItemCostPerUnit(r, false)
    }

    const sauceCostPerUnit: Record<string, number> = {}
    const sauceRowsArr = sauceRows || []
    for (const s of sauceRowsArr) {
      const code = String(s.code ?? '').trim()
      if (code) sauceCostPerUnit[code] = 0
      const name = String(s.name ?? '').trim()
      if (name && sauceCostPerUnit[name] === undefined) sauceCostPerUnit[name] = 0
    }

    for (let pass = 0; pass < 5; pass++) {
      let changed = false
      for (const s of sauceRowsArr) {
        const sid = Number(s.id ?? 0)
        const code = String(s.code ?? '').trim()
        const ings = (ingRows || []).filter((i) => Number(i.sauce_id) === sid)
        let totalCost = 0
        let totalQty = 0
        let allResolved = true
        for (const ing of ings) {
          const icode = String(ing.item_code ?? '').trim()
          const qty = Number(ing.quantity ?? 1)
          const lossRate = Number(ing.loss_rate ?? 0)
          const cost = itemCost[icode] ?? sauceCostPerUnit[icode]
          if (cost === undefined) {
            allResolved = false
            break
          }
          totalCost += cost * qty * (1 + lossRate / 100)
          totalQty += qty
        }
        const qtyForUnit = Number(s.total_quantity ?? 0) || totalQty
        if (allResolved && qtyForUnit > 0) {
          const oh = Number(s.overhead_percent ?? 5)
          const costPerUnit = (totalCost * (1 + oh / 100)) / qtyForUnit
          const prev = sauceCostPerUnit[code]
          if (Math.abs((prev ?? 0) - costPerUnit) > 1e-9) {
            sauceCostPerUnit[code] = costPerUnit
            const name = String(s.name ?? '').trim()
            if (name) sauceCostPerUnit[name] = costPerUnit
            changed = true
          }
        }
      }
      if (!changed) break
    }

    for (const s of sauceRowsArr) {
      const code = String(s.code ?? '').trim()
      const cpu = sauceCostPerUnit[code] ?? 0
      await supabaseUpdate('sauces', s.id!, {
        cost_per_unit: Math.round(cpu * 1000000) / 1000000,
        updated_at: new Date().toISOString(),
      })
    }

    return NextResponse.json({ success: true, count: sauceRowsArr.length }, { headers })
  } catch (e) {
    console.error('recalculateSauces:', e)
    return NextResponse.json({ success: false, message: String(e) }, { status: 500, headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseUpdate, supabaseSelect, supabaseSelectFilter, supabaseUpdateByFilter } from '@/lib/supabase-server'
import { hashPassword, isHashed } from '@/lib/password'
import {
  isAccountingRole,
  isFranchiseeRole,
  isDirectorRole,
  isEmployeeAuthRoleOfficerOrDirector,
} from '@/lib/permissions'
import { tryVerifyBearerFromRequest } from '@/lib/verify-auth'
import { userCanAccessEmployeeStore } from '@/lib/admin-employee-store-access'
import {
  franchiseeQueryStoreAllowed,
  getFranchiseeMultiStoreSettings,
  normalizedAllowedStoresFromJwt,
  rowRoleLooksFranchisee,
} from '@/lib/franchisee-multi-store'
import { normalizeEmployeeNameFields } from '@/lib/employee-display-name'

const EMPLOYEE_CODE_RE = /^[A-Z]{2}\d{3}$/

function toDateStr(val: unknown): string | null {
  if (!val) return null
  if (typeof val === 'string') {
    const s = val.trim().slice(0, 10)
    return s || null
  }
  const d = new Date(val as string)
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10)
}

function storePrefixFromName(storeName: string): string {
  const alpha = String(storeName || '')
    .toUpperCase()
    .replace(/[^A-Z]/g, '')
  if (alpha.length >= 2) return alpha.slice(0, 2)
  if (alpha.length === 1) return `${alpha}X`
  return 'ST'
}

function prefixCandidatesForStore(storeName: string): string[] {
  const raw = String(storeName || '').trim()
  const letters = raw.toUpperCase().replace(/[^A-Z]/g, '')
  const out: string[] = []
  const seen = new Set<string>()
  const push = (p: string) => {
    const v = String(p || '').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 2)
    if (v.length !== 2) return
    if (seen.has(v)) return
    seen.add(v)
    out.push(v)
  }

  // 1) 매장명에서 추출한 연속 알파벳 2글자 (순서 유지, CM Tower → CM, MT, …)
  if (letters.length >= 2) {
    for (let i = 0; i < letters.length - 1; i++) {
      push(`${letters[i]}${letters[i + 1]}`)
    }
  }

  // 2) 맨 앞 2글자 (1)과 겹칠 수 있으나 우선순위 고정용
  push(storePrefixFromName(raw))

  // 3) 공백으로 나뉜 단어들에서 알파벳 첫 글자만 모아 앞 2글자 (SQL cm_erp_emp_prefix_candidates 와 동일)
  const words = raw.split(/\s+/).filter(Boolean)
  let ini = ''
  for (let wi = 0; wi < Math.min(words.length, 4); wi++) {
    const a = words[wi].toUpperCase().replace(/[^A-Z]/g, '')
    if (a.length >= 1) ini += a[0]
    if (ini.length >= 2) break
  }
  if (ini.length >= 2) push(`${ini[0]}${ini[1]}`)

  // 4) 같은 매장 문자열에서 나올 수 있는 모든 알파벳 쌍 (이름 연관도↑, 충돌 시 뒤쪽 후보 사용)
  if (letters.length >= 2) {
    for (let i = 0; i < letters.length; i++) {
      for (let j = i + 1; j < letters.length; j++) {
        push(`${letters[i]}${letters[j]}`)
      }
    }
  }

  // 5) 첫 글자 + 마지막 글자
  if (letters.length >= 2) {
    push(`${letters[0]}${letters[letters.length - 1]}`)
  }

  if (letters.length === 1) {
    push(`${letters}X`)
    for (let j = 0; j < 26; j++) push(`${letters}${String.fromCharCode(65 + j)}`)
  }

  if (!letters.length) {
    push('ST')
  }

  // 6) 최후 수단: AA–ZZ (매장명과 무관하지만 전역 충돌 시에만 뒤에서 선택됨)
  for (let i = 0; i < 26; i++) {
    for (let j = 0; j < 26; j++) {
      push(`${String.fromCharCode(65 + i)}${String.fromCharCode(65 + j)}`)
    }
  }
  return out
}

function normalizeEmployeeCodeInput(raw: unknown): string {
  return String(raw ?? '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '')
    .slice(0, 5)
}

async function buildNextEmployeeCodeForStore(storeName: string): Promise<string> {
  let rows: { store?: string | null; employee_code?: string | null }[] = []
  try {
    rows = (await supabaseSelect('employees', {
      select: 'store,employee_code',
      limit: 5000,
      order: 'id.asc',
    })) as { store?: string | null; employee_code?: string | null }[]
  } catch (e) {
    const em = e instanceof Error ? e.message : String(e)
    if (/employee_code|42703|column/i.test(em)) return `${storePrefixFromName(storeName)}001`
    throw e
  }
  const targetStore = String(storeName || '').trim()
  const usedPrefixesByOtherStore = new Set<string>()
  const validPrefixCountInTarget = new Map<string, number>()
  const targetRows: string[] = []
  for (const r of rows || []) {
    const rowStore = String(r.store || '').trim()
    const c = normalizeEmployeeCodeInput(r.employee_code)
    if (!EMPLOYEE_CODE_RE.test(c)) continue
    const pfx = c.slice(0, 2)
    if (rowStore && rowStore.toLowerCase() === targetStore.toLowerCase()) {
      validPrefixCountInTarget.set(pfx, (validPrefixCountInTarget.get(pfx) || 0) + 1)
      targetRows.push(c)
    } else {
      usedPrefixesByOtherStore.add(pfx)
    }
  }
  let prefix = ''
  if (validPrefixCountInTarget.size > 0) {
    const sorted = Array.from(validPrefixCountInTarget.entries()).sort((a, b) => {
      if (b[1] !== a[1]) return b[1] - a[1]
      return a[0].localeCompare(b[0])
    })
    prefix = sorted[0][0]
  } else {
    const cands = prefixCandidatesForStore(storeName)
    prefix = cands.find((p) => !usedPrefixesByOtherStore.has(p)) || cands[0] || 'ST'
  }
  const used = new Set<number>()
  for (const c of targetRows) {
    if (!c.startsWith(prefix)) continue
    const n = Number(c.slice(2))
    if (Number.isFinite(n) && n >= 1 && n <= 999) used.add(n)
  }
  for (let i = 1; i <= 999; i++) {
    if (!used.has(i)) return `${prefix}${String(i).padStart(3, '0')}`
  }
  throw new Error(`매장(${storeName}) 직원코드가 999명을 초과했습니다.`)
}

/** 직원 저장 (신규/수정) */
export async function POST(req: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const body = await req.json()
    const d = body.d || body
    const userStore = String(body.userStore || '').trim()
    const userRole = String(body.userRole || '').toLowerCase()
    const jwt = await tryVerifyBearerFromRequest(req)
    const effectiveRole = String(jwt?.role || userRole).toLowerCase()

    const isTop =
      ['director', 'officer', 'ceo', 'hr'].some((r) => userRole.includes(r)) || isAccountingRole(userRole)
    const franchiseeJwtList =
      jwt && isFranchiseeRole(jwt.role || '') ? normalizedAllowedStoresFromJwt(jwt) : undefined

    if (!isTop) {
      if (jwt && isFranchiseeRole(effectiveRole) && !franchiseeQueryStoreAllowed(jwt, userStore)) {
        return NextResponse.json(
          { success: false, message: '❌ 선택한 매장에 대한 권한이 없습니다.' },
          { status: 403, headers }
        )
      }
      const targetStore = String(d.store || '').trim()
      if (
        !userCanAccessEmployeeStore(effectiveRole, userStore, targetStore, {
          allowedStores: franchiseeJwtList && franchiseeJwtList.length > 0 ? franchiseeJwtList : undefined,
        })
      ) {
        return NextResponse.json(
          { success: false, message: '❌ 해당 매장 직원만 수정할 수 있습니다.' },
          { headers }
        )
      }
    }

    const rowIdForRole = Number(d.row)
    const requestedRole = String(d.role || 'Staff').trim()
    const normRole = (s: string) => String(s || '').trim().toLowerCase()
    if (!isDirectorRole(effectiveRole)) {
      if (rowIdForRole === 0) {
        if (isEmployeeAuthRoleOfficerOrDirector(requestedRole)) {
          return NextResponse.json(
            {
              success: false,
              message: '❌ Officer·Director 역할은 Director급만 지정할 수 있습니다.',
            },
            { status: 403, headers }
          )
        }
      } else {
        const prevRows = (await supabaseSelectFilter('employees', `id=eq.${rowIdForRole}`, {
          limit: 1,
          select: 'role',
        })) as { role?: string | null }[]
        const prevRole = prevRows?.[0]?.role != null ? String(prevRows[0].role) : ''
        if (
          isEmployeeAuthRoleOfficerOrDirector(requestedRole) &&
          normRole(requestedRole) !== normRole(prevRole)
        ) {
          return NextResponse.json(
            {
              success: false,
              message: '❌ Officer·Director 역할은 Director급만 변경·지정할 수 있습니다.',
            },
            { status: 403, headers }
          )
        }
      }
    }

    const rawPw = String(d.pw || '').trim()
    let passwordValue: string
    if (rawPw) {
      passwordValue = isHashed(rawPw) ? rawPw : await hashPassword(rawPw)
    } else {
      passwordValue = ''
    }

    const nameNorm = normalizeEmployeeNameFields(
      String(d.name || '').trim(),
      String(d.nameTitle ?? d.name_title ?? '').trim()
    )
    const codeRaw = normalizeEmployeeCodeInput((d as { employeeCode?: unknown }).employeeCode ?? d.employee_code)
    const payload: Record<string, unknown> = {
      store: String(d.store || '').trim(),
      name: nameNorm.name,
      name_title: nameNorm.nameTitle,
      nick: String(d.nick || '').trim(),
      phone: String(d.phone || '').trim(),
      job: String(d.job || '').trim(),
      birth: toDateStr(d.birth),
      nation: String(d.nation || '').trim(),
      join_date: toDateStr(d.join),
      resign_date: toDateStr(d.resign),
      sal_type: String(d.salType || 'Monthly').trim(),
      sal_amt: Number(d.salAmt) || 0,
      role: String(d.role || 'Staff').trim(),
      email: String(d.email || '').trim(),
      annual_leave_days: d.annualLeaveDays != null && d.annualLeaveDays !== '' ? Number(d.annualLeaveDays) : null,
      id_number: d.idNumber != null ? String(d.idNumber).trim() : '',
      id_card_photo: d.idCardPhoto != null && String(d.idCardPhoto).trim() ? String(d.idCardPhoto).trim() : null,
      tax_id: d.taxId != null ? String(d.taxId).trim() : '',
      sso_number: d.ssoNumber != null ? String(d.ssoNumber).trim() : '',
      sso_exempt: !!(d as { ssoExempt?: unknown }).ssoExempt,
      address: d.address != null ? String(d.address).trim() : '',
      bank_name: d.bankName != null ? String(d.bankName).trim() : '',
      account_number: d.accountNumber != null ? String(d.accountNumber).trim() : '',
      position_allowance: d.positionAllowance != null ? Number(d.positionAllowance) : 0,
      haz_allow: d.riskAllowance != null ? Number(d.riskAllowance) : 0,
      attendance_allowance: (() => {
        const aa = (d as { attendanceAllowance?: unknown }).attendanceAllowance
        return aa == null || aa === '' ? 500 : Number(aa)
      })(),
      grade: d.grade != null ? String(d.grade).trim() : '',
      photo: d.photo != null ? String(d.photo).trim() : '',
    }
    if (codeRaw) {
      if (!EMPLOYEE_CODE_RE.test(codeRaw)) {
        return NextResponse.json(
          { success: false, message: '❌ 직원 코드는 영문 2글자 + 숫자 3자리 형식(예: AB001)이어야 합니다.' },
          { headers }
        )
      }
      const manualPrefix = codeRaw.slice(0, 2)
      const targetStoreForCode = String(payload.store || '').trim()
      try {
        const allRows = (await supabaseSelect('employees', {
          select: 'store,employee_code',
          limit: 5000,
          order: 'id.asc',
        })) as { store?: string | null; employee_code?: string | null }[]
        const usedByOtherStore = (allRows || []).some((r) => {
          const p = normalizeEmployeeCodeInput(r.employee_code).slice(0, 2)
          if (p !== manualPrefix) return false
          const s = String(r.store || '').trim()
          return !!s && s.toLowerCase() !== targetStoreForCode.toLowerCase()
        })
        if (usedByOtherStore) {
          return NextResponse.json(
            { success: false, message: `❌ 접두어 ${manualPrefix}는 다른 매장에서 이미 사용 중입니다. 매장별로 고유한 2글자 접두어를 사용해 주세요.` },
            { headers }
          )
        }
      } catch (e) {
        const em = e instanceof Error ? e.message : String(e)
        if (!/employee_code|42703|column/i.test(em)) throw e
      }
      payload.employee_code = codeRaw
    }

    const multiSettings = await getFranchiseeMultiStoreSettings()
    const roleStr = String(d.role || '').trim()
    const franchiseeRow = rowRoleLooksFranchisee(roleStr)
    if (isTop) {
      if (franchiseeRow && multiSettings.enabled) {
        const primary = String(d.store || '').trim()
        const fromTop = (body as { extraStores?: unknown }).extraStores
        const fromD = (d as { extraStores?: unknown }).extraStores
        const rawExtra = Array.isArray(fromTop)
          ? (fromTop as unknown[])
          : Array.isArray(fromD)
            ? (fromD as unknown[])
            : []
        const seen = new Set<string>()
        const extras: string[] = []
        const maxExtra = Math.max(0, multiSettings.maxStores - 1)
        for (const x of rawExtra) {
          const s = String(x || '').trim()
          if (!s || s === primary || seen.has(s)) continue
          seen.add(s)
          extras.push(s)
          if (extras.length >= maxExtra) break
        }
        payload.extra_stores = extras
      } else {
        payload.extra_stores = []
      }
    }

    const rowId = Number(d.row)
    const newStore = String(d.store || '').trim()
    const newName = String(d.name || '').trim()
    const userName = String(body.userName || body.user_name || '').trim()

    if (rowId === 0) {
      payload.password = passwordValue || ''
      if (!codeRaw) {
        payload.employee_code = await buildNextEmployeeCodeForStore(newStore)
      }
      let toInsert: Record<string, unknown> = { ...payload }
      for (;;) {
        try {
          await supabaseInsert('employees', toInsert)
          break
        } catch (insErr) {
          const em = insErr instanceof Error ? insErr.message : String(insErr)
          if (/attendance_allowance|42703|column/i.test(em) && 'attendance_allowance' in toInsert) {
            const { attendance_allowance: _aa, ...rest } = toInsert
            toInsert = rest
            continue
          }
          if (/employee_code|42703|column/i.test(em) && 'employee_code' in toInsert) {
            const { employee_code: _ec, ...rest } = toInsert
            toInsert = rest
            continue
          }
          if (/employee_code/i.test(em) && /(duplicate key|23505)/i.test(em)) {
            if (codeRaw) {
              return NextResponse.json({ success: false, message: '❌ 이미 사용 중인 직원 코드입니다.' }, { headers })
            }
            toInsert = { ...toInsert, employee_code: await buildNextEmployeeCodeForStore(newStore) }
            continue
          }
          throw insErr
        }
      }
      return NextResponse.json({ success: true, message: '✅ 신규 직원이 등록되었습니다.' }, { headers })
    }

    // 직원 수정 시: 기존 데이터 조회 (급여 변경 이력·attendance 갱신용)
    const existing = (await supabaseSelectFilter('employees', `id=eq.${rowId}`, {
      limit: 1,
      select: 'store,name,sal_type,sal_amt,position_allowance,haz_allow',
    })) as {
      store?: string
      name?: string
      sal_type?: string
      sal_amt?: number
      position_allowance?: number
      haz_allow?: number
    }[]
    const old = existing?.[0]
    const oldStore = old ? String(old.store || '').trim() : ''
    const oldName = old ? String(old.name || '').trim() : ''
    const nameOrStoreChanged = (oldName !== newName || oldStore !== newStore) && (oldName || oldStore)

    const oldSalType = old ? String(old.sal_type || '').trim() : ''
    const oldSalAmt = old ? Number(old.sal_amt) || 0 : 0
    const oldPosAllow = old ? Number(old.position_allowance) || 0 : 0
    const oldHazAllow = old ? Number(old.haz_allow) || 0 : 0
    const newSalType = String(d.salType || 'Monthly').trim()
    const newSalAmt = Number(d.salAmt) || 0
    const newPosAllow = d.positionAllowance != null ? Number(d.positionAllowance) : 0
    const newHazAllow = d.riskAllowance != null ? Number(d.riskAllowance) : 0
    const salaryChanged =
      oldSalType !== newSalType ||
      oldSalAmt !== newSalAmt ||
      oldPosAllow !== newPosAllow ||
      oldHazAllow !== newHazAllow

    if (passwordValue) payload.password = passwordValue
    try {
      await supabaseUpdate('employees', rowId, payload)
    } catch (updErr) {
      const em = updErr instanceof Error ? updErr.message : String(updErr)
      if (/attendance_allowance|42703|column/i.test(em)) {
        const { attendance_allowance: _aa, ...withoutAa } = payload
        await supabaseUpdate('employees', rowId, withoutAa)
      } else if (/employee_code/i.test(em) && /(duplicate key|23505)/i.test(em)) {
        return NextResponse.json({ success: false, message: '❌ 이미 사용 중인 직원 코드입니다.' }, { headers })
      } else {
        throw updErr
      }
    }

    if (salaryChanged) {
      try {
        await supabaseInsert('employee_salary_history', {
          employee_id: rowId,
          store: newStore,
          name: newName,
          old_sal_type: oldSalType || null,
          new_sal_type: newSalType,
          old_sal_amt: oldSalAmt,
          new_sal_amt: newSalAmt,
          old_position_allowance: oldPosAllow,
          new_position_allowance: newPosAllow,
          old_haz_allow: oldHazAllow,
          new_haz_allow: newHazAllow,
          changed_by: userName,
        })
      } catch (_) {
        // 이력 저장 실패해도 직원 저장은 완료됨
      }
    }

    if (nameOrStoreChanged) {
      try {
        const attFilter = `store_name=ilike.${encodeURIComponent(oldStore)}&name=ilike.${encodeURIComponent(oldName)}`
        await supabaseUpdateByFilter('attendance_logs', attFilter, {
          store_name: newStore,
          name: newName,
        })
      } catch (_) {
        // attendance_logs 업데이트 실패해도 직원 저장은 완료됨
      }
    }

    return NextResponse.json({ success: true, message: '✅ 직원 정보가 수정되었습니다.' }, { headers })
  } catch (e) {
    console.error('saveAdminEmployee:', e)
    return NextResponse.json(
      { success: false, message: '❌ 오류: ' + (e instanceof Error ? e.message : String(e)) },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseInsert, supabaseUpdate, supabaseSelectFilter } from '@/lib/supabase-server'

/** 통장(계좌) 추가 또는 기초잔액 수정 */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Content-Type', 'application/json')

  try {
    const body = await request.json()
    const id = body.id ? Number(body.id) : null
    const name = String(body.name || '').trim()
    const store = String(body.store || '').trim()
    const bankName = String(body.bankName ?? body.bank_name ?? '').trim()
    const openingBalance = Number(body.openingBalance ?? body.opening_balance ?? 0)
    const openingBalanceDate = body.openingBalanceDate || body.opening_balance_date
      ? String(body.openingBalanceDate || body.opening_balance_date).slice(0, 10)
      : null

    if (!name) {
      return NextResponse.json({ success: false, message: '계좌명을 입력하세요.' }, { status: 400, headers })
    }

    if (id) {
      await supabaseUpdate('bank_accounts', id, {
        name,
        store: store || null,
        bank_name: bankName || null,
        opening_balance: openingBalance,
        opening_balance_date: openingBalanceDate,
      })
      return NextResponse.json({ success: true, id, message: '수정되었습니다.' }, { headers })
    }

    const inserted = (await supabaseInsert('bank_accounts', {
      name,
      store: store || null,
      bank_name: bankName || null,
      opening_balance: openingBalance,
      opening_balance_date: openingBalanceDate,
    })) as { id?: number }[]
    const newId = Array.isArray(inserted) && inserted[0]?.id != null ? inserted[0].id : null
    return NextResponse.json({ success: true, id: newId, message: '등록되었습니다.' }, { headers })
  } catch (e) {
    console.error('saveBankAccount:', e)
    return NextResponse.json(
      { success: false, message: '오류: ' + (e instanceof Error ? e.message : String(e)) },
      { status: 500, headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseInsert, supabaseDeleteByFilter } from '@/lib/supabase-server'

/** 통장 출금 입고 연동 저장 - 기존 링크 삭제 후 새로 저장 */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Content-Type', 'application/json')

  try {
    const body = await request.json()
    const bankTxId = Number(body.bankTransactionId ?? body.bankTxId ?? body.id ?? 0)
    const links = Array.isArray(body.links) ? body.links : []
    if (!bankTxId || isNaN(bankTxId)) {
      return NextResponse.json({ success: false, message: '통장 거래 ID가 필요합니다.' }, { status: 400, headers })
    }

    const validLinks = links
      .map((l: { inboundBatchId?: number; amount?: number }) => ({
        inbound_batch_id: Number(l.inboundBatchId ?? 0),
        amount: Number(l.amount ?? 0) || 0,
      }))
      .filter((l: { inbound_batch_id: number; amount: number }) => l.inbound_batch_id > 0 && l.amount > 0)

    await supabaseDeleteByFilter('bank_transaction_inbound_links', `bank_transaction_id=eq.${bankTxId}`)

    for (const link of validLinks) {
      await supabaseInsert('bank_transaction_inbound_links', {
        bank_transaction_id: bankTxId,
        inbound_batch_id: link.inbound_batch_id,
        amount: link.amount,
      })
    }

    return NextResponse.json({ success: true, message: '저장되었습니다.' }, { headers })
  } catch (e) {
    console.error('saveBankTransactionInboundLinks:', e)
    return NextResponse.json(
      { success: false, message: e instanceof Error ? e.message : '저장 실패' },
      { status: 500, headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseInsert, supabaseUpdateByFilter } from '@/lib/supabase-server'
import { recordPriceChanges } from '@/lib/price-history'

function taxTypeToDb(taxType: string): string {
  if (taxType === 'exempt') return '면세'
  if (taxType === 'zero') return '영세율'
  return '과세'
}

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  let code = ''

  try {
    const body = (await request.json()) as {
      code?: string
      name?: string
      category?: string
      vendor?: string
      outboundLocation?: string
      spec?: string
      unit?: string
      price?: number
      cost?: number
      totalQuantity?: number | null
      taxType?: string
      imageUrl?: string
      description?: string
      editingCode?: string
      purchaseSource?: 'hq' | 'store'
      stockBaseUnit?: string
      stockUnitOptions?: { unit: string; factor: number }[]
      standardUnits?: { unit: string; totalQuantity: number }[]
    }

    code = String(body.code || '').trim()
    const name = String(body.name || '').trim()
    const editingCode = body.editingCode ? String(body.editingCode).trim() : null
    if (!code || !name) {
      return NextResponse.json({ success: false, message: '코드와 품목명이 필요합니다.' }, { headers })
    }

    const tax = taxTypeToDb(body.taxType || 'taxable')
    const purchaseSource = (body.purchaseSource || 'hq') === 'store' ? 'store' : 'hq'
    const categoryRaw = String(body.category || '').trim()
    const category = purchaseSource === 'store' && !categoryRaw ? 'Store Only' : categoryRaw
    const stockUnitOpts = Array.isArray(body.stockUnitOptions)
      ? body.stockUnitOptions
          .filter((x) => x && String(x.unit || '').trim())
          .map((x) => ({ unit: String(x.unit).trim(), factor: Number(x.factor) || 1 }))
      : []
    const standardUnitsDb = Array.isArray(body.standardUnits)
      ? body.standardUnits
          .filter((x) => x && String(x.unit || '').trim() && Number(x.totalQuantity) > 0)
          .map((x) => ({ unit: String(x.unit).trim(), total_quantity: Number(x.totalQuantity) || 1 }))
      : []
    const row = {
      code,
      name,
      category,
      vendor: String(body.vendor || '').trim(),
      outbound_location: String(body.outboundLocation || '').trim(),
      spec: String(body.spec || '').trim(),
      unit: String(body.unit || '').trim(),
      price: Number(body.price) || 0,
      cost: Number(body.cost) || 0,
      total_quantity: body.totalQuantity != null && body.totalQuantity > 0 ? Number(body.totalQuantity) : null,
      image: String(body.imageUrl || '').trim(),
      description: String(body.description || '').trim() || null,
      tax,
      purchase_source: purchaseSource,
      stock_base_unit: String(body.stockBaseUnit || '').trim(),
      stock_unit_options: stockUnitOpts,
      standard_units: standardUnitsDb,
    }

    const filterCode = editingCode || code
    const existing = (await supabaseSelectFilter(
      'items',
      `code=eq.${encodeURIComponent(filterCode)}`,
      { limit: 1 }
    )) as { id?: number; price?: number; cost?: number; name?: string; category?: string; image?: string }[] | null

    // 수정 시 폼 리셋/오류로 빈 값이 오면 기존 값 유지 (이미지·분류 누락 방지)
    if (existing && existing.length > 0) {
      const prev = existing[0] as { image?: string; category?: string }
      const incomingImage = String(body.imageUrl || '').trim()
      if (!incomingImage && prev.image != null && String(prev.image).trim()) {
        ;(row as Record<string, unknown>).image = String(prev.image).trim()
      }
      const incomingCategory = String(body.category || '').trim()
      if (!incomingCategory && prev.category != null && String(prev.category).trim()) {
        row.category = String(prev.category).trim()
      }
    }

    if (existing && existing.length > 0) {
      const prev = existing[0] as { price?: number; cost?: number; name?: string; category?: string }
      const cat = (prev.category || row.category || '').trim()
      const changes: { fieldName: string; oldValue: number | null; newValue: number | null }[] = []
      if (Number(prev.price) !== row.price) {
        changes.push({ fieldName: 'price', oldValue: prev.price ?? null, newValue: row.price as number })
      }
      if (Number(prev.cost) !== row.cost) {
        changes.push({ fieldName: 'cost', oldValue: prev.cost ?? null, newValue: row.cost as number })
      }
      if (changes.length > 0) {
        recordPriceChanges({
          entityType: 'item',
          entityId: filterCode,
          entityDisplayName: prev.name ?? name,
          changes,
          category: cat || undefined,
        }).catch(() => {})
      }
    }

    const tryWrite = async (payload: Record<string, unknown>) => {
      if (existing && existing.length > 0) {
        await supabaseUpdateByFilter('items', `code=eq.${encodeURIComponent(filterCode)}`, payload)
      } else {
        await supabaseInsert('items', payload)
        const price = Number(row.price) || 0
        const cost = Number(row.cost) || 0
        recordPriceChanges({
          entityType: 'item',
          entityId: filterCode,
          entityDisplayName: name,
          changes: [
            { fieldName: 'price', oldValue: null, newValue: price },
            { fieldName: 'cost', oldValue: null, newValue: cost },
          ],
          category: (row.category as string || '').trim() || undefined,
        }).catch(() => {})
      }
    }
    try {
      await tryWrite(row)
    } catch (colErr) {
      const errMsg = colErr instanceof Error ? colErr.message : String(colErr)
      if (/stock_base_unit|stock_unit_options|column.*does not exist/i.test(errMsg)) {
        const { stock_base_unit: _sbu, stock_unit_options: _suo, ...rowWithoutStock } = row
        await tryWrite(rowWithoutStock)
      } else {
        throw colErr
      }
    }
    return NextResponse.json({ success: true, message: existing?.length ? '수정되었습니다.' : '저장되었습니다.' }, { headers })
  } catch (e) {
    console.error('saveItem:', e)
    const errMsg = e instanceof Error ? e.message : String(e)
    const isDuplicateCode =
      errMsg.includes('23505') ||
      /duplicate key|unique constraint|items_code/i.test(errMsg)
    const message = isDuplicateCode
      ? `품목 코드 "${code || '(입력값)'}"가 이미 사용 중입니다. 다른 코드를 입력해 주세요.`
      : errMsg || '저장 실패'
    return NextResponse.json({ success: false, message }, { headers })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { postExpenseAccrualJournal } from '@/lib/accounting-posting'
import { assertAccountSubjectNotHeader } from '@/lib/account-subject-header-guard'
import { supabaseInsert, supabaseSelectFilter, supabaseUpdate, supabaseUpsert } from '@/lib/supabase-server'
import { requireAuth } from '@/lib/verify-auth'
import { parseOr400, savePayrollSchema } from '@/lib/api-validate'

const CHUNK = 50

type PayrollExpenseAccrualRow = {
  id?: number
  payee_code?: string
  status?: string
}

type AccountSubjectRow = {
  id?: number
  code?: string
  name?: string
  type?: string
}

export interface PayrollSaveRow {
  employeeId?: number
  employeeCode?: string
  store: string
  name: string
  dept?: string
  role?: string
  salary?: number
  posAllow?: number
  hazAllow?: number
  diligenceAllow?: number
  birthBonus?: number
  holidayPay?: number
  splBonus?: number
  ot15?: number
  ot20?: number
  ot30?: number
  otAmt?: number
  lateMin?: number
  lateDed?: number
  earlyMin?: number
  earlyDed?: number
  sso?: number
  tax?: number
  otherDed?: number
  netPay?: number
  status?: string
}

function toMonthDate(monthStr: string, useLastDay: boolean): string {
  const base = new Date(`${monthStr}-01T12:00:00`)
  if (Number.isNaN(base.getTime())) return `${monthStr}-01`
  if (!useLastDay) return `${monthStr}-01`
  const last = new Date(base.getFullYear(), base.getMonth() + 1, 0)
  return last.toISOString().slice(0, 10)
}

function normalizeToken(src: string): string {
  return String(src || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9가-힣]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40) || 'na'
}

function buildPayrollPayeeCode(monthStr: string, store: string, name: string, employeeToken?: string): string {
  const emp = normalizeToken(employeeToken || '')
  const suffix = emp && emp !== 'na' ? `-${emp}` : ''
  const base = `payroll-${monthStr}-${normalizeToken(store)}-${normalizeToken(name)}${suffix}`
  return `${base}::wm::expense`
}

async function resolvePayrollAccountSubject(): Promise<{ id: number | null; code: string; name: string }> {
  try {
    const rows = (await supabaseSelectFilter('account_subjects', 'type=eq.expense', {
      select: 'id,code,name,type,is_header',
      order: 'sort_order.asc,code.asc',
      limit: 400,
    })) as (AccountSubjectRow & { is_header?: boolean | null })[] | null
    const list = rows || []
    const picked = list.find((r) => {
      if (r.is_header === true) return false
      const text = `${String(r.code || '')} ${String(r.name || '')}`.toLowerCase()
      return text.includes('급여') || text.includes('salary') || text.includes('wage')
    })
    if (picked?.id) {
      return {
        id: Number(picked.id),
        code: String(picked.code || '5520'),
        name: String(picked.name || '인건비'),
      }
    }
  } catch (_) {}
  return { id: null, code: '5520', name: '인건비' }
}

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  const authResult = await requireAuth(request, 'manager')
  if (authResult.errorResponse) {
    authResult.errorResponse.headers.set('Access-Control-Allow-Origin', '*')
    return authResult.errorResponse
  }
  const { auth } = authResult

  try {
    const body = await request.json()
    const bodyForValidation = {
      ...body,
      list: body.list || body.rows || [],
      month: (body.month || body.monthStr || '').slice(0, 7),
    }
    const validated = parseOr400(savePayrollSchema, bodyForValidation, headers)
    if (validated.errorResponse) {
      validated.errorResponse.headers.set('Access-Control-Allow-Origin', '*')
      return validated.errorResponse
    }
    const { list: rawList, month: m, monthStr: ms } = validated.parsed
    const monthStr = (m || ms || '').slice(0, 7)
    let list = rawList as unknown as PayrollSaveRow[]
    const userStore = (auth.store || '').trim()
    const userRole = (auth.role || '').toLowerCase()
    if (userRole.includes('manager') && userStore) {
      list = list.filter((r) => String(r.store || '').trim() === userStore)
    }

    const rows: Record<string, unknown>[] = list.map((r) => ({
      month: monthStr,
      store: String(r.store || '').trim(),
      name: String(r.name || '').trim(),
      employee_id:
        r.employeeId != null && Number.isFinite(Number(r.employeeId)) && Number(r.employeeId) > 0
          ? Math.floor(Number(r.employeeId))
          : null,
      employee_code: String(r.employeeCode || '')
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '')
        .slice(0, 5),
      dept: String(r.dept || '').trim(),
      role: String(r.role || '').trim(),
      salary: Number(r.salary) || 0,
      pos_allow: Number(r.posAllow) || 0,
      haz_allow: Number(r.hazAllow) || 0,
      diligence_allow: Number(r.diligenceAllow) || 0,
      birth_bonus: Number(r.birthBonus) || 0,
      holiday_pay: Number(r.holidayPay) ?? 0,
      spl_bonus: Number(r.splBonus) || 0,
      ot_15: Number(r.ot15) || 0,
      ot_20: Number(r.ot20) || 0,
      ot_30: Number(r.ot30) || 0,
      ot_amt: Number(r.otAmt) || 0,
      late_min: Number(r.lateMin) || 0,
      late_ded: Number(r.lateDed) || 0,
      early_min: Number(r.earlyMin) ?? 0,
      early_ded: Number(r.earlyDed) ?? 0,
      sso: Number(r.sso) || 0,
      tax: Number(r.tax) || 0,
      other_ded: Number(r.otherDed) || 0,
      net_pay: Number(r.netPay) || 0,
      status: String(r.status || '확정').trim(),
    }))

    for (let j = 0; j < rows.length; j += CHUNK) {
      const chunk = rows.slice(j, j + CHUNK)
      const canUseEmployeeKey = chunk.every(
        (r) => r.employee_id != null && Number.isFinite(Number(r.employee_id)) && Number(r.employee_id) > 0
      )
      try {
        if (canUseEmployeeKey) {
          await supabaseUpsert('payroll_records', chunk, 'month,store,employee_id')
        } else {
          await supabaseUpsert('payroll_records', chunk, 'month,store,name')
        }
      } catch (e) {
        const em = e instanceof Error ? e.message : String(e)
        if (/employee_id|employee_code|42703|column/i.test(em)) {
          const fallbackChunk = chunk.map((r) => {
            const { employee_id: _eid, employee_code: _ecode, ...rest } = r
            return rest
          })
          await supabaseUpsert('payroll_records', fallbackChunk, 'month,store,name')
        } else if (canUseEmployeeKey) {
          // employee_id on_conflict 인덱스가 없으면 기존 키로 재시도
          await supabaseUpsert('payroll_records', chunk, 'month,store,name')
        } else {
          throw e
        }
      }
    }

    const expenseSubject = await resolvePayrollAccountSubject()
    if (expenseSubject.id != null) {
      const hdr = await assertAccountSubjectNotHeader(expenseSubject.id)
      if (!hdr.ok) {
        return NextResponse.json({ success: false, msg: hdr.message }, { status: hdr.status, headers })
      }
    }
    const expenseDate = toMonthDate(monthStr, false)
    const dueDate = toMonthDate(monthStr, true)
    const monthlyPrefix = `payroll-${monthStr}-`
    const existingAccrualRows = (await supabaseSelectFilter(
      'expense_accruals',
      `payee_code=ilike.${encodeURIComponent(`${monthlyPrefix}%::wm::expense`)}`,
      { select: 'id,payee_code,status', limit: 5000 }
    )) as PayrollExpenseAccrualRow[] | null
    const existingByPayeeCode = new Map<string, PayrollExpenseAccrualRow>()
    for (const row of existingAccrualRows || []) {
      const key = String(row.payee_code || '').trim()
      if (key) existingByPayeeCode.set(key, row)
    }

    let createdAccrualCount = 0
    let updatedAccrualCount = 0
    for (const r of list) {
      const netPay = Math.max(0, Number(r.netPay) || 0)
      const store = String(r.store || '').trim()
      const name = String(r.name || '').trim()
      const employeeCode = String(r.employeeCode || '').trim()
      const employeeId =
        r.employeeId != null && Number.isFinite(Number(r.employeeId)) ? Math.floor(Number(r.employeeId)) : 0
      const employeeToken = employeeCode || (employeeId > 0 ? `id${employeeId}` : '')
      if (!store || !name || netPay <= 0) continue

      const payeeCode = buildPayrollPayeeCode(monthStr, store, name, employeeToken)
      const memo = `[PAYROLL] ${monthStr} ${store} ${name} 급여`
      const existing = existingByPayeeCode.get(payeeCode)
      const existingId = Number(existing?.id || 0)
      const existingStatus = String(existing?.status || '').toLowerCase()
      if (existingId > 0) {
        if (existingStatus === 'paid') continue
        await supabaseUpdate('expense_accruals', existingId, {
          amount: netPay,
          expense_date: expenseDate,
          due_date: dueDate,
          memo,
          store_name: store,
          account_subject_id: expenseSubject.id,
          status: existingStatus === 'approved' ? 'approved' : 'planned',
          updated_at: new Date().toISOString(),
        })
        updatedAccrualCount++
        continue
      }

      const inserted = (await supabaseInsert('expense_accruals', {
        payee_code: payeeCode,
        payee_name: name,
        amount: netPay,
        expense_date: expenseDate,
        due_date: dueDate,
        memo,
        store_name: store,
        account_subject_id: expenseSubject.id,
        created_by: auth.name || null,
        status: 'planned',
      })) as { id?: number }[]
      const expenseAccrualId = Number(inserted?.[0]?.id || 0)
      if (!expenseAccrualId) continue

      await supabaseInsert('payable_transactions', {
        vendor_code: `EMP:${name}`.slice(0, 120),
        amount: netPay,
        ref_type: 'Expense',
        ref_id: null,
        trans_date: expenseDate,
        memo: `급여 발생 ${monthStr} ${name}`.slice(0, 200),
        expense_accrual_id: expenseAccrualId,
        account_subject_id: expenseSubject.id,
        expense_date: expenseDate,
        due_date: dueDate,
      })

      try {
        await postExpenseAccrualJournal({
          expenseAccrualId,
          accountingDate: expenseDate,
          amountAbs: netPay,
          expenseAccountCode: expenseSubject.code,
          expenseAccountName: expenseSubject.name,
          expenseAccountSubjectId: expenseSubject.id ?? null,
          memo,
          storeName: store || undefined,
          postedBy: auth.name || undefined,
        })
      } catch (postingErr) {
        console.error('savePayroll posting:', postingErr)
      }

      createdAccrualCount++
    }

    return NextResponse.json(
      {
        success: true,
        msg: `${monthStr} 급여 내역이 DB에 저장되었습니다.`,
        payrollExpenseSync: {
          created: createdAccrualCount,
          updated: updatedAccrualCount,
        },
      },
      { headers }
    )
  } catch (e) {
    console.error('savePayroll:', e)
    return NextResponse.json(
      { success: false, msg: '저장 실패: ' + (e instanceof Error ? e.message : String(e)) },
      { status: 500, headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseInsert, supabaseUpdateByFilter } from '@/lib/supabase-server'
import { recordPriceChanges } from '@/lib/price-history'

async function getMenuCategories(menuId: number): Promise<{ categoryMain: string; category: string }> {
  try {
    const menus = (await supabaseSelectFilter('pos_menus', `id=eq.${menuId}`, { limit: 1 })) as { category_main?: string; category?: string }[] | null
    if (menus && menus.length > 0) {
      const m = menus[0]
      return {
        categoryMain: (m.category_main || '').trim(),
        category: (m.category || '').trim(),
      }
    }
  } catch { /* ignore */ }
  return { categoryMain: '', category: '' }
}

/** POS 메뉴 옵션 저장 */
export async function POST(req: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const body = await req.json()
    const id = body?.id
    const menuId = Number(body?.menuId)
    const name = String(body?.name ?? '').trim()
    const priceModifier = Number(body?.priceModifier) ?? 0
    const priceModifierDelivery = body?.priceModifierDelivery != null ? Number(body.priceModifierDelivery) : null
    const priceModifierPackaging = body?.priceModifierPackaging != null ? Number(body.priceModifierPackaging) : null
    const sortOrder = Number(body?.sortOrder) ?? 0
    const optionType = (body?.optionType || 'substitution') as string
    const itemCode = body?.itemCode ? String(body.itemCode).trim() : null
    const rawAddMenu = body?.additiveSourceMenuId
    const parsedAddMenu =
      rawAddMenu != null && rawAddMenu !== '' ? Number(rawAddMenu) : NaN
    const additiveSourceMenuId =
      Number.isFinite(parsedAddMenu) && parsedAddMenu > 0 ? Math.floor(parsedAddMenu) : null
    const quantity = Math.max(0.001, Number(body?.quantity) ?? 1)
    const optionStepValues = body?.optionStepValues && typeof body.optionStepValues === 'object' && !Array.isArray(body.optionStepValues)
      ? (body.optionStepValues as Record<string, string>)
      : null
    const sellHall = body?.sellHall != null ? !!body.sellHall : true
    const sellDelivery = body?.sellDelivery != null ? !!body.sellDelivery : true
    const sellPackaging = body?.sellPackaging != null ? !!body.sellPackaging : true

    if (!menuId || !name) {
      return NextResponse.json({ success: false, message: 'menuId and name required' }, { headers })
    }

    const isAdditive = optionType === 'additive'
    const rowFull: Record<string, unknown> = {
      name,
      price_modifier: priceModifier,
      price_modifier_delivery: priceModifierDelivery,
      price_modifier_packaging: priceModifierPackaging,
      sort_order: sortOrder,
      option_type: isAdditive ? 'additive' : 'substitution',
      item_code:
        isAdditive && additiveSourceMenuId ? null : isAdditive && itemCode ? itemCode : null,
      additive_source_menu_id: isAdditive && additiveSourceMenuId ? additiveSourceMenuId : null,
      quantity: isAdditive ? quantity : 1,
      sell_hall: sellHall,
      sell_delivery: sellDelivery,
      sell_packaging: sellPackaging,
    }
    if (optionStepValues) rowFull.option_step_values = optionStepValues

    const rowMinimal: Record<string, unknown> = {
      name,
      price_modifier: priceModifier,
      sort_order: sortOrder,
    }

    const doSave = async (row: Record<string, unknown>): Promise<void> => {
      if (id) {
        const existing = (await supabaseSelectFilter(
          'pos_menu_options',
          `id=eq.${id}`,
          { limit: 1 }
        )) as { name?: string; price_modifier?: number; price_modifier_delivery?: number | null; price_modifier_packaging?: number | null }[] | null
        if (existing && existing.length > 0) {
          const prev = existing[0]
          const changes: { fieldName: string; oldValue: number | null; newValue: number | null }[] = []
          if (Number(prev.price_modifier) !== priceModifier) {
            changes.push({ fieldName: 'price_modifier', oldValue: prev.price_modifier ?? null, newValue: priceModifier })
          }
          if ((prev.price_modifier_delivery ?? null) !== priceModifierDelivery) {
            changes.push({ fieldName: 'price_modifier_delivery', oldValue: prev.price_modifier_delivery ?? null, newValue: priceModifierDelivery })
          }
          if ((prev.price_modifier_packaging ?? null) !== priceModifierPackaging) {
            changes.push({ fieldName: 'price_modifier_packaging', oldValue: prev.price_modifier_packaging ?? null, newValue: priceModifierPackaging })
          }
          if (changes.length > 0) {
            const { categoryMain, category } = await getMenuCategories(menuId)
            recordPriceChanges({
              entityType: 'pos_menu_option',
              entityId: String(id),
              entityDisplayName: prev.name ?? name,
              changes,
              category: category || undefined,
              categoryMain: categoryMain || undefined,
              parentEntityId: String(menuId),
            }).catch(() => {})
          }
        }
        await supabaseUpdateByFilter('pos_menu_options', `id=eq.${id}`, row)
      } else {
        const inserted = (await supabaseInsert('pos_menu_options', { menu_id: menuId, ...row })) as { id?: number }[] | { id?: number }
        const newRow = Array.isArray(inserted) ? inserted[0] : inserted
        const newId = newRow?.id != null ? String(newRow.id) : null
        if (newId) {
          const { categoryMain, category } = await getMenuCategories(menuId)
          const initChanges: { fieldName: string; oldValue: number | null; newValue: number | null }[] = []
          initChanges.push({ fieldName: 'price_modifier', oldValue: null, newValue: priceModifier })
          if (priceModifierDelivery != null) initChanges.push({ fieldName: 'price_modifier_delivery', oldValue: null, newValue: priceModifierDelivery })
          if (priceModifierPackaging != null) initChanges.push({ fieldName: 'price_modifier_packaging', oldValue: null, newValue: priceModifierPackaging })
          if (initChanges.length > 0) {
            recordPriceChanges({
              entityType: 'pos_menu_option',
              entityId: newId,
              entityDisplayName: name,
              changes: initChanges,
              category: category || undefined,
              categoryMain: categoryMain || undefined,
              parentEntityId: String(menuId),
            }).catch(() => {})
          }
        }
      }
    }

    try {
      await doSave(rowFull)
    } catch (err1) {
      const errStr = String(err1)
      const rowWithoutNew = { ...rowFull }
      delete rowWithoutNew.option_step_values
      delete rowWithoutNew.price_modifier_packaging
      delete rowWithoutNew.sell_hall
      delete rowWithoutNew.sell_delivery
      delete rowWithoutNew.sell_packaging
      delete rowWithoutNew.option_type
      delete rowWithoutNew.item_code
      delete rowWithoutNew.additive_source_menu_id
      delete rowWithoutNew.quantity
      if (priceModifierDelivery != null) (rowWithoutNew as Record<string, unknown>).price_modifier_delivery = priceModifierDelivery
      try {
        await doSave(rowWithoutNew)
      } catch (err2) {
        await doSave(rowMinimal)
      }
    }

    return NextResponse.json({ success: true }, { headers })
  } catch (e) {
    console.error('savePosMenuOption:', e)
    return NextResponse.json(
      { success: false, message: String(e) },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import {
  supabaseSelectFilter,
  supabaseInsert,
  supabaseUpdateByFilter,
} from '@/lib/supabase-server'
import { recordPriceChanges } from '@/lib/price-history'

/** POS 메뉴 저장 (등록/수정) */
export async function POST(req: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const body = (await req.json()) as {
      code?: string
      name?: string
      category?: string
      categoryMain?: string
      price?: number
      priceDelivery?: number | null
      imageUrl?: string
      vatIncluded?: boolean
      isActive?: boolean
      sortOrder?: number
      optionSelectionGroups?: string[]
      kitchenPrinter?: number | null
      cookingTimeMin?: number | null
      isBanban?: boolean
      id?: string
    }

    const code = String(body.code ?? '').trim()
    const name = String(body.name ?? '').trim()
    const editingId = body.id ? String(body.id).trim() : null

    if (!code || !name) {
      return NextResponse.json(
        { success: false, message: '코드와 메뉴명이 필요합니다.' },
        { headers }
      )
    }

    /** 필드 포함 시 빈 배열이어도 저장(다단계 해제). 미포함 시 기존처럼 컬럼 생략 */
    const optionSelectionGroupsExplicit = 'optionSelectionGroups' in body && Array.isArray(body.optionSelectionGroups)
    const optionSelectionGroupsCleaned = optionSelectionGroupsExplicit
      ? body.optionSelectionGroups!.map((x) => String(x).trim()).filter(Boolean)
      : null
    const optionSelectionGroupsLegacy =
      !optionSelectionGroupsExplicit && Array.isArray(body.optionSelectionGroups) && body.optionSelectionGroups.length > 0
        ? body.optionSelectionGroups.map((x) => String(x).trim()).filter(Boolean)
        : null
    const kitchenPrinter =
      body.kitchenPrinter === 0 ||
      body.kitchenPrinter === 1 ||
      body.kitchenPrinter === 2 ||
      body.kitchenPrinter === 3
        ? body.kitchenPrinter
        : null
    const cookingTimeMin = body.cookingTimeMin != null && Number.isFinite(body.cookingTimeMin) && body.cookingTimeMin >= 0 ? body.cookingTimeMin : null
    const isBanban = body.isBanban === true
    const baseRow: Record<string, unknown> = {
      code,
      name,
      category: String(body.category ?? '').trim(),
      category_main: String(body.categoryMain ?? '').trim(),
      price: Number(body.price) ?? 0,
      price_delivery: body.priceDelivery != null ? Number(body.priceDelivery) : null,
      image: String(body.imageUrl ?? '').trim(),
      vat_included: body.vatIncluded !== false,
      is_active: body.isActive !== false,
      sort_order: Number(body.sortOrder) ?? 0,
    }
    if (optionSelectionGroupsExplicit) {
      baseRow.option_selection_groups =
        optionSelectionGroupsCleaned && optionSelectionGroupsCleaned.length > 0 ? optionSelectionGroupsCleaned : []
    } else if (optionSelectionGroupsLegacy && optionSelectionGroupsLegacy.length > 0) {
      baseRow.option_selection_groups = optionSelectionGroupsLegacy
    }
    if (kitchenPrinter != null) baseRow.kitchen_printer = kitchenPrinter
    if (cookingTimeMin != null) baseRow.cooking_time_min = cookingTimeMin
    baseRow.is_banban = isBanban

    type ExistingMenuRow = {
      id?: number
      price?: number
      price_delivery?: number | null
      name?: string
      category_main?: string
      category?: string
      image?: string
      promo_id?: number | null
    }

    const doSave = async (row: Record<string, unknown>): Promise<{ success: boolean; message: string; newId?: string }> => {
      if (editingId) {
        let existing: ExistingMenuRow[] | null = null
        try {
          existing = (await supabaseSelectFilter(
            'pos_menus',
            `id=eq.${editingId}`,
            { limit: 1, select: 'id,price,price_delivery,name,category_main,category,image,promo_id' }
          )) as ExistingMenuRow[] | null
        } catch {
          existing = (await supabaseSelectFilter(
            'pos_menus',
            `id=eq.${editingId}`,
            { limit: 1 }
          )) as ExistingMenuRow[] | null
        }
        if (existing && existing.length > 0) {
          const prev = existing[0]
          const pid = prev.promo_id
          if (pid != null && Number(pid) > 0) {
            return {
              success: false,
              message: '프로모션과 연동된 메뉴는 마케팅 > 프로모션 관리에서 수정하세요.',
            }
          }
          // 수정 시 이미지 URL이 비어 있으면 기존 이미지 유지 (폼 리셋/오류로 빈 값 저장 방지)
          const incomingImage = String(body.imageUrl ?? '').trim()
          if (!incomingImage && prev.image != null && String(prev.image).trim()) {
            row.image = String(prev.image).trim()
          }
          const catMain = (prev.category_main || '').trim()
          const cat = (prev.category || '').trim()
          const changes: { fieldName: string; oldValue: number | null; newValue: number | null }[] = []
          const newPrice = Number(row.price ?? prev.price ?? 0)
          const newPriceDelivery = row.price_delivery != null ? Number(row.price_delivery) : null
          if (Number(prev.price) !== newPrice) {
            changes.push({ fieldName: 'price', oldValue: prev.price ?? null, newValue: newPrice })
          }
          if ((prev.price_delivery ?? null) !== newPriceDelivery) {
            changes.push({ fieldName: 'price_delivery', oldValue: prev.price_delivery ?? null, newValue: newPriceDelivery })
          }
          if (changes.length > 0) {
            recordPriceChanges({
              entityType: 'pos_menu',
              entityId: editingId,
              entityDisplayName: prev.name ?? code,
              changes,
              category: cat || undefined,
              categoryMain: catMain || undefined,
            }).catch(() => {})
          }
          try {
            await supabaseUpdateByFilter('pos_menus', `id=eq.${editingId}`, row)
          } catch (colErr: unknown) {
            if (String(colErr).includes('category_main') || String(colErr).includes('42703') || String(colErr).includes('is_banban')) {
              const rowWithout = { ...row } as Record<string, unknown>
              if (String(colErr).includes('category_main')) delete rowWithout.category_main
              if (String(colErr).includes('is_banban')) delete rowWithout.is_banban
              await supabaseUpdateByFilter('pos_menus', `id=eq.${editingId}`, rowWithout)
            } else throw colErr
          }
          return { success: true, message: '수정되었습니다.' }
        }
      }

      const codeExists = (await supabaseSelectFilter(
        'pos_menus',
        `code=eq.${encodeURIComponent(code)}`,
        { limit: 1 }
      )) as { id?: number }[] | null
      if (codeExists && codeExists.length > 0 && !editingId) {
        return { success: false, message: '이미 존재하는 메뉴 코드입니다.' }
      }

      try {
        const inserted = (await supabaseInsert('pos_menus', row)) as { id?: number }[] | { id?: number }
        const newRow = Array.isArray(inserted) ? inserted[0] : inserted
        const newId = newRow?.id != null ? String(newRow.id) : undefined
        if (newId && (baseRow.price != null || body.price != null)) {
          const catMain = (baseRow.category_main as string || '').trim()
          const cat = (baseRow.category as string || '').trim()
          const initChanges: { fieldName: string; oldValue: number | null; newValue: number | null }[] = []
          const price = Number(baseRow.price ?? body.price ?? 0)
          const priceDelivery = baseRow.price_delivery != null ? Number(baseRow.price_delivery) : (body.priceDelivery != null ? Number(body.priceDelivery) : null)
          initChanges.push({ fieldName: 'price', oldValue: null, newValue: price })
          if (priceDelivery != null) initChanges.push({ fieldName: 'price_delivery', oldValue: null, newValue: priceDelivery })
          recordPriceChanges({
            entityType: 'pos_menu',
            entityId: newId,
            entityDisplayName: name,
            changes: initChanges,
            category: cat || undefined,
            categoryMain: catMain || undefined,
          }).catch(() => {})
        }
        return { success: true, message: '저장되었습니다.', newId }
      } catch (insErr: unknown) {
        if (String(insErr).includes('category_main') || String(insErr).includes('42703')) {
          const { category_main: _cm, ...rowWithout } = row
          const inserted = (await supabaseInsert('pos_menus', rowWithout)) as { id?: number }[] | { id?: number }
          const newRow = Array.isArray(inserted) ? inserted[0] : inserted
          const newId = newRow?.id != null ? String(newRow.id) : undefined
          if (newId && (baseRow.price != null || body.price != null)) {
            const cat = (baseRow.category as string || '').trim()
            const price = Number(baseRow.price ?? body.price ?? 0)
            recordPriceChanges({
              entityType: 'pos_menu',
              entityId: newId,
              entityDisplayName: name,
              changes: [{ fieldName: 'price', oldValue: null, newValue: price }],
              category: cat || undefined,
            }).catch(() => {})
          }
          return { success: true, message: '저장되었습니다.', newId }
        }
        throw insErr
      }
    }

    try {
      const result = await doSave(baseRow)
      if (result.success && code && (baseRow.price != null || body.price != null)) {
        const newPrice = Number(baseRow.price ?? body.price ?? 0)
        try {
          await supabaseUpdateByFilter(
            'items',
            `code=eq.${encodeURIComponent(code)}`,
            { price: newPrice }
          )
        } catch {
          // items에 해당 code가 없으면 무시
        }
      }
      return NextResponse.json(result, { headers })
    } catch (saveErr: unknown) {
      const err = String(saveErr)
      if (
        optionSelectionGroupsExplicit &&
        (err.includes('option_selection_groups') || err.includes('option selection'))
      ) {
        return NextResponse.json(
          {
            success: false,
            message:
              'option_selection_groups 저장에 실패했습니다. Supabase pos_menus 테이블에 option_selection_groups 컬럼이 있는지 확인하세요.',
          },
          { headers }
        )
      }
      if ((optionSelectionGroupsExplicit || optionSelectionGroupsLegacy || kitchenPrinter != null || cookingTimeMin != null || isBanban) && (err.includes('option_selection_groups') || err.includes('kitchen_printer') || err.includes('cooking_time_min') || err.includes('is_banban') || err.includes('42703'))) {
        const rowWithout = { ...baseRow }
        delete rowWithout.option_selection_groups
        delete rowWithout.kitchen_printer
        delete rowWithout.cooking_time_min
        delete rowWithout.is_banban
        const result = await doSave(rowWithout)
        return NextResponse.json(result, { headers })
      }
      throw saveErr
    }
  } catch (e) {
    console.error('savePosMenu:', e)
    return NextResponse.json(
      { success: false, message: e instanceof Error ? e.message : '저장 실패' },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelectFilter, supabaseDeleteByFilter, supabaseInsertMany } from '@/lib/supabase-server'
import {
  findStaffForScheduleSlotName,
  formatEmployeeDisplayName,
  normalizeEmployeeCodeForMatch,
  normalizeEmployeeNameFields,
  type StaffRowForScheduleMatch,
} from '@/lib/employee-display-name'

/** 타임존 영향 없이 로컬 날짜만 사용 (toISOString 시 UTC로 밀릴 수 있음 방지) */
function addDays(dateStr: string, days: number): string {
  const m = dateStr.trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)
  if (!m) return dateStr
  const d = new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10))
  d.setDate(d.getDate() + days)
  const y = d.getFullYear()
  const mo = String(d.getMonth() + 1).padStart(2, '0')
  const da = String(d.getDate()).padStart(2, '0')
  return `${y}-${mo}-${da}`
}

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Access-Control-Allow-Methods', 'POST, OPTIONS')
  headers.set('Access-Control-Allow-Headers', 'Content-Type')

  if (request.method === 'OPTIONS') {
    return new NextResponse(null, { status: 204, headers })
  }

  try {
    const body = await request.json()
    const store = String(body?.store || body?.storeName || '').trim()
    const monday = String(body?.monday || body?.mondayStr || '').trim().slice(0, 10)
    const rows = Array.isArray(body?.rows || body?.scheduleArray) ? (body.rows || body.scheduleArray) : []

    if (!store || !monday) {
      return NextResponse.json(
        { success: false, message: '매장과 기준 월요일이 필요합니다.' },
        { headers }
      )
    }

    const startStr = monday
    const endStr = addDays(monday, 6)

    const existingFilter = `schedule_date=gte.${startStr}&schedule_date=lte.${endStr}&store_name=ilike.${encodeURIComponent(store)}`
    await supabaseDeleteByFilter('schedules', existingFilter)

    if (rows.length === 0) {
      return NextResponse.json(
        { success: true, message: `${store} 해당 주 시간표가 삭제되었습니다.` },
        { headers }
      )
    }

    type EmpRow = { id?: number; name?: string; nick?: string; name_title?: string; employee_code?: string | null }
    const empSelectCandidates = [
      'id,name,nick,name_title,employee_code',
      'id,name,nick,name_title',
      'id,name,nick',
      'id,name',
    ] as const
    let employeeRows: EmpRow[] = []
    for (const sel of empSelectCandidates) {
      try {
        employeeRows = (await supabaseSelectFilter('employees', `store=ilike.${encodeURIComponent(store)}`, {
          select: sel,
          limit: 5000,
          order: 'id.asc',
        })) as EmpRow[]
        break
      } catch {
        continue
      }
    }

    function toStaffLite(e: EmpRow): StaffRowForScheduleMatch {
      const rawName = String(e.name || '').trim()
      const rawTitle = String(e.name_title || '').trim()
      const { name: normName } = normalizeEmployeeNameFields(rawName, rawTitle)
      const nickVal = String(e.nick || normName || rawName).trim() || rawName
      return { name: normName || rawName, nick: nickVal }
    }

    const nameKeyToId = new Map<string, number>()
    const idByCode = new Map<string, number>()
    const roster: { id: number; lite: StaffRowForScheduleMatch }[] = []
    for (const e of employeeRows || []) {
      const idNum = e.id != null && Number.isFinite(Number(e.id)) ? Math.floor(Number(e.id)) : 0
      if (idNum <= 0) continue
      const rawName = String(e.name || '').trim()
      const rawTitle = String(e.name_title || '').trim()
      const { name: normName } = normalizeEmployeeNameFields(rawName, rawTitle)
      const lite = toStaffLite(e)
      roster.push({ id: idNum, lite })
      const addNameKey = (k: string) => {
        const lo = String(k || '').trim().toLowerCase()
        if (!lo) return
        if (!nameKeyToId.has(lo)) nameKeyToId.set(lo, idNum)
      }
      addNameKey(rawName)
      addNameKey(normName)
      addNameKey(formatEmployeeDisplayName(normName, rawTitle))
      const nickOnly = String(e.nick || '').trim()
      if (nickOnly) addNameKey(nickOnly)
      const ck = normalizeEmployeeCodeForMatch(String(e.employee_code ?? ''))
      if (ck) idByCode.set(ck, idNum)
    }

    function resolveEmployeeId(slotName: string): number | null {
      const n = String(slotName || '').trim()
      if (!n) return null
      const lo = n.toLowerCase()
      if (nameKeyToId.has(lo)) return nameKeyToId.get(lo)!
      const ck = normalizeEmployeeCodeForMatch(n)
      if (ck && idByCode.has(ck)) return idByCode.get(ck)!
      const hit = findStaffForScheduleSlotName(
        roster.map((r) => r.lite),
        n
      )
      if (!hit) return null
      const row = roster.find((r) => r.lite.name === hit.name && r.lite.nick === hit.nick)
      return row ? row.id : null
    }

    // (schedule_date, store_name, name) 유니크: 한 직원은 같은 날 주방 또는 서비스 한 곳만 배정 가능
    const seen = new Map<string, string>()
    const duplicates: { name: string; date: string }[] = []
    for (const s of rows) {
      const dateStr = String(s.date || '').trim().slice(0, 10)
      if (!dateStr) continue
      const name = String(s.name || '').trim()
      if (!name) continue
      const key = `${dateStr}|${store}|${name}`
      const area = String(s.remark || s.memo || '').trim() || ''
      if (seen.has(key)) {
        const firstArea = seen.get(key) || ''
        if (!duplicates.some((d) => d.name === name && d.date === dateStr)) {
          duplicates.push({ name, date: dateStr })
        }
      } else {
        seen.set(key, area)
      }
    }
    if (duplicates.length > 0) {
      const namesList = [...new Set(duplicates.map((d) => d.name))].join(', ')
      return NextResponse.json(
        {
          success: false,
          message: 'schedule_dup_area',
          duplicateNames: namesList,
          duplicateCount: duplicates.length,
        },
        { headers }
      )
    }

    const toInsert: Record<string, unknown>[] = []
    for (const s of rows) {
      const dateStr = String(s.date || '').trim().slice(0, 10)
      if (!dateStr) continue
      const name = String(s.name || '').trim()
      if (!name) continue
      toInsert.push({
        schedule_date: dateStr,
        store_name: store,
        name,
        employee_id: resolveEmployeeId(name) || null,
        plan_in: String(s.pIn || s.plan_in || '09:00').trim(),
        plan_out: String(s.pOut || s.plan_out || '18:00').trim(),
        break_start: String(s.pBS || s.break_start || '').trim(),
        break_end: String(s.pBE || s.break_end || '').trim(),
        plan_in_prev_day: !!s.plan_in_prev_day,
        memo: String(s.remark || s.memo || '').trim() || '스마트스케줄러',
      })
    }

    if (toInsert.length > 0) {
      const CHUNK = 50
      for (let k = 0; k < toInsert.length; k += CHUNK) {
        const chunk = toInsert.slice(k, k + CHUNK)
        try {
          await supabaseInsertMany('schedules', chunk)
        } catch (e) {
          const em = e instanceof Error ? e.message : String(e)
          if (/employee_id|42703|column/i.test(em)) {
            const fallbackChunk = chunk.map((r) => {
              const { employee_id: _eid, ...rest } = r
              return rest
            })
            await supabaseInsertMany('schedules', fallbackChunk)
          } else {
            throw e
          }
        }
      }
    }

    return NextResponse.json(
      { success: true, message: `${store} 주간 시간표가 저장되었습니다!` },
      { headers }
    )
  } catch (e) {
    console.error('saveSchedule:', e)
    return NextResponse.json(
      {
        success: false,
        message: '저장 실패: ' + (e instanceof Error ? e.message : String(e)),
      },
      { headers }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter } from '@/lib/supabase-server'

/**
 * 선택한 급여 명세서 이메일 일괄 발송.
 * Apps Script sendPayrollStatementEmailBatch와 동일 기능.
 * RESEND_API_KEY 설정 시 실제 발송, 미설정 시 준비 중 메시지 반환.
 */
export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')

  try {
    const body = await request.json()
    const monthStr = String(body?.monthStr || '').trim().slice(0, 7)
    const list = Array.isArray(body?.list) ? body.list : []
    const userStore = String(body?.userStore || '').trim()
    const userRole = (String(body?.userRole || '').toLowerCase())

    if (!monthStr || monthStr.length < 7) {
      return NextResponse.json(
        { sent: 0, failed: [], msg: '조회월이 없습니다. 먼저 조회하기를 실행해 주세요.' },
        { status: 400, headers }
      )
    }
    if (list.length === 0) {
      return NextResponse.json(
        { sent: 0, failed: [], msg: '발송할 대상이 없습니다. 행의 체크박스를 선택해 주세요.' },
        { status: 400, headers }
      )
    }

    const resendKey = (process.env.RESEND_API_KEY || '').trim()
    if (!resendKey) {
      return NextResponse.json({
        sent: 0,
        failed: list.map((r: { store?: string; name?: string }) => r.name || r.store || '?'),
        msg: '이메일 발송 기능이 아직 설정되지 않았습니다. RESEND_API_KEY를 환경 변수에 추가해 주세요. (resend.com)',
      }, { headers })
    }

    // 직원 이메일 조회 (employees 테이블)
    const employees = (await supabaseSelect('employees', { order: 'id.asc', limit: 2000, select: 'store,name,email' })) as { store?: string; name?: string; email?: string }[]
    const emailMap = new Map<string, string>()
    for (const e of employees || []) {
      if (e.store && e.name && e.email) {
        const key = `${String(e.store).trim()}|${String(e.name).trim()}`
        emailMap.set(key, String(e.email).trim())
      }
    }

    // 급여 데이터 조회
    const payrollRows = (await supabaseSelectFilter(
      'payroll_records',
      `month=eq.${encodeURIComponent(monthStr)}`,
      { order: 'store.asc,name.asc', limit: 1000 }
    )) as Record<string, unknown>[]

    const payrollMap = new Map<string, Record<string, unknown>>()
    for (const p of payrollRows || []) {
      const store = String(p.store || '').trim()
      const name = String(p.name || '').trim()
      if (store || name) payrollMap.set(`${store}|${name}`, p)
    }

    const sent: string[] = []
    const failed: string[] = []
    const errors: string[] = []

    for (const item of list) {
      const store = String(item?.store || '').trim()
      const name = String(item?.name || '').trim()
      const key = `${store}|${name}`
      const email = emailMap.get(key)
      const p = payrollMap.get(key)

      if (!email) {
        failed.push(name || store || '?')
        errors.push((name || store) + ': 해당 직원의 이메일이 직원정보에 등록되어 있지 않습니다.')
        continue
      }
      if (!p) {
        failed.push(name || store || '?')
        errors.push((name || store) + ': 해당 월·매장·이름의 급여 내역이 없습니다.')
        continue
      }

      try {
        const html = buildPayrollEmailHtml(p, monthStr)
        const subject = `[Payroll Statement] ${formatMonthEn(monthStr)} - ${name}`
        const res = await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${resendKey}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            from: process.env.RESEND_FROM || 'onboarding@resend.dev',
            to: email,
            subject,
            html,
          }),
        })
        const data = (await res.json()) as { id?: string; message?: string; statusCode?: number }
        if (res.ok && data.id) {
          sent.push(name || store)
        } else {
          const errMsg = data.message || `HTTP ${res.status}` || '발송 실패'
          failed.push(name || store || '?')
          errors.push((name || store) + ': ' + errMsg)
          console.error('Resend API error:', res.status, errMsg, data)
        }
      } catch (e) {
        failed.push(name || store || '?')
        errors.push((name || store) + ': ' + (e instanceof Error ? e.message : String(e)))
      }
    }

    const msg = sent.length > 0
      ? `발송 완료: ${sent.length}명`
      : failed.length > 0
        ? (errors[0] || '발송 실패')
        : ''
    return NextResponse.json({
      sent: sent.length,
      failed,
      errors: errors.slice(0, 10),
      msg,
    }, { headers })
  } catch (e) {
    console.error('sendPayrollStatementEmail:', e)
    return NextResponse.json(
      {
        sent: 0,
        failed: [],
        msg: '이메일 발송 중 오류가 발생했습니다: ' + (e instanceof Error ? e.message : String(e)),
      },
      { status: 500, headers }
    )
  }
}

function formatMonthEn(monthStr: string): string {
  if (!monthStr || monthStr.length < 7) return monthStr
  const [, m] = monthStr.split('-')
  const months = ['', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
  return (months[parseInt(m, 10) || 0] || m) + ' ' + monthStr.slice(0, 4)
}

function buildPayrollEmailHtml(p: Record<string, unknown>, monthStr: string): string {
  const salary = Number(p.salary) || 0
  const posAllow = Number(p.pos_allow ?? p.posAllow) || 0
  const hazAllow = Number(p.haz_allow ?? p.hazAllow) || 0
  const birthBonus = Number(p.birth_bonus ?? p.birthBonus) || 0
  const holidayPay = Number(p.holiday_pay ?? p.holidayPay) || 0
  const splBonus = Number(p.spl_bonus ?? p.splBonus) || 0
  const otAmt = Number(p.ot_amt ?? p.otAmt) || 0
  const lateDed = Number(p.late_ded ?? p.lateDed) || 0
  const sso = Number(p.sso) || 0
  const tax = Number(p.tax) || 0
  const otherDed = Number(p.other_ded ?? p.otherDed) || 0
  const netPay = Number(p.net_pay ?? p.netPay) || 0
  const totalAllow = posAllow + hazAllow + birthBonus + holidayPay + splBonus
  const totalDed = lateDed + sso + tax + otherDed
  const yearMonth = formatMonthEn(monthStr)
  const fmt = (n: number) => n.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })

  return `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:'Segoe UI',Arial,sans-serif;color:#1e293b;line-height:1.5;max-width:560px;margin:0 auto;">
<div style="padding:20px;">
<h2 style="color:#0f172a;margin-bottom:8px;">Payroll Statement</h2>
<p style="color:#64748b;margin-bottom:20px;">${yearMonth} - ${p.name || ''} (${p.store || ''})</p>
<table style="width:100%;border-collapse:collapse;border:1px solid #e2e8f0;">
<tr style="background:#f8fafc;"><td style="padding:8px;border:1px solid #e2e8f0;"><b>Earnings</b></td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;"></td></tr>
<tr><td style="padding:8px;border:1px solid #e2e8f0;">Base Salary</td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;">${fmt(salary)} THB</td></tr>
<tr><td style="padding:8px;border:1px solid #e2e8f0;">Position + Risk + Birth + Holiday + Bonus</td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;">+${fmt(totalAllow)} THB</td></tr>
<tr><td style="padding:8px;border:1px solid #e2e8f0;">OT</td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;">+${fmt(otAmt)} THB</td></tr>
<tr style="background:#fef2f2;"><td style="padding:8px;border:1px solid #e2e8f0;"><b>Deductions</b></td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;"></td></tr>
<tr><td style="padding:8px;border:1px solid #e2e8f0;">Late + SSO + Tax + Other</td><td style="padding:8px;border:1px solid #e2e8f0;text-align:right;">-${fmt(totalDed)} THB</td></tr>
<tr style="background:#e0f2fe;"><td style="padding:12px;border:1px solid #e2e8f0;"><b>Net Pay</b></td><td style="padding:12px;border:1px solid #e2e8f0;text-align:right;color:#0c4a6e;font-size:1.1em;"><b>${fmt(netPay)} THB</b></td></tr>
</table>
<p style="margin-top:24px;font-size:12px;color:#94a3b8;">CHOONGMAN ERP - Payroll</p>
</div></body></html>`
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseSelect, supabaseSelectFilter, supabaseInsert } from '@/lib/supabase-server'
import { parseOr400, submitAttendanceSchema } from '@/lib/api-validate'
const TZ = 'Asia/Bangkok'

function todayStr() {
  return new Date().toLocaleDateString('en-CA', { timeZone: TZ })
}

/** 방콕 기준 현재 시(hour) 0~23. 자정 넘김 퇴근 판별용 */
function getBangkokHour(): number {
  const str = new Date().toLocaleTimeString('en-US', { timeZone: TZ, hour: '2-digit', hour12: false })
  return parseInt(str, 10) || 0
}

/** 날짜 YYYY-MM-DD에 delta일 더한 날짜 */
function addDays(dateStr: string, delta: number): string {
  const d = new Date(dateStr + 'T12:00:00')
  d.setDate(d.getDate() + delta)
  return d.toISOString().slice(0, 10)
}

function calcDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371e3
  const radLat1 = (lat1 * Math.PI) / 180
  const radLat2 = (lat2 * Math.PI) / 180
  const diffLat = ((lat2 - lat1) * Math.PI) / 180
  const diffLon = ((lon2 - lon1) * Math.PI) / 180
  const a =
    Math.sin(diffLat / 2) ** 2 +
    Math.cos(radLat1) * Math.cos(radLat2) * Math.sin(diffLon / 2) ** 2
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return R * c
}

/**
 * 계획 시각(planVal, 예: "18:00", "02:00")을 dateStr 날짜와 합쳐 방콕 기준 Date 생성.
 * 서버가 UTC라도 plan은 방콕 시각으로 해석해 비교 시 정확한 earlyMin/otMin 산출.
 */
function parsePlanTimeToDate(
  dateStr: string,
  planVal: string | unknown
): Date | null {
  if (!dateStr || planVal == null || (typeof planVal === 'string' && planVal.trim() === ''))
    return null
  const s = String(planVal).trim()
  if (!s) return null
  const m = s.match(/(\d{1,2})\s*:\s*(\d{1,2})(?:\s*:\s*(\d{1,2}))?/)
  if (!m) return null
  let h = parseInt(m[1], 10)
  const mn = parseInt(m[2], 10)
  const sec = m[3] ? parseInt(m[3], 10) : 0
  let useDateStr = dateStr.trim().slice(0, 10)
  if (h >= 24) {
    const d = new Date(useDateStr + 'T12:00:00Z')
    if (isNaN(d.getTime())) return null
    d.setUTCDate(d.getUTCDate() + 1)
    useDateStr = d.toISOString().slice(0, 10)
    h = h % 24
  }
  // 방콕(UTC+7) 시각으로 해석: "YYYY-MM-DDTHH:mm:ss+07:00"
  const iso = `${useDateStr}T${String(h).padStart(2, '0')}:${String(mn).padStart(2, '0')}:${String(sec).padStart(2, '0')}+07:00`
  const d = new Date(iso)
  return isNaN(d.getTime()) ? null : d
}

function safeMinutes(val: number): number {
  const n = Number(val)
  if (typeof n !== 'number' || isNaN(n) || !isFinite(n)) return 0
  return Math.floor(n)
}

export async function POST(request: NextRequest) {
  const headers = new Headers()
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Access-Control-Allow-Methods', 'POST, OPTIONS')
  headers.set('Access-Control-Allow-Headers', 'Content-Type')
  if (request.method === 'OPTIONS') return new NextResponse(null, { status: 204, headers })

  try {
    const raw = await request.json()
    const bodyForValidation = { ...raw, storeName: raw.storeName || raw.store || '' }
    const validated = parseOr400(submitAttendanceSchema, bodyForValidation, headers)
    if (validated.errorResponse) return validated.errorResponse
    const { storeName, name: empNameRaw, type: logType, employeeId } = validated.parsed
    const dataLat = validated.parsed.lat ?? raw.lat
    const dataLng = validated.parsed.lng ?? raw.lng
    let empName = String(empNameRaw || '').trim()
    const empId = employeeId != null && Number.isFinite(Number(employeeId)) ? Math.floor(Number(employeeId)) : 0
    if (empId > 0) {
      const empRows = (await supabaseSelectFilter(
        'employees',
        `id=eq.${empId}&store=ilike.${encodeURIComponent(storeName)}`,
        { limit: 1, select: 'id,name' }
      )) as { id?: number; name?: string }[]
      const er = empRows?.[0]
      if (!er) {
        return NextResponse.json(
          { success: false, message: '직원 정보를 확인할 수 없습니다. 다시 로그인 후 시도해 주세요.' },
          { headers }
        )
      }
      if (String(er.name || '').trim()) empName = String(er.name || '').trim()
    }

    const todayStrVal = todayStr()
    const nowTime = new Date()

    const oncePerDayTypes = ['출근', '퇴근', '휴식시작', '휴식종료']
    if (oncePerDayTypes.includes(logType)) {
      const logFilter =
        empId > 0
          ? `store_name=ilike.${encodeURIComponent(storeName)}&employee_id=eq.${empId}`
          : `store_name=ilike.${encodeURIComponent(storeName)}&name=ilike.${encodeURIComponent(empName)}`
      const logs = (await supabaseSelectFilter('attendance_logs', logFilter, {
        order: 'log_at.desc',
        limit: 100,
        select: 'log_at,log_type',
      })) as { log_at?: string; log_type?: string }[]
      const todayLogs = (logs || []).filter((r) => {
        const rowDate = r.log_at ? new Date(r.log_at).toLocaleDateString('en-CA', { timeZone: TZ }) : ''
        return rowDate === todayStrVal
      })
      if (logType === '퇴근') {
        // [퇴근 특별 처리] 퇴근→출근 시나리오(실수로 퇴근 먼저 누른 경우): 새 근무 세션으로 간주하여 퇴근 재기록 허용
        const lastOut = todayLogs.find((r) => String(r.log_type || '').trim() === '퇴근')
        const lastIn = todayLogs.find((r) => String(r.log_type || '').trim() === '출근')
        if (lastOut && lastIn && new Date(lastIn.log_at!).getTime() > new Date(lastOut.log_at!).getTime()) {
          // 출근이 퇴근보다 더 최근 → 퇴근 후 재출근한 새 세션 → 퇴근 허용
        } else if (lastOut) {
          return NextResponse.json(
            { success: false, message: '오늘 이미 [퇴근] 기록이 있습니다. 하루에 한 번만 기록할 수 있습니다.' },
            { headers }
          )
        }
      } else {
        const hasDuplicate = todayLogs.some((r) => String(r.log_type || '').trim() === logType)
        if (hasDuplicate) {
          return NextResponse.json(
            { success: false, message: `오늘 이미 [${logType}] 기록이 있습니다. 하루에 한 번만 기록할 수 있습니다.` },
            { headers }
          )
        }
      }
      // 퇴근·휴식시작·휴식종료(재개)는 출근 기록이 있어야만 기록 가능
      // 1) 당일 출근, 2) 자정 넘김 00~07시: 전날 출근, 3) 미종료 세션: 전날 출근 후 퇴근 누락 → 익일 퇴근 허용
      if (logType === '퇴근' || logType === '휴식시작' || logType === '휴식종료') {
        const bangkokHour = getBangkokHour()
        const validDates = [todayStrVal]
        if (bangkokHour >= 0 && bangkokHour <= 7) {
          validDates.push(addDays(todayStrVal, -1))
        }
        const hasInValidDate = (logs || []).some(
          (r) => {
            const rowDate = r.log_at ? new Date(r.log_at).toLocaleDateString('en-CA', { timeZone: TZ }) : ''
            return validDates.includes(rowDate) && String(r.log_type || '').trim() === '출근'
          }
        )
        // 퇴근만: 미종료 세션(출근 후 퇴근 없음)이면 전날 출근도 인정 (getTodayAttendanceTypes와 동일한 오픈 세션 판단)
        let hasOpenSession = false
        if (logType === '퇴근' && !hasInValidDate) {
          const lastOut = (logs || []).find((r) => String(r.log_type || '').trim() === '퇴근')
          const lastIn = (logs || []).find((r) => String(r.log_type || '').trim() === '출근')
          hasOpenSession = !!lastIn && (!lastOut || new Date(lastIn.log_at!).getTime() > new Date(lastOut.log_at!).getTime())
        }
        if (!hasInValidDate && !hasOpenSession) {
          return NextResponse.json(
            {
              success: false,
              message: '출근을 먼저 기록해 주세요. 오늘 출근 기록이 없으면 휴식·재개·퇴근을 기록할 수 없습니다.',
            },
            { headers }
          )
        }
      }
    }

    let targetLat = 0,
      targetLng = 0,
      locationOk = false
    const vendors = (await supabaseSelect('vendors', { limit: 2000 })) as {
      id?: number
      gps_name?: string
      name?: string
      type?: string
      lat?: string | number
      lng?: string | number
    }[]
    const storeNorm = String(storeName || '').trim().toLowerCase()
    // 매칭 후보: 직원 store + CM 접두사 변형 (CM Office ↔ Office 등)
    const storeCandidates = [storeNorm]
    if (storeNorm.startsWith('cm ')) {
      storeCandidates.push(storeNorm.replace(/^cm\s+/, '').trim())
    } else if (storeNorm) {
      storeCandidates.push('cm ' + storeNorm)
    }
    const isOfficeStore = storeNorm.includes('office') || storeNorm.includes('오피스') || storeNorm.includes('본사') || storeNorm.includes('본점')
    // gps_name/name이 후보 중 하나와 일치할 때 매칭
    for (const v of vendors || []) {
      const gpsName = String(v.gps_name || '').trim()
      const name = String(v.name || '').trim()
      const gpsLower = gpsName.toLowerCase()
      const nameLower = name.toLowerCase()
      const matched =
        storeCandidates.some((c) => gpsLower === c) ||
        (gpsName === '' && storeCandidates.some((c) => nameLower === c))
      if (matched) {
        const lat = Number(v.lat) || 0
        const lng = Number(v.lng) || 0
        if (lat !== 0 || lng !== 0) {
          targetLat = lat
          targetLng = lng
          break
        }
      }
    }
    // 오피스 매장인데 위에서 매칭 안 됐으면, 본사(type=본사/Head Office) 좌표 사용
    if (targetLat === 0 && targetLng === 0 && isOfficeStore) {
      const headOffice = (vendors || []).find(
        (v) => String(v.type || '').toLowerCase().includes('본사') || String(v.type || '').toLowerCase().includes('head office')
      )
      if (headOffice) {
        const lat = Number(headOffice.lat) || 0
        const lng = Number(headOffice.lng) || 0
        if (lat !== 0 || lng !== 0) {
          targetLat = lat
          targetLng = lng
        }
      }
    }
    const userGpsInvalid = dataLat === 'Unknown' || dataLat === '' || dataLng === '' || dataLng === 'Unknown'
    if (targetLat !== 0 || targetLng !== 0) {
      // 매장에 GPS 등록된 경우: 사용자 GPS 필수 (원격 출근/퇴근 방지)
      if (userGpsInvalid) {
        return NextResponse.json(
          {
            success: false,
            message: `❌ 위치 확인 실패! GPS를 켜고 매장 근처에서 다시 시도해 주세요. (현재 위치를 확인할 수 없습니다)`,
          },
          { headers }
        )
      }
      const dist = calcDistance(
        targetLat,
        targetLng,
        Number(dataLat),
        Number(dataLng)
      )
      if (dist <= 999) locationOk = true
      // 매장 999m 밖이면 기록 거부 (출근/퇴근/휴식 공통)
      if (dist > 999) {
        return NextResponse.json(
          {
            success: false,
            message: `❌ 위치 부적합! 매장 근처(999m 이내)가 아닙니다. (현재 거리: ${Math.round(dist)}m)`,
          },
          { headers }
        )
      }
    } else if (targetLat === 0 && targetLng === 0) {
      // 본사·매장 공통: GPS 미등록 시 기록 거부
      return NextResponse.json(
        {
          success: false,
          message: `❌ ${storeName}의 위치(GPS)가 등록되지 않아 출퇴근 기록이 불가합니다. 관리자에게 문의해 주세요.`,
        },
        { headers }
      )
    }
    // GPS 미확인 시에도 승인 대기 없음 (매장 폰/태블릿 활용 정책)
    const needManagerApproval = false

    let planIn = '',
      planOut = '',
      planBS = '',
      planBE = ''
    const scheduleFilter =
      empId > 0
        ? `schedule_date=eq.${todayStrVal}&store_name=ilike.${encodeURIComponent(storeName)}&employee_id=eq.${empId}`
        : `schedule_date=eq.${todayStrVal}&store_name=ilike.${encodeURIComponent(storeName)}&name=ilike.${encodeURIComponent(empName)}`
    let schRows = (await supabaseSelectFilter(
      'schedules',
      scheduleFilter,
      { limit: 5 }
    )) as { plan_in?: string; plan_out?: string; break_start?: string; break_end?: string; plan_in_prev_day?: boolean }[]
    if ((!schRows || schRows.length === 0) && logType === '출근') {
      const tomorrow = (() => {
        const d = new Date(todayStrVal + 'T12:00:00')
        d.setDate(d.getDate() + 1)
        return d.toISOString().slice(0, 10)
      })()
      const prevDayFilter =
        empId > 0
          ? `schedule_date=eq.${tomorrow}&plan_in_prev_day=eq.true&store_name=ilike.${encodeURIComponent(storeName)}&employee_id=eq.${empId}`
          : `schedule_date=eq.${tomorrow}&plan_in_prev_day=eq.true&store_name=ilike.${encodeURIComponent(storeName)}&name=ilike.${encodeURIComponent(empName)}`
      schRows = (await supabaseSelectFilter('schedules', prevDayFilter, { limit: 5 })) as { plan_in?: string; plan_out?: string; break_start?: string; break_end?: string; plan_in_prev_day?: boolean }[]
    }
    let usedYesterdaySchedule = false
    // 퇴근: 당일 스케줄 없으면 전날(자정 넘는 근무) 스케줄 확인
    if ((!schRows || schRows.length === 0) && logType === '퇴근') {
      const yesterday = (() => {
        const d = new Date(todayStrVal + 'T12:00:00Z')
        d.setUTCDate(d.getUTCDate() - 1)
        return d.toISOString().slice(0, 10)
      })()
      const yesterdayFilter =
        empId > 0
          ? `schedule_date=eq.${yesterday}&store_name=ilike.${encodeURIComponent(storeName)}&employee_id=eq.${empId}`
          : `schedule_date=eq.${yesterday}&store_name=ilike.${encodeURIComponent(storeName)}&name=ilike.${encodeURIComponent(empName)}`
      schRows = (await supabaseSelectFilter('schedules', yesterdayFilter, { limit: 5 })) as { plan_in?: string; plan_out?: string; break_start?: string; break_end?: string; plan_in_prev_day?: boolean }[]
      usedYesterdaySchedule = !!(schRows && schRows.length > 0)
    }
    if (schRows && schRows.length > 0) {
      planIn = String(schRows[0].plan_in || '').trim()
      planOut = String(schRows[0].plan_out || '').trim()
      planBS = String(schRows[0].break_start || '').trim()
      planBE = String(schRows[0].break_end || '').trim()
    }

    let lateMin = 0,
      earlyMin = 0,
      otMin = 0,
      breakMin = 0,
      status = '정상',
      planTime = ''
    if (logType === '출근' && planIn) {
      planTime = planIn
      const pInDate = parsePlanTimeToDate(todayStrVal, planIn)
      if (pInDate && nowTime > pInDate) {
        lateMin = safeMinutes((nowTime.getTime() - pInDate.getTime()) / (1000 * 60))
        if (lateMin > 1) status = '지각'
      }
    } else if (logType === '퇴근' && planOut) {
      planTime = planOut
      // 전날 스케줄 사용 시: plan_in_prev_day면 익일 퇴근(오늘날짜), 아니면 당일 퇴근(전날날짜)
      const pOutDateStr =
        usedYesterdaySchedule && !schRows?.[0]?.plan_in_prev_day
          ? (() => {
              const d = new Date(todayStrVal + 'T12:00:00Z')
              d.setUTCDate(d.getUTCDate() - 1)
              return d.toISOString().slice(0, 10)
            })()
          : todayStrVal
      const pOutDate = parsePlanTimeToDate(pOutDateStr, planOut)
      if (pOutDate) {
        if (nowTime < pOutDate) {
          earlyMin = safeMinutes(
            (pOutDate.getTime() - nowTime.getTime()) / (1000 * 60)
          )
          status = '조퇴'
        } else {
          otMin = safeMinutes(
            (nowTime.getTime() - pOutDate.getTime()) / (1000 * 60)
          )
          if (otMin >= 30) status = '연장'
        }
      }
    } else if (logType === '휴식종료') {
      const allLogsFilter =
        empId > 0 ? `store_name=ilike.${encodeURIComponent(storeName)}&employee_id=eq.${empId}` : `name=ilike.${encodeURIComponent(empName)}`
      const allLogs = (await supabaseSelectFilter('attendance_logs', allLogsFilter, {
        order: 'log_at.desc',
        limit: 50,
        select: 'log_at,log_type',
      })) as { log_at?: string; log_type?: string }[]
      for (const r of allLogs || []) {
        const rowDate = r.log_at
          ? new Date(r.log_at).toLocaleDateString('en-CA', { timeZone: TZ })
          : ''
        if (
          rowDate === todayStrVal &&
          String(r.log_type || '').trim() === '휴식시작'
        ) {
          const actualStart = new Date(r.log_at || '')
          breakMin = isNaN(actualStart.getTime())
            ? 0
            : safeMinutes(
                (nowTime.getTime() - actualStart.getTime()) / (1000 * 60)
              )
          if (planBS && planBE) {
            const pBSDate = parsePlanTimeToDate(todayStrVal, planBS)
            const pBEDate = parsePlanTimeToDate(todayStrVal, planBE)
            if (pBSDate && pBEDate) {
              const planDur = safeMinutes(
                (pBEDate.getTime() - pBSDate.getTime()) / (1000 * 60)
              )
              status = breakMin > planDur ? '휴게초과' : '휴게정상'
            }
          }
          break
        }
      }
    }

    if (needManagerApproval) status = '위치미확인(승인대기)'

    const payload: Record<string, unknown> = {
      log_at: nowTime.toISOString(),
      store_name: storeName,
      name: empName,
      log_type: logType,
      lat: String(dataLat != null ? dataLat : '').trim(),
      lng: String(dataLng != null ? dataLng : '').trim(),
      planned_time: planTime.trim(),
      late_min: lateMin,
      early_min: earlyMin,
      ot_min: otMin,
      break_min: breakMin,
      reason: '',
      status,
      approved: '대기',
    }
    if (empId > 0) payload.employee_id = empId
    try {
      await supabaseInsert('attendance_logs', payload)
    } catch (e) {
      const em = e instanceof Error ? e.message : String(e)
      if (/employee_id|42703|column/i.test(em) && 'employee_id' in payload) {
        const { employee_id: _eid, ...fallbackPayload } = payload
        await supabaseInsert('attendance_logs', fallbackPayload)
      } else {
        throw e
      }
    }

    if (needManagerApproval) {
      return NextResponse.json(
        { success: true, code: 'ATT_GPS_PENDING', message: '위치 확인 대기 중입니다.' },
        { headers }
      )
    }
    return NextResponse.json(
      { success: true, message: `✅ ${logType} 완료! (${status})` },
      { headers }
    )
  } catch (e) {
    console.error('submitAttendance:', e)
    return NextResponse.json(
      {
        success: false,
        message:
          '❌ 오류: ' + (e instanceof Error ? e.message : String(e)),
      },
      { headers: new Headers({ 'Access-Control-Allow-Origin': '*' }) }
    )
  }
}

