        receiptStampOnlyTaxInvoice={receiptStampOnlyTaxInvoice}
        receiptMembershipQrImageUrl={receiptMembershipQrImageUrl}
        receiptMembershipQrLinkUrl={receiptMembershipQrLinkUrl}
        receiptMembershipQrText={receiptMembershipQrText}
        receiptShowMembershipQr={receiptShowMembershipQr}
        signatureLine={signatureLine}
        receiptBarcode={
          receiptBarcode && receiptData?.receiptAutoPrintContext !== 'payment'
        }
        itemBarcode={
          itemBarcode && receiptData?.receiptAutoPrintContext !== 'payment'
        }
      />
      <DeliveryEditOrderNoDialog
        open={deliveryEditOrderNoOpen}
        onOpenChange={setDeliveryEditOrderNoOpen}
        order={selectedDeliveryOrder}
        value={deliveryEditOrderNoValue}
        onValueChange={setDeliveryEditOrderNoValue}
        onSaved={async (newTableName) => {
          setSelectedDeliveryTargetLabel(newTableName)
          await refetchStores()
        }}
        t={t}
        deliveryApps={deliveryAppsFromApi}
      />
      </div>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import QRCode from "qrcode"
import Link from "next/link"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { LANG_CODES, type LangCode, isLangCode, useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { cn } from "@/lib/utils"

const QR_LANG_LABELS: Record<LangCode, string> = {
  ko: "🇰🇷 한국어",
  en: "🇺🇸 English",
  th: "🇹🇭 ภาษาไทย",
  mm: "🇲🇲 မြန်မာ",
  la: "🇱🇦 ພາສາລາວ",
  kh: "🇰🇭 ភាសាខ្មែរ",
  vi: "🇻🇳 Tiếng Việt",
  ms: "🇲🇾 Bahasa Melayu",
}

type QrTarget = "mobile" | "admin" | "pos"

const PATHS: Record<QrTarget, string> = {
  mobile: "/login",
  admin: "/admin/login",
  pos: "/pos/login",
}

function targetToFilename(target: QrTarget): string {
  switch (target) {
    case "admin":
      return "cm-erp-qr-admin.png"
    case "pos":
      return "cm-erp-qr-pos.png"
    default:
      return "cm-erp-qr-mobile.png"
  }
}

/** ERP 접속용 QR — 모바일 / 관리자 / POS 로그인 URL 각각 생성 */
export default function QrAccessPage() {
  const { lang, setLang } = useLang()
  const t = useT(lang)
  const [target, setTarget] = useState<QrTarget>("mobile")
  const [dataUrl, setDataUrl] = useState<string | null>(null)
  const [targetUrl, setTargetUrl] = useState<string>("")
  const [copied, setCopied] = useState(false)

  const regenerate = useCallback((url: string) => {
    if (!url) {
      setDataUrl(null)
      setTargetUrl("")
      return
    }
    setTargetUrl(url)
    QRCode.toDataURL(url, { width: 320, margin: 2 })
      .then(setDataUrl)
      .catch(() => setDataUrl(null))
  }, [])

  useEffect(() => {
    const origin =
      typeof window !== "undefined"
        ? (process.env.NEXT_PUBLIC_APP_URL || "").replace(/\/$/, "") || window.location.origin
        : ""
    if (!origin) return
    regenerate(`${origin}${PATHS[target]}`)
  }, [target, regenerate])

  const handleDownload = () => {
    if (!dataUrl) return
    const a = document.createElement("a")
    a.href = dataUrl
    a.download = targetToFilename(target)
    a.click()
  }

  const handleCopyUrl = async () => {
    if (!targetUrl) return
    try {
      await navigator.clipboard.writeText(targetUrl)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      // ignore
    }
  }

  const segments: { id: QrTarget; labelKey: string }[] = [
    { id: "mobile", labelKey: "qrSegmentMobile" },
    { id: "admin", labelKey: "qrSegmentAdmin" },
    { id: "pos", labelKey: "qrSegmentPos" },
  ]

  const handleLangChange = (v: string) => {
    if (!isLangCode(v)) return
    setLang(v)
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-900 to-slate-800 p-6">
      <div className="mx-auto max-w-md">
        <div className="rounded-2xl border border-white/10 bg-white/5 p-8 shadow-xl backdrop-blur">
          <h1 className="mb-2 text-center text-xl font-bold text-white">{t("qrPageTitle")}</h1>
          <div className="mb-4">
            <label className="mb-1.5 block text-center text-xs font-medium text-white/55" htmlFor="qr-lang-select">
              {t("posLanguage")}
            </label>
            <Select value={lang} onValueChange={handleLangChange}>
              <SelectTrigger
                id="qr-lang-select"
                className="border-white/25 bg-white/10 text-white ring-offset-slate-900 focus:ring-orange-500/40 [&>svg]:text-white/70"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="border-white/15 bg-slate-900 text-white">
                {LANG_CODES.map((code) => (
                  <SelectItem
                    key={code}
                    value={code}
                    className="focus:bg-white/15 focus:text-white"
                  >
                    {QR_LANG_LABELS[code]}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <p className="mb-4 text-center text-sm text-white/70">{t("qrPageSubtitle")}</p>

          <div className="mb-6 grid grid-cols-3 gap-2">
            {segments.map(({ id, labelKey }) => (
              <button
                key={id}
                type="button"
                onClick={() => setTarget(id)}
                className={cn(
                  "rounded-xl px-2 py-2.5 text-center text-xs font-semibold transition sm:text-sm",
                  target === id
                    ? "bg-orange-500 text-white shadow-md"
                    : "border border-white/20 bg-white/5 text-white/80 hover:bg-white/10"
                )}
              >
                {t(labelKey)}
              </button>
            ))}
          </div>

          <p className="mb-4 text-center text-xs text-white/55">{t("qrSegmentHint")}</p>

          {dataUrl ? (
            <>
              <div className="mb-6 flex justify-center">
                <div className="rounded-xl border-4 border-white bg-white p-3 shadow-lg">
                  <img
                    src={dataUrl}
                    alt={t("qrPageTitle")}
                    width={280}
                    height={280}
                    className="block"
                  />
                </div>
              </div>
              <p className="mb-4 break-all text-center text-xs text-white/60">{targetUrl}</p>
              <div className="flex flex-col gap-3">
                <button
                  type="button"
                  onClick={handleDownload}
                  className="w-full rounded-xl bg-orange-500 px-4 py-3 font-medium text-white transition hover:bg-orange-600"
                >
                  {t("qrDownloadPng")}
                </button>
                <button
                  type="button"
                  onClick={handleCopyUrl}
                  className="w-full rounded-xl border border-white/30 bg-white/10 px-4 py-3 font-medium text-white transition hover:bg-white/20"
                >
                  {copied ? t("qrCopied") : t("qrCopyUrl")}
                </button>
              </div>
            </>
          ) : (
            <div className="flex flex-col items-center gap-4 py-12">
              <div className="h-10 w-10 animate-spin rounded-full border-2 border-orange-500 border-t-transparent" />
              <p className="text-sm text-white/60">{t("qrGenerating")}</p>
            </div>
          )}
        </div>

        <div className="mt-6 flex flex-wrap items-center justify-center gap-x-4 gap-y-2 text-center text-sm">
          <Link href="/login" className="text-white/60 underline hover:text-white/80">
            {t("qrFooterMobileLogin")}
          </Link>
          <span className="text-white/30" aria-hidden>
            |
          </span>
          <Link href="/admin/login" className="text-white/60 underline hover:text-white/80">
            {t("qrFooterAdminLogin")}
          </Link>
          <span className="text-white/30" aria-hidden>
            |
          </span>
          <Link href="/pos/login" className="text-white/60 underline hover:text-white/80">
            {t("qrFooterPosLogin")}
          </Link>
        </div>
      </div>
    </div>
  )
}

"use client"
import { appAlert } from "@/lib/app-message"

import { useState, useEffect, useCallback } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  adminTabsBarCn,
  adminTabsContentCn,
  adminTabsListRowCn,
  adminTabsRootCn,
  adminTabsScrollCn,
  adminTabsTriggerCn,
} from "@/lib/admin-tab-styles"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Search, Save, Image } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import { useAuth } from "@/lib/auth-context"
import { isManagerRole } from "@/lib/permissions"
import {
  useStoreList,
  getComplaintLogList,
  saveComplaintLog,
  updateComplaintLog,
  translateTexts,
  type ComplaintLogItem,
} from "@/lib/api-client"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { ImageViewerWithRotate } from "@/components/ui/image-viewer-with-rotate"

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

function timeStr() {
  const d = new Date()
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
}

const VISIT_PATHS = ["홀", "배달", "포장"]
const PLATFORMS = ["__none__", "Grab", "Lineman", "Shopee", "Robinhood", "기타"]
const TYPES = ["음식", "서비스", "환경/청결", "가격/결제", "기타"]
const SEVERITIES = ["경미", "보통", "심각"]
const STATUSES = ["접수", "조사중", "처리완료", "보류", "종료"]

const visitPathToKey: Record<string, string> = { "홀": "complaint_path_hall", "배달": "complaint_path_delivery", "포장": "complaint_path_takeout" }
const typeToKey: Record<string, string> = { "음식": "complaint_type_food", "서비스": "complaint_type_service", "환경/청결": "complaint_type_env", "가격/결제": "complaint_type_price", "기타": "complaint_type_etc" }
const severityToKey: Record<string, string> = { "경미": "complaint_sev_low", "보통": "complaint_sev_mid", "심각": "complaint_sev_high" }
const statusToKey: Record<string, string> = { "접수": "complaint_status_recv", "조사중": "complaint_status_inv", "처리완료": "complaint_status_done", "보류": "complaint_status_hold", "종료": "complaint_status_closed" }

const emptyForm = () => ({
  date: todayStr(),
  time: timeStr(),
  store: "",
  writer: "",
  customer: "",
  contact: "",
  visitPath: "홀",
  platform: "__none__",
  type: "음식",
  menu: "",
  title: "",
  content: "",
  severity: "경미",
  status: "접수",
  handler: "",
  doneDate: "",
  action: "",
  photoUrl: "",
  remark: "",
})

export function AdminComplaints() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)

  const [tab, setTab] = useState<"input" | "list">("input")
  const [stores, setStores] = useState<string[]>([])
  const [editId, setEditId] = useState<string>("")

  const [form, setForm] = useState<Record<string, string>>(emptyForm())
  const [saveLoading, setSaveLoading] = useState(false)

  const [listStart, setListStart] = useState(todayStr())
  const [listEnd, setListEnd] = useState(todayStr())
  const [listStore, setListStore] = useState("All")
  const [listVisitPath, setListVisitPath] = useState("__all__")
  const [listType, setListType] = useState("__all__")
  const [listStatus, setListStatus] = useState("__all__")
  const [listData, setListData] = useState<ComplaintLogItem[]>([])
  const [listLoading, setListLoading] = useState(false)
  const [photoPreviewUrl, setPhotoPreviewUrl] = useState<string | null>(null)
  const [transMap, setTransMap] = useState<Record<string, string>>({})

  const writerName = auth?.user || auth?.store || ""
  const isManager = isManagerRole(auth?.role || "")
  const isHQ = auth?.role === "director" || auth?.role === "officer"

  const { stores: storeList } = useStoreList()
  // 조회 탭: 매니저는 전 매장 조회 가능 (입력 탭은 stores 사용, 자기 매장만)
  const listStoresForFilter = isManager
    ? ["All", ...(storeList || []).filter((k) => k && String(k).trim()).sort()]
    : stores
  useEffect(() => {
    if (!auth?.store) return
    const keys = storeList.filter((k) => k && String(k).trim()).sort()
    let list: string[]
    if (isManager) {
      list = [auth.store]
      setForm((f) => ({ ...f, store: auth.store, writer: writerName }))
      // 조회 탭에서는 전 매장 조회 가능 → listStore는 "All" 유지
    } else {
      list = isHQ ? ["All", ...keys] : keys
      if (keys.length && !form.store) setForm((f) => ({ ...f, store: keys[0], writer: writerName }))
    }
    setStores(list)
  }, [auth?.store, auth?.role, isManager, isHQ, storeList])

  useEffect(() => {
    setForm((f) => ({ ...f, writer: writerName }))
  }, [writerName])

  useEffect(() => {
    if (lang === "ko") {
      setTransMap({})
      return
    }
    const texts = [...new Set(
      listData.flatMap((item) =>
        [item.customer, item.title, item.content, item.menu, item.action].filter((s): s is string => Boolean(s && String(s).trim()))
      )
    )]
    if (texts.length === 0) {
      setTransMap({})
      return
    }
    let cancelled = false
    translateTexts(texts, lang)
      .then((translated) => {
        if (cancelled) return
        const map: Record<string, string> = {}
        texts.forEach((txt, i) => { map[txt] = translated[i] ?? txt })
        setTransMap(map)
      })
      .catch(() => setTransMap({}))
    return () => { cancelled = true }
  }, [listData, lang])

  const getTrans = (text: string) => (text && transMap[text]) || text || ""
  const tr = (val: string | undefined, keyMap: Record<string, string>) =>
    val && keyMap[val] ? t(keyMap[val] as never) : (val || "-")

  const loadList = useCallback(async () => {
    setListLoading(true)
    try {
      const list = await getComplaintLogList({
        startStr: listStart || undefined,
        endStr: listEnd || undefined,
        store: listStore && listStore !== "All" ? listStore : undefined,
        visitPath: listVisitPath && listVisitPath !== "__all__" ? listVisitPath : undefined,
        typeFilter: listType && listType !== "__all__" ? listType : undefined,
        statusFilter: listStatus && listStatus !== "__all__" ? listStatus : undefined,
      })
      setListData(list || [])
    } catch {
      setListData([])
    } finally {
      setListLoading(false)
    }
  }, [listStart, listEnd, listStore, listVisitPath, listType, listStatus])

  const resetForm = useCallback(() => {
    setEditId("")
    setForm(emptyForm())
    setForm((f) => ({ ...f, writer: writerName }))
  }, [writerName])

  const openDetail = useCallback((item: ComplaintLogItem) => {
    const id = String(item.row ?? item.id ?? "")
    setForm({
      date: item.date || "",
      time: item.time || "",
      store: item.store || "",
      writer: item.writer || writerName,
      customer: item.customer || "",
      contact: item.contact || "",
      visitPath: item.visitPath || "홀",
      platform: item.platform || "__none__",
      type: item.type || "음식",
      menu: item.menu || "",
      title: item.title || "",
      content: item.content || "",
      severity: item.severity || "경미",
      status: item.status || "접수",
      handler: item.handler || "",
      doneDate: item.doneDate || "",
      action: item.action || "",
      photoUrl: item.photoUrl || "",
      remark: item.remark || "",
    })
    setEditId(id)
    setTab("input")
  }, [writerName])

  const handleSave = async () => {
    if (!form.store) {
      await appAlert(t("store_load_hint"))
      return
    }
    setSaveLoading(true)
    try {
      const data = {
        date: form.date,
        time: form.time,
        store: form.store,
        writer: form.writer,
        customer: form.customer,
        contact: form.contact,
        visitPath: form.visitPath,
        platform: form.platform === "__none__" ? "" : form.platform,
        type: form.type,
        menu: form.menu,
        title: form.title,
        content: form.content,
        severity: form.severity,
        status: form.status,
        handler: form.handler,
        doneDate: form.doneDate,
        action: form.action,
        photoUrl: form.photoUrl,
        remark: form.remark,
      }
      if (editId) {
        const res = await updateComplaintLog(editId, data)
        if (res.success) {
          await appAlert(translateApiMessage(res.message, t) || t("store_check_updated"))
          resetForm()
          loadList()
        } else {
          await appAlert(translateApiMessage(res.message, t) || t("msg_modify_fail"))
        }
      } else {
        const res = await saveComplaintLog(data)
        if (res.success) {
          await appAlert(translateApiMessage(res.message, t) || t("store_check_saved"))
          resetForm()
          loadList()
        } else {
          await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail"))
        }
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaveLoading(false)
    }
  }

  const showPlatform = form.visitPath === "배달"

  return (
    <div className="flex-1 overflow-auto">
      <div className="mx-auto max-w-5xl px-4 py-6 sm:px-6 lg:px-8 space-y-4">
        <div className="mb-4">
          <h1 className="text-xl font-bold tracking-tight">{t("adminComplaints")}</h1>
        </div>

        <Tabs value={tab} onValueChange={(v) => setTab(v as "input" | "list")} className={adminTabsRootCn}>
          <div className={adminTabsBarCn}>
            <div className={adminTabsScrollCn}>
              <TabsList className={adminTabsListRowCn}>
                <TabsTrigger value="input" className={adminTabsTriggerCn}>
                  {t("tab_complaint_input")}
                </TabsTrigger>
                <TabsTrigger value="list" className={adminTabsTriggerCn}>
                  {t("tab_complaint_list")}
                </TabsTrigger>
              </TabsList>
            </div>
          </div>

          <TabsContent value="input" className={adminTabsContentCn}>
            <Card>
              <CardContent className="pt-6 space-y-4">
                <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-5 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("label_date")}</label>
                    <Input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} className="h-9 text-xs" />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_time")}</label>
                    <Input type="time" value={form.time} onChange={(e) => setForm((f) => ({ ...f, time: e.target.value }))} className="h-9 text-xs" />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("store")}</label>
                    <Select value={form.store || undefined} onValueChange={(v) => setForm((f) => ({ ...f, store: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue placeholder={t("store")} />
                      </SelectTrigger>
                      <SelectContent>
                        {stores.filter((s) => s && s !== "All").map((st) => (
                          <SelectItem key={st} value={st}>{st}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_writer")}</label>
                    <Input value={form.writer} readOnly className="h-9 text-xs bg-muted" />
                  </div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_customer")}</label>
                    <Input
                      value={form.customer}
                      onChange={(e) => setForm((f) => ({ ...f, customer: e.target.value }))}
                      className="h-9 text-xs"
                      placeholder={t("complaint_ph_customer")}
                    />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_contact")}</label>
                    <Input
                      value={form.contact}
                      onChange={(e) => setForm((f) => ({ ...f, contact: e.target.value }))}
                      className="h-9 text-xs"
                      placeholder={t("complaint_ph_contact")}
                    />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_visit_path")}</label>
                    <Select value={form.visitPath} onValueChange={(v) => setForm((f) => ({ ...f, visitPath: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {VISIT_PATHS.map((p) => (
                          <SelectItem key={p} value={p}>{t(p === "홀" ? "complaint_path_hall" : p === "배달" ? "complaint_path_delivery" : "complaint_path_takeout")}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  {showPlatform && (
                    <div>
                      <label className="text-xs font-semibold block mb-1">{t("complaint_platform")}</label>
                      <Select value={form.platform || "__none__"} onValueChange={(v) => setForm((f) => ({ ...f, platform: v }))}>
                        <SelectTrigger className="h-9 text-xs">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {PLATFORMS.map((p) => (
                            <SelectItem key={p} value={p}>{p === "__none__" ? "-" : p === "기타" ? t("complaint_platform_etc") : p}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_type")}</label>
                    <Select value={form.type} onValueChange={(v) => setForm((f) => ({ ...f, type: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {TYPES.map((ty) => (
                          <SelectItem key={ty} value={ty}>{t("complaint_type_" + (ty === "음식" ? "food" : ty === "서비스" ? "service" : ty === "환경/청결" ? "env" : ty === "가격/결제" ? "price" : "etc"))}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_menu")}</label>
                    <Input value={form.menu} onChange={(e) => setForm((f) => ({ ...f, menu: e.target.value }))} className="h-9 text-xs" placeholder={t("complaint_ph_menu")} />
                  </div>
                  <div className="sm:col-span-2">
                    <label className="text-xs font-semibold block mb-1">{t("complaint_title")}</label>
                    <Input value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} className="h-9 text-xs" placeholder={t("complaint_ph_title")} />
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold block mb-1">{t("complaint_content")}</label>
                  <Textarea value={form.content} onChange={(e) => setForm((f) => ({ ...f, content: e.target.value }))} rows={3} className="text-xs" placeholder={t("complaint_ph_content")} />
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_severity")}</label>
                    <Select value={form.severity} onValueChange={(v) => setForm((f) => ({ ...f, severity: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {SEVERITIES.map((s) => (
                          <SelectItem key={s} value={s}>{t("complaint_sev_" + (s === "경미" ? "low" : s === "보통" ? "mid" : "high"))}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_status")}</label>
                    <Select value={form.status} onValueChange={(v) => setForm((f) => ({ ...f, status: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {STATUSES.map((s) => (
                          <SelectItem key={s} value={s}>{t("complaint_status_" + (s === "접수" ? "recv" : s === "조사중" ? "inv" : s === "처리완료" ? "done" : s === "보류" ? "hold" : "closed"))}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_handler")}</label>
                    <Input value={form.handler} onChange={(e) => setForm((f) => ({ ...f, handler: e.target.value }))} className="h-9 text-xs" />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_done_date")}</label>
                    <Input type="date" value={form.doneDate} onChange={(e) => setForm((f) => ({ ...f, doneDate: e.target.value }))} className="h-9 text-xs" />
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold block mb-1">{t("complaint_action")}</label>
                  <Textarea value={form.action} onChange={(e) => setForm((f) => ({ ...f, action: e.target.value }))} rows={2} className="text-xs" placeholder={t("complaint_ph_action")} />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_photo")}</label>
                    <Input value={form.photoUrl} onChange={(e) => setForm((f) => ({ ...f, photoUrl: e.target.value }))} className="h-9 text-xs" placeholder={t("complaint_ph_photo")} />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("store_remark")}</label>
                    <Input value={form.remark} onChange={(e) => setForm((f) => ({ ...f, remark: e.target.value }))} className="h-9 text-xs" />
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button className="h-9" onClick={handleSave} disabled={saveLoading}>
                    <Save className="mr-1.5 h-3.5 w-3.5" />
                    {saveLoading ? t("loading") : t("btn_save")}
                  </Button>
                  <Button variant="outline" className="h-9" onClick={resetForm}>
                    {t("complaint_btn_reset")}
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="list" className={adminTabsContentCn}>
            <Card>
              <CardContent className="pt-6">
                <div className="flex flex-wrap items-end gap-2 mb-4">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("visit_start_date")}</label>
                    <Input type="date" value={listStart} onChange={(e) => setListStart(e.target.value)} className="h-9 w-[130px] text-xs" />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("visit_end_date")}</label>
                    <Input type="date" value={listEnd} onChange={(e) => setListEnd(e.target.value)} className="h-9 w-[130px] text-xs" />
                  </div>
                  <Select value={listStore || "All"} onValueChange={setListStore}>
                    <SelectTrigger className="h-9 w-[110px] text-xs">
                      <SelectValue placeholder={t("store")} />
                    </SelectTrigger>
                    <SelectContent>
                      {listStoresForFilter.filter((s) => s).map((st) => (
                        <SelectItem key={st} value={st}>{st === "All" ? t("all") : st}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Select value={listVisitPath || "__all__"} onValueChange={setListVisitPath}>
                    <SelectTrigger className="h-9 w-[100px] text-xs">
                      <SelectValue placeholder={t("complaint_visit_path")} />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">{t("all")}</SelectItem>
                      {VISIT_PATHS.map((p) => (
                        <SelectItem key={p} value={p}>{t(p === "홀" ? "complaint_path_hall" : p === "배달" ? "complaint_path_delivery" : "complaint_path_takeout")}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Select value={listType || "__all__"} onValueChange={setListType}>
                    <SelectTrigger className="h-9 w-[100px] text-xs">
                      <SelectValue placeholder={t("complaint_type")} />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">{t("all")}</SelectItem>
                      {TYPES.map((ty) => (
                        <SelectItem key={ty} value={ty}>{t("complaint_type_" + (ty === "음식" ? "food" : ty === "서비스" ? "service" : ty === "환경/청결" ? "env" : ty === "가격/결제" ? "price" : "etc"))}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Select value={listStatus || "__all__"} onValueChange={setListStatus}>
                    <SelectTrigger className="h-9 w-[100px] text-xs">
                      <SelectValue placeholder={t("complaint_status")} />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">{t("all")}</SelectItem>
                      {STATUSES.map((s) => (
                        <SelectItem key={s} value={s}>{t("complaint_status_" + (s === "접수" ? "recv" : s === "조사중" ? "inv" : s === "처리완료" ? "done" : s === "보류" ? "hold" : "closed"))}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Button className="h-9 font-medium" onClick={loadList} disabled={listLoading}>
                    <Search className="mr-1.5 h-3.5 w-3.5" />
                    {listLoading ? t("loading") : t("search")}
                  </Button>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-xs border-collapse">
                    <thead>
                      <tr className="border-b bg-muted/50">
                        <th className="p-2 text-center font-medium">{t("label_date")}</th>
                        <th className="p-2 text-center font-medium">{t("store")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_col_customer")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_col_visit")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_type")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_title")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_severity")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_status")}</th>
                        <th className="p-2 text-center font-medium">{t("photo")}</th>
                        <th className="p-2 text-center font-medium">{t("complaint_btn_detail")}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {listLoading ? (
                        <tr>
                          <td colSpan={10} className="p-6 text-center text-muted-foreground">{t("loading")}</td>
                        </tr>
                      ) : listData.length === 0 ? (
                        <tr>
                          <td colSpan={10} className="p-6 text-center text-muted-foreground">{t("complaint_query_please")}</td>
                        </tr>
                      ) : (
                        listData.map((item, i) => (
                          <tr key={i} className="border-b border-border/60 hover:bg-muted/30">
                            <td className="p-2 text-center">{item.date}</td>
                            <td className="p-2 text-center">{item.store}</td>
                            <td className="p-2 text-center">{getTrans(item.customer || "") || "-"}</td>
                            <td className="p-2 text-center">{tr(item.visitPath, visitPathToKey)}</td>
                            <td className="p-2 text-center">{tr(item.type, typeToKey)}</td>
                            <td className="p-2 text-left max-w-[160px] truncate" title={getTrans(item.title || "") || item.title}>{getTrans(item.title || "") || "-"}</td>
                            <td className="p-2 text-center">{tr(item.severity, severityToKey)}</td>
                            <td className="p-2 text-center">{tr(item.status, statusToKey)}</td>
                            <td className="p-2 text-center">
                              {item.photoUrl ? (
                                <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={() => setPhotoPreviewUrl(item.photoUrl || null)} title={t("photo")}>
                                  <Image className="h-4 w-4" />
                                </Button>
                              ) : (
                                <span className="text-muted-foreground">-</span>
                              )}
                            </td>
                            <td className="p-2 text-center">
                              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => openDetail(item)}>
                                {t("complaint_btn_detail")}
                              </Button>
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>

        <Dialog open={!!photoPreviewUrl} onOpenChange={(open) => !open && setPhotoPreviewUrl(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>{t("photo")}</DialogTitle>
            </DialogHeader>
            {photoPreviewUrl && (
              <div className="overflow-hidden rounded-md">
                <ImageViewerWithRotate
                  src={photoPreviewUrl}
                  alt={t("photo")}
                  imgClassName="w-full h-auto max-h-[70vh] object-contain"
                  rotateLeftLabel={t("imageRotateLeft") || "반시계"}
                  rotateRightLabel={t("imageRotateRight") || "시계"}
                />
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </div>
  )
}

"use client"
import { appAlert, appConfirm } from "@/lib/app-message"

import { useState, useEffect } from "react"
import { useSearchParams } from "next/navigation"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Badge } from "@/components/ui/badge"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { ImageViewerWithRotate } from "@/components/ui/image-viewer-with-rotate"
import { CalendarCheck, Search, Image } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage as translateApiMsg } from "@/lib/translate-api-message"
import { useAuth } from "@/lib/auth-context"
import { useStoreList, getLeavePendingList, processLeaveApproval } from "@/lib/api-client"
import { displayLabelShort } from "@/lib/utils"
import { translateLeaveTypeFromDb } from "@/lib/leave-type-i18n"

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

export function AdminLeaveApproval() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const searchParams = useSearchParams()

  const [leaveDateFilterType, setLeaveDateFilterType] = useState<'request' | 'leave'>('leave')
  const [leaveStart, setLeaveStart] = useState(todayStr)
  const [leaveEnd, setLeaveEnd] = useState(todayStr)
  const [leaveStoreFilter, setLeaveStoreFilter] = useState("All")
  const [leaveTypeFilter, setLeaveTypeFilter] = useState("All")
  const [leaveStatusFilter, setLeaveStatusFilter] = useState("대기")
  const [leaveStores, setLeaveStores] = useState<string[]>([])
  const [leaveList, setLeaveList] = useState<
    {
      id: number
      store: string
      name: string
      employeeCode: string
      nick: string
      type: string
      date: string
      requestDate: string
      reason: string
      status: string
      certificateUrl: string
    }[]
  >([])
  const [leaveLoading, setLeaveLoading] = useState(false)
  const [certPreviewUrl, setCertPreviewUrl] = useState<string | null>(null)
  const [rejectDialog, setRejectDialog] = useState<{ id: number } | null>(null)
  const [rejectReason, setRejectReason] = useState("")
  const [leaveNameFilter, setLeaveNameFilter] = useState("")

  const { stores: storeList } = useStoreList()
  useEffect(() => {
    if (!auth?.store) return
    const isOffice = auth.role === 'director' || auth.role === 'officer'
    queueMicrotask(() => {
      if (isOffice) {
        setLeaveStores(["All", ...storeList.filter((s) => s !== "All")])
      } else {
        setLeaveStores([auth.store])
        setLeaveStoreFilter(auth.store)
      }
    })
  }, [auth?.store, auth?.role, storeList])

  const isOffice = auth?.role === "director" || auth?.role === "officer"

  /** 급여 수정 등에서 ?month=yyyy-MM&store&name&status=all 로 진입 시 기간·조회 자동 적용 */
  useEffect(() => {
    if (!auth?.store) return
    const month = searchParams.get("month")
    if (!month || !/^\d{4}-\d{2}$/.test(month)) return

    const [y, mo] = month.split("-").map(Number)
    const lastD = new Date(y, mo, 0)
    const mm = String(mo).padStart(2, "0")
    const monthEnd = `${y}-${mm}-${String(lastD.getDate()).padStart(2, "0")}`
    const focusRaw = String(searchParams.get("focusDate") || "").trim()
    const useFocusDay = /^\d{4}-\d{2}-\d{2}$/.test(focusRaw)
    const start = useFocusDay ? focusRaw : `${month}-01`
    const end = useFocusDay ? focusRaw : monthEnd

    const storeRaw = searchParams.get("store")
    const decStore = storeRaw ? decodeURIComponent(storeRaw).trim() : ""
    const nameRaw = searchParams.get("name")
    const decName = nameRaw ? decodeURIComponent(nameRaw).trim() : ""

    setLeaveStart(start)
    setLeaveEnd(end)
    setLeaveDateFilterType("leave")
    if (searchParams.get("status") === "all") setLeaveStatusFilter("All")

    if (!isOffice && auth.store) {
      setLeaveStoreFilter(auth.store)
    } else if (decStore) {
      setLeaveStoreFilter(decStore)
    }

    if (decName) setLeaveNameFilter(decName)

    const apiStore = !isOffice && auth.store ? auth.store : decStore && decStore !== "All" ? decStore : undefined

    setLeaveLoading(true)
    const statusForApi = searchParams.get("status") === "all" ? "All" : leaveStatusFilter

    getLeavePendingList({
      startStr: start,
      endStr: end,
      store: apiStore,
      typeFilter: undefined,
      status: statusForApi,
      userStore: auth.store,
      userRole: auth.role,
      dateFilterType: "leave",
    })
      .then(setLeaveList)
      .catch(() => setLeaveList([]))
      .finally(() => setLeaveLoading(false))
    // eslint-disable-next-line react-hooks/exhaustive-deps -- 급여에서 넘긴 쿼리 문자열이 바뀔 때만 자동 조회
  }, [auth?.store, auth?.role, isOffice, searchParams.toString()])

  const statusLabelMap: Record<string, string> = { "대기": "statusPending", "승인": "statusApproved", "반려": "statusRejected" }
  const translateLeaveType = (type: string) => translateLeaveTypeFromDb(type, t)

  const translateApiMessage = (msg: string | undefined) => translateApiMsg(msg, t)

  const leaveStoreSelectValue =
    leaveStores.length > 0 && leaveStores.includes(leaveStoreFilter) ? leaveStoreFilter : leaveStores[0] ?? "All"

  const nameQ = leaveNameFilter.trim().toLowerCase()
  const visibleLeaveList = nameQ
    ? leaveList.filter(
        (item) =>
          (item.name || "").toLowerCase().includes(nameQ) ||
          (item.nick || "").toLowerCase().includes(nameQ) ||
          (item.employeeCode || "").toLowerCase().includes(nameQ)
      )
    : leaveList

  const loadLeaveList = () => {
    if (!auth?.store) return
    setLeaveLoading(true)
    getLeavePendingList({
      startStr: leaveStart,
      endStr: leaveEnd,
      store: leaveStoreFilter === "All" ? undefined : leaveStoreFilter,
      typeFilter: leaveTypeFilter === "All" ? undefined : leaveTypeFilter,
      status: leaveStatusFilter,
      userStore: auth.store,
      userRole: auth.role,
      dateFilterType: leaveDateFilterType,
    })
      .then(setLeaveList)
      .catch(() => setLeaveList([]))
      .finally(() => setLeaveLoading(false))
  }

  const handleLeaveApprove = async (id: number, decision: string, rejectReasonArg?: string) => {
    if (!auth?.store) return
    const res = await processLeaveApproval({
      id,
      decision,
      userStore: auth.store,
      userRole: auth.role,
      ...(rejectReasonArg != null && { rejectReason: rejectReasonArg }),
    })
    if (res.success) {
      setRejectDialog(null)
      setRejectReason("")
      loadLeaveList()
    } else {
      await appAlert(translateApiMessage(res.message) || t("processFail"))
    }
  }

  const handleRejectClick = (id: number) => {
    setRejectReason("")
    setRejectDialog({ id })
  }

  const handleRejectConfirm = async () => {
    if (!rejectDialog) return
    const reason = rejectReason.trim()
    if (!reason) {
      await appAlert(t("leaveRejectReasonRequired") || "반려 사유를 입력해 주세요.")
      return
    }
    handleLeaveApprove(rejectDialog.id, "반려", reason)
  }

  return (
    <>
    <Card className="shadow-sm">
      <CardHeader className="flex flex-row items-center gap-2 pb-3">
        <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-primary/10">
          <CalendarCheck className="h-3.5 w-3.5 text-primary" />
        </div>
        <CardTitle className="text-base font-semibold">{t("adminLeaveApproval")}</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-2">
          <Select value={leaveDateFilterType} onValueChange={(v: 'request' | 'leave') => setLeaveDateFilterType(v)}>
            <SelectTrigger className="h-9 w-[120px] text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="request">{t("adminLeaveByRequest")}</SelectItem>
              <SelectItem value="leave">{t("adminLeaveByLeave")}</SelectItem>
            </SelectContent>
          </Select>
          <Input type="date" value={leaveStart} onChange={(e) => setLeaveStart(e.target.value)} className="h-9 w-[130px] text-xs" />
          <Input type="date" value={leaveEnd} onChange={(e) => setLeaveEnd(e.target.value)} className="h-9 w-[130px] text-xs" />
          <Select value={leaveStoreFilter} onValueChange={setLeaveStoreFilter}>
            <SelectTrigger className="h-9 w-[100px] text-xs">
              <SelectValue placeholder={t("store")} />
            </SelectTrigger>
            <SelectContent>
              {leaveStores.map((st) => (
                <SelectItem key={st} value={st}>{st}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={leaveTypeFilter} onValueChange={setLeaveTypeFilter}>
            <SelectTrigger className="h-9 w-[90px] text-xs">
              <SelectValue placeholder={t("leave_col_type")} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="All">{t("all")}</SelectItem>
              <SelectItem value="연차">{t("annual")}</SelectItem>
              <SelectItem value="ลากิจ">{t("lakij")}</SelectItem>
              <SelectItem value="반차">{t("half")}</SelectItem>
              <SelectItem value="병가">{t("sick")}</SelectItem>
              <SelectItem value="무급휴가">{t("unpaid")}</SelectItem>
            </SelectContent>
          </Select>
          <Select value={leaveStatusFilter} onValueChange={setLeaveStatusFilter}>
            <SelectTrigger className="h-9 w-20 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="대기">{t("statusPending")}</SelectItem>
              <SelectItem value="승인">{t("statusApproved")}</SelectItem>
              <SelectItem value="반려">{t("statusRejected")}</SelectItem>
              <SelectItem value="All">{t("all")}</SelectItem>
            </SelectContent>
          </Select>
          <div className="min-w-[120px] flex-1 space-y-1 sm:max-w-[200px]">
            <label className="sr-only">{t("leave_filter_name")}</label>
            <Input
              type="search"
              value={leaveNameFilter}
              onChange={(e) => setLeaveNameFilter(e.target.value)}
              placeholder={t("leave_filter_name")}
              className="h-9 text-xs"
            />
          </div>
          <Button className="h-9 shrink-0 px-4 font-medium" onClick={loadLeaveList} disabled={leaveLoading}>
          <Search className="mr-1.5 h-3.5 w-3.5" />
          {leaveLoading ? t("loading") : t("search")}
          </Button>
        </div>
        <div className="overflow-x-auto -mx-2">
          {leaveList.length === 0 ? (
            <p className="py-6 text-center text-xs text-muted-foreground">{t("adminLeaveNoResult")}</p>
          ) : visibleLeaveList.length === 0 ? (
            <p className="py-6 text-center text-xs text-muted-foreground">{t("pay_hist_no_match")}</p>
          ) : (
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="border-b border-border bg-muted/50">
                  <th className="p-2 text-center font-medium">{t("store")}</th>
                  <th className="p-2 text-center font-medium min-w-[100px] whitespace-nowrap">{t("leave_col_name")}</th>
                  <th className="p-2 text-center font-medium whitespace-nowrap tabular-nums">{t("emp_label_employee_code")}</th>
                  <th className="p-2 text-center font-medium whitespace-nowrap">{t("leave_col_request_date")}</th>
                  <th className="p-2 text-center font-medium whitespace-nowrap">{t("leave_col_leave_date")}</th>
                  <th className="p-2 text-center font-medium">{t("leave_col_type")}</th>
                  <th className="p-2 text-center font-medium min-w-[200px]">{t("leave_col_reason")}</th>
                  <th className="p-2 text-center font-medium w-20">{t("leave_col_cert")}</th>
                  <th className="p-2 text-center font-medium w-28">{t("leave_col_action")}</th>
                </tr>
              </thead>
              <tbody>
                {visibleLeaveList.map((item) => (
                  <tr key={item.id} className="border-b border-border/60 hover:bg-muted/30">
                    <td className="p-2 text-center">{item.store}</td>
                    <td className="p-2 text-center whitespace-nowrap">{item.name}{item.nick ? ` (${displayLabelShort(item.nick)})` : ""}</td>
                    <td className="p-2 text-center whitespace-nowrap tabular-nums">{item.employeeCode || "-"}</td>
                    <td className="p-2 text-center whitespace-nowrap">{item.requestDate}</td>
                    <td className="p-2 text-center whitespace-nowrap">{item.date}</td>
                    <td className="p-2 text-center">{translateLeaveType(item.type)}</td>
                    <td className="p-2 text-center">{item.reason || "-"}</td>
                    <td className="p-2 text-center">
                      {(item.type.indexOf("병가") !== -1 || item.type.indexOf("ลากิจ") !== -1) ? (
                        item.certificateUrl ? (
                          <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={() => setCertPreviewUrl(item.certificateUrl)} title={item.type.indexOf("ลากิจ") !== -1 ? t("leaveProofView") : t("leaveCertView")}>
                            <Image className="h-4 w-4" />
                          </Button>
                        ) : (
                          <span className="text-amber-600 text-xs font-medium" title={t("leaveCertPending")}>{t("leaveCertPending")}</span>
                        )
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </td>
                    <td className="p-2 text-center">
                      {item.status === "대기" ? (
                        <div className="flex items-center justify-center gap-1.5">
                          <Button size="sm" className="h-7 px-2 text-xs font-medium" onClick={() => handleLeaveApprove(item.id, "승인")}>{t("adminApproved")}</Button>
                          <Button variant="outline" size="sm" className="h-7 px-2 text-xs font-medium" onClick={() => handleRejectClick(item.id)}>{t("adminRejected")}</Button>
                          <Button variant="outline" size="sm" className="h-7 px-2 text-xs font-medium text-destructive hover:text-destructive" onClick={async () => { if (await appConfirm(t("leaveDeleteConfirm") || "이 휴가 신청을 삭제하시겠습니까?")) handleLeaveApprove(item.id, "삭제") }}>{t("delete")}</Button>
                        </div>
                      ) : (
                        <div className="flex items-center justify-center gap-1.5">
                          <Badge variant={item.status === "승인" || item.status === "Approved" ? "default" : "outline"} className="text-xs">{t(statusLabelMap[item.status] || item.status)}</Badge>
                          {(item.status === "승인" || item.status === "Approved") && (
                            <Button size="sm" className="h-7 px-2 text-xs font-medium" onClick={() => handleLeaveApprove(item.id, "승인")}>{t("adminApproved")}</Button>
                          )}
                          <Button variant="ghost" size="sm" className="h-7 px-2 text-xs text-destructive hover:text-destructive" onClick={async () => { if (await appConfirm(t("leaveDeleteConfirm") || "이 휴가 신청을 삭제하시겠습니까?")) handleLeaveApprove(item.id, "삭제") }}>{t("delete")}</Button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </CardContent>
    </Card>

    <Dialog open={!!rejectDialog} onOpenChange={(open) => !open && setRejectDialog(null)}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{t("leaveRejectTitle") || "반려 사유"}</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">{t("leaveRejectPrompt") || "반려 사유를 입력하세요. 신청자에게 표시됩니다."}</p>
          <Input
            placeholder={t("leaveRejectReasonPh") || "반려 사유 입력"}
            value={rejectReason}
            onChange={(e) => setRejectReason(e.target.value)}
            className="h-10"
          />
          <div className="flex justify-end gap-2">
            <Button variant="outline" size="sm" onClick={() => setRejectDialog(null)}>{t("cancel") || "취소"}</Button>
            <Button variant="destructive" size="sm" onClick={handleRejectConfirm}>{t("adminRejected")}</Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>

    <Dialog open={!!certPreviewUrl} onOpenChange={(open) => !open && setCertPreviewUrl(null)}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t("leaveCertView")}</DialogTitle>
        </DialogHeader>
        {certPreviewUrl && (
          <div className="overflow-hidden rounded-md">
            <ImageViewerWithRotate
              src={certPreviewUrl}
              alt={t("leaveCertView")}
              imgClassName="w-full h-auto max-h-[70vh] object-contain"
              rotateLeftLabel={t("imageRotateLeft") || "반시계"}
              rotateRightLabel={t("imageRotateRight") || "시계"}
            />
          </div>
        )}
      </DialogContent>
    </Dialog>
    </>
  )
}

"use client"
import { appConfirm } from "@/lib/app-message"

import { useState, useEffect } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Search, Plus, Pencil, Trash2 } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"

type HolidayRow = { id?: number; year: number; date: string; name: string }

function fmtDate(d: string): string {
  if (!d || d.length < 10) return ""
  return d.slice(0, 10)
}

export function AdminPublicHolidays() {
  const { lang } = useLang()
  const t = useT(lang)

  const currentYear = new Date().getFullYear()
  const [year, setYear] = useState(currentYear.toString())
  const [list, setList] = useState<HolidayRow[]>([])
  const [loading, setLoading] = useState(false)
  const [queried, setQueried] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const [addDate, setAddDate] = useState("")
  const [addName, setAddName] = useState("")
  const [adding, setAdding] = useState(false)

  const [editId, setEditId] = useState<number | null>(null)
  const [editDate, setEditDate] = useState("")
  const [editName, setEditName] = useState("")
  const [saving, setSaving] = useState(false)

  const handleQuery = async () => {
    const y = parseInt(year, 10)
    if (!y || isNaN(y)) {
      setError(t("holiday_year_required") || "연도를 입력해 주세요.")
      return
    }
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(`/api/getPublicHolidays?year=${y}`)
      const data = await res.json()
      if (data.success && Array.isArray(data.list)) {
        setList(data.list.map((r: { id?: number; year?: number; date?: string; name?: string }) => ({
          id: r.id,
          year: Number(r.year) || y,
          date: fmtDate(r.date || ""),
          name: String(r.name || "").trim(),
        })))
      } else {
        setList([])
        setError(data.msg || t("pay_error"))
      }
    } catch {
      setList([])
      setError(t("pay_error"))
    } finally {
      setLoading(false)
      setQueried(true)
    }
  }

  const handleAdd = async () => {
    const y = parseInt(year, 10)
    const d = fmtDate(addDate)
    if (!y || isNaN(y) || !d) {
      setError(t("holiday_date_required") || "연도와 날짜(yyyy-MM-dd)를 입력해 주세요.")
      return
    }
    setAdding(true)
    setError(null)
    try {
      const res = await fetch("/api/savePublicHoliday", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "add", year: y, date: d, name: addName || "-" }),
      })
      const data = await res.json()
      if (data.success) {
        setAddDate("")
        setAddName("")
        handleQuery()
      } else {
        setError(data.msg || t("pay_save_fail"))
      }
    } catch {
      setError(t("pay_save_fail"))
    } finally {
      setAdding(false)
    }
  }

  const handleEdit = (row: HolidayRow) => {
    if (row.id) {
      setEditId(row.id)
      setEditDate(row.date)
      setEditName(row.name)
    }
  }

  const handleSaveEdit = async () => {
    if (editId == null) return
    const d = fmtDate(editDate)
    if (!d) {
      setError(t("holiday_date_required") || "날짜를 yyyy-MM-dd 형식으로 입력해 주세요.")
      return
    }
    setSaving(true)
    setError(null)
    try {
      const y = parseInt(year, 10)
      const res = await fetch("/api/savePublicHoliday", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "update",
          id: editId,
          year: y || undefined,
          date: d,
          name: editName || "-",
        }),
      })
      const data = await res.json()
      if (data.success) {
        setEditId(null)
        handleQuery()
      } else {
        setError(data.msg || t("pay_save_fail"))
      }
    } catch {
      setError(t("pay_save_fail"))
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (id: number) => {
    if (!await appConfirm(t("holiday_delete_confirm"))) return
    setError(null)
    try {
      const res = await fetch("/api/savePublicHoliday", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "delete", id }),
      })
      const data = await res.json()
      if (data.success) {
        handleQuery()
      } else {
        setError(data.msg || t("pay_save_fail"))
      }
    } catch {
      setError(t("pay_save_fail"))
    }
  }


  return (
    <Card className="shadow-sm">
      <CardContent className="pt-6">
        <div className="flex flex-wrap items-end gap-3 mb-4">
          <div className="flex-1 min-w-[120px]">
            <label className="text-xs font-semibold block mb-1">{t("holiday_year") || "연도"}</label>
            <Input
              type="number"
              value={year}
              onChange={(e) => setYear(e.target.value)}
              className="h-9 text-xs"
              min={2020}
              max={2035}
            />
          </div>
          <Button className="h-9 font-medium" onClick={handleQuery} disabled={loading}>
            <Search className="mr-1.5 h-3.5 w-3.5" />
            {loading ? t("loading") : t("search")}
          </Button>
        </div>

        <div className="flex flex-wrap items-end gap-3 mb-4 p-3 rounded-lg bg-muted/50">
          <div className="min-w-[130px]">
            <label className="text-xs font-semibold block mb-1">{t("holiday_date") || "날짜"}</label>
            <Input
              type="date"
              value={addDate}
              onChange={(e) => setAddDate(e.target.value)}
              className="h-9 text-xs"
            />
          </div>
          <div className="flex-1 min-w-[140px]">
            <label className="text-xs font-semibold block mb-1">{t("holiday_name") || "휴일명"}</label>
            <Input
              value={addName}
              onChange={(e) => setAddName(e.target.value)}
              placeholder={t("holiday_name") || "휴일명"}
              className="h-9 text-xs"
            />
          </div>
          <Button
            variant="outline"
            className="h-9 font-medium"
            onClick={handleAdd}
            disabled={adding}
          >
            <Plus className="mr-1.5 h-3.5 w-3.5" />
            {adding ? t("loading") : (t("holiday_add") || "추가")}
          </Button>
        </div>

        {error && (
          <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
            {error}
          </div>
        )}

        {list.length > 0 && (
          <div className="overflow-x-auto">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="border-b border-border bg-muted/50">
                  <th className="p-2 text-left font-medium">{t("holiday_date") || "날짜"}</th>
                  <th className="p-2 text-left font-medium">{t("holiday_name") || "휴일명"}</th>
                  <th className="p-2 text-right font-medium w-24">{t("cancel") || "작업"}</th>
                </tr>
              </thead>
              <tbody>
                {list.map((r) => (
                  <tr key={r.id ?? r.date} className="border-b border-border/60 hover:bg-muted/30">
                    {editId === r.id ? (
                      <>
                        <td className="p-2">
                          <Input
                            type="date"
                            value={editDate}
                            onChange={(e) => setEditDate(e.target.value)}
                            className="h-8 text-xs w-full"
                          />
                        </td>
                        <td className="p-2">
                          <Input
                            value={editName}
                            onChange={(e) => setEditName(e.target.value)}
                            className="h-8 text-xs"
                          />
                        </td>
                        <td className="p-2 text-right">
                          <div className="flex gap-1 justify-end">
                            <Button size="sm" variant="ghost" className="h-7" onClick={() => setEditId(null)}>
                              {t("cancel")}
                            </Button>
                            <Button size="sm" className="h-7" onClick={handleSaveEdit} disabled={saving}>
                              {saving ? t("loading") : t("pay_save")}
                            </Button>
                          </div>
                        </td>
                      </>
                    ) : (
                      <>
                        <td className="p-2">{r.date}</td>
                        <td className="p-2">{r.name}</td>
                        <td className="p-2 text-right">
                          {r.id ? (
                            <div className="flex gap-1 justify-end">
                              <Button
                                size="sm"
                                variant="ghost"
                                className="h-7 w-7 p-0"
                                onClick={() => handleEdit(r)}
                              >
                                <Pencil className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                size="sm"
                                variant="ghost"
                                className="h-7 w-7 p-0 text-destructive"
                                onClick={() => handleDelete(r.id!)}
                              >
                                <Trash2 className="h-3.5 w-3.5" />
                              </Button>
                            </div>
                          ) : (
                            <span className="text-muted-foreground">-</span>
                          )}
                        </td>
                      </>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {!queried && (
          <div className="rounded-lg border border-dashed border-border py-12 text-center text-sm text-muted-foreground">
            {t("holiday_query_please") || "연도를 선택하고 [조회]를 눌러주세요."}
          </div>
        )}

        {queried && list.length === 0 && !error && (
          <div className="rounded-lg border border-dashed border-border py-8 text-center text-sm text-muted-foreground">
            {t("pay_no_data")}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

"use client"
