  const isHQ = isOfficeRole(auth?.role || "")

  const { stores: storeList } = useStoreList()
  const listStoresForFilter = isManager
    ? ["All", ...(storeList || []).filter((k) => k && String(k).trim()).sort()]
    : stores

  useEffect(() => {
    if (!auth?.store) return
    const keys = storeList.filter((k) => k && String(k).trim()).sort()
    let list: string[]
    if (isManager) {
      list = [auth.store]
      setForm((f) => ({ ...f, store: auth.store || "", reporter: writerName }))
    } else {
      list = isHQ ? ["All", ...keys] : keys
      if (keys.length && !form.store) setForm((f) => ({ ...f, store: keys[0], reporter: writerName }))
    }
    setStores(list)
  }, [auth?.store, auth?.role, isManager, isHQ, storeList, writerName])

  useEffect(() => {
    setForm((f) => ({ ...f, reporter: writerName }))
  }, [writerName])

  const loadList = useCallback(async () => {
    setListLoading(true)
    try {
      const list = await getStoreRepairTicketList({
        startStr: listStart || undefined,
        endStr: listEnd || undefined,
        store: listStore && listStore !== "All" ? listStore : undefined,
        status: listStatus && listStatus !== "__all__" ? listStatus : undefined,
        category: listCategory && listCategory !== "__all__" ? listCategory : undefined,
        q: listQ.trim() || undefined,
      })
      setListData(list || [])
    } catch {
      setListData([])
    } finally {
      setListLoading(false)
    }
  }, [listStart, listEnd, listStore, listStatus, listCategory, listQ])

  useEffect(() => {
    loadList()
  }, [loadList])

  const listTitles = useMemo(() => listData.map((r) => r.title || ""), [listData])
  const translateTitle = useTranslatedTextMap(listTitles, lang)
  const newTitleTrans = useDebouncedTranslatedText(form.title, lang)
  const editTitleTrans = useDebouncedTranslatedText(editItem?.title || "", lang)

  const stats = useMemo(() => {
    const recv = listData.filter((x) => x.status === "접수").length
    const prog = listData.filter((x) => x.status === "진행중").length
    const done = listData.filter((x) => x.status === "완료").length
    const urgentOpen = listData.filter((x) => x.priority === "긴급" && x.status !== "완료" && x.status !== "취소").length
    const doneWithLead = listData.filter((x) => x.status === "완료" && x.completedAt && x.reportedAt)
    let avgDays = 0
    if (doneWithLead.length) {
      const sum = doneWithLead.reduce((s, x) => {
        const a = new Date(x.reportedAt).getTime()
        const b = new Date(x.completedAt!).getTime()
        return s + (b - a) / 86400000
      }, 0)
      avgDays = sum / doneWithLead.length
    }
    const byStatus: Record<string, number> = {}
    const byCat: Record<string, number> = {}
    for (const x of listData) {
      byStatus[x.status || "?"] = (byStatus[x.status || "?"] || 0) + 1
      const c = x.category || "기타"
      byCat[c] = (byCat[c] || 0) + 1
    }
    const stKey = (s: string) => STATUSES.find((x) => x.v === s)?.k || "repair_st_recv"
    const catKey = (c: string) => CATEGORIES.find((x) => x.v === c)?.k || "repair_cat_etc"
    const statusChart = Object.entries(byStatus).map(([name, value]) => ({
      name: t(stKey(name)),
      value,
    }))
    const catChart = Object.entries(byCat).map(([name, value]) => ({
      name: t(catKey(name)),
      value,
    }))
    return { recv, prog, done, urgentOpen, avgDays, statusChart, catChart }
  }, [listData, t])

  const statusChartConfig = useMemo(
    () =>
      Object.fromEntries(stats.statusChart.map((d, i) => [d.name, { label: d.name, color: CHART_COLORS[i % CHART_COLORS.length] }])),
    [stats.statusChart]
  )
  const catChartConfig = useMemo(
    () =>
      Object.fromEntries(stats.catChart.map((d, i) => [d.name, { label: d.name, color: CHART_COLORS[i % CHART_COLORS.length] }])),
    [stats.catChart]
  )

  const resetForm = useCallback(() => {
    setForm((f) => ({
      ...f,
      category: "시설",
      priority: "보통",
      area: "",
      title: "",
      description: "",
      photoUrls: [],
      status: "접수",
      handler: "",
      resolutionNote: "",
      vendorName: "",
      store: isManager ? auth?.store || "" : f.store,
      reporter: writerName,
    }))
  }, [isManager, auth?.store, writerName])

  const handleUploadFiles = async (files: FileList | null, target: "form" | "dialog") => {
    if (!files?.length) return
    const store = target === "form" ? form.store : editItem?.store || form.store
    if (!store) {
      await appAlert(t("store_load_hint"))
      return
    }
    const urls: string[] = []
    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      const res = await uploadStoreRepairPhoto(store, file)
      if (res.success && res.url) urls.push(res.url)
      else await appAlert(translateApiMessage(res.message, t) || t("msg_upload_fail"))
    }
    if (!urls.length) return
    if (target === "form") {
      setForm((f) => ({ ...f, photoUrls: [...f.photoUrls, ...urls] }))
    } else if (editItem) {
      const next = [...(editItem.photoUrls || []), ...urls]
      setEditItem({ ...editItem, photoUrls: next })
    }
  }

  const handleSaveNew = async () => {
    if (!form.store) {
      await appAlert(t("store_load_hint"))
      return
    }
    if (!form.title.trim()) {
      await appAlert(t("repair_field_title"))
      return
    }
    setSaveLoading(true)
    try {
      const res = await saveStoreRepairTicket({
        store: form.store,
        reporter: form.reporter,
        category: form.category,
        priority: form.priority,
        area: form.area,
        title: form.title,
        description: form.description,
        photoUrls: form.photoUrls,
        status: form.status,
        handler: form.handler,
        resolutionNote: form.resolutionNote,
        vendorName: form.vendorName,
      })
      if (res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("store_check_saved"))
        resetForm()
        loadList()
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail"))
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaveLoading(false)
    }
  }

  const openEdit = (item: StoreRepairTicketItem) => {
    setEditItem(item)
    setEditOpen(true)
  }

  const clearProcessFocus = useCallback(() => {
    setProcessFocusTicketId(null)
  }, [])

  const goToProcessWithTicket = (row: StoreRepairTicketItem) => {
    if (row.id == null) return
    setProcessFocusTicketId(row.id)
    setTab("process")
  }

  const handleSaveEdit = async () => {
    if (!editItem?.id) return
    setSaveLoading(true)
    try {
      const res = await updateStoreRepairTicket(editItem.id, {
        store: editItem.store,
        reporter: editItem.reporter,
        category: editItem.category,
        priority: editItem.priority,
        area: editItem.area,
        title: editItem.title,
        description: editItem.description,
        photoUrls: editItem.photoUrls,
        status: editItem.status,
        handler: editItem.handler,
        resolutionNote: editItem.resolutionNote,
        vendorName: editItem.vendorName,
      })
      if (res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("store_check_updated"))
        setEditOpen(false)
        setEditItem(null)
        loadList()
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("msg_modify_fail"))
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaveLoading(false)
    }
  }

  const labelPri = (v: string) => PRIORITIES.find((c) => c.v === v)?.k || "repair_pri_normal"
  const labelSt = (v: string) => STATUSES.find((c) => c.v === v)?.k || "repair_st_recv"

  return (
    <div className="flex-1 overflow-auto">
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8 space-y-4">
        <div className="mb-4 flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
            <Wrench className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t("adminStoreRepairs")}</h1>
            <p className="text-xs text-muted-foreground">{t("repair_page_sub")}</p>
          </div>
        </div>

        <Tabs value={tab} onValueChange={(v) => setTab(v as typeof tab)} className={adminTabsRootCn}>
          <div className={adminTabsBarCn}>
            <div className={adminTabsScrollCn}>
              <TabsList className={adminTabsListRowCn}>
                <TabsTrigger value="dash" className={adminTabsTriggerCn}>
                  {t("tab_repair_dashboard")}
                </TabsTrigger>
                <TabsTrigger value="list" className={adminTabsTriggerCn}>
                  {t("tab_repair_list")}
                </TabsTrigger>
                <TabsTrigger value="process" className={adminTabsTriggerCn}>
                  {t("tab_repair_process")}
                </TabsTrigger>
                <TabsTrigger value="new" className={adminTabsTriggerCn}>
                  {t("tab_repair_new")}
                </TabsTrigger>
              </TabsList>
            </div>
          </div>

          <TabsContent value="dash" className={cn(adminTabsContentCn, "space-y-4")}>
            <div className="flex flex-wrap gap-2">
              <Input type="date" value={listStart} onChange={(e) => setListStart(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Input type="date" value={listEnd} onChange={(e) => setListEnd(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Select value={listStore} onValueChange={setListStore}>
                <SelectTrigger className="h-9 w-[200px] text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {listStoresForFilter.map((s) => (
                    <SelectItem key={s} value={s}>
                      {s}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button type="button" variant="secondary" size="sm" className="h-9" onClick={() => loadList()} disabled={listLoading}>
                {t("repair_btn_load")}
              </Button>
            </div>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
              {[
                { label: t("repair_kpi_recv"), value: stats.recv, className: "border-amber-500/40" },
                { label: t("repair_kpi_prog"), value: stats.prog, className: "border-blue-500/40" },
                { label: t("repair_kpi_done"), value: stats.done, className: "border-emerald-500/40" },
                { label: t("repair_kpi_urgent"), value: stats.urgentOpen, className: "border-red-500/40" },
                {
                  label: t("repair_kpi_avg_days"),
                  value: stats.avgDays > 0 ? stats.avgDays.toFixed(1) : "—",
                  className: "border-slate-500/40",
                },
              ].map((k) => (
                <Card key={k.label} className={`border-l-4 ${k.className}`}>
                  <CardContent className="p-4">
                    <p className="text-xs text-muted-foreground">{k.label}</p>
                    <p className="text-2xl font-bold tabular-nums">{k.value}</p>
                  </CardContent>
                </Card>
              ))}
            </div>
            <div className="grid gap-4 lg:grid-cols-2">
              <Card>
                <CardContent className="pt-4">
                  <h3 className="mb-2 text-sm font-semibold">{t("repair_chart_by_status")}</h3>
                  <ChartContainer config={statusChartConfig} className="h-[240px] w-full aspect-auto">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={stats.statusChart} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
                        <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                        <YAxis allowDecimals={false} tick={{ fontSize: 11 }} width={32} />
                        <ChartTooltip content={<ChartTooltipContent />} />
                        <Bar dataKey="value" radius={[4, 4, 0, 0]} fill="#2563eb" />
                      </BarChart>
                    </ResponsiveContainer>
                  </ChartContainer>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <h3 className="mb-2 text-sm font-semibold">{t("repair_chart_by_category")}</h3>
                  <ChartContainer config={catChartConfig} className="h-[240px] w-full aspect-auto">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <ChartTooltip content={<ChartTooltipContent />} />
                        <Pie
                          data={stats.catChart}
                          dataKey="value"
                          nameKey="name"
                          cx="50%"
                          cy="50%"
                          outerRadius={88}
                          label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                        >
                          {stats.catChart.map((_, i) => (
                            <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                          ))}
                        </Pie>
                      </PieChart>
                    </ResponsiveContainer>
                  </ChartContainer>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          <TabsContent value="process" className={cn(adminTabsContentCn, "space-y-4")}>
            <div className="flex flex-wrap gap-2">
              <Input type="date" value={listStart} onChange={(e) => setListStart(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Input type="date" value={listEnd} onChange={(e) => setListEnd(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Select value={listStore} onValueChange={setListStore}>
                <SelectTrigger className="h-9 w-[200px] text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {listStoresForFilter.map((s) => (
                    <SelectItem key={s} value={s}>
                      {s}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <StoreRepairsProcessTab
              tickets={listData}
              ticketsLoading={listLoading}
              onRefreshTickets={() => void loadList()}
              writerName={writerName}
              focusTicketId={processFocusTicketId}
              onFocusTicketConsumed={clearProcessFocus}
            />
          </TabsContent>

          <TabsContent value="list" className={cn(adminTabsContentCn, "space-y-4")}>
            <div className="flex flex-wrap gap-2 items-center">
              <Input type="date" value={listStart} onChange={(e) => setListStart(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Input type="date" value={listEnd} onChange={(e) => setListEnd(e.target.value)} className="h-9 w-[140px] text-xs" />
              <Select value={listStore} onValueChange={setListStore}>
                <SelectTrigger className="h-9 w-[180px] text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {listStoresForFilter.map((s) => (
                    <SelectItem key={s} value={s}>
                      {s}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={listStatus} onValueChange={setListStatus}>
                <SelectTrigger className="h-9 w-[130px] text-xs">
                  <SelectValue placeholder={t("all")} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__all__">{t("all")}</SelectItem>
                  {STATUSES.map((s) => (
                    <SelectItem key={s.v} value={s.v}>
                      {t(s.k)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={listCategory} onValueChange={setListCategory}>
                <SelectTrigger className="h-9 w-[150px] text-xs">
                  <SelectValue placeholder={t("all")} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__all__">{t("all")}</SelectItem>
                  {CATEGORIES.map((s) => (
                    <SelectItem key={s.v} value={s.v}>
                      {t(s.k)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <div className="relative flex-1 min-w-[160px] max-w-sm">
                <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
                <Input
                  className="h-9 pl-8 text-xs"
                  placeholder={t("repair_search_placeholder")}
                  value={listQ}
                  onChange={(e) => setListQ(e.target.value)}
                />
              </div>
              <Button type="button" variant="secondary" size="sm" className="h-9" onClick={() => loadList()} disabled={listLoading}>
                {t("repair_btn_load")}
              </Button>
            </div>
            <Card>
              <CardContent className="p-0 overflow-x-auto">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b bg-muted/50">
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_ticket")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_store")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_title")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_status")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_priority")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_reported")}</th>
                      <th className="px-3 py-2 text-left font-medium">{t("repair_col_lead")}</th>
                      <th className="px-3 py-2 text-center font-medium">{t("photo")}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {listLoading ? (
                      <tr>
                        <td colSpan={8} className="px-3 py-8 text-center text-muted-foreground">
                          {t("loading")}
                        </td>
                      </tr>
                    ) : listData.length === 0 ? (
                      <tr>
                        <td colSpan={9} className="px-3 py-8 text-center text-muted-foreground">
                          —
                        </td>
                      </tr>
                    ) : (
                      listData.map((row) => {
                        const stale = row.status === "접수" && daysSinceReportedBangkok(row.reportedAt) >= 3
                        return (
                          <tr
                            key={row.id}
                            className={`border-b cursor-pointer hover:bg-muted/40 ${stale ? "bg-amber-500/10" : ""}`}
                            onClick={() => goToProcessWithTicket(row)}
                          >
                            <td className="px-3 py-2 font-mono">{row.ticketNumber}</td>
                            <td className="px-3 py-2">{row.store}</td>
                            <td className="px-3 py-2 max-w-[200px] truncate" title={row.title || undefined}>
                              {translateTitle(row.title || "")}
                            </td>
                            <td className="px-3 py-2">{t(labelSt(row.status))}</td>
                            <td className="px-3 py-2">{t(labelPri(row.priority))}</td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {row.reportedAt ? row.reportedAt.slice(0, 16).replace("T", " ") : "—"}
                              {stale ? (
                                <span className="ml-1 text-amber-700 dark:text-amber-400">
                                  ({daysSinceReportedBangkok(row.reportedAt)} {t("repair_stale_days")})
                                </span>
                              ) : null}
                            </td>
                            <td className="px-3 py-2">{leadTimeLabel(row, t)}</td>
                            <td className="px-3 py-2 text-center">
                              {row.photoUrls?.length ? (
                                <ImageIcon className="inline h-4 w-4 text-primary" />
                              ) : (
                                "—"
                              )}
                            </td>
                            <td className="px-3 py-2 text-center">
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 shrink-0"
                                title={t("repair_list_full_edit")}
                                aria-label={t("repair_list_full_edit")}
                                onClick={(e) => {
                                  e.stopPropagation()
                                  openEdit(row)
                                }}
                              >
                                <Pencil className="h-3.5 w-3.5" />
                              </Button>
                            </td>
                          </tr>
                        )
                      })
                    )}
                  </tbody>
                </table>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="new" className={adminTabsContentCn}>
            <Card>
              <CardContent className="pt-6 space-y-4">
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("store")}</label>
                    <Select value={form.store || undefined} onValueChange={(v) => setForm((f) => ({ ...f, store: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue placeholder={t("store")} />
                      </SelectTrigger>
                      <SelectContent>
                        {stores.filter((s) => s && s !== "All").map((st) => (
                          <SelectItem key={st} value={st}>
                            {st}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("complaint_writer")}</label>
                    <Input value={form.reporter} readOnly className="h-9 text-xs bg-muted" />
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("repair_field_category")}</label>
                    <Select value={form.category} onValueChange={(v) => setForm((f) => ({ ...f, category: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {CATEGORIES.map((c) => (
                          <SelectItem key={c.v} value={c.v}>
                            {t(c.k)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold block mb-1">{t("repair_field_priority")}</label>
                    <Select value={form.priority} onValueChange={(v) => setForm((f) => ({ ...f, priority: v }))}>
                      <SelectTrigger className="h-9 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {PRIORITIES.map((c) => (
                          <SelectItem key={c.v} value={c.v}>
                            {t(c.k)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div>
                  <label className="text-xs font-semibold block mb-1">{t("repair_field_area")}</label>
                  <Input
                    value={form.area}
                    onChange={(e) => setForm((f) => ({ ...f, area: e.target.value }))}
                    className="h-9 text-xs"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold block mb-1">{t("repair_field_title")}</label>
                  <Input
                    value={form.title}
                    onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
                    className="h-9 text-xs"
                  />
                  {form.title.trim() ? (
                    <div className="mt-1 rounded border border-dashed border-border/80 bg-muted/25 px-2 py-1 text-[11px]">
                      <span className="font-medium text-muted-foreground">{t("repair_translate_preview")}</span>
                      {newTitleTrans.pending ? (
                        <p className="mt-0.5 text-muted-foreground">{t("repair_translate_loading")}</p>
                      ) : newTitleTrans.translated && newTitleTrans.translated !== form.title.trim() ? (
                        <p className="mt-0.5 text-foreground/90">{newTitleTrans.translated}</p>
                      ) : (
                        <p className="mt-0.5 text-muted-foreground">—</p>
                      )}
                    </div>
                  ) : null}
                </div>
                <div>
                  <label className="text-xs font-semibold block mb-1">{t("repair_field_description")}</label>
                  <Textarea
                    value={form.description}
                    onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
                    rows={3}
                    className="text-xs"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold block mb-1">{t("repair_field_photos")}</label>
                  <p className="text-[11px] text-muted-foreground mb-2">{t("repair_photo_hint")}</p>
                  <input
                    ref={fileRef}
                    type="file"
                    accept="image/*"
                    multiple
                    className="hidden"
                    onChange={(e) => {
                      void handleUploadFiles(e.target.files, "form")
                      e.target.value = ""
                    }}
                  />
                  <Button type="button" variant="outline" size="sm" className="h-8 text-xs" onClick={() => fileRef.current?.click()}>
                    {t("repair_photo_add")}
                  </Button>
                  <div className="flex flex-wrap gap-2 mt-2">
                    {form.photoUrls.map((url) => (
                      <div key={url} className="relative h-16 w-16 rounded border overflow-hidden group">
                        <button
                          type="button"
                          className="absolute top-0 right-0 z-10 bg-background/80 p-0.5 rounded-bl"
                          onClick={() => setForm((f) => ({ ...f, photoUrls: f.photoUrls.filter((u) => u !== url) }))}
                        >
                          <X className="h-3 w-3" />
                        </button>
                        <button type="button" onClick={() => setPhotoPreview(url)} className="block h-full w-full">
                          {/* eslint-disable-next-line @next/next/no-img-element */}
                          <img src={url} alt="" className="h-full w-full object-cover" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button type="button" size="sm" onClick={() => void handleSaveNew()} disabled={saveLoading}>
                    <Save className="h-3.5 w-3.5 mr-1" />
                    {t("repair_btn_save")}
                  </Button>
                  <Button type="button" variant="outline" size="sm" onClick={resetForm}>
                    {t("repair_btn_new")}
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>

      <Dialog open={editOpen} onOpenChange={setEditOpen}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{t("repair_detail_title")}</DialogTitle>
          </DialogHeader>
          {editItem && (
            <div className="space-y-3 text-xs">
              <p className="font-mono text-muted-foreground">{editItem.ticketNumber}</p>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="font-semibold block mb-1">{t("store")}</label>
                  <Input value={editItem.store} onChange={(e) => setEditItem({ ...editItem, store: e.target.value })} className="h-8" />
                </div>
                <div>
                  <label className="font-semibold block mb-1">{t("repair_field_status")}</label>
                  <Select value={editItem.status} onValueChange={(v) => setEditItem({ ...editItem, status: v })}>
                    <SelectTrigger className="h-8">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {STATUSES.map((s) => (
                        <SelectItem key={s.v} value={s.v}>
                          {t(s.k)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="font-semibold block mb-1">{t("repair_field_category")}</label>
                  <Select value={editItem.category} onValueChange={(v) => setEditItem({ ...editItem, category: v })}>
                    <SelectTrigger className="h-8">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CATEGORIES.map((c) => (
                        <SelectItem key={c.v} value={c.v}>
                          {t(c.k)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <label className="font-semibold block mb-1">{t("repair_field_priority")}</label>
                  <Select value={editItem.priority} onValueChange={(v) => setEditItem({ ...editItem, priority: v })}>
                    <SelectTrigger className="h-8">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PRIORITIES.map((c) => (
                        <SelectItem key={c.v} value={c.v}>
                          {t(c.k)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_title")}</label>
                <Input value={editItem.title} onChange={(e) => setEditItem({ ...editItem, title: e.target.value })} className="h-8" />
                {editItem.title.trim() ? (
                  <div className="mt-1 rounded border border-dashed border-border/80 bg-muted/25 px-2 py-1 text-[11px]">
                    <span className="font-medium text-muted-foreground">{t("repair_translate_preview")}</span>
                    {editTitleTrans.pending ? (
                      <p className="mt-0.5 text-muted-foreground">{t("repair_translate_loading")}</p>
                    ) : editTitleTrans.translated && editTitleTrans.translated !== editItem.title.trim() ? (
                      <p className="mt-0.5 text-foreground/90">{editTitleTrans.translated}</p>
                    ) : (
                      <p className="mt-0.5 text-muted-foreground">—</p>
                    )}
                  </div>
                ) : null}
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_description")}</label>
                <Textarea
                  value={editItem.description}
                  onChange={(e) => setEditItem({ ...editItem, description: e.target.value })}
                  rows={3}
                />
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_handler")}</label>
                <Input
                  value={editItem.handler}
                  onChange={(e) => setEditItem({ ...editItem, handler: e.target.value })}
                  className="h-8"
                />
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_resolution")}</label>
                <Textarea
                  value={editItem.resolutionNote}
                  onChange={(e) => setEditItem({ ...editItem, resolutionNote: e.target.value })}
                  rows={2}
                />
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_vendor")}</label>
                <Input
                  value={editItem.vendorName}
                  onChange={(e) => setEditItem({ ...editItem, vendorName: e.target.value })}
                  className="h-8"
                />
              </div>
              <div>
                <label className="font-semibold block mb-1">{t("repair_field_photos")}</label>
                <input
                  ref={fileRefDialog}
                  type="file"
                  accept="image/*"
                  multiple
                  className="hidden"
                  onChange={(e) => {
                    void handleUploadFiles(e.target.files, "dialog")
                    e.target.value = ""
                  }}
                />
                <Button type="button" variant="outline" size="sm" className="h-8 text-xs mb-2" onClick={() => fileRefDialog.current?.click()}>
                  {t("repair_photo_add")}
                </Button>
                <div className="flex flex-wrap gap-2">
                  {editItem.photoUrls?.map((url) => (
                    <div key={url} className="relative h-14 w-14 rounded border overflow-hidden">
                      <button
                        type="button"
                        className="absolute top-0 right-0 z-10 bg-background/80 p-0.5"
                        onClick={() =>
                          setEditItem({
                            ...editItem,
                            photoUrls: editItem.photoUrls.filter((u) => u !== url),
                          })
                        }
                      >
                        <X className="h-3 w-3" />
                      </button>
                      <button type="button" onClick={() => setPhotoPreview(url)} className="block h-full w-full">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={url} alt="" className="h-full w-full object-cover" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
              <p className="text-muted-foreground">
                {t("repair_col_lead")}: {leadTimeLabel(editItem, t)}
              </p>
              <Button type="button" className="w-full" onClick={() => void handleSaveEdit()} disabled={saveLoading}>
                {t("repair_btn_save")}
              </Button>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <Dialog open={!!photoPreview} onOpenChange={() => setPhotoPreview(null)}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>{t("photo")}</DialogTitle>
          </DialogHeader>
          {photoPreview && <ImageViewerWithRotate src={photoPreview} alt="" />}
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"
import { appAlert } from "@/lib/app-message"

import { useState, useEffect, useCallback, useMemo, useRef } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ImageIcon, X, ClipboardList, Save } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import {
  getStoreRepairProgressLogs,
  addStoreRepairProgressLog,
  updateStoreRepairTicket,
  uploadStoreRepairPhoto,
  type StoreRepairTicketItem,
  type StoreRepairProgressLog,
} from "@/lib/api-client"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { ImageViewerWithRotate } from "@/components/ui/image-viewer-with-rotate"
import { cn } from "@/lib/utils"
import { useTranslatedTextMap, useDebouncedTranslatedText } from "@/lib/use-ui-translate"

const OPEN_STATUSES = new Set(["접수", "진행중", "보류"])

const STATUSES: { v: string; k: string }[] = [
  { v: "접수", k: "repair_st_recv" },
  { v: "진행중", k: "repair_st_prog" },
  { v: "완료", k: "repair_st_done" },
  { v: "보류", k: "repair_st_hold" },
  { v: "취소", k: "repair_st_cancel" },
]

type Props = {
  tickets: StoreRepairTicketItem[]
  ticketsLoading: boolean
  onRefreshTickets: () => void
  writerName: string
  /** 목록에서 행 클릭 시 선택할 티켓 id (소비 후 onFocusTicketConsumed 호출) */
  focusTicketId?: number | null
  onFocusTicketConsumed?: () => void
}

export function StoreRepairsProcessTab({
  tickets,
  ticketsLoading,
  onRefreshTickets,
  writerName,
  focusTicketId = null,
  onFocusTicketConsumed,
}: Props) {
  const { lang } = useLang()
  const t = useT(lang)
  const fileRef = useRef<HTMLInputElement>(null)

  const [openOnly, setOpenOnly] = useState(true)
  const [selectedId, setSelectedId] = useState<number | null>(null)
  const [logs, setLogs] = useState<StoreRepairProgressLog[]>([])
  const [logsLoading, setLogsLoading] = useState(false)
  const [progressNote, setProgressNote] = useState("")
  const [progressPhotoUrls, setProgressPhotoUrls] = useState<string[]>([])
  const [saving, setSaving] = useState(false)
  const [photoPreview, setPhotoPreview] = useState<string | null>(null)

  const [draftStatus, setDraftStatus] = useState("")
  const [draftHandler, setDraftHandler] = useState("")
  const [draftResolution, setDraftResolution] = useState("")
  const [draftVendor, setDraftVendor] = useState("")
  const [draftActualCost, setDraftActualCost] = useState("")

  const ticketTitles = useMemo(() => tickets.map((x) => x.title || ""), [tickets])
  const translateTitle = useTranslatedTextMap(ticketTitles, lang)
  const progressTrans = useDebouncedTranslatedText(progressNote, lang)

  const filteredTickets = useMemo(() => {
    if (!openOnly) return tickets
    return tickets.filter((x) => OPEN_STATUSES.has(x.status))
  }, [tickets, openOnly])

  const selected = useMemo(
    () => (selectedId != null ? tickets.find((x) => x.id === selectedId) : null),
    [tickets, selectedId]
  )

  const loadLogs = useCallback(async (ticketId: number) => {
    setLogsLoading(true)
    try {
      const list = await getStoreRepairProgressLogs(ticketId)
      setLogs(Array.isArray(list) ? list : [])
    } catch {
      setLogs([])
    } finally {
      setLogsLoading(false)
    }
  }, [])

  useEffect(() => {
    if (selectedId == null) {
      setLogs([])
      return
    }
    void loadLogs(selectedId)
  }, [selectedId, loadLogs])

  useEffect(() => {
    if (!selected) return
    setDraftStatus(selected.status || "접수")
    setDraftHandler(selected.handler || "")
    setDraftResolution(selected.resolutionNote || "")
    setDraftVendor(selected.vendorName || "")
    setDraftActualCost(selected.actualCost != null ? String(selected.actualCost) : "")
    setProgressNote("")
    setProgressPhotoUrls([])
  }, [selected?.id])

  useEffect(() => {
    if (focusTicketId != null) {
      const tix = tickets.find((x) => x.id === focusTicketId)
      if (tix && !OPEN_STATUSES.has(tix.status)) setOpenOnly(false)
      if (tix) setSelectedId(focusTicketId)
      onFocusTicketConsumed?.()
      return
    }
    if (filteredTickets.length === 0) {
      setSelectedId(null)
      return
    }
    if (selectedId == null || !filteredTickets.some((x) => x.id === selectedId)) {
      setSelectedId(filteredTickets[0].id ?? null)
    }
  }, [focusTicketId, tickets, filteredTickets, selectedId, onFocusTicketConsumed])

  const labelSt = (v: string) => STATUSES.find((c) => c.v === v)?.k || "repair_st_recv"

  const onPickProgressPhotos = async (files: FileList | null) => {
    if (!files?.length || !selected?.store) return
    const next: string[] = []
    for (let i = 0; i < files.length; i++) {
      const res = await uploadStoreRepairPhoto(selected.store, files[i])
      if (res.success && res.url) next.push(res.url)
      else await appAlert(translateApiMessage(res.message, t) || t("msg_upload_fail"))
    }
    if (next.length) setProgressPhotoUrls((u) => [...u, ...next])
  }

  const saveTicketMeta = async () => {
    if (!selected?.id) return
    setSaving(true)
    try {
      const res = await updateStoreRepairTicket(selected.id, {
        store: selected.store,
        reporter: selected.reporter,
        category: selected.category,
        priority: selected.priority,
        area: selected.area,
        title: selected.title,
        description: selected.description,
        photoUrls: selected.photoUrls,
        status: draftStatus,
        handler: draftHandler,
        resolutionNote: draftResolution,
        vendorName: draftVendor,
        estimatedCost: selected.estimatedCost,
        actualCost: draftActualCost.trim() === "" ? null : Number(draftActualCost),
      })
      if (res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("store_check_updated"))
        onRefreshTickets()
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("msg_modify_fail"))
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaving(false)
    }
  }

  const saveProgressLog = async () => {
    if (!selected?.id) return
    const note = progressNote.trim()
    if (!note) {
      await appAlert(t("repair_progress_note_required"))
      return
    }
    setSaving(true)
    try {
      const res = await addStoreRepairProgressLog({
        ticketId: selected.id,
        author: writerName,
        note,
        photoUrls: progressPhotoUrls,
      })
      if (res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("store_check_saved"))
        setProgressNote("")
        setProgressPhotoUrls([])
        await loadLogs(selected.id)
        onRefreshTickets()
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail"))
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaving(false)
    }
  }

  const saveAll = async () => {
    if (!selected?.id) return
    const note = progressNote.trim()
    setSaving(true)
    try {
      if (note) {
        const r1 = await addStoreRepairProgressLog({
          ticketId: selected.id,
          author: writerName,
          note,
          photoUrls: progressPhotoUrls,
        })
        if (!r1.success) {
          await appAlert(translateApiMessage(r1.message, t) || t("msg_save_fail"))
          return
        }
        setProgressNote("")
        setProgressPhotoUrls([])
      }
      const r2 = await updateStoreRepairTicket(selected.id, {
        store: selected.store,
        reporter: selected.reporter,
        category: selected.category,
        priority: selected.priority,
        area: selected.area,
        title: selected.title,
        description: selected.description,
        photoUrls: selected.photoUrls,
        status: draftStatus,
        handler: draftHandler,
        resolutionNote: draftResolution,
        vendorName: draftVendor,
        estimatedCost: selected.estimatedCost,
        actualCost: draftActualCost.trim() === "" ? null : Number(draftActualCost),
      })
      if (r2.success) {
        await appAlert(translateApiMessage(r2.message, t) || t("store_check_updated"))
        await loadLogs(selected.id)
        onRefreshTickets()
      } else {
        await appAlert(translateApiMessage(r2.message, t) || t("msg_modify_fail"))
      }
    } catch (e) {
      await appAlert(t("msg_error_prefix") + (e instanceof Error ? e.message : String(e)))
    } finally {
      setSaving(false)
    }
  }

  const formatWhen = (iso: string) => {
    if (!iso) return "—"
    try {
      return new Date(iso).toLocaleString(lang === "ko" ? "ko-KR" : lang === "th" ? "th-TH" : "en-GB", {
        timeZone: "Asia/Bangkok",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
      })
    } catch {
      return iso.slice(0, 16).replace("T", " ")
    }
  }

  return (
    <div className="space-y-4">
      <p className="text-xs text-muted-foreground">{t("repair_process_sub")}</p>

      <div className="flex flex-wrap items-center gap-4">
        <label className="flex items-center gap-2 text-xs cursor-pointer">
          <Checkbox checked={openOnly} onCheckedChange={(c) => setOpenOnly(c === true)} />
          {t("repair_process_open_only")}
        </label>
        <Button type="button" variant="outline" size="sm" className="h-8 text-xs" onClick={() => onRefreshTickets()} disabled={ticketsLoading}>
          {t("repair_btn_load")}
        </Button>
      </div>

      <div className="grid gap-4 lg:grid-cols-12">
        <Card className="lg:col-span-4">
          <CardContent className="p-3 space-y-1 max-h-[70vh] overflow-y-auto">
            <p className="text-xs font-semibold text-muted-foreground mb-2 flex items-center gap-1">
              <ClipboardList className="h-3.5 w-3.5" />
              {t("repair_process_pick")}
            </p>
            {ticketsLoading ? (
              <p className="text-xs text-muted-foreground">{t("loading")}</p>
            ) : filteredTickets.length === 0 ? (
              <p className="text-xs text-muted-foreground">—</p>
            ) : (
              filteredTickets.map((row) => (
                <button
                  key={row.id}
                  type="button"
                  onClick={() => setSelectedId(row.id ?? null)}
                  className={cn(
                    "w-full text-left rounded-md border px-2 py-2 text-xs transition-colors",
                    selectedId === row.id ? "border-primary bg-primary/10" : "border-border hover:bg-muted/50"
                  )}
                >
                  <div className="font-mono text-[10px] text-muted-foreground">{row.ticketNumber}</div>
                  <div className="font-medium line-clamp-2" title={row.title || undefined}>
                    {translateTitle(row.title || "")}
                  </div>
                  <div className="text-muted-foreground mt-0.5">
                    {row.store} · {t(labelSt(row.status))}
                  </div>
                </button>
              ))
            )}
          </CardContent>
        </Card>

        <div className="lg:col-span-8 space-y-4">
          {!selected ? (
            <Card>
              <CardContent className="p-8 text-center text-sm text-muted-foreground">{t("repair_process_pick")}</CardContent>
            </Card>
          ) : (
            <>
              <Card>
                <CardContent className="p-4 space-y-3 text-xs">
                  <div className="flex flex-wrap justify-between gap-2">
                    <div>
                      <span className="font-mono text-muted-foreground">{selected.ticketNumber}</span>
                      <h3 className="text-sm font-semibold mt-1" title={selected.title || undefined}>
                        {translateTitle(selected.title || "")}
                      </h3>
                      <p className="text-muted-foreground mt-1">
                        {selected.store} · {t("repair_field_category")}: {selected.category}
                      </p>
                    </div>
                  </div>
                  {selected.description ? (
                    <p className="text-muted-foreground border-l-2 border-border pl-2 whitespace-pre-wrap">{selected.description}</p>
                  ) : null}

                  <div className="grid sm:grid-cols-2 gap-3 pt-2 border-t">
                    <div>
                      <label className="font-semibold block mb-1">{t("repair_field_status")}</label>
                      <Select value={draftStatus} onValueChange={setDraftStatus}>
                        <SelectTrigger className="h-8">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {STATUSES.map((s) => (
                            <SelectItem key={s.v} value={s.v}>
                              {t(s.k)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <label className="font-semibold block mb-1">{t("repair_field_handler")}</label>
                      <Input className="h-8" value={draftHandler} onChange={(e) => setDraftHandler(e.target.value)} />
                    </div>
                    <div className="sm:col-span-2">
                      <label className="font-semibold block mb-1">{t("repair_process_resolution_summary")}</label>
                      <p className="text-[11px] text-muted-foreground mb-1">{t("repair_process_resolution_hint")}</p>
                      <Textarea rows={3} value={draftResolution} onChange={(e) => setDraftResolution(e.target.value)} />
                    </div>
                    <div>
                      <label className="font-semibold block mb-1">{t("repair_field_vendor")}</label>
                      <Input className="h-8" value={draftVendor} onChange={(e) => setDraftVendor(e.target.value)} />
                    </div>
                    <div>
                      <label className="font-semibold block mb-1">{t("repair_process_actual_cost")}</label>
                      <Input
                        className="h-8"
                        type="number"
                        inputMode="decimal"
                        value={draftActualCost}
                        onChange={(e) => setDraftActualCost(e.target.value)}
                      />
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2 pt-2">
                    <Button type="button" size="sm" variant="secondary" onClick={() => void saveTicketMeta()} disabled={saving}>
                      {t("repair_process_save_ticket_only")}
                    </Button>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-4 space-y-3">
                  <h4 className="text-sm font-semibold">{t("repair_process_timeline")}</h4>
                  {logsLoading ? (
                    <p className="text-xs text-muted-foreground">{t("loading")}</p>
                  ) : logs.length === 0 ? (
                    <p className="text-xs text-muted-foreground">{t("repair_no_progress_yet")}</p>
                  ) : (
                    <ul className="space-y-3 border-l-2 border-primary/30 pl-3 ml-1">
                      {logs.map((log) => (
                        <li key={log.id} className="relative text-xs">
                          <div className="text-[10px] text-muted-foreground">{formatWhen(log.createdAt)}</div>
                          <div className="text-[10px] text-muted-foreground">{log.author || "—"}</div>
                          <p className="mt-1 whitespace-pre-wrap">{log.note}</p>
                          {log.photoUrls?.length ? (
                            <div className="flex flex-wrap gap-1 mt-2">
                              {log.photoUrls.map((url) => (
                                <button
                                  key={url}
                                  type="button"
                                  onClick={() => setPhotoPreview(url)}
                                  className="h-12 w-12 rounded border overflow-hidden"
                                >
                                  {/* eslint-disable-next-line @next/next/no-img-element */}
                                  <img src={url} alt="" className="h-full w-full object-cover" />
                                </button>
                              ))}
                            </div>
                          ) : null}
                        </li>
                      ))}
                    </ul>
                  )}
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-4 space-y-3">
                  <h4 className="text-sm font-semibold">{t("repair_process_new_entry")}</h4>
                  <p className="text-[11px] text-muted-foreground">{t("repair_progress_note_ph")}</p>
                  <Textarea
                    rows={5}
                    className="text-xs"
                    placeholder={t("repair_progress_note_ph")}
                    value={progressNote}
                    onChange={(e) => setProgressNote(e.target.value)}
                  />
                  {progressNote.trim() ? (
                    <div className="rounded-md border border-dashed border-border/80 bg-muted/25 px-2 py-1.5 text-[11px]">
                      <div className="font-medium text-muted-foreground">{t("repair_translate_preview")}</div>
                      {progressTrans.pending ? (
                        <p className="mt-1 text-muted-foreground">{t("repair_translate_loading")}</p>
                      ) : progressTrans.translated && progressTrans.translated !== progressNote.trim() ? (
                        <p className="mt-1 whitespace-pre-wrap text-foreground/90">{progressTrans.translated}</p>
                      ) : (
                        <p className="mt-1 text-muted-foreground">—</p>
                      )}
                    </div>
                  ) : null}
                  <input
                    ref={fileRef}
                    type="file"
                    accept="image/*"
                    multiple
                    className="hidden"
                    onChange={(e) => {
                      void onPickProgressPhotos(e.target.files)
                      e.target.value = ""
                    }}
                  />
                  <Button type="button" variant="outline" size="sm" className="h-8 text-xs" onClick={() => fileRef.current?.click()}>
                    <ImageIcon className="h-3.5 w-3.5 mr-1" />
                    {t("repair_photo_add")}
                  </Button>
                  {progressPhotoUrls.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {progressPhotoUrls.map((url) => (
                        <div key={url} className="relative h-14 w-14 rounded border overflow-hidden">
                          <button
                            type="button"
                            className="absolute top-0 right-0 z-10 bg-background/90 p-0.5"
                            onClick={() => setProgressPhotoUrls((u) => u.filter((x) => x !== url))}
                          >
                            <X className="h-3 w-3" />
                          </button>
                          <button type="button" onClick={() => setPhotoPreview(url)} className="block h-full w-full">
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img src={url} alt="" className="h-full w-full object-cover" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                  <div className="flex flex-wrap gap-2 pt-2">
                    <Button type="button" size="sm" onClick={() => void saveProgressLog()} disabled={saving || !progressNote.trim()}>
                      {t("repair_process_save_log_only")}
                    </Button>
                    <Button type="button" size="sm" variant="default" onClick={() => void saveAll()} disabled={saving}>
                      <Save className="h-3.5 w-3.5 mr-1" />
                      {t("repair_process_save_all")}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            </>
          )}
        </div>
      </div>

      <Dialog open={!!photoPreview} onOpenChange={() => setPhotoPreview(null)}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>{t("photo")}</DialogTitle>
          </DialogHeader>
          {photoPreview && <ImageViewerWithRotate src={photoPreview} alt="" />}
        </DialogContent>
      </Dialog>
    </div>
  )
}

