"use client"
import { appAlert } from "@/lib/app-message"

import * as React from "react"
import {
  Send,
  Paperclip,
  X,
  Store,
  Briefcase,
  Shield,
  Users,
  FileText,
  Image as ImageIcon,
  File,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Checkbox } from "@/components/ui/checkbox"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import { getNoticeOptions, sendNotice, useStoreList } from "@/lib/api-client"

interface AttachedFile {
  id: string
  name: string
  size: string
  type: "image" | "pdf" | "doc"
  dataUrl: string
  mime: string
}

const MAX_FILE_SIZE = 1024 * 1024
const MAX_FILES = 3

export function AdminNoticeCompose() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [title, setTitle] = React.useState("")
  const [content, setContent] = React.useState("")
  const [stores, setStores] = React.useState<string[]>([])
  const [positions, setPositions] = React.useState<string[]>([])
  const [permissionGroups, setPermissionGroups] = React.useState<string[]>([])
  const [selectedStores, setSelectedStores] = React.useState<string[]>([])
  const [selectedPositions, setSelectedPositions] = React.useState<string[]>([])
  const [selectedPermissionGroups, setSelectedPermissionGroups] = React.useState<string[]>([])
  const [selectedRecipients, setSelectedRecipients] = React.useState<string[]>([])
  const [files, setFiles] = React.useState<AttachedFile[]>([])
  const { staffByStore } = useStoreList()
  const [sending, setSending] = React.useState(false)
  const fileInputRef = React.useRef<HTMLInputElement>(null)

  React.useEffect(() => {
    if (!auth?.store) return
    const isOffice = auth.role === "director" || auth.role === "officer"
    getNoticeOptions().then((r) => {
      const allLabel = t("noticeFilterAll")
      const storeList = isOffice ? (r.stores || []) : [auth.store!]
      setStores([allLabel, ...storeList])
      setPositions([allLabel, ...(r.roles || [])])
      setPermissionGroups([allLabel, ...(r.permissionGroups || [])])
    })
  }, [auth?.store, auth?.role, lang])

  const toggleStore = (store: string) => {
    const allLabel = t("noticeFilterAll")
    if (store === allLabel) {
      setSelectedStores(
        selectedStores.length === stores.length - 1
          ? []
          : stores.filter((s) => s !== allLabel)
      )
      return
    }
    setSelectedStores((prev) =>
      prev.includes(store) ? prev.filter((s) => s !== store) : [...prev, store]
    )
  }

  const togglePosition = (position: string) => {
    const allLabel = t("noticeFilterAll")
    if (position === allLabel) {
      setSelectedPositions(
        selectedPositions.length === positions.length - 1
          ? []
          : positions.filter((p) => p !== allLabel)
      )
      return
    }
    setSelectedPositions((prev) =>
      prev.includes(position)
        ? prev.filter((p) => p !== position)
        : [...prev, position]
    )
  }

  const togglePermissionGroup = (perm: string) => {
    const allLabel = t("noticeFilterAll")
    if (perm === allLabel) {
      setSelectedPermissionGroups(
        selectedPermissionGroups.length === permissionGroups.length - 1
          ? []
          : permissionGroups.filter((p) => p !== allLabel)
      )
      return
    }
    setSelectedPermissionGroups((prev) =>
      prev.includes(perm) ? prev.filter((p) => p !== perm) : [...prev, perm]
    )
  }

  const toggleRecipient = (store: string, name: string) => {
    const key = `${store}|${name}`
    setSelectedRecipients((prev) =>
      prev.includes(key) ? prev.filter((x) => x !== key) : [...prev, key]
    )
  }

  const allStoresForStaff =
    selectedStores.length === 0 ||
    selectedStores.length === stores.length - 1
  const storeNamesForStaff = allStoresForStaff
    ? stores.filter((s) => s !== t("noticeFilterAll"))
    : selectedStores
  const allPositionsForStaff =
    selectedPositions.length === 0 ||
    selectedPositions.length === positions.length - 1
  const positionsToMatch = allPositionsForStaff
    ? null
    : new Set(
        selectedPositions
          .filter((p) => p !== t("noticeFilterAll"))
          .map((r) => r.trim().toLowerCase())
          .filter(Boolean)
      )
  const allPermissionGroupsForStaff =
    selectedPermissionGroups.length === 0 ||
    selectedPermissionGroups.length === permissionGroups.length - 1
  const permissionGroupsToMatch = allPermissionGroupsForStaff
    ? null
    : new Set(
        selectedPermissionGroups
          .filter((p) => p !== t("noticeFilterAll"))
          .map((r) => r.trim().toLowerCase())
          .filter(Boolean)
      )
  const employeeList = (() => {
    const list: { store: string; name: string; nick: string }[] = []
    for (const store of storeNamesForStaff) {
      const staff = staffByStore[store] || []
      for (const s of staff) {
        if (!s.name) continue
        if (positionsToMatch && positionsToMatch.size > 0) {
          const empJob = String(s.job || "").trim().toLowerCase()
          if (!empJob || !positionsToMatch.has(empJob)) continue
        }
        if (permissionGroupsToMatch && permissionGroupsToMatch.size > 0) {
          const empRole = String(s.role || "").trim().toLowerCase()
          if (!empRole || !permissionGroupsToMatch.has(empRole)) continue
        }
        list.push({ store, name: s.name, nick: s.nick || s.name })
      }
    }
    return list.sort((a, b) => (a.nick || "").localeCompare(b.nick || ""))
  })()

  // 매장/권한그룹/부서 선택 시 해당 직원을 모두 체크(선택) 상태로. 필요 없는 직원만 체크 해제하면 됨
  const employeeKeysStr = employeeList.map((e) => `${e.store}|${e.name}`).sort().join(",")
  React.useEffect(() => {
    const keys = employeeList.map((e) => `${e.store}|${e.name}`)
    setSelectedRecipients(keys)
  }, [employeeKeysStr])

  const removeFile = (id: string) => {
    setFiles((prev) => prev.filter((f) => f.id !== id))
  }

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const input = e.target
    const selected = input.files
    if (!selected || selected.length === 0) return
    const remaining = MAX_FILES - files.length
    if (remaining <= 0) {
      await appAlert(t("noticeFileLimit") || "파일당 5MB, 최대 10개")
      input.value = ""
      return
    }
    const newFiles: AttachedFile[] = []
    const processNext = async (idx: number) => {
      if (idx >= selected.length || newFiles.length >= remaining) {
        if (newFiles.length > 0) setFiles((prev) => [...prev, ...newFiles])
        input.value = ""
        return
      }
      const file = selected[idx]
      if (file.size > MAX_FILE_SIZE) {
        await appAlert(`${file.name}: ` + (t("noticeFileLimit") || "파일당 1MB, 최대 3개"))
        void processNext(idx + 1)
        return
      }
      const reader = new FileReader()
      reader.onload = () => {
        const dataUrl = reader.result as string
        const mime = file.type || "application/octet-stream"
        let typ: "image" | "pdf" | "doc" = "doc"
        if (mime.startsWith("image/")) typ = "image"
        else if (mime.includes("pdf")) typ = "pdf"
        newFiles.push({
          id: `f-${Date.now()}-${idx}`,
          name: file.name,
          size: `${(file.size / 1024).toFixed(1)} KB`,
          type: typ,
          dataUrl,
          mime,
        })
        void processNext(idx + 1)
      }
      reader.readAsDataURL(file)
    }
    void processNext(0)
  }

  const handleSend = async () => {
    if (!title.trim()) {
      await appAlert(t("adminNoticeSubjectRequired"))
      return
    }
    if (!auth?.store || !auth?.user) return
    const allStores = selectedStores.length === stores.length - 1
    const allPos = selectedPositions.length === positions.length - 1
    const allPerm = selectedPermissionGroups.length === permissionGroups.length - 1
    const targetStore =
      selectedStores.length === 0 || allStores ? "전체" : selectedStores.join(",")
    const targetRole =
      selectedPositions.length === 0 || allPos ? "전체" : selectedPositions.join(",")
    const targetPermissionGroup =
      selectedPermissionGroups.length === 0 || allPerm ? "" : selectedPermissionGroups.join(",")
    const targetRecipients =
      selectedRecipients.length > 0
        ? selectedRecipients.map((k) => {
            const [s, n] = k.split("|")
            return { store: s || "", name: n || "" }
          })
        : undefined
    setSending(true)
    try {
      const attachments = files.map((f) => ({ name: f.name, mime: f.mime, url: f.dataUrl }))
      const res = await sendNotice({
        title: title.trim(),
        content: content.trim(),
        targetStore,
        targetRole,
        targetPermissionGroup: targetPermissionGroup || undefined,
        sender: auth.user,
        userStore: auth.store,
        userRole: auth.role,
        attachments,
        targetRecipients,
      })
      if (res.success) {
        setTitle("")
        setContent("")
        setSelectedStores([])
        setSelectedPositions([])
        setSelectedPermissionGroups([])
        setSelectedRecipients([])
        setFiles([])
        window.dispatchEvent(new CustomEvent("notice-sent"))
        await appAlert(translateApiMessage(res.message, t) || t("noticeSentSuccess"))
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("noticeSendFail"))
      }
    } finally {
      setSending(false)
    }
  }

  if (!auth?.store || !auth?.user) return null

  return (
    <div className="rounded-xl border bg-card shadow-sm">
      {/* Header */}
      <div className="flex items-center justify-between gap-3 border-b px-6 py-4">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
            <Send className="h-[18px] w-[18px] text-primary" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-card-foreground">
              {t("noticeNewTitle")}
            </h3>
            <p className="text-[11px] text-muted-foreground">
              {t("noticeNewSub")}
            </p>
          </div>
        </div>
        <button
          type="button"
          className="text-[11px] text-muted-foreground hover:text-foreground underline"
          onClick={async () => {
            try {
              const r = await fetch('/api/debugPushStatus')
              const d = await r.json()
              const msg = [
                `푸시 알림: ${d.pushNoticeEnabled ? 'ON' : 'OFF'}`,
                `Firebase: ${d.firebaseConfigured ? '설정됨' : '미설정'}`,
                `등록 토큰: ${d.pushTokensCount}개`,
                d.employeesWithoutTokenTotal > 0
                  ? `토큰 미등록: ${d.employeesWithoutTokenTotal}명`
                  : '',
                d.hint || '',
              ]
                .filter(Boolean)
                .join('\n')
              await appAlert(msg)
            } catch (e) {
              await appAlert('점검 실패: ' + (e instanceof Error ? e.message : String(e)))
            }
          }}
        >
          푸시 상태 점검
        </button>
      </div>

      <div className="flex flex-col gap-5 p-6">
        {/* Title */}
        <div className="flex flex-col gap-2">
          <label className="text-xs font-semibold text-foreground">
            {t("labelSubject")}
          </label>
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder={t("noticeTitlePlaceholder")}
            className="h-10 text-sm"
          />
        </div>

        {/* 매장 | 권한 그룹 | 대상 부서 한 줄 */}
        <div className="grid grid-cols-3 gap-4">
          {/* 매장 */}
          <div className="flex flex-col gap-2">
            <label className="flex items-center gap-2 text-xs font-semibold text-foreground">
              <Store className="h-3.5 w-3.5 text-primary" />
              {t("store")}
              {selectedStores.length > 0 && (
                <span className="rounded-md bg-primary/10 px-1.5 py-0.5 text-[10px] font-bold text-primary">
                  {selectedStores.length === stores.length - 1
                    ? t("noticeFilterAll")
                    : `${selectedStores.length}${t("noticeStoreCountSuffix")}`}
                </span>
              )}
            </label>
            <ScrollArea className="h-[180px] rounded-lg border bg-muted/20 p-1">
              <div className="flex flex-col gap-0.5">
                {stores.map((store) => {
                  const isAll = store === t("noticeFilterAll")
                  const checked = isAll
                    ? selectedStores.length === stores.length - 1
                    : selectedStores.includes(store)
                  return (
                    <label
                      key={store}
                      className={cn(
                        "flex items-center gap-2.5 rounded-md px-3 py-2 text-xs cursor-pointer transition-colors",
                        checked
                          ? "bg-primary/10 font-semibold text-primary"
                          : "text-card-foreground hover:bg-muted/50"
                      )}
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => toggleStore(store)}
                        className="h-4 w-4"
                      />
                      <span>{store}</span>
                    </label>
                  )
                })}
              </div>
            </ScrollArea>
          </div>

          {/* 권한 그룹 */}
          <div className="flex flex-col gap-2">
            <label className="flex items-center gap-2 text-xs font-semibold text-foreground">
              <Shield className="h-3.5 w-3.5 text-amber-600" />
              {t("adminTargetPermissionGroups")}
              {selectedPermissionGroups.length > 0 && (
                <span className="rounded-md bg-amber-500/10 px-1.5 py-0.5 text-[10px] font-bold text-amber-700">
                  {selectedPermissionGroups.length === permissionGroups.length - 1
                    ? t("noticePermissionGroupAll")
                    : `${selectedPermissionGroups.length}${t("noticePermissionGroupCountSuffix")}`}
                </span>
              )}
            </label>
            <ScrollArea className="h-[180px] rounded-lg border bg-muted/20 p-1">
              <div className="flex flex-col gap-0.5">
                {permissionGroups.map((perm) => {
                  const isAll = perm === t("noticeFilterAll")
                  const checked = isAll
                    ? selectedPermissionGroups.length === permissionGroups.length - 1
                    : selectedPermissionGroups.includes(perm)
                  return (
                    <label
                      key={perm}
                      className={cn(
                        "flex items-center gap-2.5 rounded-md px-3 py-2 text-xs cursor-pointer transition-colors",
                        checked
                          ? "bg-amber-500/10 font-semibold text-amber-700"
                          : "text-card-foreground hover:bg-muted/50"
                      )}
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => togglePermissionGroup(perm)}
                        className="h-4 w-4"
                      />
                      <span>{perm}</span>
                    </label>
                  )
                })}
              </div>
            </ScrollArea>
          </div>

          {/* 대상 부서 */}
          <div className="flex flex-col gap-2">
            <label className="flex items-center gap-2 text-xs font-semibold text-foreground">
              <Briefcase className="h-3.5 w-3.5 text-success" />
              {t("noticeTargetDept") || "대상 부서"}
              {selectedPositions.length > 0 && (
                <span className="rounded-md bg-success/10 px-1.5 py-0.5 text-[10px] font-bold text-success">
                  {selectedPositions.length === positions.length - 1
                    ? t("noticeFilterAll")
                    : `${selectedPositions.length}${t("noticePositionCountSuffix")}`}
                </span>
              )}
            </label>
            <ScrollArea className="h-[180px] rounded-lg border bg-muted/20 p-1">
              <div className="flex flex-col gap-0.5">
                {positions.map((pos) => {
                  const isAll = pos === t("noticeFilterAll")
                  const checked = isAll
                    ? selectedPositions.length === positions.length - 1
                    : selectedPositions.includes(pos)
                  return (
                    <label
                      key={pos}
                      className={cn(
                        "flex items-center gap-2.5 rounded-md px-3 py-2 text-xs cursor-pointer transition-colors",
                        checked
                          ? "bg-success/10 font-semibold text-success"
                          : "text-card-foreground hover:bg-muted/50"
                      )}
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => togglePosition(pos)}
                        className="h-4 w-4"
                      />
                      <span>{pos}</span>
                    </label>
                  )
                })}
              </div>
            </ScrollArea>
          </div>
        </div>

        {/* Individual employees (by nickname) */}
        <div className="flex flex-col gap-2">
          <label className="flex items-center gap-2 text-xs font-semibold text-foreground">
            <Users className="h-3.5 w-3.5 text-amber-500" />
            {t("adminTargetIndividuals")}
            {selectedRecipients.length > 0 && (
              <span className="rounded-md bg-amber-500/10 px-1.5 py-0.5 text-[10px] font-bold text-amber-600">
                {selectedRecipients.length}{t("adminRecipientsCountSuffix")}
              </span>
            )}
          </label>
          <ScrollArea className="h-[120px] rounded-lg border bg-muted/20 p-2">
            <div className="flex flex-wrap gap-1.5">
              {employeeList.length === 0 ? (
                <span className="text-xs text-muted-foreground">-</span>
              ) : (
                employeeList.map((emp) => {
                  const key = `${emp.store}|${emp.name}`
                  const checked = selectedRecipients.includes(key)
                  return (
                    <label
                      key={key}
                      className={cn(
                        "inline-flex items-center gap-1.5 rounded-md px-2.5 py-1.5 text-xs cursor-pointer transition-colors",
                        checked
                          ? "bg-amber-500/15 font-semibold text-amber-700"
                          : "text-card-foreground hover:bg-muted/50"
                      )}
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => toggleRecipient(emp.store, emp.name)}
                        className="h-3.5 w-3.5"
                      />
                      <span>{emp.nick}</span>
                    </label>
                  )
                })
              )}
            </div>
          </ScrollArea>
        </div>

        {/* Content */}
        <div className="flex flex-col gap-2">
          <label className="text-xs font-semibold text-foreground">
            {t("labelContent")}
          </label>
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={t("noticeContentPlaceholder")}
            className="min-h-[160px] text-sm resize-none"
          />
        </div>

        {/* File attachment */}
        <div className="flex flex-col gap-2">
          <label className="text-xs font-semibold text-foreground">
            {t("noticeFileLabel")}
          </label>
          {files.length > 0 && (
            <div className="flex flex-col gap-1.5">
              {files.map((file) => (
                <div
                  key={file.id}
                  className="flex items-center gap-2.5 rounded-lg border bg-muted/20 px-3 py-2"
                >
                  {file.type === "image" ? (
                    <ImageIcon className="h-4 w-4 shrink-0 text-primary" />
                  ) : file.type === "pdf" ? (
                    <FileText className="h-4 w-4 shrink-0 text-destructive" />
                  ) : (
                    <File className="h-4 w-4 shrink-0 text-muted-foreground" />
                  )}
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-xs font-semibold text-card-foreground">
                      {file.name}
                    </p>
                    <p className="text-[10px] text-muted-foreground">{file.size}</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => removeFile(file.id)}
                    className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
          <div className="flex items-center gap-3">
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*,.pdf,.doc,.docx,.xls,.xlsx"
              multiple
              className="hidden"
              onChange={handleFileSelect}
            />
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 rounded-lg border-2 border-dashed border-border px-4 py-3 text-xs font-semibold text-muted-foreground transition-colors hover:bg-muted/30 hover:border-muted-foreground/30"
            >
              <Paperclip className="h-4 w-4" />
              <span>{t("noticeFileAdd").split("(")[0]?.trim() || t("noticeFileAdd")}</span>
            </button>
            <p className="text-[11px] text-muted-foreground">{t("noticeFileLimit")}</p>
          </div>
        </div>

        {/* Submit */}
        <Button
          className="h-11 text-sm font-bold"
          onClick={handleSend}
          disabled={sending}
        >
          <Send className="mr-2 h-4 w-4" />
          {sending ? t("loading") : t("adminSendNoticeBtn")}
        </Button>
      </div>
    </div>
  )
}

"use client"
import { appAlert, appConfirm } from "@/lib/app-message"

import * as React from "react"
import {
  Search,
  Clock,
  Eye,
  Users,
  FileText,
  ChevronDown,
  ChevronUp,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import {
  getSentNotices,
  deleteNoticeAdmin,
  getNoticeReadDetail,
  getNoticeSenders,
  translateTexts,
  type SentNoticeItem,
  type NoticeReadDetailItem,
} from "@/lib/api-client"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { ListPaginationBar } from "@/components/list-pagination-bar"

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

function defaultStartStr() {
  const d = new Date()
  d.setMonth(d.getMonth() - 1)
  return d.toISOString().slice(0, 10)
}

export function AdminNoticeHistory() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [startDate, setStartDate] = React.useState(todayStr)
  const [endDate, setEndDate] = React.useState(todayStr)
  const [senderFilter, setSenderFilter] = React.useState<string>("mine")
  const [senders, setSenders] = React.useState<string[]>([])
  const [expandedId, setExpandedId] = React.useState<string | null>(null)
  const [notices, setNotices] = React.useState<SentNoticeItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [transMap, setTransMap] = React.useState<Record<string, string>>({})
  const [readDetailOpen, setReadDetailOpen] = React.useState(false)
  const [readDetailTitle, setReadDetailTitle] = React.useState("")
  const [readDetailItems, setReadDetailItems] = React.useState<NoticeReadDetailItem[]>([])
  const [readDetailLoading, setReadDetailLoading] = React.useState(false)
  const [searchType, setSearchType] = React.useState<"all" | "notice" | "order">("all")
  const [searchKeyword, setSearchKeyword] = React.useState("")
  const [listPage, setListPage] = React.useState(1)
  const listPageSize = 15
  const [listTotal, setListTotal] = React.useState(0)
  const [listTruncated, setListTruncated] = React.useState(false)
  type SentListQuery = {
    startDate: string
    endDate: string
    senderFilter: string
    searchType: "all" | "notice" | "order"
    keyword: string
  }
  const [listQuery, setListQuery] = React.useState<SentListQuery | null>(null)

  const runSentListFetch = React.useCallback(
    (page: number, query: SentListQuery) => {
      if (!auth?.store || !auth?.user) return
      setLoading(true)
      const sender = query.senderFilter === "all" ? "all" : query.senderFilter === "mine" ? auth.user : query.senderFilter
      getSentNotices({
        sender: sender || auth.user,
        startDate: query.startDate,
        endDate: query.endDate,
        userStore: auth.store,
        userRole: auth.role,
        searchType: query.searchType,
        keyword: query.keyword.trim() || undefined,
        page,
        pageSize: listPageSize,
      })
        .then((res) => {
          setNotices(res.items)
          setListTotal(res.total)
          setListTruncated(Boolean(res.truncated))
          setListPage(res.page)
        })
        .catch(() => {
          setNotices([])
          setListTotal(0)
          setListTruncated(false)
        })
        .finally(() => setLoading(false))
    },
    [auth?.store, auth?.user, auth?.role, listPageSize]
  )

  React.useEffect(() => {
    if (!listQuery) return
    runSentListFetch(listPage, listQuery)
  }, [listQuery, listPage, runSentListFetch])

  const handleSearchNotices = React.useCallback(() => {
    setListQuery({
      startDate,
      endDate,
      senderFilter,
      searchType,
      keyword: searchKeyword,
    })
    setListPage(1)
  }, [startDate, endDate, senderFilter, searchType, searchKeyword])

  const loadSenders = React.useCallback(() => {
    getNoticeSenders({ startDate, endDate })
      .then(({ senders: s }) => setSenders(s))
      .catch(() => setSenders([]))
  }, [startDate, endDate])

  React.useEffect(() => {
    loadSenders()
  }, [loadSenders])

  React.useEffect(() => {
    const onSent = () => {
      if (listQuery) runSentListFetch(listPage, listQuery)
    }
    window.addEventListener("notice-sent", onSent)
    return () => window.removeEventListener("notice-sent", onSent)
  }, [listQuery, listPage, runSentListFetch])

  React.useEffect(() => {
    const texts = [...new Set(notices.flatMap((n) => [n.title, n.content || n.preview].filter(Boolean)))]
    if (texts.length === 0) {
      setTransMap({})
      return
    }
    let cancelled = false
    translateTexts(texts, lang).then((translated) => {
      if (cancelled) return
      const map: Record<string, string> = {}
      texts.forEach((txt, i) => { map[txt] = translated[i] ?? txt })
      setTransMap(map)
    }).catch(() => setTransMap({}))
    return () => { cancelled = true }
  }, [notices, lang])

  const getTrans = (text: string) => (text && transMap[text]) || text || ""

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation()
    if (!await appConfirm(t("noticeDeleteConfirm"))) return
    const res = await deleteNoticeAdmin({ id: Number(id) })
    if (res.success) {
      setNotices((prev) => prev.filter((n) => n.id !== id))
      setExpandedId(null)
    } else {
      await appAlert(translateApiMessage(res.message, t) || t("noticeDeleteFail"))
    }
  }

  const handleOpenReadDetail = React.useCallback(
    async (e: React.MouseEvent, notice: SentNoticeItem) => {
      e.stopPropagation()
      setReadDetailTitle(transMap[notice.title] || notice.title)
      setReadDetailOpen(true)
      setReadDetailItems([])
      setReadDetailLoading(true)
      try {
        const { items } = await getNoticeReadDetail({ noticeId: Number(notice.id) })
        setReadDetailItems(items)
      } catch {
        setReadDetailItems([])
      } finally {
        setReadDetailLoading(false)
      }
    },
    [transMap]
  )

  if (!auth?.store || !auth?.user) return null

  return (
    <div className="rounded-xl border bg-card shadow-sm">
      {/* Header */}
      <div className="flex items-center gap-3 border-b px-6 py-4">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-warning/10">
          <Clock className="h-[18px] w-[18px] text-warning" />
        </div>
        <div>
          <h3 className="text-sm font-bold text-card-foreground">
            {t("noticeHistoryTitle")}
          </h3>
          <p className="text-[11px] text-muted-foreground">
            {t("noticeHistorySub")}
          </p>
        </div>
      </div>

      {/* 1행: 공지사항 검색타입 + 검색창 + 검색 버튼 */}
      {/* 2행: 내 발송분 + 기간 */}
      <div className="border-b px-6 py-4 space-y-3 bg-muted/20">
        <div className="flex flex-wrap items-center gap-2">
          <Select value={searchType} onValueChange={(v) => setSearchType(v as "all" | "notice" | "order")}>
            <SelectTrigger className="h-9 w-[100px] text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">{t("noticeSearchTypeAll")}</SelectItem>
              <SelectItem value="notice">{t("noticeSearchTypeNotice")}</SelectItem>
              <SelectItem value="order">{t("noticeSearchTypeOrder")}</SelectItem>
            </SelectContent>
          </Select>
          <Input
            placeholder={
              searchType === "all"
                ? t("noticeSearchNoticePh")
                : searchType === "notice"
                  ? t("noticeSearchNoticePh")
                  : t("noticeSearchOrderApprovalPh")
            }
            value={searchKeyword}
            onChange={(e) => setSearchKeyword(e.target.value)}
            className="h-9 flex-1 min-w-[140px] max-w-[280px] text-xs"
          />
          <Button
            size="sm"
            className="h-9 px-4 text-xs font-semibold shrink-0"
            onClick={handleSearchNotices}
            disabled={loading}
          >
            <Search className="mr-1.5 h-3.5 w-3.5" />
            {loading ? t("loading") : t("search")}
          </Button>
          <span className="text-[11px] font-semibold text-muted-foreground ml-auto">
            {t("noticeCountPrefix")}{" "}
            <span className="text-foreground">{listQuery ? listTotal : 0}</span>
            {t("noticeCountSuffix")}
          </span>
        </div>
        {listQuery && listTruncated && (
          <p className="text-[11px] text-amber-600 dark:text-amber-500">
            기간 내 일부만 불러왔습니다. 기간을 나누어 검색해 보세요.
          </p>
        )}
        <div className="flex flex-wrap items-center gap-2">
          <div className="min-w-[120px]">
            <Select value={senderFilter} onValueChange={setSenderFilter}>
              <SelectTrigger className="h-9 text-xs">
                <SelectValue placeholder={t("noticeSenderAll")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("noticeSenderAll")}</SelectItem>
                <SelectItem value="mine">{t("noticeSenderMine")}</SelectItem>
                {senders
                  .filter((s) => s !== (auth?.user || ''))
                  .map((s) => (
                    <SelectItem key={s} value={s}>{s}</SelectItem>
                  ))}
              </SelectContent>
            </Select>
          </div>
          <Input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="date-input-compact h-9 w-[140px] text-xs"
          />
          <span className="text-xs font-medium text-muted-foreground">~</span>
          <Input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="date-input-compact h-9 w-[140px] text-xs"
          />
        </div>
      </div>

      {/* Notice list */}
      <div className="flex flex-col">
        {!listQuery ? (
          <div className="py-12 px-6 text-center text-sm text-muted-foreground">
            {t("msg_click_query") || "검색 버튼을 눌러 주세요."}
          </div>
        ) : notices.length === 0 ? (
          <div className="py-12 px-6 text-center text-sm text-muted-foreground">
            {t("adminNoNoticesFound")}
          </div>
        ) : (
          notices.map((notice, idx) => {
            const isExpanded = expandedId === notice.id
            const readPercent =
              notice.totalCount > 0
                ? Math.round((notice.readCount / notice.totalCount) * 100)
                : 0
            const allRead = notice.readCount === notice.totalCount

            return (
              <div
                key={notice.id}
                className={cn(
                  "border-b last:border-b-0 transition-colors",
                  isExpanded && "bg-muted/10"
                )}
              >
                {/* Row */}
                <button
                  type="button"
                  onClick={() =>
                    setExpandedId(isExpanded ? null : notice.id)
                  }
                  className="flex w-full flex-col gap-2 px-6 py-3 text-left hover:bg-muted/30 transition-colors"
                >
                  {/* Line 1: Index + 제목 | 대상 | 내용 */}
                  <div className="flex w-full items-center gap-3">
                    <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted text-[11px] font-bold tabular-nums text-muted-foreground">
                      {(listPage - 1) * listPageSize + idx + 1}
