"use client"
import { appAlert } from "@/lib/app-message"

import * as React from "react"
import {
  Send,
  Paperclip,
  X,
  ChevronDown,
  ChevronUp,
  Store,
  Briefcase,
  Shield,
  FileText,
  Image as ImageIcon,
  File,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import { getNoticeOptions, sendNotice } from "@/lib/api-client"

interface AttachedFile {
  id: string
  name: string
  size: string
  type: "image" | "pdf" | "doc"
  dataUrl: string
  mime: string
}

const MAX_FILE_SIZE = 1024 * 1024
const MAX_FILES = 3

export function NoticeCompose() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [title, setTitle] = React.useState("")
  const [content, setContent] = React.useState("")
  const [stores, setStores] = React.useState<string[]>([])
  const [positions, setPositions] = React.useState<string[]>([])
  const [permissionGroups, setPermissionGroups] = React.useState<string[]>([])
  const [selectedStores, setSelectedStores] = React.useState<string[]>([])
  const [selectedPositions, setSelectedPositions] = React.useState<string[]>([])
  const [selectedPermissionGroups, setSelectedPermissionGroups] = React.useState<string[]>([])
  const [storesOpen, setStoresOpen] = React.useState(false)
  const [positionsOpen, setPositionsOpen] = React.useState(false)
  const [permissionGroupsOpen, setPermissionGroupsOpen] = React.useState(false)
  const [files, setFiles] = React.useState<AttachedFile[]>([])
  const [sending, setSending] = React.useState(false)
  const fileInputRef = React.useRef<HTMLInputElement>(null)

  React.useEffect(() => {
    if (!auth?.store) return
    const isOffice = auth.role === "director" || auth.role === "officer"
    getNoticeOptions().then((r) => {
      const allLabel = t("noticeFilterAll")
      const storeList = isOffice ? (r.stores || []) : [auth.store!]
      setStores([allLabel, ...storeList])
      setPositions([allLabel, ...(r.roles || [])])
      setPermissionGroups([allLabel, ...(r.permissionGroups || [])])
    })
  }, [auth?.store, auth?.role, lang])

  const toggleStore = (store: string) => {
    const allLabel = t("noticeFilterAll")
    if (store === allLabel) {
      setSelectedStores(
        selectedStores.length === stores.length - 1
          ? []
          : stores.filter((s) => s !== allLabel)
      )
      return
    }
    setSelectedStores((prev) =>
      prev.includes(store) ? prev.filter((s) => s !== store) : [...prev, store]
    )
  }

  const togglePosition = (position: string) => {
    const allLabel = t("noticeFilterAll")
    if (position === allLabel) {
      setSelectedPositions(
        selectedPositions.length === positions.length - 1
          ? []
          : positions.filter((p) => p !== allLabel)
      )
      return
    }
    setSelectedPositions((prev) =>
      prev.includes(position)
        ? prev.filter((p) => p !== position)
        : [...prev, position]
    )
  }

  const togglePermissionGroup = (perm: string) => {
    const allLabel = t("noticeFilterAll")
    if (perm === allLabel) {
      setSelectedPermissionGroups(
        selectedPermissionGroups.length === permissionGroups.length - 1
          ? []
          : permissionGroups.filter((p) => p !== allLabel)
      )
      return
    }
    setSelectedPermissionGroups((prev) =>
      prev.includes(perm) ? prev.filter((p) => p !== perm) : [...prev, perm]
    )
  }

  const removeFile = (id: string) => {
    setFiles((prev) => prev.filter((f) => f.id !== id))
  }

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const input = e.target
    const selected = input.files
    if (!selected || selected.length === 0) return
    const remaining = MAX_FILES - files.length
    if (remaining <= 0) {
      await appAlert(t("noticeFileLimit") || "파일당 5MB, 최대 10개")
      input.value = ""
      return
    }
    const newFiles: AttachedFile[] = []
    const processNext = async (idx: number) => {
      if (idx >= selected.length || newFiles.length >= remaining) {
        if (newFiles.length > 0) setFiles((prev) => [...prev, ...newFiles])
        input.value = ""
        return
      }
      const file = selected[idx]
      if (file.size > MAX_FILE_SIZE) {
        await appAlert(`${file.name}: ` + (t("noticeFileLimit") || "파일당 1MB, 최대 3개"))
        void processNext(idx + 1)
        return
      }
      const reader = new FileReader()
      reader.onload = () => {
        const dataUrl = reader.result as string
        const mime = file.type || "application/octet-stream"
        let typ: "image" | "pdf" | "doc" = "doc"
        if (mime.startsWith("image/")) typ = "image"
        else if (mime.includes("pdf")) typ = "pdf"
        newFiles.push({
          id: `f-${Date.now()}-${idx}`,
          name: file.name,
          size: `${(file.size / 1024).toFixed(1)} KB`,
          type: typ,
          dataUrl,
          mime,
        })
        void processNext(idx + 1)
      }
      reader.readAsDataURL(file)
    }
    void processNext(0)
  }

  const storeLabel =
    selectedStores.length === 0
      ? t("noticeStorePlaceholder")
      : selectedStores.length === stores.length - 1
      ? t("scheduleStoreAll")
      : `${selectedStores.length}${t("noticeStoreCountSuffix")}`

  const positionLabel =
    selectedPositions.length === 0
      ? t("noticePositionSelect")
      : selectedPositions.length === positions.length - 1
      ? t("noticePositionAll")
      : `${selectedPositions.length}${t("noticePositionCountSuffix")}`

  const permissionGroupLabel =
    selectedPermissionGroups.length === 0
      ? t("noticePermissionGroupSelect")
      : selectedPermissionGroups.length === permissionGroups.length - 1
      ? t("noticePermissionGroupAll")
      : `${selectedPermissionGroups.length}${t("noticePermissionGroupCountSuffix")}`

  const handleSend = async () => {
    if (!title.trim()) {
      await appAlert(t("adminNoticeSubjectRequired"))
      return
    }
    if (!auth?.store || !auth?.user) return
    const allStores = selectedStores.length === stores.length - 1
    const allPos = selectedPositions.length === positions.length - 1
    const allPerm = selectedPermissionGroups.length === permissionGroups.length - 1
    const targetStore =
      selectedStores.length === 0 || allStores ? "전체" : selectedStores.join(",")
    const targetRole =
      selectedPositions.length === 0 || allPos ? "전체" : selectedPositions.join(",")
    const targetPermissionGroup =
      selectedPermissionGroups.length === 0 || allPerm ? "" : selectedPermissionGroups.join(",")
    setSending(true)
    try {
      const attachments = files.map((f) => ({ name: f.name, mime: f.mime, url: f.dataUrl }))
      const res = await sendNotice({
        title: title.trim(),
        content: content.trim(),
        targetStore,
        targetRole,
        targetPermissionGroup: targetPermissionGroup || undefined,
        sender: auth.user,
        userStore: auth.store,
        userRole: auth.role,
        attachments,
      })
      if (res.success) {
        setTitle("")
        setContent("")
        setSelectedStores([])
        setSelectedPositions([])
        setSelectedPermissionGroups([])
        setFiles([])
        window.dispatchEvent(new CustomEvent("notice-sent"))
        await appAlert(translateApiMessage(res.message, t) || t("noticeSentSuccess"))
      } else {
        await appAlert(translateApiMessage(res.message, t) || t("noticeSendFail"))
      }
    } finally {
      setSending(false)
    }
  }

  if (!auth?.store || !auth?.user) return null

  return (
    <div className="rounded-2xl border bg-card shadow-sm">
      <div className="flex items-center gap-3 px-4 pt-5 pb-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(215,80%,50%)]/10">
          <Send className="h-[18px] w-[18px] text-[hsl(215,80%,50%)]" />
        </div>
        <div>
          <h3 className="text-[15px] font-bold text-card-foreground">
            {t("noticeNewTitle")}
          </h3>
          <p className="text-[11px] text-muted-foreground">
            {t("noticeNewSub")}
          </p>
        </div>
      </div>

      <div className="flex flex-col gap-4 px-4 pb-5">
        <div className="flex flex-col gap-1.5">
          <label className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
            {t("labelSubject")}
          </label>
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder={t("noticeTitlePlaceholder")}
            className="h-10 rounded-lg text-sm"
          />
        </div>

        <div className="grid grid-cols-3 gap-2">
          {/* 매장 */}
          <div className="flex flex-col gap-1.5">
          <button
            type="button"
            onClick={() => setStoresOpen(!storesOpen)}
            className="flex items-center justify-between rounded-lg border bg-card px-2.5 py-2 transition-colors active:bg-muted/30 min-h-10"
          >
            <div className="flex items-center gap-1.5 min-w-0">
              <Store className="h-3.5 w-3.5 shrink-0 text-[hsl(215,80%,50%)]" />
              <span className="text-[11px] font-semibold text-card-foreground truncate">
                {t("store")}
              </span>
              <span
                className={cn(
                  "rounded px-1.5 py-0.5 text-[9px] font-bold shrink-0",
                  selectedStores.length > 0
                    ? "bg-[hsl(215,80%,50%)]/10 text-[hsl(215,80%,50%)]"
                    : "bg-muted text-muted-foreground"
                )}
              >
                {storeLabel}
              </span>
            </div>
            {storesOpen ? (
              <ChevronUp className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            ) : (
              <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            )}
          </button>
          {storesOpen && (
            <div className="grid grid-cols-1 gap-1 rounded-lg border bg-muted/20 p-2">
              {stores.map((store) => {
                const isAll = store === t("noticeFilterAll")
                const checked = isAll
                  ? selectedStores.length === stores.length - 1
                  : selectedStores.includes(store)
                return (
                  <label
                    key={store}
                    className={cn(
                      "flex items-center gap-2 rounded-lg px-2 py-1.5 text-[11px] transition-colors cursor-pointer",
                      checked
                        ? "bg-[hsl(215,80%,50%)]/10 font-semibold text-[hsl(215,80%,50%)]"
                        : "bg-card text-card-foreground hover:bg-muted/50"
                    )}
                  >
                    <Checkbox
                      checked={checked}
                      onCheckedChange={() => toggleStore(store)}
                      className="h-3 w-3 rounded"
                    />
                    <span className="truncate">{store}</span>
                  </label>
                )
              })}
            </div>
          )}
        </div>

        <div className="flex flex-col gap-1.5">
          <button
            type="button"
            onClick={() => setPermissionGroupsOpen(!permissionGroupsOpen)}
            className="flex items-center justify-between rounded-lg border bg-card px-2.5 py-2 transition-colors active:bg-muted/30 min-h-10"
          >
            <div className="flex items-center gap-1.5 min-w-0">
              <Shield className="h-3.5 w-3.5 shrink-0 text-amber-600" />
              <span className="text-[11px] font-semibold text-card-foreground truncate">
                {t("adminTargetPermissionGroups")}
              </span>
              <span
                className={cn(
                  "rounded px-1.5 py-0.5 text-[9px] font-bold shrink-0",
                  selectedPermissionGroups.length > 0
                    ? "bg-amber-500/10 text-amber-700"
                    : "bg-muted text-muted-foreground"
                )}
              >
                {permissionGroupLabel}
              </span>
            </div>
            {permissionGroupsOpen ? (
              <ChevronUp className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            ) : (
              <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            )}
          </button>
          {permissionGroupsOpen && (
            <div className="grid grid-cols-1 gap-1 rounded-lg border bg-muted/20 p-2">
              {permissionGroups.map((perm) => {
                const isAll = perm === t("noticeFilterAll")
                const checked = isAll
                  ? selectedPermissionGroups.length === permissionGroups.length - 1
                  : selectedPermissionGroups.includes(perm)
                return (
                  <label
                    key={perm}
                    className={cn(
                      "flex items-center gap-2 rounded-lg px-2 py-1.5 text-[11px] transition-colors cursor-pointer",
                      checked
                        ? "bg-amber-500/10 font-semibold text-amber-700"
                        : "bg-card text-card-foreground hover:bg-muted/50"
                    )}
                  >
                    <Checkbox
                      checked={checked}
                      onCheckedChange={() => togglePermissionGroup(perm)}
                      className="h-3 w-3 rounded"
                    />
                    <span className="truncate">{perm}</span>
                  </label>
                )
              })}
            </div>
          )}
        </div>

        <div className="flex flex-col gap-1.5">
          <button
            type="button"
            onClick={() => setPositionsOpen(!positionsOpen)}
            className="flex items-center justify-between rounded-lg border bg-card px-2.5 py-2 transition-colors active:bg-muted/30 min-h-10"
          >
            <div className="flex items-center gap-1.5 min-w-0">
              <Briefcase className="h-3.5 w-3.5 shrink-0 text-[hsl(152,60%,42%)]" />
              <span className="text-[11px] font-semibold text-card-foreground truncate">
                {t("noticeTargetDept") || "대상 부서"}
              </span>
              <span
                className={cn(
                  "rounded px-1.5 py-0.5 text-[9px] font-bold shrink-0",
                  selectedPositions.length > 0
                    ? "bg-[hsl(152,60%,42%)]/10 text-[hsl(152,60%,42%)]"
                    : "bg-muted text-muted-foreground"
                )}
              >
                {positionLabel}
              </span>
            </div>
            {positionsOpen ? (
              <ChevronUp className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            ) : (
              <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            )}
          </button>
          {positionsOpen && (
            <div className="grid grid-cols-1 gap-1 rounded-lg border bg-muted/20 p-2">
              {positions.map((pos) => {
                const isAll = pos === t("noticeFilterAll")
                const checked = isAll
                  ? selectedPositions.length === positions.length - 1
                  : selectedPositions.includes(pos)
                return (
                  <label
                    key={pos}
                    className={cn(
                      "flex items-center gap-2 rounded-lg px-2 py-1.5 text-[11px] transition-colors cursor-pointer",
                      checked
                        ? "bg-[hsl(152,60%,42%)]/10 font-semibold text-[hsl(152,60%,42%)]"
                        : "bg-card text-card-foreground hover:bg-muted/50"
                    )}
                  >
                    <Checkbox
                      checked={checked}
                      onCheckedChange={() => togglePosition(pos)}
                      className="h-3 w-3 rounded"
                    />
                    <span className="truncate">{pos}</span>
                  </label>
                )
              })}
            </div>
          )}
        </div>
        </div>

        <div className="flex flex-col gap-1.5">
          <label className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
            {t("labelContent")}
          </label>
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={t("noticeContentPlaceholder")}
            className="min-h-[120px] rounded-lg text-sm resize-none"
          />
        </div>

        <div className="flex flex-col gap-2">
          <label className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
            {t("noticeFileLabel")}
          </label>
          {files.length > 0 && (
            <div className="flex flex-col gap-1.5">
              {files.map((file) => (
                <div
                  key={file.id}
                  className="flex items-center gap-2.5 rounded-lg border bg-muted/20 px-3 py-2"
                >
                  {file.type === "image" ? (
                    <ImageIcon className="h-4 w-4 shrink-0 text-[hsl(215,80%,50%)]" />
                  ) : file.type === "pdf" ? (
                    <FileText className="h-4 w-4 shrink-0 text-[hsl(0,72%,51%)]" />
                  ) : (
                    <File className="h-4 w-4 shrink-0 text-muted-foreground" />
                  )}
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-xs font-semibold text-card-foreground">
                      {file.name}
                    </p>
                    <p className="text-[10px] text-muted-foreground">{file.size}</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => removeFile(file.id)}
                    className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-card-foreground transition-colors"
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,.pdf,.doc,.docx,.xls,.xlsx"
            multiple
            className="hidden"
            onChange={handleFileSelect}
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center justify-center gap-2 rounded-lg border-2 border-dashed border-border px-4 py-4 text-xs font-semibold text-muted-foreground transition-colors active:bg-muted/30"
          >
            <Paperclip className="h-4 w-4" />
            <span>{t("noticeFileAdd")}</span>
          </button>
          <p className="text-[10px] text-muted-foreground/60">{t("noticeFileLimit")}</p>
        </div>

        <Button
          className="h-12 rounded-xl text-sm font-bold mt-1"
          onClick={handleSend}
          disabled={sending}
        >
          <Send className="mr-2 h-4 w-4" />
          {sending ? t("loading") : t("adminSendNoticeBtn")}
        </Button>
      </div>
    </div>
  )
}

"use client"
import { appAlert, appConfirm } from "@/lib/app-message"

import * as React from "react"
import {
  Search,
  Clock,
  Trash2,
  CheckCircle2,
  Eye,
  ChevronDown,
  ChevronUp,
  Users,
  FileText,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import {
  getSentNotices,
  deleteNoticeAdmin,
  getNoticeReadDetail,
  getNoticeSenders,
  translateTexts,
  type SentNoticeItem,
  type NoticeReadDetailItem,
} from "@/lib/api-client"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { ListPaginationBar } from "@/components/list-pagination-bar"

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

function defaultStartStr() {
  const d = new Date()
  d.setMonth(d.getMonth() - 1)
  return d.toISOString().slice(0, 10)
}

export function NoticeHistory() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [startDate, setStartDate] = React.useState(todayStr)
  const [endDate, setEndDate] = React.useState(todayStr)
  const [senderFilter, setSenderFilter] = React.useState<string>("mine")
  const [senders, setSenders] = React.useState<string[]>([])
  const [expandedId, setExpandedId] = React.useState<string | null>(null)
  const [notices, setNotices] = React.useState<SentNoticeItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [sentPage, setSentPage] = React.useState(1)
  const sentPageSize = 15
  const [sentTotal, setSentTotal] = React.useState(0)
  const [sentTruncated, setSentTruncated] = React.useState(false)
  const [transMap, setTransMap] = React.useState<Record<string, string>>({})
  const [readDetailOpen, setReadDetailOpen] = React.useState(false)
  const [readDetailTitle, setReadDetailTitle] = React.useState("")
  const [readDetailItems, setReadDetailItems] = React.useState<NoticeReadDetailItem[]>([])
  const [readDetailLoading, setReadDetailLoading] = React.useState(false)

  const loadNotices = React.useCallback(
    (page: number) => {
      if (!auth?.store || !auth?.user) return
      setLoading(true)
      const sender = senderFilter === "all" ? "all" : senderFilter === "mine" ? auth.user : senderFilter
      getSentNotices({
        sender: sender || auth.user,
        startDate,
        endDate,
        userStore: auth.store,
        userRole: auth.role,
        page,
        pageSize: sentPageSize,
      })
        .then((res) => {
          setNotices(res.items)
          setSentTotal(res.total)
          setSentTruncated(Boolean(res.truncated))
          setSentPage(res.page)
        })
        .catch(() => {
          setNotices([])
          setSentTotal(0)
          setSentTruncated(false)
        })
        .finally(() => setLoading(false))
    },
    [auth?.store, auth?.user, auth?.role, startDate, endDate, senderFilter, sentPageSize]
  )

  const loadSenders = React.useCallback(() => {
    getNoticeSenders({ startDate, endDate })
      .then(({ senders: s }) => setSenders(s))
      .catch(() => setSenders([]))
  }, [startDate, endDate])

  const [hasSearched, setHasSearched] = React.useState(false)

  const handleSearch = React.useCallback(() => {
    setHasSearched(true)
    loadSenders()
    loadNotices(1)
  }, [loadSenders, loadNotices])

  React.useEffect(() => {
    const onSent = () => {
      if (hasSearched) loadNotices(sentPage)
    }
    window.addEventListener("notice-sent", onSent)
    return () => window.removeEventListener("notice-sent", onSent)
  }, [loadNotices, hasSearched, sentPage])

  React.useEffect(() => {
    const texts = [...new Set(notices.flatMap((n) => [n.title, n.content || n.preview].filter(Boolean)))]
    if (texts.length === 0) {
      setTransMap({})
      return
    }
    let cancelled = false
    translateTexts(texts, lang).then((translated) => {
      if (cancelled) return
      const map: Record<string, string> = {}
      texts.forEach((txt, i) => { map[txt] = translated[i] ?? txt })
      setTransMap(map)
    }).catch(() => setTransMap({}))
    return () => { cancelled = true }
  }, [notices, lang])

  const getTrans = (text: string) => (text && transMap[text]) || text || ""

  const handleDelete = async (id: string) => {
    if (!await appConfirm(t("noticeDeleteConfirm"))) return
    const res = await deleteNoticeAdmin({ id: Number(id) })
    if (res.success) {
      setNotices((prev) => prev.filter((n) => n.id !== id))
      setExpandedId(null)
    } else {
      await appAlert(translateApiMessage(res.message, t) || t("noticeDeleteFail"))
    }
  }

  const handleOpenReadDetail = React.useCallback(
    async (e: React.MouseEvent, notice: SentNoticeItem) => {
      e.stopPropagation()
      setReadDetailTitle(transMap[notice.title] || notice.title)
      setReadDetailOpen(true)
      setReadDetailItems([])
      setReadDetailLoading(true)
      try {
        const { items } = await getNoticeReadDetail({ noticeId: Number(notice.id) })
        setReadDetailItems(items)
      } catch {
        setReadDetailItems([])
      } finally {
        setReadDetailLoading(false)
      }
    },
    [transMap]
  )

  if (!auth?.store || !auth?.user) return null

  return (
    <div className="rounded-2xl border bg-card shadow-sm">
      <div className="flex items-center gap-3 px-4 pt-5 pb-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(38,92%,50%)]/10">
          <Clock className="h-[18px] w-[18px] text-[hsl(38,92%,50%)]" />
        </div>
        <div>
          <h3 className="text-[15px] font-bold text-card-foreground">
            {t("noticeHistoryTitle")}
          </h3>
          <p className="text-[11px] text-muted-foreground">
            {t("noticeHistorySub")}
          </p>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2 px-4 pb-3">
        <div className="min-w-[120px]">
          <Select value={senderFilter} onValueChange={setSenderFilter}>
            <SelectTrigger className="h-9 text-xs rounded-lg">
              <SelectValue placeholder={t("noticeSenderAll")} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">{t("noticeSenderAll")}</SelectItem>
              <SelectItem value="mine">{t("noticeSenderMine")}</SelectItem>
              {senders
                .filter((s) => s !== (auth?.user || ''))
                .map((s) => (
                  <SelectItem key={s} value={s}>{s}</SelectItem>
                ))}
            </SelectContent>
          </Select>
        </div>
        <Input
          type="date"
          value={startDate}
          onChange={(e) => setStartDate(e.target.value)}
          className="date-input-compact flex-1 min-w-0 h-9 text-xs rounded-lg"
        />
        <span className="text-xs text-muted-foreground font-medium">~</span>
        <Input
          type="date"
          value={endDate}
          onChange={(e) => setEndDate(e.target.value)}
          className="date-input-compact flex-1 min-w-0 h-9 text-xs rounded-lg"
        />
        <Button
          size="sm"
          className="h-9 shrink-0 rounded-lg px-3 text-xs font-semibold"
          onClick={handleSearch}
          disabled={loading}
        >
          <Search className="mr-1 h-3.5 w-3.5" />
          {loading ? t("loading") : t("search")}
        </Button>
      </div>

      <div className="flex flex-col gap-1 border-t px-4 py-2.5 bg-muted/20">
        <span className="text-[11px] font-semibold text-muted-foreground">
          {t("noticeCountPrefix")}{" "}
          <span className="text-card-foreground">{hasSearched ? sentTotal : 0}</span>
          {t("noticeCountSuffix")}
        </span>
        {hasSearched && sentTruncated && (
          <span className="text-[10px] text-amber-600 dark:text-amber-500">
            기간 내 일부만 불러왔습니다. 기간을 나누어 검색해 보세요.
          </span>
        )}
      </div>

      <div className="flex flex-col">
        {!hasSearched ? (
          <div className="py-8 px-4 text-center text-sm text-muted-foreground">
            {t("msg_click_query") || "검색 버튼을 눌러 주세요."}
          </div>
        ) : notices.length === 0 ? (
          <div className="py-8 px-4 text-center text-sm text-muted-foreground">
            {t("adminNoNoticesFound")}
          </div>
        ) : (
          notices.map((notice, idx) => {
            const isExpanded = expandedId === notice.id
            const readPercent =
              notice.totalCount > 0
                ? Math.round((notice.readCount / notice.totalCount) * 100)
                : 0
            const allRead = notice.readCount === notice.totalCount
            return (
              <div
                key={notice.id}
                className={cn(
                  "border-b last:border-b-0",
                  isExpanded && "bg-muted/10"
                )}
              >
                <button
                  type="button"
                  onClick={() =>
                    setExpandedId(isExpanded ? null : notice.id)
                  }
                  className="flex w-full items-start gap-3 px-4 py-3.5 text-left active:bg-muted/20 transition-colors"
                >
                  <div className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-muted text-[10px] font-bold tabular-nums text-muted-foreground">
                    {(sentPage - 1) * sentPageSize + idx + 1}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <h4 className="text-[13px] font-bold text-card-foreground leading-tight truncate flex-1 min-w-0">
                        {getTrans(notice.title)}
                      </h4>
                      {isExpanded ? (
                        <ChevronUp className="h-4 w-4 shrink-0 text-muted-foreground mt-0.5" />
                      ) : (
                        <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground mt-0.5" />
                      )}
                    </div>
                    <p className="mt-0.5 text-[11px] text-muted-foreground truncate">
                      {getTrans(notice.preview)}
                    </p>
                    <div className="mt-1.5 flex flex-wrap items-center gap-1.5">
                      <span className="text-[10px] tabular-nums text-muted-foreground shrink-0">
                        {notice.date}
                      </span>
                      {senderFilter === "all" && notice.sender && (
                        <span className="inline-flex items-center rounded-md bg-muted/80 px-1.5 py-0.5 text-[9px] font-semibold text-muted-foreground">
                          {notice.sender}
                        </span>
                      )}
                      {notice.recipients.map((r) => (
                        <span
                          key={r}
                          className="inline-flex items-center rounded-md bg-[hsl(215,80%,50%)]/10 px-1.5 py-0.5 text-[9px] font-bold text-[hsl(215,80%,50%)]"
                        >
                          {r === "전체" ? t("noticeFilterAll") : r}
                        </span>
                      ))}
                    </div>
                    <div className="mt-2 flex items-center gap-2">
                      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted">
                        <div
                          className={cn(
                            "h-full rounded-full transition-all",
                            allRead ? "bg-[hsl(152,60%,42%)]" : "bg-[hsl(215,80%,50%)]"
                          )}
                          style={{ width: `${readPercent}%` }}
                        />
                      </div>
                      <div className="flex items-center gap-1">
                        <Eye className="h-3 w-3 text-muted-foreground" />
                        <span
                          className={cn(
                            "text-[10px] font-bold tabular-nums",
                            allRead ? "text-[hsl(152,60%,42%)]" : "text-muted-foreground"
                          )}
                        >
                          {notice.readCount}/{notice.totalCount}
                        </span>
                      </div>
                    </div>
                  </div>
                </button>
                {isExpanded && (
                  <div className="border-t bg-muted/10 px-4 py-3">
                    <div className="mb-3 rounded-lg bg-card border px-3 py-2.5">
                      <div className="flex items-center gap-1.5 mb-1.5">
                        <FileText className="h-3 w-3 text-muted-foreground" />
                        <span className="text-[10px] font-bold text-muted-foreground">
                          {t("noticePreview")}
                        </span>
                      </div>
                      <p className="text-xs text-card-foreground leading-relaxed whitespace-pre-wrap">
                        {getTrans(notice.content || notice.preview || "") || "(내용 없음)"}
                      </p>
                    </div>
                    <div className="mb-3 rounded-lg bg-card border px-3 py-2.5">
                      <div className="flex items-center gap-1.5 mb-2">
                        <Users className="h-3 w-3 text-muted-foreground" />
                        <span className="text-[10px] font-bold text-muted-foreground">
                          {t("noticeReadStats")}
                        </span>
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        <div className="flex flex-col items-center gap-0.5 rounded-lg bg-muted/50 py-2">
