  inquiryMode?: "bundle" | "campaign"
}

function posPromoValidityOverlapsRange(p: PosPromo, from: string, to: string): boolean {
  const fs = from.trim().slice(0, 10)
  const te = to.trim().slice(0, 10)
  if (!fs && !te) return true
  const vf = (p.validFrom ?? "").trim().slice(0, 10)
  const vt = (p.validTo ?? "").trim().slice(0, 10)
  if (!vf && !vt) return true
  const ps = vf || "1970-01-01"
  const pe = vt || vf || "2999-12-31"
  if (fs && te) {
    const [a, b] = fs <= te ? [fs, te] : [te, fs]
    return ps <= b && pe >= a
  }
  const d = fs || te
  return ps <= d && pe >= d
}

function buildSavePayload(p: PosPromo, overrides: { isActive?: boolean } = {}) {
  const isActive = overrides.isActive ?? p.isActive
  return {
    id: p.id,
    code: p.code,
    name: p.name,
    category: (p.category ?? "").trim() || PROMOTION_DEFAULT_SUBCATEGORIES[0],
    categoryMain: (p.categoryMain ?? "").trim() || PROMOTION_MAIN_CATEGORY,
    price: p.price,
    priceDelivery: p.priceDelivery,
    vatIncluded: p.vatIncluded,
    isActive,
    marketingCampaignId: p.marketingCampaignId?.trim() || null,
    channelHall: p.channelHall !== false,
    channelTakeout: p.channelTakeout !== false,
    channelDelivery: p.channelDelivery !== false,
    deliveryAppCodes:
      p.channelDelivery !== false && p.deliveryAppCodes && p.deliveryAppCodes.length > 0
        ? p.deliveryAppCodes
        : null,
    discountPercent: p.discountPercent ?? null,
    validFrom: p.validFrom?.trim() || null,
    validTo: p.validTo?.trim() || null,
    marketingActualCost: p.marketingActualCost ?? 0,
    standaloneSetMenu: !p.marketingCampaignId?.trim(),
  }
}

export function PosSetMenuInquiryTab({
  promos,
  promosLoading,
  onRefresh,
  onOpenInSetTab,
  filterCampaignId,
  hideOpenMarketingLink,
  hideLinkCampaign,
  inquiryMode = "bundle",
}: PosSetMenuInquiryTabProps) {
  const { lang } = useLang()
  const t = useT(lang)
  const { auth } = useAuth()
  const [search, setSearch] = React.useState("")
  const [promoCategoryFilter, setPromoCategoryFilter] = React.useState("")
  const [promoValidFrom, setPromoValidFrom] = React.useState("")
  const [promoValidTo, setPromoValidTo] = React.useState("")
  const [showInactive, setShowInactive] = React.useState(true)
  const [busyId, setBusyId] = React.useState<string | null>(null)
  const [linkTarget, setLinkTarget] = React.useState<PosPromo | null>(null)
  const [linkCampaignId, setLinkCampaignId] = React.useState("")
  const [campaigns, setCampaigns] = React.useState<MarketingCampaign[]>([])
  const [campaignsLoading, setCampaignsLoading] = React.useState(false)
  const [economicsByPromoId, setEconomicsByPromoId] = React.useState<Record<string, InquiryPromoEconomics>>({})
  const [economicsLoading, setEconomicsLoading] = React.useState(false)

  React.useEffect(() => {
    if (!linkTarget) {
      setLinkCampaignId("")
      return
    }
    let cancelled = false
    setCampaignsLoading(true)
    getMarketingCampaigns()
      .then((list) => {
        if (!cancelled) setCampaigns(Array.isArray(list) ? list : [])
      })
      .catch(() => {
        if (!cancelled) setCampaigns([])
      })
      .finally(() => {
        if (!cancelled) setCampaignsLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [linkTarget])

  React.useEffect(() => {
    if (!promos.length) {
      setEconomicsByPromoId({})
      return
    }
    let cancelled = false
    setEconomicsLoading(true)
    const cid = (filterCampaignId ?? "").trim() || undefined
    void (async () => {
      try {
        const [rows, withItems] = await Promise.all([
          getPosMenuCostAnalysis({ summary: true }),
          getPosPromosWithItems({ campaignId: cid, includeInactive: true }),
        ])
        if (cancelled) return
        setEconomicsByPromoId(buildInquiryEconomicsByPromoId(Array.isArray(withItems) ? withItems : [], rows))
      } catch {
        if (!cancelled) setEconomicsByPromoId({})
      } finally {
        if (!cancelled) setEconomicsLoading(false)
      }
    })()
    return () => {
      cancelled = true
    }
  }, [promos, filterCampaignId])

  const filterCid = (filterCampaignId ?? "").trim()

  const promoCategoryOptions = React.useMemo(() => {
    const set = new Set<string>()
    for (const p of promos) {
      const c = (p.category ?? "").trim()
      if (c) set.add(c)
    }
    return Array.from(set).sort((a, b) => a.localeCompare(b, lang === "ko" ? "ko" : "en"))
  }, [promos, lang])

  const filtered = React.useMemo(() => {
    const q = search.trim().toLowerCase()
    const cat = promoCategoryFilter.trim()
    return promos.filter((p) => {
      if (filterCid && (p.marketingCampaignId ?? "").trim() !== filterCid) return false
      if (!showInactive && !p.isActive) return false
      if (cat && (p.category ?? "").trim() !== cat) return false
      if (inquiryMode === "campaign" && !posPromoValidityOverlapsRange(p, promoValidFrom, promoValidTo)) {
        return false
      }
      if (!q) return true
      return (
        (p.code ?? "").toLowerCase().includes(q) ||
        (p.name ?? "").toLowerCase().includes(q) ||
        (p.marketingCampaignNo ?? "").toLowerCase().includes(q)
      )
    })
  }, [
    promos,
    search,
    showInactive,
    filterCid,
    promoCategoryFilter,
    promoValidFrom,
    promoValidTo,
    inquiryMode,
  ])

  const showCampaignCol = inquiryMode !== "campaign"

  const runBusy = async (id: string, fn: () => Promise<void>) => {
    if (busyId) return
    setBusyId(id)
    try {
      await fn()
    } finally {
      setBusyId(null)
    }
  }

  const handleActivate = (p: PosPromo) =>
    runBusy(p.id, async () => {
      const res = await savePosPromo({
        ...buildSavePayload(p, { isActive: true }),
        userRole: auth?.role,
        userName: auth?.user,
      })
      if (!res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail_detail"))
        return
      }
      await appAlert(t("posSetInquiryActivated"))
      onRefresh()
    })

  const handleDeactivate = (p: PosPromo) =>
    runBusy(p.id, async () => {
      if (!(await appConfirm(t("posSetInquiryDeactivateConfirm").replace("{{name}}", p.name || p.code)))) return
      const res = await savePosPromo({
        ...buildSavePayload(p, { isActive: false }),
        userRole: auth?.role,
        userName: auth?.user,
      })
      if (!res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail_detail"))
        return
      }
      await appAlert(t("posSetInquiryDeactivated"))
      onRefresh()
    })

  const handleDelete = (p: PosPromo) =>
    runBusy(p.id, async () => {
      if (!(await appConfirm(t("posSetInquiryDeleteConfirm").replace("{{name}}", p.name || p.code)))) return
      const res = await deletePosPromo({ id: p.id })
      if (!res.success) {
        await appAlert(translateApiMessage(res.message, t) || res.message || t("msg_save_fail_detail"))
        return
      }
      await appAlert(t("posSetInquiryDeleted"))
      onRefresh()
    })

  const handleCopy = (p: PosPromo) =>
    runBusy(p.id, async () => {
      const items = await getPosPromoItems({ promoId: p.id }).catch(() => [])
      const standalone = !p.marketingCampaignId?.trim()
      const res = await savePosPromo({
        name: p.name,
        category: (p.category ?? "").trim() || PROMOTION_DEFAULT_SUBCATEGORIES[0],
        categoryMain: (p.categoryMain ?? "").trim() || PROMOTION_MAIN_CATEGORY,
        price: p.price,
        priceDelivery: p.priceDelivery,
        vatIncluded: p.vatIncluded,
        isActive: true,
        marketingCampaignId: p.marketingCampaignId?.trim() || null,
        channelHall: p.channelHall !== false,
        channelTakeout: p.channelTakeout !== false,
        channelDelivery: p.channelDelivery !== false,
        deliveryAppCodes:
          p.channelDelivery !== false && p.deliveryAppCodes && p.deliveryAppCodes.length > 0
            ? p.deliveryAppCodes
            : null,
        discountPercent: p.discountPercent ?? null,
        validFrom: p.validFrom?.trim() || null,
        validTo: p.validTo?.trim() || null,
        marketingActualCost: 0,
        standaloneSetMenu: standalone,
        userRole: auth?.role,
        userName: auth?.user,
      })
      if (!res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail_detail"))
        return
      }
      const newId = res.id ? String(res.id) : ""
      if (!newId) {
        await appAlert(t("msg_save_fail_detail"))
        onRefresh()
        return
      }
      for (let i = 0; i < (items || []).length; i++) {
        const it = items[i]
        const ir = await savePosPromoItem({
          promoId: Number(newId),
          menuId: Number(it.menuId),
          optionId: it.optionId ? Number(it.optionId) : null,
          quantity: Number(it.quantity) || 1,
          sortOrder: i,
        })
        if (!ir.success) {
          await appAlert(translateApiMessage(ir.message, t) || ir.message || t("msg_save_fail_detail"))
          onRefresh()
          return
        }
      }
      await appAlert(t("posSetInquiryCopied"))
      onRefresh()
    })

  const handleConfirmLinkCampaign = async () => {
    if (!linkTarget) return
    await runBusy(linkTarget.id, async () => {
      const cid = linkCampaignId.trim()
      if (!cid) {
        await appAlert(t("posSetLinkCampaignNeedSelection"))
        return
      }
      if (!(await appConfirm(t("posSetLinkCampaignConfirm")))) return
      let nextCode: string | null = null
      try {
        const r = await getNextPosPromoCode({ campaignId: cid })
        nextCode = r?.code?.trim() || null
      } catch {
        nextCode = null
      }
      if (!nextCode) {
        await appAlert(t("posSetLinkCampaignNoNextCode"))
        return
      }
      const res = await savePosPromo({
        ...buildSavePayload(linkTarget),
        marketingCampaignId: cid,
        code: nextCode,
        standaloneSetMenu: false,
        userRole: auth?.role,
        userName: auth?.user,
      })
      if (!res.success) {
        await appAlert(translateApiMessage(res.message, t) || t("msg_save_fail_detail"))
        return
      }
      setLinkTarget(null)
      await appAlert(t("posSetLinkCampaignSuccess"))
      onRefresh()
    })
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h3 className="text-base font-bold tracking-tight">{t("posSetInquiryTitle")}</h3>
          <p className="mt-1 max-w-2xl text-xs text-muted-foreground leading-relaxed">{t("posSetInquiryDesc")}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button type="button" variant="outline" size="sm" className="h-9 gap-1.5 text-xs" asChild>
            <Link href="/admin/marketing/promos">
              <ExternalLink className="h-3.5 w-3.5" />
              {t("posMenuSetOpenMarketing")}
            </Link>
          </Button>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            className="h-9 gap-1 text-xs"
            disabled={promosLoading}
            onClick={() => onRefresh()}
          >
            <RefreshCw className={cn("h-3.5 w-3.5", promosLoading && "animate-spin")} />
            {t("posSetInquiryRefresh")}
          </Button>
        </div>
      </div>

      <Dialog open={!!linkTarget} onOpenChange={(o) => !o && setLinkTarget(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{t("posSetLinkCampaignTitle")}</DialogTitle>
          </DialogHeader>
          <p className="text-xs text-muted-foreground leading-relaxed">{t("posSetLinkCampaignHint")}</p>
          {linkTarget ? (
            <p className="text-sm font-medium">
              {linkTarget.name} <span className="font-mono text-xs text-muted-foreground">({linkTarget.code})</span>
            </p>
          ) : null}
          <div className="space-y-1">
            <label className="text-xs font-medium text-muted-foreground">{t("posSetLinkCampaignSelect")}</label>
            <Select
              value={linkCampaignId || "_none"}
              onValueChange={(v) => setLinkCampaignId(v === "_none" ? "" : v)}
              disabled={campaignsLoading}
            >
              <SelectTrigger className="h-10">
                <SelectValue placeholder={t("posPromoCampaignSelectPlaceholder")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="_none">{t("marketingPromoCampaignSelectRequiredOption")}</SelectItem>
                {campaigns.map((c) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.campaignNo ? `[${c.campaignNo}] ` : ""}
                    {c.topic}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={() => setLinkTarget(null)}>
              {t("cancel")}
            </Button>
            <Button
              type="button"
              disabled={!linkTarget || busyId === linkTarget?.id || campaignsLoading}
              onClick={() => void handleConfirmLinkCampaign()}
            >
              {t("posSetLinkCampaign")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <div className="space-y-3 rounded-xl border border-border/80 bg-card p-4 shadow-sm">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <Input
            className="h-9 max-w-md text-sm"
            placeholder={t("posSetInquirySearchPh")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <label className="flex items-center gap-2 text-xs">
            <Checkbox checked={showInactive} onCheckedChange={(c) => setShowInactive(c === true)} />
            {t("posSetInquiryShowInactive")}
          </label>
        </div>

        {inquiryMode === "campaign" ? (
          <div className="space-y-3 rounded-lg border border-border/70 bg-muted/10 px-3 py-3 sm:px-4">
            <p className="text-[11px] font-medium text-muted-foreground">{t("posPromoListFilterTitle")}</p>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 lg:items-end">
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{t("marketingPromoFilterPromoCategory")}</Label>
                <Select
                  value={promoCategoryFilter || "_all"}
                  onValueChange={(v) => setPromoCategoryFilter(v === "_all" ? "" : v)}
                >
                  <SelectTrigger className="h-9 text-sm">
                    <SelectValue placeholder={t("all")} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="_all">{t("all")}</SelectItem>
                    {promoCategoryOptions.map((c) => (
                      <SelectItem key={c} value={c}>
                        {c}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{t("posPromoListFilterFrom")}</Label>
                <Input
                  type="date"
                  className="h-9"
                  value={promoValidFrom}
                  onChange={(e) => setPromoValidFrom(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{t("posPromoListFilterTo")}</Label>
                <Input
                  type="date"
                  className="h-9"
                  value={promoValidTo}
                  onChange={(e) => setPromoValidTo(e.target.value)}
                />
              </div>
            </div>
            <p className="text-[11px] leading-relaxed text-muted-foreground">{t("posPromoListFilterOverlapHint")}</p>
          </div>
        ) : null}
      </div>

      {promosLoading && promos.length === 0 ? (
        <div className="rounded-lg border bg-muted/30 px-4 py-3 text-sm text-muted-foreground">{t("loading")}</div>
      ) : (
        <div className="overflow-x-auto rounded-xl border border-border/80">
          <table className="w-full min-w-[1040px] border-collapse text-sm">
            <thead>
              <tr className="border-b bg-muted/50 text-left text-xs font-medium text-muted-foreground">
                <th className="whitespace-nowrap px-3 py-2.5 align-bottom">{t("itemsColCode")}</th>
                <th className="min-w-[140px] px-3 py-2.5 align-bottom">{t("posPromoName")}</th>
                {showCampaignCol ? (
                  <th className="whitespace-nowrap px-3 py-2.5 align-bottom">{t("posSetInquiryColCampaign")}</th>
                ) : null}
                <th className="whitespace-nowrap px-3 py-2.5 text-right align-bottom">{t("posMenuPriceHall")}</th>
                <th className="whitespace-nowrap px-3 py-2.5 text-right align-bottom">{t("posMenuPriceDelivery")}</th>
                <th className="whitespace-nowrap px-3 py-2.5 text-right align-bottom">{t("posSetInquiryColCostHall")}</th>
                <th className="whitespace-nowrap px-3 py-2.5 text-right align-bottom">{t("posSetInquiryColCostRateHall")}</th>
                <th className="whitespace-nowrap px-3 py-2.5 text-right align-bottom">{t("posSetInquiryColCostRateDel")}</th>
                <th className="whitespace-nowrap px-3 py-2.5 align-bottom">{t("posSetInquiryColStatus")}</th>
                <th className="min-w-[200px] px-3 py-2.5 text-right align-bottom">{t("posSetInquiryColActions")}</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td
                    colSpan={showCampaignCol ? 10 : 9}
                    className="px-4 py-10 text-center text-muted-foreground"
                  >
                    {t("posSetInquiryEmpty")}
                  </td>
                </tr>
              ) : (
                filtered.map((p) => {
                  const b = busyId === p.id
                  const ec = economicsByPromoId[p.id]
                  const costCell =
                    ec == null || ec.lineCount === 0
                      ? "—"
                      : `฿${ec.costHall.toFixed(1)}${ec.incomplete ? "*" : ""}`
                  const rateHallCell = ec == null || ec.lineCount === 0 ? "—" : `${ec.costRateHall.toFixed(1)}%`
                  const rateDelCell = ec == null || ec.lineCount === 0 ? "—" : `${ec.costRateDel.toFixed(1)}%`
                  return (
                    <tr key={p.id} className="border-b border-border/40 last:border-0">
                      <td className="px-3 py-2.5 align-middle font-mono text-xs">{p.code}</td>
                      <td className="px-3 py-2.5 align-middle font-medium break-words">{p.name}</td>
                      {showCampaignCol ? (
                        <td className="px-3 py-2.5 align-middle text-xs">
                          {p.marketingCampaignNo?.trim() ? (
                            <span className="font-mono text-muted-foreground">{p.marketingCampaignNo}</span>
                          ) : (
                            <Badge variant="secondary" className="text-[10px] font-normal">
                              {t("posSetBundleNoCampaignBadge")}
                            </Badge>
                          )}
                        </td>
                      ) : null}
                      <td className="px-3 py-2.5 align-middle text-right tabular-nums">
                        ฿{Math.round(p.price ?? 0).toLocaleString()}
                      </td>
                      <td className="px-3 py-2.5 align-middle text-right tabular-nums text-muted-foreground">
                        {p.priceDelivery != null && Number(p.priceDelivery) > 0
                          ? `฿${Math.round(Number(p.priceDelivery)).toLocaleString()}`
                          : "—"}
                      </td>
                      <td
                        className="px-3 py-2.5 align-middle text-right font-mono tabular-nums text-muted-foreground"
                        title={ec?.incomplete ? t("posSetInquiryEconomicsHint") : undefined}
                      >
                        {economicsLoading && ec == null ? "…" : costCell}
                      </td>
                      <td className="px-3 py-2.5 align-middle text-right font-mono tabular-nums text-muted-foreground">
                        {economicsLoading && ec == null ? "…" : rateHallCell}
                      </td>
                      <td className="px-3 py-2.5 align-middle text-right font-mono tabular-nums text-muted-foreground">
                        {economicsLoading && ec == null ? "…" : rateDelCell}
                      </td>
                      <td className="px-3 py-2.5 align-middle whitespace-nowrap">
                        {p.isActive ? (
                          <Badge className="bg-emerald-600/90 text-[10px]">{t("posSetInquiryActive")}</Badge>
                        ) : (
                          <Badge variant="secondary" className="text-[10px]">
                            {t("posSetInquiryInactive")}
                          </Badge>
                        )}
                      </td>
                      <td className="px-3 py-2.5 align-top text-right">
                        <div className="flex flex-wrap justify-end gap-1">
                          {!hideLinkCampaign && !p.marketingCampaignId?.trim() ? (
                            <Button
                              type="button"
                              variant="secondary"
                              size="sm"
                              className="h-8 gap-1 px-2 text-[11px]"
                              disabled={b}
                              onClick={() => {
                                setLinkCampaignId("")
                                setLinkTarget(p)
                              }}
                            >
                              <Link2 className="h-3 w-3" />
                              {t("posSetLinkCampaign")}
                            </Button>
                          ) : null}
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="h-8 gap-1 px-2 text-[11px]"
                            disabled={b}
                            onClick={() => onOpenInSetTab(p.id)}
                          >
                            <Pencil className="h-3 w-3" />
                            {t("posSetInquiryOpenInSetTab")}
                          </Button>
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="h-8 gap-1 px-2 text-[11px]"
                            disabled={b}
                            onClick={() => void handleCopy(p)}
                          >
                            <ClipboardCopy className="h-3 w-3" />
                            {t("posSetInquiryCopy")}
                          </Button>
                          {p.isActive ? (
                            <>
                              <Button
                                type="button"
                                variant="secondary"
                                size="sm"
                                className="h-8 gap-1 px-2 text-[11px]"
                                disabled={b}
                                onClick={() => void handleDeactivate(p)}
                              >
                                <Ban className="h-3 w-3" />
                                {t("posSetInquirySuspend")}
                              </Button>
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="h-8 gap-1 px-2 text-[11px] text-destructive hover:text-destructive"
                                disabled={b}
                                onClick={() => void handleDelete(p)}
                              >
                                <Trash2 className="h-3 w-3" />
                                {t("posSetInquiryDelete")}
                              </Button>
                            </>
                          ) : (
                            <Button
                              type="button"
                              variant="default"
                              size="sm"
                              className="h-8 gap-1 bg-emerald-600 px-2 text-[11px] hover:bg-emerald-700"
                              disabled={b}
                              onClick={() => void handleActivate(p)}
                            >
                              <Play className="h-3 w-3" />
                              {t("posSetInquiryActivate")}
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>
      )}
      {filtered.length > 0 ? (
        <p className="text-[10px] leading-relaxed text-muted-foreground">
          {economicsLoading ? `${t("loading")} · ${t("posSetInquiryEconomicsHint")}` : t("posSetInquiryEconomicsHint")}
        </p>
      ) : null}
    </div>
  )
}

"use client"
import { appAlert, appConfirm } from "@/lib/app-message"

import * as React from "react"
import { History, Search, Calendar } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { getPriceHistory, getPosMenus, getPosMenuCategoriesConfig, getItemCategories, type PriceHistoryRow, backfillPriceHistory, restoreFromPriceHistory } from "@/lib/api-client"
import { POS_MAIN_CATEGORIES, getPresetCategoriesForMain } from "@/lib/pos-menu-categories"
import { useT } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"
import { cn } from "@/lib/utils"

const FIELD_LABELS: Record<string, string> = {
  price: "price",
  price_delivery: "price_delivery",
  price_modifier: "price_modifier",
  price_modifier_delivery: "price_modifier_delivery",
  price_modifier_packaging: "price_modifier_packaging",
  cost: "cost",
}

export interface PriceHistoryTabProps {
  /** 조회할 엔티티 타입들 (메뉴 페이지: pos_menu, pos_menu_option / 품목 페이지: item) */
  entityTypes: ("pos_menu" | "pos_menu_option" | "item")[]
  /** 메뉴 모드(카테고리+메뉴 선택) 또는 품목 모드(카테고리 선택) */
  mode: "menu" | "item"
  /** 탭 제목 (선택) */
  title?: string
}

export function PriceHistoryTab({ entityTypes, mode, title }: PriceHistoryTabProps) {
  const { lang } = useLang()
  const t = useT(lang)
  const [rows, setRows] = React.useState<PriceHistoryRow[]>([])
  const [loading, setLoading] = React.useState(false)
  const [searchTerm, setSearchTerm] = React.useState("")
  const [mainCategoryFilter, setMainCategoryFilter] = React.useState("all")
  const [categoryFilter, setCategoryFilter] = React.useState("all")
  const [menuFilter, setMenuFilter] = React.useState("all")
  const [fromDate, setFromDate] = React.useState("")
  const [toDate, setToDate] = React.useState("")
  const [categories, setCategories] = React.useState<string[]>([])
  const [categoriesByMain, setCategoriesByMain] = React.useState<Record<string, string[]>>({})
  const [menus, setMenus] = React.useState<{ id: string; name: string; code: string; categoryMain?: string; category?: string }[]>([])
  const [backfilling, setBackfilling] = React.useState(false)
  const [restoreDate, setRestoreDate] = React.useState("")
  const [restoring, setRestoring] = React.useState(false)
  /** 품목 모드: 원가 vs 홀/판매가 선택 */
  const [itemFieldFilter, setItemFieldFilter] = React.useState<"cost" | "price">("price")
  /** 메뉴 모드: 가격 항목 선택 */
  const [menuFieldFilter, setMenuFieldFilter] = React.useState<string>("price")

  React.useEffect(() => {
    if (mode === "menu") {
      Promise.all([getPosMenuCategoriesConfig(), getPosMenus()])
        .then(([config, menuList]) => {
          const mainCats = config?.mainCategories || [...POS_MAIN_CATEGORIES]
          const byMain = config?.categoriesByMain || {}
          setCategories(mainCats)
          setCategoriesByMain(byMain)
          setMenus((menuList || []).map((m) => ({
            id: String(m.id),
            name: m.name,
            code: m.code || "",
            categoryMain: m.categoryMain,
            category: m.category,
          })))
        })
        .catch(() => { setCategories([]); setCategoriesByMain({}); setMenus([]) })
    } else {
      getItemCategories()
        .then((r) => setCategories((r?.categories || []).filter(Boolean).sort()))
        .catch(() => setCategories([]))
    }
  }, [mode])

  const loadHistory = React.useCallback(async () => {
    setLoading(true)
    try {
      const allRows: PriceHistoryRow[] = []
      const catMain = mode === "menu" && mainCategoryFilter !== "all" ? mainCategoryFilter : undefined
      const cat = categoryFilter !== "all" ? categoryFilter : undefined
      const menuId = mode === "menu" && menuFilter !== "all" ? menuFilter : undefined
      for (const et of entityTypes) {
        const params: Parameters<typeof getPriceHistory>[0] = {
          entityType: et,
          from: fromDate || undefined,
          to: toDate || undefined,
          search: searchTerm.trim() || undefined,
          categoryMain: catMain,
          category: cat,
          menuId,
          limit: 200,
        }
        const data = await getPriceHistory(params)
        allRows.push(...(Array.isArray(data) ? data : []))
      }
      allRows.sort((a, b) => new Date(b.changed_at).getTime() - new Date(a.changed_at).getTime())
      setRows(allRows.slice(0, 300))
    } catch (e) {
      console.error("getPriceHistory:", e)
      setRows([])
    } finally {
      setLoading(false)
    }
  }, [entityTypes, mode, fromDate, toDate, searchTerm, mainCategoryFilter, categoryFilter, menuFilter])

  const handleBackfill = React.useCallback(async () => {
    if (!await appConfirm(t("priceHistoryBackfillConfirm") || "기존 메뉴·품목의 현재 가격을 이력에 등록합니다. 계속할까요?")) return
    setBackfilling(true)
    try {
      const res = await backfillPriceHistory()
      if (res.success) {
        await appAlert(res.message || `${res.inserted}건 등록됨`)
        loadHistory()
      } else {
        await appAlert(res.error || t("msg_save_fail_detail"))
      }
    } catch (e) {
      await appAlert(e instanceof Error ? e.message : "실패")
    } finally {
      setBackfilling(false)
    }
  }, [loadHistory, t])

  const handleRestoreByDate = React.useCallback(async () => {
    const date = restoreDate.trim()
    if (!date) {
      await appAlert(t("priceHistoryRestoreDateRequired") || "복구할 날짜(YYYY-MM-DD)를 선택하세요.")
      return
    }
    if (!await appConfirm(t("priceHistoryRestoreByDateConfirm") || `가격 이력의 ${date} 시점 가격으로 메뉴·옵션 가격을 덮어씁니다. 계속할까요?`)) return
    setRestoring(true)
    try {
      const res = await restoreFromPriceHistory({ targetDate: date, dryRun: false })
      if (res.success) {
        await appAlert(res.message || "복구 완료")
        setRestoreDate("")
        loadHistory()
      } else {
        await appAlert(res.error || t("msg_save_fail_detail"))
      }
    } catch (e) {
      await appAlert(e instanceof Error ? e.message : "실패")
    } finally {
      setRestoring(false)
    }
  }, [restoreDate, loadHistory, t])

  const formatDate = (s: string) => {
    try {
      const d = new Date(s)
      return d.toLocaleString(lang === "ko" ? "ko-KR" : "en-US", {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
      })
    } catch {
      return s
    }
  }

  const formatField = (fn: string) => {
    const pascal = fn.split('_').map((s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase()).join('')
    const key = `priceHistoryField${pascal}`
    return t(key) || FIELD_LABELS[fn] || fn
  }

  const formatValue = (v: number | null) =>
    v != null ? Number(v).toLocaleString(lang === "ko" ? "ko-KR" : "en-US", { minimumFractionDigits: 0, maximumFractionDigits: 2 }) : "—"

  const formatDateOnly = React.useCallback((dateStr: string) => {
    try {
      const d = new Date(dateStr)
      return d.toLocaleDateString(lang === "ko" ? "ko-KR" : "en-US", {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      })
    } catch {
      return dateStr
    }
  }, [lang])

  const subCategories = React.useMemo(() => {
    if (mode !== "menu") return []
    if (mainCategoryFilter === "all") {
      const all = Object.values(categoriesByMain).flat()
      const preset = POS_MAIN_CATEGORIES.flatMap((m) => getPresetCategoriesForMain(m) || [])
      return [...new Set([...all, ...preset])].filter(Boolean).sort()
    }
    const preset = getPresetCategoriesForMain(mainCategoryFilter)
    const fromConfig = categoriesByMain[mainCategoryFilter] || []
    return [...new Set([...(preset || []), ...fromConfig])].filter(Boolean).sort()
  }, [mode, mainCategoryFilter, categoriesByMain])

  const filteredMenus = React.useMemo(() => {
    if (mode !== "menu") return []
    return menus.filter((m) => {
      if (mainCategoryFilter !== "all" && (m.categoryMain || "").trim() !== mainCategoryFilter) return false
      if (categoryFilter !== "all" && (m.category || "").trim() !== categoryFilter) return false
      return true
    })
  }, [mode, menus, mainCategoryFilter, categoryFilter])

  /** 품목 모드: 품목별 타임라인 (품목명 > 초기 > 변경날짜1 > 변경날짜2 > ... > 현재) */
  const itemTimelines = React.useMemo(() => {
    if (mode !== "item" || rows.length === 0) return []
    const filtered = rows.filter((r) => r.field_name === itemFieldFilter)
    const byEntity = new Map<string, PriceHistoryRow[]>()
    for (const r of filtered) {
      const key = r.entity_id
      if (!byEntity.has(key)) byEntity.set(key, [])
      byEntity.get(key)!.push(r)
    }
    return Array.from(byEntity.entries())
      .map(([entityId, list]) => {
        const sorted = [...list].sort((a, b) => new Date(a.changed_at).getTime() - new Date(b.changed_at).getTime())
        const name = sorted[0]?.entity_display_name || entityId
        const nodes: { label: string; price: number | null; date?: string }[] = []
        for (const row of sorted) {
          if (row.old_value == null) {
            nodes.push({ label: t("priceHistoryInitial") || "초기", price: row.new_value, date: row.changed_at })
          } else {
            nodes.push({
              label: formatDateOnly(row.changed_at),
              price: row.new_value,
              date: row.changed_at,
            })
          }
        }
        const lastPrice = sorted.length > 0 ? sorted[sorted.length - 1].new_value : null
        if (nodes.length > 0) {
          nodes.push({ label: t("priceHistoryCurrent") || "현재", price: lastPrice })
        }
        return { entityId, name, nodes }
      })
      .sort((a, b) => (a.name || "").localeCompare(b.name || ""))
  }, [mode, rows, itemFieldFilter, t, formatDateOnly])

  /** 메뉴 모드: 메뉴/옵션별 타임라인 (품목과 동일 양식) */
  const menuTimelines = React.useMemo(() => {
    if (mode !== "menu" || rows.length === 0) return []
    const filtered = rows.filter((r) => r.field_name === menuFieldFilter)
    const byEntity = new Map<string, PriceHistoryRow[]>()
    for (const r of filtered) {
      const key = r.entity_id
      if (!byEntity.has(key)) byEntity.set(key, [])
      byEntity.get(key)!.push(r)
    }
    return Array.from(byEntity.entries())
      .map(([entityId, list]) => {
        const sorted = [...list].sort((a, b) => new Date(a.changed_at).getTime() - new Date(b.changed_at).getTime())
        const name = sorted[0]?.entity_display_name || entityId
        const nodes: { label: string; price: number | null; date?: string }[] = []
        for (const row of sorted) {
          if (row.old_value == null) {
            nodes.push({ label: t("priceHistoryInitial") || "초기", price: row.new_value, date: row.changed_at })
          } else {
            nodes.push({
              label: formatDateOnly(row.changed_at),
              price: row.new_value,
              date: row.changed_at,
            })
          }
        }
        const lastPrice = sorted.length > 0 ? sorted[sorted.length - 1].new_value : null
        if (nodes.length > 0) {
          nodes.push({ label: t("priceHistoryCurrent") || "현재", price: lastPrice })
        }
        return { entityId, name, nodes }
      })
      .sort((a, b) => (a.name || "").localeCompare(b.name || ""))
  }, [mode, rows, menuFieldFilter, t, formatDateOnly])

  /** 타임라인용 (품목/메뉴 공통): max 노드 수, 테이블용 정렬 */
  const timelines = mode === "item" ? itemTimelines : menuTimelines
  const maxNodes = React.useMemo(() => {
    if (timelines.length === 0) return 0
    return Math.max(...timelines.map((t) => t.nodes.length))
  }, [timelines])

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        {mode === "menu" && (
          <>
            <Select
              value={mainCategoryFilter}
              onValueChange={(v) => {
                setMainCategoryFilter(v)
                setCategoryFilter("all")
              }}
            >
              <SelectTrigger className="h-9 w-[120px] text-xs">
                <SelectValue placeholder={t("posMenuCategoryMain") || "대분류"} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("posMenuCategoryAll") || "전체"}</SelectItem>
                {categories.map((c) => (
                  <SelectItem key={c} value={c}>{c}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={categoryFilter} onValueChange={setCategoryFilter}>
              <SelectTrigger className="h-9 w-[140px] text-xs">
                <SelectValue placeholder={t("posMenuCategory") || "카테고리"} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("posMenuCategoryAll") || "전체"}</SelectItem>
                {subCategories.map((c) => (
                  <SelectItem key={c} value={c}>{c}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={menuFieldFilter} onValueChange={setMenuFieldFilter}>
              <SelectTrigger className="h-9 w-[140px] text-xs">
                <SelectValue placeholder={t("priceHistoryFieldPrice") || "홀/판매가"} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="price">{t("priceHistoryFieldPrice") || "홀/판매가"}</SelectItem>
                <SelectItem value="price_delivery">{t("priceHistoryFieldPriceDelivery") || "배달앱"}</SelectItem>
                <SelectItem value="price_modifier">{t("priceHistoryFieldPriceModifier") || "옵션 추가금(홀)"}</SelectItem>
                <SelectItem value="price_modifier_delivery">{t("priceHistoryFieldPriceModifierDelivery") || "옵션 추가금(배달)"}</SelectItem>
                <SelectItem value="price_modifier_packaging">{t("priceHistoryFieldPriceModifierPackaging") || "옵션 추가금(포장)"}</SelectItem>
              </SelectContent>
            </Select>
          </>
        )}
        {mode === "item" && (
          <>
            <Select value={categoryFilter} onValueChange={setCategoryFilter}>
              <SelectTrigger className="h-9 w-[140px] text-xs">
                <SelectValue placeholder={t("posMenuCategory") || "카테고리"} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("posMenuCategoryAll") || "전체"}</SelectItem>
                {categories.map((c) => (
                  <SelectItem key={c} value={c}>{c}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={itemFieldFilter} onValueChange={(v: "cost" | "price") => setItemFieldFilter(v)}>
              <SelectTrigger className="h-9 w-[120px] text-xs">
                <SelectValue placeholder={t("priceHistoryFieldCost") || "원가"} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="cost">{t("priceHistoryFieldCost") || "원가"}</SelectItem>
                <SelectItem value="price">{t("priceHistoryFieldPrice") || "홀/판매가"}</SelectItem>
              </SelectContent>
            </Select>
          </>
        )}
        {mode === "menu" && (
          <Select value={menuFilter} onValueChange={setMenuFilter}>
            <SelectTrigger className="h-9 w-[180px] text-xs">
              <SelectValue placeholder={t("priceHistoryMenuSelect") || "메뉴 선택"} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">{t("posMenuCategoryAll") || "전체"}</SelectItem>
              {filteredMenus.map((m) => (
                <SelectItem key={m.id} value={m.id}>{m.code} {m.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
        <div className="relative flex-1 min-w-[180px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder={t("priceHistorySearchPh") || "메뉴/품목명 검색"}
            className="h-9 pl-9 text-sm"
          />
        </div>
        <div className="flex items-center gap-2">
          <Calendar className="h-4 w-4 text-muted-foreground" />
          <Input
            type="date"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
            className="h-9 w-[140px] text-sm"
          />
          <span className="text-muted-foreground">~</span>
          <Input
            type="date"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
            className="h-9 w-[140px] text-sm"
          />
        </div>
        <Button size="sm" className="h-9 gap-1.5" onClick={loadHistory} disabled={loading}>
          <Search className={cn("h-3.5 w-3.5", loading && "animate-pulse")} />
          {loading ? (t("loading") || "조회 중") : (t("priceHistoryBtnSearch") || "검색")}
        </Button>
        <Button size="sm" variant="outline" className="h-9 gap-1.5" onClick={handleBackfill} disabled={backfilling}>
          {backfilling ? (t("loading") || "처리 중") : (t("priceHistoryBackfillBtn") || "일괄 초기 등록")}
        </Button>
        {mode === "menu" && (
          <>
            <Input
              type="date"
              value={restoreDate}
              onChange={(e) => setRestoreDate(e.target.value)}
              className="h-9 w-[140px] text-sm"
              title={t("priceHistoryRestoreDatePh") || "복구할 날짜"}
            />
            <Button size="sm" variant="secondary" className="h-9 gap-1.5" onClick={handleRestoreByDate} disabled={restoring || !restoreDate.trim()}>
              {restoring ? (t("loading") || "처리 중") : (t("priceHistoryRestoreByDateBtn") || "해당 날짜 가격으로 복구")}
            </Button>
          </>
        )}
      </div>

      <div className="rounded-xl border bg-card overflow-hidden">
        {/* 품목/메뉴 공통: 이름 > 초기 > 변경날짜1 > ... > 현재 (테이블로 칸 정렬) */}
        {timelines.length > 0 && maxNodes > 0 && (
          <div className="overflow-x-auto">
            <table className="w-full text-sm border-collapse">
              <thead>
                <tr className="border-b bg-muted/50">
                  <th className="px-4 py-3 text-left font-semibold text-xs w-[200px] min-w-[180px]">
                    {mode === "item" ? (t("priceHistoryColName") || "품목명") : (t("priceHistoryColName") || "메뉴/품목")}
                  </th>
                  {Array.from({ length: maxNodes }, (_, i) => (
                    <th key={i} className="px-2 py-3 text-center font-semibold text-xs w-[100px] min-w-[90px]">
                      {" "}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {timelines.map(({ entityId, name, nodes }) => (
                  <tr key={entityId} className="border-b last:border-b-0 hover:bg-muted/20">
                    <td className="px-4 py-2 font-medium align-top w-[200px] min-w-[180px]">
                      <span className="line-clamp-2" title={name}>{name}</span>
                    </td>
                    {Array.from({ length: maxNodes }, (_, i) => {
                      const node = nodes[i]
                      return (
                        <td key={i} className="px-2 py-2 text-center align-top w-[100px] min-w-[90px]">
                          {node ? (
                            <>
                              <div className="text-xs text-muted-foreground mb-0.5">{node.label}</div>
                              <div className="tabular-nums font-medium text-primary">{formatValue(node.price)}</div>
                            </>
                          ) : (
                            <span className="text-muted-foreground/50">—</span>
                          )}
                        </td>
                      )
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        {timelines.length === 0 && !loading && (
          <div className="px-6 py-12 text-center text-sm text-muted-foreground space-y-2">
            <History className="mx-auto h-10 w-10 mb-2 opacity-50" />
            <p>{t("priceHistoryEmpty") || "검색"}</p>
            <p className="text-xs opacity-80">{t("priceHistoryEmptyHint") || "메뉴/품목 가격을 수정하면 이력이 기록됩니다. Supabase에 price_history 테이블이 있는지 확인하세요."}</p>
          </div>
        )}
        {rows.length === 0 && loading && (
          <div className="px-6 py-12 text-center text-sm text-muted-foreground">{t("loading")}</div>
        )}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Search, Radio, CalendarDays } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { useStoreList, getTodaySchedule, getTodayAttendanceSummary, type TodayScheduleItem, type TodayAttendanceItem } from "@/lib/api-client"
import { todayStrBangkok } from "@/lib/attendance-utils"
import { cn } from "@/lib/utils"

function todayStr() {
  return todayStrBangkok()
}

function parseTimeToDecimal(s: string | null | undefined): number | null {
  if (!s || typeof s !== "string") return null
  const match = s.trim().match(/(\d{1,2}):(\d{2})/)
  if (!match) return null
  return parseInt(match[1], 10) + parseInt(match[2], 10) / 60
}

/** 근무=● 파란(정상)/빨간(문제), 휴게=○ 테두리만 */
const WORK_NORMAL = "bg-blue-500"
const WORK_PROBLEM = "bg-red-500"

/** ●/○ 원형 마크 - 시간표 정상=파란, 문제=빨간 */
function ScheduleCellMark({
  fullBreak,
  fullWork,
  breakFirst,
  breakSecond,
  workFirst,
  workSecond,
  hasProblem,
}: {
  fullBreak: boolean
  fullWork: boolean
  breakFirst: boolean
  breakSecond: boolean
  workFirst: boolean
  workSecond: boolean
  hasProblem: boolean
}) {
  const workClass = hasProblem ? WORK_PROBLEM : WORK_NORMAL
  if (fullBreak) {
    return <span className="inline-block h-4 w-4 rounded-full border-2 border-muted-foreground/50 flex-shrink-0 bg-transparent" />
  }
  if (fullWork) {
    return <span className={cn("inline-block h-4 w-4 rounded-full flex-shrink-0", workClass)} />
  }
  if (breakFirst && workSecond) {
    return (
      <span className="relative inline-block h-4 w-4 flex-shrink-0">
        <span className="absolute left-0 top-0 h-4 w-[8px] rounded-l-full border-2 border-muted-foreground/50 border-r-0 bg-transparent box-border" />
        <span className={cn("absolute right-0 top-0 h-4 w-[8px] rounded-r-full", workClass)} />
      </span>
    )
  }
  if (workFirst && breakSecond) {
    return (
      <span className="relative inline-block h-4 w-4 flex-shrink-0">
        <span className={cn("absolute left-0 top-0 h-4 w-[8px] rounded-l-full", workClass)} />
        <span className="absolute right-0 top-0 h-4 w-[8px] rounded-r-full border-2 border-muted-foreground/50 border-l-0 bg-transparent box-border" />
      </span>
    )
  }
  if (workFirst && !workSecond) {
    return (
      <span className="relative inline-block h-4 w-4 flex-shrink-0">
        <span className={cn("absolute left-0 top-0 h-4 w-[8px] rounded-l-full", workClass)} />
      </span>
    )
  }
  if (workSecond && !workFirst) {
    return (
      <span className="relative inline-block h-4 w-4 flex-shrink-0">
        <span className={cn("absolute right-0 top-0 h-4 w-[8px] rounded-r-full", workClass)} />
      </span>
    )
  }
  return <span className="inline-block h-4 w-4 flex-shrink-0" />
}

const zoneStyle: Record<string, string> = {
  Service: "bg-[hsl(215,80%,50%)] text-[hsl(0,0%,100%)]",
  Kitchen: "bg-[hsl(152,60%,42%)] text-[hsl(0,0%,100%)]",
  Office: "bg-muted text-muted-foreground",
}

interface RealtimeWorkProps {
  storeFilter?: string
  storeList?: string[]
}

export function RealtimeWork({ storeFilter: storeFilterProp = "", storeList: storeListProp = [] }: RealtimeWorkProps) {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [storeList, setStoreList] = React.useState<string[]>([])
  const [storeFilter, setStoreFilter] = React.useState("")
  const storeFilterFinal = storeFilterProp || storeFilter
  const [date, setDate] = React.useState(todayStr)
  const [areaFilter, setAreaFilter] = React.useState("all")
  const [schedule, setSchedule] = React.useState<TodayScheduleItem[]>([])
  const [attendance, setAttendance] = React.useState<TodayAttendanceItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [hasSearched, setHasSearched] = React.useState(false)

  const { stores: storeListFromHook } = useStoreList()
  React.useEffect(() => {
    if (auth?.store && storeListProp.length === 0 && storeListFromHook.length > 0) {
      setStoreFilter(auth.store)
      const unique = Array.from(new Set([auth.store, ...storeListFromHook])).filter(Boolean).sort()
      setStoreList(unique)
    }
  }, [auth?.store, storeListProp.length, storeListFromHook])

  const loadTodayData = React.useCallback(() => {
    let store = storeFilterFinal || auth?.store
    if (!store) return
    setHasSearched(true)
    store = (store === t("scheduleStoreAll") || store === "All" || store === "전체") ? "All" : store
    setLoading(true)
    Promise.all([getTodaySchedule({ store, date }), getTodayAttendanceSummary({ store, date })])
      .then(([sch, att]) => {
        setSchedule(sch || [])
        setAttendance(att || [])
      })
      .catch(() => {
        setSchedule([])
        setAttendance([])
      })
      .finally(() => setLoading(false))
  }, [storeFilterFinal, auth?.store, date])

  // 당일 조회 중일 때 실시간 반영: 30초마다 출퇴근 데이터 재조회
  const isViewingToday = date === todayStr()
  React.useEffect(() => {
    if (!hasSearched || !isViewingToday) return
    const interval = setInterval(() => {
      loadTodayData()
    }, 30 * 1000)
    return () => clearInterval(interval)
  }, [hasSearched, isViewingToday, loadTodayData])

  const filteredSchedule =
    areaFilter === "all"
      ? schedule
      : schedule.filter((r) => (r.area || "Service") === (areaFilter === "service" ? "Service" : areaFilter === "kitchen" ? "Kitchen" : "Office"))
  const attByKey: Record<string, TodayAttendanceItem> = {}
  for (const a of attendance) {
    attByKey[`${a.store}|${a.name}`] = a
  }

  const byPerson: Record<string, { name: string; store: string; area: string; pIn: string; pOut: string; pBS: string; pBE: string; leaveType?: string }> = {}
  for (const s of filteredSchedule) {
    const key = `${s.store}|${s.name}`
    byPerson[key] = {
      name: s.nick || s.name,
      store: s.store,
      area: s.area || "Service",
      pIn: s.pIn,
      pOut: s.pOut,
      pBS: s.pBS,
      pBE: s.pBE,
      leaveType: s.leaveType,
    }
  }

  let minDec = 24,
    maxDec = 0
  for (const p of Object.values(byPerson)) {
    const inD = parseTimeToDecimal(p.pIn),
      outD = parseTimeToDecimal(p.pOut),
      bsD = parseTimeToDecimal(p.pBS),
      beD = parseTimeToDecimal(p.pBE)
    if (inD != null && inD < minDec) minDec = inD
    if (bsD != null && bsD < minDec) minDec = bsD
    if (outD != null && outD > maxDec) maxDec = outD
    if (beD != null && beD > maxDec) maxDec = beD
  }
  const hourStart = minDec <= maxDec ? Math.max(0, Math.floor(minDec)) : 6
  const hourEnd = minDec <= maxDec ? Math.min(24, Math.ceil(maxDec) + 1) : 24
  const hours: number[] = []
  for (let h = hourStart; h < hourEnd; h++) hours.push(h)

  const areaOrder: Record<string, number> = { Service: 0, Kitchen: 1, Office: 2 }
  const personKeys = Object.keys(byPerson).sort((a, b) => {
    const pA = byPerson[a],
      pB = byPerson[b]
    const oA = areaOrder[pA.area] ?? 3
    const oB = areaOrder[pB.area] ?? 3
    if (oA !== oB) return oA - oB
    const inA = parseTimeToDecimal(pA.pIn) ?? 0
    const inB = parseTimeToDecimal(pB.pIn) ?? 0
    return inA - inB
  })

  const multiArea = new Set(filteredSchedule.map((r) => r.area || "Service")).size > 1
  const showArea = areaFilter === "all" && multiArea

  const areaLabel = (ar: string) => {
    if (ar === "Service") return t("scheduleAreaService") || "서비스"
    if (ar === "Kitchen") return t("scheduleAreaKitchen") || "주방"
    if (ar === "Office") return t("scheduleAreaOffice") || "오피스"
    return ar
  }

  if (!auth?.store) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 rounded-2xl border border-dashed py-12">
        <CalendarDays className="h-10 w-10 text-muted-foreground/50" />
        <p className="text-center text-sm text-muted-foreground">{t("att_select_store_login")}</p>
      </div>
    )
  }

  return (
    <div className="rounded-2xl border bg-card shadow-sm">
      {/* Header */}
      <div className="flex items-center gap-3 px-4 pt-5 pb-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(215,80%,50%)]/10">
          <Radio className="h-[18px] w-[18px] text-[hsl(215,80%,50%)]" />
        </div>
        <div>
          <h3 className="text-[15px] font-bold text-card-foreground">{t("scheduleToday")}</h3>
          <p className="text-[11px] text-muted-foreground">{t("scheduleCurrentStaff")}</p>
        </div>
      </div>

      {/* Filters - 날짜, 구역, 검색 (사진과 동일) */}
      <div className="flex flex-wrap items-end gap-3 px-4 pb-3">
        <div className="flex flex-col gap-1">
          <label className="text-[10px] font-medium text-muted-foreground">{t("dateFrom") || "날짜"}</label>
          <Input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="h-9 w-32 rounded-lg text-xs" />
        </div>
        <div className="flex flex-col gap-1">
          <label className="text-[10px] font-medium text-muted-foreground">{t("scheduleArea") || "구역"}</label>
          <Select value={areaFilter} onValueChange={setAreaFilter}>
            <SelectTrigger className="h-9 w-24 rounded-lg text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">{t("noticeFilterAll")}</SelectItem>
              <SelectItem value="service">{areaLabel("Service")}</SelectItem>
              <SelectItem value="kitchen">{areaLabel("Kitchen")}</SelectItem>
              <SelectItem value="office">{areaLabel("Office")}</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <Button size="sm" className="h-9 rounded-lg px-4 text-xs font-semibold" onClick={loadTodayData} disabled={loading}>
          <Search className="mr-1.5 h-3.5 w-3.5" />
          {loading ? t("loading") : t("search")}
        </Button>
      </div>

      {/* 테이블 - 구역 | 이름 | 9시~21시 */}
      <div className="px-4 pb-4">
        {!hasSearched ? (
          <div className="rounded-xl border border-dashed border-border py-8 text-center">
            <CalendarDays className="mx-auto h-8 w-8 text-muted-foreground/30" />
            <p className="mt-2 text-xs text-muted-foreground">{t("scheduleLoadHint")}</p>
          </div>
        ) : loading ? (
          <div className="py-8 text-center text-sm text-muted-foreground">{t("loading")}</div>
        ) : filteredSchedule.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border py-8 text-center">
            <CalendarDays className="mx-auto h-8 w-8 text-muted-foreground/30" />
            <p className="mt-2 text-xs text-muted-foreground">{t("scheduleTodayEmpty")}</p>
          </div>
        ) : (
          <div className="overflow-x-auto overscroll-x-contain rounded-xl border">
            <table className="w-full border-collapse text-left">
              {/* 헤더: 구역 | 이름 | 9 | 10 | ... | 21 */}
              <thead>
                <tr className="bg-muted/50">
                  <th className="border-b border-r border-border px-3 py-2.5 text-[11px] font-bold text-muted-foreground w-[72px]">{t("scheduleArea") || "구역"}</th>
                  <th className="border-b border-r border-border px-3 py-2.5 text-[11px] font-bold text-muted-foreground w-[80px]">{t("scheduleName") || "이름"}</th>
                  {hours.map((h) => (
                    <th key={h} className="border-b border-r border-border px-0 py-2 text-center text-[10px] font-bold tabular-nums text-muted-foreground w-[28px] min-w-[28px] last:border-r-0">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {personKeys.map((key) => {
                  const p = byPerson[key]
                  const isLeave = !!p.leaveType
                  const att = attByKey[key]
                  const inDec = parseTimeToDecimal(p.pIn)
                  const outDec = parseTimeToDecimal(p.pOut)
                  const bsDec = parseTimeToDecimal(p.pBS)
                  const beDec = parseTimeToDecimal(p.pBE)
                  // 휴가일: 보라 배경. 그 외 출근만 하면 파란색, 지각·조퇴 등이면 빨간색. 퇴근미기록(근무중)은 정상
                  const hasProblem: boolean = !isLeave && (!att
                    ? true
                    : Boolean(
                        (att.lateMin && att.lateMin > 0) ||
                          (att.status && att.status !== '퇴근미기록' && /지각|결석|미기록|조퇴|휴게초과/.test(att.status))
                      ))
                  const rowBg = isLeave
                    ? "bg-violet-50/80 dark:bg-violet-950/40"
                    : hasProblem
                      ? "bg-red-50/60 dark:bg-red-950/40"
                      : "bg-white dark:bg-card"

                  return (
                    <tr key={key} className={cn("border-b border-border last:border-b-0", rowBg)}>
                      <td className="border-r border-border px-2 py-2 align-middle">
                        <span
                          className={cn(
                            "inline-flex items-center rounded px-2 py-0.5 text-[10px] font-bold",
                            zoneStyle[p.area] || "bg-muted text-muted-foreground"
                          )}
                        >
                          {areaLabel(p.area)}
                        </span>
                      </td>
                      <td className="border-r border-border px-2 py-2 text-[13px] font-bold text-foreground align-middle">
                        <span className="inline-flex items-center gap-1.5 flex-wrap">
                          {p.name}
                          {isLeave && (
                            <span className="inline-flex items-center rounded px-1.5 py-0.5 text-[10px] font-semibold bg-violet-200 dark:bg-violet-800 text-violet-800 dark:text-violet-200">
                              {t("scheduleLeave")}
                            </span>
                          )}
                        </span>
                      </td>
                      {isLeave ? (
                        hours.map((h) => (
                          <td key={h} className="border-r border-border px-0 py-1.5 text-center align-middle last:border-r-0 w-[28px] min-w-[28px]">
                            <span className="inline-block h-4 w-4" />
                          </td>
                        ))
                      ) : hours.map((h) => {
                        const h0 = h,
                          h05 = h + 0.5,
                          h1 = h + 1
                        const breakFirst = bsDec != null && beDec != null && bsDec < h05 && beDec > h0
                        const breakSecond = bsDec != null && beDec != null && bsDec < h1 && beDec > h05
                        const workFirst = inDec != null && outDec != null && inDec < h05 && outDec > h0 && !breakFirst
                        const workSecond = inDec != null && outDec != null && inDec < h1 && outDec > h05 && !breakSecond
                        const fullBreak = breakFirst && breakSecond
                        const fullWork = workFirst && workSecond
                        const inAny = fullBreak || fullWork || breakFirst || breakSecond || workFirst || workSecond

                        return (
                          <td key={h} className="border-r border-border px-0 py-1.5 text-center align-middle last:border-r-0 w-[28px] min-w-[28px]">
                            {inAny ? (
                              <div className="flex justify-center">
                                <ScheduleCellMark
                                  fullBreak={fullBreak}
                                  fullWork={fullWork}
                                  breakFirst={breakFirst}
                                  breakSecond={breakSecond}
                                  workFirst={workFirst}
                                  workSecond={workSecond}
                                  hasProblem={hasProblem}
                                />
                              </div>
                            ) : (
                              <span className="inline-block h-4 w-4" />
                            )}
                          </td>
                        )
                      })}
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Legend - ● 파란=정상, ● 빨간=문제, ○ 휴게 */}
      <div className="flex flex-wrap items-center justify-center gap-4 rounded-b-2xl border-t bg-muted/20 px-4 py-3">
        <div className="flex items-center gap-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-blue-500 shrink-0" />
          <span className="text-[10px] font-semibold text-muted-foreground">{t("scheduleWork")} ● {t("scheduleTodayNormal")}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-red-500 shrink-0" />
          <span className="text-[10px] font-semibold text-muted-foreground">{t("scheduleWork")} ● {t("scheduleTodayProblem")}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="h-3.5 w-3.5 rounded-full border-2 border-muted-foreground/50 shrink-0" />
          <span className="text-[10px] font-semibold text-muted-foreground">{t("scheduleBreak")} ○</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="text-[10px] font-semibold text-muted-foreground">{t("scheduleNotWorking")}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="inline-flex items-center rounded px-1.5 py-0.5 text-[10px] font-semibold bg-violet-200 dark:bg-violet-800 text-violet-800 dark:text-violet-200">{t("scheduleLeave")}</span>
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Search, CalendarRange, ChevronLeft, ChevronRight, CalendarDays, Printer, FileSpreadsheet, ChevronUp } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { useAuth } from "@/lib/auth-context"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { useStoreList, getWeeklySchedule, type WeeklyScheduleItem } from "@/lib/api-client"
import { getMondayOfWeekBangkok, addDaysSchedule } from "@/lib/attendance-utils"
import { normalizeEmployeeNameFields } from "@/lib/employee-display-name"
import { cn, displayLabelShort } from "@/lib/utils"

function scheduleRowIsLeave(r: WeeklyScheduleItem): boolean {
  const lt = r.leaveType
  return lt != null && String(lt).trim() !== ""
}

function scheduleTimeOnly(v: string | null | undefined): string {
  if (v == null || (typeof v === "string" && !v.trim())) return ""
  const s = String(v).trim()
  const match = s.match(/(\d{1,2}):(\d{2})/)
  if (match) return ("0" + match[1]).slice(-2) + ":" + match[2]
  if (s.indexOf("T") !== -1) {
    const tPart = s.split("T")[1]
    if (tPart) {
      const m = tPart.match(/(\d{1,2}):(\d{2})/)
      if (m) return ("0" + m[1]).slice(-2) + ":" + m[2]
    }
  }
  return s.length >= 5 && s.charAt(2) === ":" ? s.substring(0, 5) : s
}

const zoneStyle: Record<string, string> = {
  Service: "bg-[hsl(215,80%,50%)] text-[hsl(0,0%,100%)]",
  Kitchen: "bg-[hsl(152,60%,42%)] text-[hsl(0,0%,100%)]",
  Office: "bg-muted text-muted-foreground",
}

interface WeeklyScheduleProps {
  storeFilter?: string
  storeList?: string[]
  onStoreChange?: (store: string) => void
}

export function WeeklySchedule({ storeFilter: storeFilterProp = "", storeList: storeListProp = [], onStoreChange }: WeeklyScheduleProps) {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const [storeList, setStoreList] = React.useState<string[]>([])
  const [storeFilter, setStoreFilter] = React.useState("")
  const storeFilterFinal = storeFilterProp || storeFilter
  const [date, setDate] = React.useState(() => getMondayOfWeekBangkok())
  const [areaFilter, setAreaFilter] = React.useState("all")
  const [schedule, setSchedule] = React.useState<WeeklyScheduleItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [hasSearched, setHasSearched] = React.useState(false)
  const [collapsedRows, setCollapsedRows] = React.useState<Set<string>>(new Set())

  /**
   * 가로 드래그 스크롤: (1) flex 자식은 min-w-0 없으면 부모가 내용만큼 커져 scrollWidth===clientWidth가 됨
   * (2) capture/setPointerCapture는 환경에 따라 동작이 달라 버블 pointerdown + window move/up만 사용
   */
  const scheduleHScrollRef = React.useRef<HTMLDivElement>(null)
  const suppressScheduleRowClickRef = React.useRef(false)
  const [scheduleHScrollDragging, setScheduleHScrollDragging] = React.useState(false)

  React.useLayoutEffect(() => {
    const node = scheduleHScrollRef.current
    if (!node) return
    /** ref.current 는 클로저에서 null 로 좁혀지지 않아 명시 타입으로 고정 */
    const scrollEl: HTMLDivElement = node

    let activeId: number | null = null
    let startX = 0
    let startScroll = 0
    let dragMoved = false
    let uiDragging = false

    function detachWindowListeners() {
      window.removeEventListener("pointermove", onPointerMove)
      window.removeEventListener("pointerup", onPointerEnd)
      window.removeEventListener("pointercancel", onPointerEnd)
    }

    function onPointerEnd(e: PointerEvent) {
      if (activeId == null || e.pointerId !== activeId) return
      activeId = null
      detachWindowListeners()
      if (uiDragging) {
        uiDragging = false
        setScheduleHScrollDragging(false)
      }
      if (dragMoved) suppressScheduleRowClickRef.current = true
      dragMoved = false
    }

    function onPointerMove(e: PointerEvent) {
      if (activeId == null || e.pointerId !== activeId) return
      const dx = e.clientX - startX
      if (Math.abs(dx) <= 4) return
      dragMoved = true
      scrollEl.scrollLeft = startScroll - dx
      e.preventDefault()
      if (!uiDragging) {
        uiDragging = true
        setScheduleHScrollDragging(true)
      }
    }

    function onPointerDownBubble(e: PointerEvent) {
      if (e.target instanceof Node && !scrollEl.contains(e.target)) return
      if (e.pointerType === "mouse" && e.button !== 0) return
      activeId = e.pointerId
      startX = e.clientX
      startScroll = scrollEl.scrollLeft
      dragMoved = false
      window.addEventListener("pointermove", onPointerMove, { passive: false })
      window.addEventListener("pointerup", onPointerEnd)
      window.addEventListener("pointercancel", onPointerEnd)
    }

    function onWheel(e: WheelEvent) {
      if (scrollEl.scrollWidth <= scrollEl.clientWidth + 2) return
      if (e.shiftKey && e.deltaY !== 0) {
        scrollEl.scrollLeft += e.deltaY
        e.preventDefault()
        return
      }
      if (Math.abs(e.deltaX) > Math.abs(e.deltaY) && e.deltaX !== 0) {
        scrollEl.scrollLeft += e.deltaX
        e.preventDefault()
      }
    }

    scrollEl.addEventListener("pointerdown", onPointerDownBubble)
    scrollEl.addEventListener("wheel", onWheel, { passive: false })

    return () => {
      detachWindowListeners()
      activeId = null
      scrollEl.removeEventListener("pointerdown", onPointerDownBubble)
      scrollEl.removeEventListener("wheel", onWheel)
    }
  }, [hasSearched, schedule.length, loading])

  const displayStoreList = storeListProp.length > 0 ? storeListProp : storeList
  const isOffice = displayStoreList.length > 1 && ["director", "officer", "ceo", "hr"].includes(auth?.role || "")
  const storeOptions = isOffice ? [t("scheduleStoreAll"), ...displayStoreList.filter((s) => s !== t("scheduleStoreAll") && s !== "All")] : displayStoreList

  const { stores: storeListRaw } = useStoreList()
  React.useEffect(() => {
    if (auth?.store && storeListProp.length === 0 && storeListRaw.length > 0) {
      const isOffice = ["director", "officer", "ceo", "hr"].includes(auth?.role || "")
      if (isOffice) {
        setStoreList([t("scheduleStoreAll"), ...storeListRaw].filter(Boolean))
        setStoreFilter(t("scheduleStoreAll"))
      } else {
        setStoreList([auth.store!])
        setStoreFilter(auth.store)
      }
    }
  }, [auth?.store, auth?.role, t, storeListProp.length, storeListRaw])

  const loadWeekData = React.useCallback(() => {
    let store = storeFilterFinal || auth?.store
    if (!store) return
    setHasSearched(true)
    setLoading(true)
    const area = areaFilter === "all" ? undefined : areaFilter === "service" ? "Service" : areaFilter === "kitchen" ? "Kitchen" : "Office"
    store = (store === t("scheduleStoreAll") || store === "All" || store === "전체") ? "All" : store
    const storeParam = store
    getWeeklySchedule({ store: storeParam, monday: date, area })
      .then((list) => setSchedule(list || []))
      .catch(() => setSchedule([]))
      .finally(() => setLoading(false))
  }, [auth?.store, storeFilterFinal, date, areaFilter])

  const handleStoreChange = (v: string) => {
    if (onStoreChange) onStoreChange(v)
    else setStoreFilter(v)
  }

  const areaLabel = (ar: string) => {
    if (ar === "Service") return t("scheduleAreaService") || "서비스"
    if (ar === "Kitchen") return t("scheduleAreaKitchen") || "주방"
    if (ar === "Office") return t("scheduleAreaOffice") || "오피스"
    return ar
  }

  const dayStrs = Array.from({ length: 7 }, (_, i) => addDaysSchedule(date, i))
  const dayLabels = [
    t("scheduleMon") || "월",
    t("scheduleTue") || "화",
    t("scheduleWed") || "수",
    t("scheduleThu") || "목",
    t("scheduleFri") || "금",
    t("scheduleSat") || "토",
    t("scheduleSun") || "일",
  ]
  const daysFull = dayStrs.map((s) => {
    const [y, m, d] = s.split("-")
    return `${parseInt(m, 10)}/${parseInt(d, 10)}`
  })
  const weekRangeStr = dayStrs.length >= 2
    ? `${dayStrs[0].replace(/-/g, ".")} ~ ${dayStrs[6].slice(5).replace(/-/g, ".")}`
    : ""

  const byPerson: Record<string, { name: string; store: string; area: string; byDate: Record<string, WeeklyScheduleItem> }> = {}
  for (const r of schedule) {
    const st = String(r.store || "").trim()
    const rawName = String(r.name || "").trim()
    const { name: normName } = normalizeEmployeeNameFields(rawName, "")
    const canonical = (normName || rawName).trim() || rawName
    const mergeKey = `${st}|${canonical}`
    if (!byPerson[mergeKey]) {
      byPerson[mergeKey] = {
        name: String(r.nick || canonical || rawName).trim() || rawName,
        store: st,
        area: String(r.area || "Service"),
        byDate: {},
      }
    } else {
      const nk = String(r.nick || "").trim()
      if (nk) byPerson[mergeKey].name = nk
      if (!scheduleRowIsLeave(r)) {
        byPerson[mergeKey].area = String(r.area || byPerson[mergeKey].area || "Service")
      }
    }
    // schedule_date는 근무 시작일. plan_in_prev_day 시 퇴근만 다음날이므로 당일(r.date)에만 표시
    const d = r.date
    const prev = byPerson[mergeKey].byDate[d]
    const incLeave = scheduleRowIsLeave(r)
    const prevLeave = prev ? scheduleRowIsLeave(prev) : false
    if (!prev) {
      byPerson[mergeKey].byDate[d] = r
    } else if (incLeave && !prevLeave) {
      byPerson[mergeKey].byDate[d] = r
    } else if (!incLeave && prevLeave) {
      // 같은 날 휴가가 있으면 근무 행으로 덮어쓰지 않음
    } else {
      byPerson[mergeKey].byDate[d] = r
    }
  }
  const personKeys = Object.keys(byPerson).sort()
  const dailyCount = [0, 0, 0, 0, 0, 0, 0]
  const multiArea = new Set(schedule.map((r) => r.area || "Service")).size > 1
  const showArea = multiArea

  type PersonData = {
    /** 집계 키(store|API name) — 닉네임이 같아도 직원별로 유일 */
    personKey: string
    name: string
    store: string
    area: string
    workDays: string[]
    breakDays: string[]
    leaveDays: (string | undefined)[]
  }
  const persons: PersonData[] = []
  for (const key of personKeys) {
    const p = byPerson[key]
    const workDays: string[] = []
    const breakDays: string[] = []
    const leaveDays: (string | undefined)[] = []
    for (let i = 0; i < 7; i++) {
      const row = p.byDate[dayStrs[i]] as (WeeklyScheduleItem & { leaveType?: string }) | undefined
      const leaveType = row?.leaveType
      leaveDays.push(leaveType)
      if (leaveType) {
        workDays.push("")
        breakDays.push("")
        dailyCount[i]++
        continue
      }
      const pIn = row?.pIn ? scheduleTimeOnly(row.pIn) : ""
      const pOut = row?.pOut ? scheduleTimeOnly(row.pOut) : ""
      const workStr = row && (pIn || pOut) ? `${pIn || "-"}-${pOut || "-"}` : ""
      const pBS = row?.pBS ? scheduleTimeOnly(row.pBS) : ""
      const pBE = row?.pBE ? scheduleTimeOnly(row.pBE) : ""
      const breakStr = row && pBS && pBE ? `${pBS}-${pBE}` : ""
      workDays.push(workStr)
      breakDays.push(breakStr)
      if (workStr) dailyCount[i]++
    }
    persons.push({ personKey: key, name: p.name, store: p.store, area: p.area, workDays, breakDays, leaveDays })
  }

  // 전체 매장 선택 시 매장별로 그룹화
  const storeFilterIsAll = storeFilterFinal === t("scheduleStoreAll") || storeFilterFinal === "All" || storeFilterFinal === "전체" || !storeFilterFinal
  const personsByStore: { store: string; persons: PersonData[] }[] = []
  if (storeFilterIsAll && persons.length > 0) {
    const byStore: Record<string, PersonData[]> = {}
    for (const p of persons) {
      const st = p.store || ""
      if (!byStore[st]) byStore[st] = []
      byStore[st].push(p)
    }
    const storesSorted = Object.keys(byStore).filter(Boolean).sort()
    for (const st of storesSorted) {
      personsByStore.push({ store: st, persons: byStore[st] })
    }
  } else {
    personsByStore.push({ store: storeFilterFinal, persons })
  }

  const goPrevWeek = () => setDate(addDaysSchedule(date, -7))
  const goNextWeek = () => setDate(addDaysSchedule(date, 7))

  const toggleRow = (key: string) => {
    setCollapsedRows((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }

  const handlePrint = () => {
    if (!hasSearched || schedule.length === 0) return
    setCollapsedRows(new Set())
    setTimeout(() => {
    const area = document.getElementById("weekly-schedule-print-area")
    if (!area) return
    const style = document.createElement("style")
    style.id = "schedule-print-style"
    style.textContent = `@media print {
      @page { margin: 0.5in; }
      body * { visibility: hidden; }
      #weekly-schedule-print-area, #weekly-schedule-print-area * { visibility: visible; }
      #weekly-schedule-print-area { position: absolute; left: 0; top: 0; width: 100%; }
      .print\\:hidden { display: none !important; }
      #weekly-schedule-print-area .print-schedule-header {
        text-align: center;
        font-size: 1.2rem;
        font-weight: 800;
        font-family: "Malgun Gothic", "Apple SD Gothic Neo", "Pretendard", "Noto Sans KR", sans-serif;
        letter-spacing: 0.03em;
      }
      #weekly-schedule-print-area .print-schedule-header p { margin: 0.4em 0; }
      #weekly-schedule-print-area .print-schedule-wrap { width: 100% !important; min-width: 100% !important; }
      #weekly-schedule-print-area .print-schedule-grid {
        grid-template-columns: 72px repeat(7, 1fr) !important;
        width: 100% !important;
      }
      #weekly-schedule-print-area .print-schedule-person { padding: 4px 6px !important; min-height: 28px !important; gap: 2px !important; }
      #weekly-schedule-print-area .print-schedule-slot { min-height: 24px !important; padding: 2px 4px !important; font-size: 10px !important; }
      #weekly-schedule-print-area .print-schedule-slot-empty { min-height: 24px !important; font-size: 9px !important; }
      #weekly-schedule-print-area .print-schedule-person-name { font-size: 10px !important; }
      #weekly-schedule-print-area .print-schedule-person-area { font-size: 9px !important; }
      #weekly-schedule-print-area .print-schedule-gap { gap: 4px !important; }
      #weekly-schedule-print-area .print-schedule-card { border-radius: 4px !important; }
    }`
    document.head.appendChild(style)
    window.print()
    document.getElementById("schedule-print-style")?.remove()
    }, 50)
  }

  const escapeXml = (s: string) =>
    String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;")

  const handleExcel = () => {
    if (!hasSearched || schedule.length === 0) return
    const storeLabel = storeFilterFinal === t("scheduleStoreAll") || storeFilterFinal === "All" || !storeFilterFinal ? t("scheduleStoreAll") : storeFilterFinal
    const headers = ["", ...dayLabels.map((d, i) => `${d} ${daysFull[i]}`)]
    const dataRows: string[][] = []
    for (const p of persons) {
      const workRow = [p.name + (showArea ? ` (${areaLabel(p.area)})` : "")]
      const breakRow = [""]
      for (let i = 0; i < 7; i++) {
        workRow.push(p.leaveDays?.[i] ? t("scheduleLeave") : (p.workDays[i] || "-"))
        breakRow.push(p.leaveDays?.[i] ? "" : (p.breakDays[i] ? `R ${p.breakDays[i]}` : ""))
      }
      dataRows.push(workRow)
      dataRows.push(breakRow)
    }
    const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
<head><meta charset="utf-8"/><style>td{border:1px solid #ccc;padding:4px 8px;font-size:11px}.head{font-weight:bold;background:#f0f0f0}table{width:100%;border-collapse:collapse}</style></head>
<body>
<table>
<tr><td class="head">${escapeXml(t("scheduleWeek") || "주간 시간표")}</td><td colspan="7">${escapeXml(weekRangeStr)}</td></tr>
<tr><td class="head">${escapeXml(t("scheduleStorePlaceholder") || "매장")}</td><td colspan="7">${escapeXml(storeLabel)}</td></tr>
<tr></tr>
<tr class="head">${headers.map((c) => `<td>${escapeXml(c)}</td>`).join("")}</tr>
${dataRows.map((row) => `<tr>${row.map((c) => `<td>${escapeXml(c)}</td>`).join("")}</tr>`).join("")}
</table>
</body>
</html>`
    const blob = new Blob(["\uFEFF" + html], { type: "application/vnd.ms-excel;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `schedule_${storeLabel}_${date}.xls`
    a.click()
    URL.revokeObjectURL(url)
  }

  if (!auth?.store) return null

  return (
    <div className="rounded-2xl border bg-card shadow-sm w-full min-w-0 max-w-full">
      {/* Header */}
      <div className="flex items-center gap-3 px-4 pt-5 pb-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(215,80%,50%)]/10">
          <CalendarRange className="h-[18px] w-[18px] text-[hsl(215,80%,50%)]" />
        </div>
        <div>
          <h3 className="text-[15px] font-bold text-card-foreground">{t("scheduleWeek")}</h3>
          <p className="text-[11px] text-muted-foreground leading-tight">{t("scheduleWeekHint")}</p>
        </div>
      </div>

      {/* Filters - 매장, 날짜, 구역, 검색 (한 줄) */}
      <div className="flex flex-wrap items-center gap-2 px-4 pb-3">
        {storeOptions.length > 0 ? (
          <Select
            value={storeFilterFinal || storeOptions[0] || ""}
            onValueChange={handleStoreChange}
          >
            <SelectTrigger className="h-9 w-28 rounded-lg text-xs shrink-0">
              <SelectValue placeholder={t("scheduleStorePlaceholder")} />
            </SelectTrigger>
            <SelectContent>
              {storeOptions.map((s) => (
                <SelectItem key={s} value={s}>{s}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : null}
        <Input type="date" value={date} onChange={(e) => setDate(getMondayOfWeekBangkok(e.target.value))} className="date-input-compact h-9 w-36 rounded-lg text-xs shrink-0" />
        <Select value={areaFilter} onValueChange={setAreaFilter}>
          <SelectTrigger className="h-9 w-24 rounded-lg text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">{t("noticeFilterAll")}</SelectItem>
            <SelectItem value="service">{areaLabel("Service")}</SelectItem>
            <SelectItem value="kitchen">{areaLabel("Kitchen")}</SelectItem>
            <SelectItem value="office">{areaLabel("Office")}</SelectItem>
          </SelectContent>
        </Select>
        <Button size="sm" className="h-9 rounded-lg px-3 text-xs font-semibold" onClick={loadWeekData} disabled={loading}>
          <Search className="mr-1 h-3.5 w-3.5" />
          {loading ? t("loading") : t("search")}
        </Button>
        {hasSearched && schedule.length > 0 && (
          <>
            <Button size="sm" variant="outline" className="h-9 rounded-lg px-3 text-xs print:hidden" onClick={handlePrint} title={t("schedulePrintHint") || t("pettyPrintHint")}>
              <Printer className="mr-1 h-3.5 w-3.5" />
              {t("printBtn")}
            </Button>
            <Button size="sm" variant="outline" className="h-9 rounded-lg px-3 text-xs print:hidden" onClick={handleExcel} title={t("scheduleExcelHint") || t("pettyExcelHint")}>
              <FileSpreadsheet className="mr-1 h-3.5 w-3.5" />
              {t("excelBtn")}
            </Button>
          </>
        )}
      </div>

      {/* Week Navigation */}
      <div className="flex items-center justify-between border-y bg-muted/20 px-4 py-2.5">
        <Button variant="ghost" size="icon" className="h-7 w-7 rounded-lg" onClick={goPrevWeek}>
          <ChevronLeft className="h-4 w-4" />
        </Button>
        <span className="text-xs font-bold text-card-foreground">{weekRangeStr}</span>
        <Button variant="ghost" size="icon" className="h-7 w-7 rounded-lg" onClick={goNextWeek}>
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>

      {!hasSearched ? (
        <div className="rounded-xl border border-dashed border-border py-8 text-center">
          <CalendarDays className="mx-auto h-8 w-8 text-muted-foreground/30" />
          <p className="mt-2 text-xs text-muted-foreground">{t("scheduleLoadHint")}</p>
        </div>
      ) : loading ? (
        <div className="py-8 text-center text-sm text-muted-foreground">{t("loading")}</div>
      ) : schedule.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border py-8 text-center">
          <CalendarDays className="mx-auto h-8 w-8 text-muted-foreground/30" />
          <p className="mt-2 text-xs text-muted-foreground">{t("scheduleTodayEmpty")}</p>
        </div>
      ) : (
        <>
          <div id="weekly-schedule-print-area">
            {/* 인쇄용 상단 - 매장, 기간 (가운데 정렬, 제목 스타일) */}
            <div className="hidden print:block print-schedule-header border-b border-border pb-3 mb-3 pt-1">
              <p>{t("scheduleStorePlaceholder")}: {storeFilterFinal === t("scheduleStoreAll") || storeFilterFinal === "All" || !storeFilterFinal ? t("scheduleStoreAll") : storeFilterFinal}</p>
              <p>{t("schedulePeriod")}: {weekRangeStr}</p>
            </div>
            {/* 가로 스크롤 영역 - 마우스로 끌어 스크롤 (행이 button이라 기본 제스처만으로는 불편함) */}
            <div
              ref={scheduleHScrollRef}
              className={cn(
                "min-w-0 w-full max-w-full max-h-[min(75vh,42rem)] overflow-x-auto overflow-y-auto overscroll-contain px-4 pb-4 [-webkit-overflow-scrolling:touch] print:max-h-none print:overflow-visible print:px-0",
                scheduleHScrollDragging ? "cursor-grabbing" : "cursor-grab"
              )}
            >
            <div
              className="w-max print:!min-w-0 print:w-full print:max-w-none print-schedule-wrap"
              style={{ minWidth: "max(720px, max-content, calc(100% + 1px))" }}
            >
              {/* 요일 헤더 */}
              <div className="grid gap-1 mb-2 print-schedule-grid" style={{ gridTemplateColumns: "72px repeat(7, minmax(72px, 80px))" }}>
                <div className="shrink-0" />
                {dayLabels.map((day, i) => (
                  <div key={day} className="flex flex-col items-center gap-0.5 shrink-0 min-w-[72px]">
                    <span
                      className={cn(
                        "text-[10px] font-bold",
                        i === 5 ? "text-[hsl(215,80%,50%)]" : i === 6 ? "text-[hsl(0,72%,51%)]" : "text-muted-foreground"
                      )}
                    >
                      {day}
                    </span>
                    <span className="text-[9px] text-muted-foreground/70 tabular-nums">{daysFull[i]}</span>
                  </div>
                ))}
              </div>

              {/* 이름+부서 | 시간표 - 근무시간/쉬는시간 각각 한 줄 (매장별 그룹) */}
              <div className="flex flex-col gap-4 print-schedule-gap">
                {personsByStore.map(({ store: storeName, persons: storePersons }) => (
                  <div key={storeName} className="space-y-2">
                    {storeFilterIsAll && storeName && (
                      <div className="text-sm font-bold text-card-foreground px-2 py-1.5 rounded-lg bg-muted/50 border print:bg-transparent print:border-0">
                        {storeName}
                      </div>
                    )}
                    {storePersons.map((p) => {
                  const key = p.personKey
                  const isCollapsed = collapsedRows.has(key)
                  return (
                    <div key={key} className="rounded-xl border bg-card overflow-hidden print-schedule-card">
                      {/* button 대신 div: 버튼은 포인터/드래그가 가로 스크롤과 충돌하는 경우가 많음 */}
                      <div
                        role="button"
                        tabIndex={0}
                        onKeyDown={(ev) => {
                          if (ev.key !== "Enter" && ev.key !== " ") return
                          ev.preventDefault()
                          if (suppressScheduleRowClickRef.current) {
                            suppressScheduleRowClickRef.current = false
                            return
                          }
                          toggleRow(key)
                        }}
                        onClick={() => {
                          if (suppressScheduleRowClickRef.current) {
                            suppressScheduleRowClickRef.current = false
                            return
                          }
                          toggleRow(key)
                        }}
                        className={cn(
                          "grid gap-1 w-full items-stretch px-2 py-2.5 text-left active:bg-muted/30 transition-colors print-schedule-grid print-schedule-person outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                          scheduleHScrollDragging ? "cursor-grabbing" : "cursor-grab"
                        )}
                        style={{ gridTemplateColumns: "72px repeat(7, minmax(72px, 80px))" }}
                      >
                        {/* 이름 + 부서 + 접기 버튼 */}
                        <div className="flex flex-col items-start justify-center shrink-0 min-w-[72px]">
                          <div className="flex items-center gap-1">
                            <span className="text-[13px] font-bold text-card-foreground leading-tight print-schedule-person-name">{displayLabelShort(p.name)}</span>
                            {!isCollapsed && (
                              <span className="inline-flex shrink-0" title={t("scheduleCollapseAll") || "접기"}>
                                <ChevronUp
                                  className="h-4 w-4 text-muted-foreground hover:text-foreground"
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    if (suppressScheduleRowClickRef.current) {
                                      suppressScheduleRowClickRef.current = false
                                      return
                                    }
                                    toggleRow(key)
                                  }}
                                />
                              </span>
                            )}
                          </div>
                          <span className="text-[10px] font-medium text-muted-foreground leading-tight mt-0.5 print-schedule-person-area">
                            {areaLabel(p.area)}
                          </span>
                        </div>
                        {/* 시간표 7열 - 근무 1줄, 쉬는 1줄, 휴가 시 로 표시 */}
                        {p.workDays.map((workStr, dayIdx) => {
                          const leaveType = p.leaveDays?.[dayIdx]
                          return (
                          <div key={dayIdx} className="flex flex-col items-center justify-center shrink-0 min-w-[72px]">
                            {leaveType ? (
                              <div className="h-[44px] w-full rounded-md flex items-center justify-center bg-violet-100 dark:bg-violet-950/50 print-schedule-slot px-1">
                                <span className="text-[11px] font-semibold text-violet-700 dark:text-violet-300 whitespace-nowrap" title={leaveType}>
                                  {t("scheduleLeave")}
                                </span>
                              </div>
                            ) : workStr ? (
                              isCollapsed ? (
                                <div className="h-[44px] w-full rounded-md flex items-center justify-center bg-[hsl(215,80%,50%)]/10 print-schedule-slot">
                                  <div className="h-2 w-2 rounded-full bg-[hsl(215,80%,50%)]" />
                                </div>
                              ) : (
                                <div className="flex flex-col items-center justify-center gap-1 rounded-lg bg-[hsl(215,80%,50%)]/10 px-2 py-2 w-full min-h-[44px] print-schedule-slot">
                                  <span className="text-[12px] font-bold tabular-nums text-[hsl(215,80%,50%)] leading-tight whitespace-nowrap">
                                    {workStr}
                                  </span>
                                  {p.breakDays[dayIdx] ? (
                                    <span className="text-[11px] text-muted-foreground leading-tight whitespace-nowrap">
                                      R {p.breakDays[dayIdx]}
                                    </span>
                                  ) : (
                                    <span className="text-[11px] text-muted-foreground/50 leading-tight">-</span>
                                  )}
                                </div>
                              )
                            ) : (
                              <div className="h-[44px] w-full rounded-md flex items-center justify-center bg-muted/50 print-schedule-slot print-schedule-slot-empty">
                                <span className="text-[11px] font-medium text-muted-foreground">{t("scheduleOff")}</span>
                              </div>
                            )}
                          </div>
                          )
                        })}
                      </div>
                    </div>
                  )
                    })}
                  </div>
                ))}
              </div>
            </div>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

"use client"
import { appAlert, appConfirm, appPrompt } from "@/lib/app-message"

import * as React from "react"
import {
  CalendarIcon,
  Search,
  ShieldCheck,
  MessageSquarePlus,
  Building2,
  User,
  Trash2,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import {
  getWorkLogManagerReport,
  updateWorkLogManagerCheck,
  updateWorkLogPriority,
  deleteWorkLogItem,
  getWorkLogOfficeOptions,
  translateTexts,
  type WorkLogManagerItem,
} from "@/lib/api-client"

function defaultStartStr() {
  const d = new Date()
  d.setDate(d.getDate() - 7)
  return d.toISOString().slice(0, 10)
}

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

export function WorklogApproval() {
  const { lang } = useLang()
  const t = useT(lang)
  const [contentTransMap, setContentTransMap] = React.useState<Record<string, string>>({})
  const [startStr, setStartStr] = React.useState(todayStr)
  const [endStr, setEndStr] = React.useState(todayStr)
  const [deptFilter, setDeptFilter] = React.useState("all")
  const [employeeFilter, setEmployeeFilter] = React.useState("all")
  const [statusFilter, setStatusFilter] = React.useState("all")
  const [workTypeFilter, setWorkTypeFilter] = React.useState<string>("all")
  const [contentSearch, setContentSearch] = React.useState("")
  const [depts, setDepts] = React.useState<string[]>([])
  const [staffList, setStaffList] = React.useState<{ name: string; displayName: string }[]>([])
  const [list, setList] = React.useState<WorkLogManagerItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [updating, setUpdating] = React.useState<string | null>(null)
  const [hasSearched, setHasSearched] = React.useState(false)

  React.useEffect(() => {
    getWorkLogOfficeOptions().then((r) => {
      setDepts(r.depts || [])
      setStaffList(r.staff || [])
    })
  }, [])

  const loadData = React.useCallback(async () => {
    setLoading(true)
    try {
      const res = await getWorkLogManagerReport({
        startStr,
        endStr,
        dept: deptFilter,
        employee: employeeFilter,
        status: statusFilter,
      })
      setList(res)
    } catch {
      setList([])
    } finally {
      setLoading(false)
    }
  }, [startStr, endStr, deptFilter, employeeFilter, statusFilter])

  const handleSearch = () => {
    setHasSearched(true)
    loadData()
  }

  React.useEffect(() => {
    const contents = [...new Set(list.map((it) => it.content).filter(Boolean))]
    const comments = list
      .map((it) => (it.managerComment || "").trim())
      .filter((c) => c && !c.startsWith("⚡"))
    const texts = [...new Set([...contents, ...comments])]
    if (texts.length === 0) {
      setContentTransMap({})
      return
    }
    let cancelled = false
    translateTexts(texts, lang).then((translated) => {
      if (cancelled) return
      const map: Record<string, string> = {}
      texts.forEach((txt, i) => { map[txt] = translated[i] ?? txt })
      setContentTransMap(map)
    }).catch(() => setContentTransMap({}))
    return () => { cancelled = true }
  }, [list, lang])

  const getTransContent = (content: string) => (content && contentTransMap[content]) || content || "-"
  const formatManagerComment = (comment: string) => {
    if (!comment) return ""
    return comment
      .replace(/이월됨/g, t("workLogCarriedOver"))
      .replace(/부터/g, t("workLogFrom"))
  }
  const getTransComment = (comment: string) => {
    const trimmed = (comment || "").trim()
    if (!trimmed) return ""
    if (trimmed.startsWith("⚡")) return formatManagerComment(trimmed)
    return contentTransMap[trimmed] || formatManagerComment(trimmed)
  }
  const getWorkTypeDisplay = (status: string) => {
    const s = (status || "").trim()
    if (s === "Finish") return "Finish"
    if (s === "Continue" || s === "Carry Over") return "Continue"
    if (s === "Today") return "Today"
    return s || "-"
  }

  const getReviewStatusDisplay = (item: WorkLogManagerItem): React.ReactNode => {
    const check = item.managerCheck || ""
    const comment = (item.managerComment || "").trim()
    const hasComment = !!comment && !comment.startsWith("⚡")
    if (check === "대기") return "Wait"
    if (check === "승인") {
      if (hasComment) {
        return (
          <span title={t("workLogCommentBtn")}>
            <MessageSquarePlus className="inline h-3.5 w-3.5" />
          </span>
        )
      }
      return "OK"
    }
    return check
  }
  const PRIORITIES = [
    { value: "긴급", key: "workLogPriorityUrgent" },
    { value: "상", key: "workLogPriorityHigh" },
    { value: "중", key: "workLogPriorityMedium" },
    { value: "하", key: "workLogPriorityLow" },
  ] as const

  const handlePriorityChange = async (id: string, priority: string) => {
    setUpdating(id)
    try {
      const res = await updateWorkLogPriority({ id, priority })
      if (res.success) loadData()
      else await appAlert((res as { messageKey?: string; message?: string }).messageKey ? t((res as { messageKey?: string }).messageKey!) : translateApiMessage((res as { message?: string }).message, t) || t("workLogSaveFail"))
    } catch {
      await appAlert(t("workLogProcessError"))
    } finally {
      setUpdating(null)
    }
  }

  const handleConfirm = async (id: string) => {
    setUpdating(id)
    try {
      const res = await updateWorkLogManagerCheck({ id, status: "승인" })
      if (res.success) loadData()
      else await appAlert((res as { messageKey?: string }).messageKey ? t((res as { messageKey?: string }).messageKey!) : (translateApiMessage(res.message, t) || t("workLogProcessError")))
    } catch {
      await appAlert(t("workLogProcessError"))
    } finally {
      setUpdating(null)
    }
  }

  const handleAddComment = async (id: string, existingComment?: string) => {
    const comment = await appPrompt(t("workLogCommentPrompt"), existingComment ?? "")
    if (comment === null) return
    setUpdating(id)
    try {
      const res = await updateWorkLogManagerCheck({
        id,
        status: "승인",
        comment: comment.trim() || undefined,
      })
      if (res.success) loadData()
      else await appAlert((res as { messageKey?: string }).messageKey ? t((res as { messageKey?: string }).messageKey!) : (translateApiMessage(res.message, t) || t("workLogProcessError")))
    } catch {
      await appAlert(t("workLogProcessError"))
    } finally {
      setUpdating(null)
    }
  }

  const handleDelete = async (id: string) => {
    if (!await appConfirm(t("workLogDeleteConfirm"))) return
    setUpdating(id)
    try {
      const res = await deleteWorkLogItem({ id })
      if (res.success) loadData()
      else await appAlert((res as { messageKey?: string; message?: string }).messageKey ? t((res as { messageKey?: string }).messageKey!) : (translateApiMessage((res as { message?: string }).message, t) || t("workLogDeleteFail")))
    } catch {
      await appAlert(t("workLogDeleteFail"))
    } finally {
      setUpdating(null)
    }
  }

  const filteredList = React.useMemo(() => {
    const q = (contentSearch || "").trim().toLowerCase()
    if (!q) return list
    return list.filter((it) => {
      const content = (it.content || "").toLowerCase()
      const name = (it.name || "").toLowerCase()
      const dept = (it.dept || "").toLowerCase()
      const displayName = (staffList.find((s) => s.name === it.name || s.displayName === it.name)?.displayName || "").toLowerCase()
      return content.includes(q) || name.includes(q) || dept.includes(q) || displayName.includes(q)
    })
  }, [list, contentSearch, staffList])

  const filteredByWorkType = React.useMemo(() => {
    if (!workTypeFilter || workTypeFilter === "all") return filteredList
    if (workTypeFilter === "Continue") {
      return filteredList.filter((it) => (it.status || "").trim() === "Continue" || (it.status || "").trim() === "Carry Over")
    }
    return filteredList.filter((it) => (it.status || "").trim() === workTypeFilter)
  }, [filteredList, workTypeFilter])

  const sortedList = React.useMemo(() => {
    const statusOrder: Record<string, number> = {
      Finish: 0,
      "Carry Over": 1,
      Continue: 1,
      Today: 2,
    }
    return [...filteredByWorkType].sort((a, b) => {
      const dateCmp = (a.date || "").localeCompare(b.date || "")
      if (dateCmp !== 0) return dateCmp
      const orderA = statusOrder[(a.status || "").trim()] ?? 3
      const orderB = statusOrder[(b.status || "").trim()] ?? 3
      return orderA - orderB
    })
  }, [filteredByWorkType])

  const pendingItems = filteredByWorkType.filter((it) => it.managerCheck === "대기")
  const byDept = React.useMemo(() => {
    const map: Record<string, Record<string, WorkLogManagerItem[]>> = {}
    for (const it of sortedList) {
      const d = it.dept || "기타"
      const n = it.name || ""
      if (!map[d]) map[d] = {}
      if (!map[d][n]) map[d][n] = []
      map[d][n].push(it)
    }
    return map
  }, [sortedList])

  return (
    <div className="flex flex-col gap-6">
      {/* Filters */}
      <div className="rounded-xl border bg-card p-5 shadow-sm">
        <div className="flex flex-wrap items-end gap-3">
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <CalendarIcon className="h-3.5 w-3.5 text-primary" />
              {t("workLogPeriod")}
            </label>
            <div className="flex items-center gap-1.5">
              <Input
                type="date"
                value={startStr}
                onChange={(e) => { setStartStr(e.target.value); setHasSearched(false) }}
                className="h-9 w-32 text-xs shrink-0"
              />
              <span className="text-xs text-muted-foreground shrink-0">~</span>
              <Input
                type="date"
                value={endStr}
                onChange={(e) => { setEndStr(e.target.value); setHasSearched(false) }}
                className="h-9 w-32 text-xs shrink-0"
              />
            </div>
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <Building2 className="h-3.5 w-3.5 text-primary" />
              {t("workLogDept")}
            </label>
            <Select value={deptFilter} onValueChange={(v) => { setDeptFilter(v); setHasSearched(false) }}>
              <SelectTrigger className="h-9 w-28 text-xs shrink-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("all")}</SelectItem>
                {depts.map((d) => (
                  <SelectItem key={d} value={d}>
                    {d}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <User className="h-3.5 w-3.5 text-primary" />
              {t("workLogEmployee")}
            </label>
            <Select value={employeeFilter} onValueChange={(v) => { setEmployeeFilter(v); setHasSearched(false) }}>
              <SelectTrigger className="h-9 w-32 text-xs shrink-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("all")}</SelectItem>
                {staffList.map((s) => (
                  <SelectItem key={s.name} value={s.displayName || s.name}>
                    {s.displayName || s.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <Search className="h-3.5 w-3.5 text-primary" />
              {t("search")}
            </label>
            <Input
              type="text"
              placeholder={t("workLogSearchPlaceholder")}
              value={contentSearch}
              onChange={(e) => setContentSearch(e.target.value)}
              className="h-9 w-36 text-xs min-w-0"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-semibold text-foreground">{t("workLogStatus")}</label>
            <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v); setHasSearched(false) }}>
              <SelectTrigger className="h-9 w-24 text-xs shrink-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("all")}</SelectItem>
                <SelectItem value="대기">Wait</SelectItem>
                <SelectItem value="승인">OK / Commented</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-semibold text-foreground">{t("workLogColWorkType")}</label>
            <Select value={workTypeFilter} onValueChange={setWorkTypeFilter}>
              <SelectTrigger className="h-9 w-28 text-xs shrink-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("all")}</SelectItem>
                <SelectItem value="Finish">Finish</SelectItem>
                <SelectItem value="Continue">Continue</SelectItem>
                <SelectItem value="Today">Today</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <Button size="sm" className="h-9 px-4 text-xs font-semibold" onClick={handleSearch} disabled={loading}>
            <Search className="mr-1.5 h-3.5 w-3.5" />
            {t("workLogSearch")}
          </Button>
        </div>
      </div>

      {/* Table by dept/employee */}
      <div className="rounded-xl border bg-card shadow-sm overflow-hidden">
        <div className="flex items-center gap-2.5 border-b bg-muted/30 px-6 py-3">
          <ShieldCheck className="h-4 w-4 text-primary" />
          <h3 className="text-sm font-bold text-foreground">{t("workLogApprovalTitle")}</h3>
          {pendingItems.length > 0 && (
            <span className="rounded-full bg-warning/20 px-2 py-0.5 text-xs font-bold text-warning">
              {t("workLogPendingCount")} {pendingItems.length}
            </span>
          )}
        </div>
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-16">
              <div className="h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
            </div>
          ) : !hasSearched ? (
            <div className="py-12 text-center text-sm text-muted-foreground">
              {t("orderSearchHint") || "조회 버튼을 눌러 주세요."}
            </div>
          ) : list.length === 0 ? (
            <div className="py-12 text-center text-sm text-muted-foreground">
              {t("workLogNoResult")}
            </div>
          ) : filteredByWorkType.length === 0 ? (
            <div className="py-12 text-center text-sm text-muted-foreground">
              {t("workLogNoSearchResult")}
            </div>
          ) : (
            <div className="divide-y">
              {Object.entries(byDept).map(([dept, byName]) => (
                <div key={dept}>
                  {Object.entries(byName).map(([name, items]) => (
                    <div key={`${dept}-${name}`} className="border-b last:border-b-0">
                      <div className="bg-muted/20 px-5 py-2 text-xs font-bold text-muted-foreground">
                        {(dept === "기타" ? t("workLogOther") : dept)} · {staffList.find((s) => s.name === name || s.displayName === name)?.displayName || name}
                      </div>
                      <table className="w-full table-fixed text-left text-sm">
                        <colgroup>
                          <col className="w-32" />
                          <col className="w-28" />
                          <col />
                          <col className="w-24" />
                          <col className="w-20" />
                          <col className="w-28" />
                          <col className="w-40" />
                        </colgroup>
                        <thead>
                          <tr className="border-b bg-muted/10">
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogColDate")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogColWorkType")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center min-w-0 align-top break-words">{t("workLogColContent")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogPriority")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogColProgress")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogColReviewStatus")}</th>
                            <th className="px-5 py-2 text-[11px] font-bold text-muted-foreground text-center whitespace-nowrap align-top">{t("workLogColAction")}</th>
                          </tr>
                        </thead>
                        <tbody>
                          {items.map((it) => (
                            <tr key={it.id} className="border-b last:border-b-0 hover:bg-muted/5">
                              <td className="px-5 py-2 text-xs tabular-nums text-center whitespace-nowrap align-top">{it.date}</td>
                              <td className="px-5 py-2 text-center whitespace-nowrap align-top">
                                <span
                                  className={cn(
                                    "inline-flex rounded px-2 py-0.5 text-[10px] font-semibold",
                                    it.status === "Finish" && "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300",
                                    (it.status === "Continue" || it.status === "Carry Over") && "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300",
                                    it.status === "Today" && "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300"
                                  )}
                                >
                                  {getWorkTypeDisplay(it.status)}
                                </span>
                              </td>
                              <td className="px-5 py-2 min-w-0 align-top break-words">
                                <p className="text-sm text-foreground whitespace-pre-wrap [overflow-wrap:anywhere]">{getTransContent(it.content || "")}</p>
                                {it.managerComment && (
                                  <p className="mt-0.5 text-[10px] text-muted-foreground whitespace-pre-wrap [overflow-wrap:anywhere]">{getTransComment(it.managerComment)}</p>
                                )}
                              </td>
                              <td className="px-5 py-2 text-center align-top whitespace-nowrap">
                                <Select
                                  value={it.priority || "_none"}
                                  onValueChange={(v) => handlePriorityChange(it.id, v === "_none" ? "" : v)}
                                  disabled={updating === it.id}
                                >
                                  <SelectTrigger className="h-7 w-20 mx-auto text-[10px]">
                                    <SelectValue placeholder={t("workLogPriority")} />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="_none">-</SelectItem>
                                    {PRIORITIES.map((p) => (
                                      <SelectItem key={p.value} value={p.value}>
                                        {t(p.key)}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              </td>
                              <td className="px-5 py-2 text-center align-top whitespace-nowrap">
                                <span className="text-xs font-bold tabular-nums">{it.progress}%</span>
                              </td>
                              <td className="px-5 py-2 text-center align-top whitespace-nowrap">
                                <span
                                  className={cn(
                                    "inline-flex rounded-md px-2 py-0.5 text-[10px] font-bold",
                                    it.managerCheck === "승인" && (it.managerComment?.trim() && !it.managerComment.startsWith("⚡") ? "bg-primary/10 text-primary" : "bg-success/10 text-success"),
                                    it.managerCheck === "대기" && "bg-warning/10 text-warning"
                                  )}
                                >
                                  {getReviewStatusDisplay(it)}
                                </span>
                              </td>
                              <td className="px-5 py-2 align-top whitespace-nowrap">
                                <div className="flex flex-row items-center justify-center gap-2">
                                  {it.managerCheck === "대기" && (
                                    <Button
                                      size="sm"
                                      variant="outline"
                                      className="h-7 w-7 p-0 text-success shrink-0"
                                      onClick={() => handleConfirm(it.id)}
                                      disabled={updating === it.id}
                                      title={t("workLogConfirmBtn")}
                                    >
                                      ✓
                                    </Button>
                                  )}
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-7 px-2 text-[10px] text-primary shrink-0"
                                    onClick={() => handleAddComment(it.id, it.managerComment)}
                                    disabled={updating === it.id}
                                    title={t("workLogCommentBtn")}
                                  >
                                    <MessageSquarePlus className="h-3.5 w-3.5" />
                                  </Button>
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-7 px-2 text-[10px] text-destructive hover:text-destructive shrink-0"
                                    onClick={() => handleDelete(it.id)}
                                    disabled={updating === it.id}
                                    title={t("workLogDeleteBtn")}
                                  >
                                    <Trash2 className="h-3 w-3" />
                                  </Button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

"use client"
import { appAlert, appConfirm } from "@/lib/app-message"

import * as React from "react"
import {
  CalendarIcon,
  User,
  CheckCircle2,
  ArrowRightFromLine,
  Play,
  Plus,
  Save,
  LogOut,
  Search,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { translateApiMessage } from "@/lib/translate-api-message"
import {
  getWorkLogStaffList,
  getWorkLogData,
  saveWorkLogData,
  submitDailyClose,
  translateTexts,
  type WorkLogItem,
  type WorkLogData,
} from "@/lib/api-client"

function todayStr() {
  return new Date().toISOString().slice(0, 10)
}

const PRIORITIES = [
  { value: "긴급", key: "workLogPriorityUrgent" },
  { value: "상", key: "workLogPriorityHigh" },
  { value: "중", key: "workLogPriorityMedium" },
  { value: "하", key: "workLogPriorityLow" },
] as const

interface WorklogMyProps {
  userName: string
}

export function WorklogMy({ userName }: WorklogMyProps) {
  const { lang } = useLang()
  const t = useT(lang)
  const [dateStr, setDateStr] = React.useState(todayStr)
  const [selectedStaff, setSelectedStaff] = React.useState(userName)
  const [staffList, setStaffList] = React.useState<{ name: string; displayName: string }[]>([])
  const [data, setData] = React.useState<WorkLogData | null>(null)
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [localFinish, setLocalFinish] = React.useState<WorkLogItem[]>([])
  const [localContinue, setLocalContinue] = React.useState<WorkLogItem[]>([])
  const [localToday, setLocalToday] = React.useState<WorkLogItem[]>([])
  const [selectedContinueIds, setSelectedContinueIds] = React.useState<Set<string>>(new Set())
  const [contentTransMap, setContentTransMap] = React.useState<Record<string, string>>({})
  const [hasSearched, setHasSearched] = React.useState(false)
  const unfinishedCount = React.useMemo(() => {
    const continueCount = localContinue.filter((it) => {
      const hasContent = Boolean((it.content || "").trim())
      const progress = Number(it.progress) || 0
      return hasContent && progress < 100
    }).length
    const todayCount = localToday.filter((it) => {
      const hasContent = Boolean((it.content || "").trim())
      const progress = Number(it.progress) || 0
      return hasContent && progress < 100
    }).length
    return continueCount + todayCount
  }, [localContinue, localToday])

  React.useEffect(() => {
    if (userName) setSelectedStaff(userName)
  }, [userName])

  React.useEffect(() => {
    if (staffList.length > 0 && selectedStaff && !staffList.some((s) => s.name === selectedStaff)) {
      const match = staffList.find((s) => s.displayName === selectedStaff || s.name === selectedStaff)
      if (match) setSelectedStaff(match.name)
    }
  }, [staffList, selectedStaff])

  React.useEffect(() => {
    getWorkLogStaffList().then((r) => setStaffList(r.staff || []))
  }, [])

  // 직원은 로그인 사용자로 고정
  React.useEffect(() => {
    if (userName) setSelectedStaff(userName)
  }, [userName])

  const loadData = React.useCallback(async () => {
    if (!selectedStaff) return
    setLoading(true)
    try {
      const res = await getWorkLogData({ dateStr, name: selectedStaff })
      setData(res)
      setLocalFinish(res.finish || [])
      setLocalContinue((res.continueItems || []).map((it) => ({ ...it, progress: 0 })))
      setLocalToday(res.todayItems || [])
    } catch {
      setData(null)
      setLocalFinish([])
      setLocalContinue([])
      setLocalToday([])
    } finally {
      setLoading(false)
    }
  }, [dateStr, selectedStaff])

  const handleSearch = () => {
    setHasSearched(true)
    loadData()
  }

  const contentsToTranslate = React.useMemo(() => {
    const set = new Set<string>()
    for (const it of localFinish) {
      if (it.content?.trim()) set.add(it.content.trim())
      const c = it.managerComment?.trim()
      if (c && !c.startsWith("⚡")) set.add(c)
    }
    for (const it of localContinue) {
      if (it.content?.trim()) set.add(it.content.trim())
      const c = it.managerComment?.trim()
      if (c && !c.startsWith("⚡")) set.add(c)
    }
    for (const it of localToday) {
      if (it.content?.trim()) set.add(it.content.trim())
      const c = it.managerComment?.trim()
      if (c && !c.startsWith("⚡")) set.add(c)
    }
    return Array.from(set)
  }, [localFinish, localContinue, localToday])

  React.useEffect(() => {
    if (contentsToTranslate.length === 0) {
      setContentTransMap({})
      return
    }
    let cancelled = false
    translateTexts(contentsToTranslate, lang).then((translated) => {
      if (cancelled) return
      const map: Record<string, string> = {}
      contentsToTranslate.forEach((txt, i) => { map[txt] = translated[i] ?? txt })
      setContentTransMap(map)
    }).catch(() => setContentTransMap({}))
    return () => { cancelled = true }
  }, [contentsToTranslate.join("\u241E"), lang])

  const getTransContent = (content: string) => (content?.trim() && contentTransMap[content.trim()]) || content || t("workLogNoContent")

  const updateProgress = (
    list: WorkLogItem[],
    setList: React.Dispatch<React.SetStateAction<WorkLogItem[]>>,
    id: string,
    progress: number
  ) => {
    setList((prev) =>
      prev.map((it) =>
        it.id === id ? { ...it, progress, status: progress >= 100 ? "Finish" : it.status } : it
      )
    )
  }

  const addNewContinue = () => {
    setLocalContinue((prev) => [
      ...prev,
      {
        id: `_temp_${Date.now()}`,
        content: "",
        progress: 0,
        status: "Continue",
        priority: "중",
      },
    ])
  }

  const toggleSelectContinue = (id: string) => {
    setSelectedContinueIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const moveSelectedToToday = () => {
    if (selectedContinueIds.size === 0) return
    const toMove = localContinue.filter((it) => selectedContinueIds.has(it.id || ""))
    const toKeep = localContinue.filter((it) => !selectedContinueIds.has(it.id || ""))
    setLocalContinue(toKeep)
    setLocalToday((prev) => [
      ...prev,
      ...toMove.map((it) => ({ ...it, status: "Today", progress: 0 })),
    ])
    setSelectedContinueIds(new Set())
  }

  const removeItem = (
    list: WorkLogItem[],
    setList: React.Dispatch<React.SetStateAction<WorkLogItem[]>>,
    id: string
  ) => {
    if (!id) {
      setList((prev) => prev.filter((_, i) => prev.length - 1 !== i))
      return
    }
    setList((prev) => prev.filter((it) => it.id !== id))
  }

  const updateContent = (
    setList: React.Dispatch<React.SetStateAction<WorkLogItem[]>>,
    idOrIndex: string | number,
    content: string
  ) => {
    setList((prev) => {
      if (typeof idOrIndex === 'number') {
        return prev.map((it, i) => (i === idOrIndex ? { ...it, content } : it))
      }
      return prev.map((it) => (it.id === idOrIndex ? { ...it, content } : it))
    })
  }

  const updatePriority = (
    setList: React.Dispatch<React.SetStateAction<WorkLogItem[]>>,
    idOrIndex: string | number,
    priority: string
  ) => {
    setList((prev) => {
      if (typeof idOrIndex === 'number') {
        return prev.map((it, i) => (i === idOrIndex ? { ...it, priority } : it))
      }
      return prev.map((it) => (it.id === idOrIndex ? { ...it, priority } : it))
    })
  }

  const formatManagerComment = (comment: string) => {
    if (!comment) return ""
    return comment
      .replace(/이월됨/g, t("workLogCarriedOver") || "Carried over")
      .replace(/부터/g, t("workLogFrom") || "from")
  }

  const getTransComment = (comment: string) => {
    const trimmed = comment?.trim()
    if (!trimmed) return ""
    if (trimmed.startsWith("⚡")) return formatManagerComment(trimmed)
    return contentTransMap[trimmed] || formatManagerComment(trimmed)
  }

  const ManagerFeedback = ({ item }: { item: WorkLogItem }) => {
    const confirmed = item.managerCheck === "승인"
    const rawComment = item.managerComment?.trim() || ""
    const isCarryOverMsg = rawComment.startsWith("⚡")
    const hasComment = !!rawComment && !isCarryOverMsg
    if (!confirmed && !hasComment) return null
    return (
      <div className="mt-2 rounded-md border border-primary/20 bg-primary/5 px-2.5 py-1.5 text-xs">
        {confirmed && (
          <span className="inline-flex items-center gap-1 font-semibold text-primary">
            ✓ {t("workLogReviewConfirmed")}
          </span>
        )}
        {hasComment && (
          <p className="mt-1 text-foreground">
            <span className="font-semibold text-muted-foreground">{t("workLogManagerFeedback")}:</span>{" "}
            {getTransComment(rawComment)}
          </p>
        )}
      </div>
    )
  }

  const updateProgressByIndex = (
    setList: React.Dispatch<React.SetStateAction<WorkLogItem[]>>,
    index: number,
    progress: number
  ) => {
    setList((prev) =>
      prev.map((it, i) =>
        i === index ? { ...it, progress, status: progress >= 100 ? "Finish" : it.status } : it
      )
    )
  }

  const handleSaveProgress = async () => {
    if (!selectedStaff) return
    if (unfinishedCount > 0) {
      const proceed = await appConfirm(
        `미완료 업무가 ${unfinishedCount}건 있습니다.\n` +
        `Save Progress만 하면 Continue가 생성되지 않습니다.\n` +
        `익일 Continue 생성을 원하면 Daily Close를 눌러주세요.\n\n` +
        `그래도 Save Progress를 진행할까요?`
      )
      if (!proceed) return
    }
    setSaving(true)
    try {
      const allLogs: WorkLogItem[] = [
        ...localFinish.map((it) => ({ ...it, type: undefined })),
        ...localContinue.map((it) => ({ ...it, type: "continue" as const, progress: 0 })),
        ...localToday.map((it) => ({ ...it, type: undefined })),
      ].filter((it) => it.content || it.id)
      const res = await saveWorkLogData({
        date: dateStr,
        name: selectedStaff,
        logs: allLogs,
      })
      if (res.success) {
        loadData()
      } else {
        const r = res as { messageKey?: string; message?: string }
        await appAlert(r.messageKey ? t(r.messageKey) : (translateApiMessage(r.message, t) || t("workLogSaveFail")))
      }
    } catch (e) {
      await appAlert(t("workLogSaveError"))
    } finally {
      setSaving(false)
    }
  }

  const handleDailyClose = async () => {
    if (!selectedStaff) return
        if (!await appConfirm(t("workLogDailyCloseConfirm"))) return
    setSaving(true)
    try {
      const toClose = [...localContinue, ...localToday].filter((it) => it.content || it.id)
      const res = await submitDailyClose({
        date: dateStr,
        name: selectedStaff,
        logs: toClose,
      })
      if (res.success) {
        loadData()
        await appAlert((res as { messageKey?: string }).messageKey ? t((res as { messageKey?: string }).messageKey!) : (translateApiMessage(res.message, t) || t("workLogCloseDone")))
      } else {
        const r = res as { messageKey?: string; message?: string }
        await appAlert(r.message ? `${t(r.messageKey || "workLogCloseFail")}: ${translateApiMessage(r.message, t)}` : t(r.messageKey || "workLogCloseFail"))
      }
    } catch (e) {
      await appAlert(t("workLogCloseError"))
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="flex flex-col gap-6">
      {/* Filters */}
      <div className="rounded-xl border bg-card p-5 shadow-sm">
        <div className="flex flex-wrap items-end gap-4">
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <CalendarIcon className="h-3.5 w-3.5 text-primary" />
              {t("workLogDate")}
            </label>
            <Input
              type="date"
              value={dateStr}
              onChange={(e) => { setDateStr(e.target.value); setHasSearched(false) }}
              className="h-9 w-40 text-xs"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <User className="h-3.5 w-3.5 text-primary" />
              {t("workLogEmployee")}
            </label>
            <div className="flex h-9 items-center rounded-md border bg-muted/30 px-3 text-xs font-medium">
              {staffList.find((s) => s.name === selectedStaff || s.displayName === selectedStaff)?.displayName || selectedStaff || userName}
            </div>
          </div>
          <Button size="sm" className="h-9 px-4 text-xs font-semibold" onClick={handleSearch} disabled={loading}>
            <Search className="mr-1.5 h-3.5 w-3.5" />
            {t("workLogSearch")}
          </Button>
          <Button size="sm" variant="outline" className="h-9 px-4 text-xs font-semibold" onClick={handleSaveProgress} disabled={saving}>
            <Save className="mr-1.5 h-3.5 w-3.5" />
            {t("workLogSaveProgress")}
          </Button>
          <Button size="sm" className="h-9 px-4 text-xs font-semibold" onClick={handleDailyClose} disabled={saving}>
            <LogOut className="mr-1.5 h-3.5 w-3.5" />
            {t("workLogDailyClose")}
          </Button>
        </div>
      </div>

      {!hasSearched ? (
        <div className="rounded-xl border bg-card py-16 text-center text-sm text-muted-foreground">
          {t("orderSearchHint") || "조회 버튼을 눌러 주세요."}
        </div>
      ) : loading ? (
        <div className="flex items-center justify-center rounded-xl border bg-card py-16">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
        </div>
      ) : (
        <div className="flex flex-col gap-6">
          {/* 직렬 배치: Finish → Continue → Today */}
          {/* Finish Work */}
          <div className="rounded-xl border bg-card shadow-sm overflow-hidden">
            <div className="flex items-center gap-2.5 border-b bg-success/5 px-5 py-3">
              <CheckCircle2 className="h-4 w-4 text-success" />
              <h3 className="text-sm font-bold text-foreground">{t("workLogFinishWork")}</h3>
            </div>
            <div className="min-h-[80px] max-h-64 overflow-y-auto p-4 space-y-2">
              {localFinish.length === 0 ? (
                <p className="text-xs text-muted-foreground">{t("workLogNoFinish")}</p>
              ) : (
                localFinish.map((it) => (
                  <div key={it.id} className="rounded-lg border bg-background p-3 text-sm">
                    <p className="font-medium text-foreground whitespace-pre-wrap">{getTransContent(it.content || "")}</p>
                    <p className="mt-1 text-xs text-muted-foreground">{it.progress}%</p>
                    <ManagerFeedback item={it} />
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Continue Work */}
          <div className="rounded-xl border bg-card shadow-sm overflow-hidden">
            <div className="flex items-center gap-2.5 border-b bg-warning/5 px-5 py-3">
              <ArrowRightFromLine className="h-4 w-4 text-warning" />
              <h3 className="text-sm font-bold text-foreground">{t("workLogContinueWork")}</h3>
              <Button size="sm" variant="ghost" className="ml-auto h-7 px-2 text-xs" onClick={addNewContinue} title={t("workLogAddTask")}>
                <Plus className="h-3.5 w-3.5" />
              </Button>
            </div>
            {selectedContinueIds.size > 0 && (
              <div className="flex items-center gap-2 px-4 py-2 bg-warning/10 border-b">
                <Button size="sm" className="h-7 text-xs" onClick={moveSelectedToToday}>
                  <Play className="mr-1 h-3 w-3" />
                  {t("workLogStartToday")} ({selectedContinueIds.size})
                </Button>
              </div>
            )}
            <div className="min-h-[80px] max-h-64 overflow-y-auto p-4 space-y-2">
              {localContinue.length === 0 ? (
                <p className="text-xs text-muted-foreground">{t("workLogNoContinue")}</p>
              ) : (
                localContinue.map((it) => (
                  <div key={it.id} className="rounded-lg border bg-background p-3">
                    <div className="flex items-start gap-2 mb-2">
                      <input
                        type="checkbox"
                        checked={selectedContinueIds.has(it.id || "")}
                        onChange={() => toggleSelectContinue(it.id || "")}
                        className="mt-2.5 h-4 w-4 shrink-0"
                      />
                      <Textarea
                        value={it.content}
                        onChange={(e) => updateContent(setLocalContinue, it.id, e.target.value)}
                        placeholder={t("workLogTaskPlaceholder")}
                        className="min-h-[36px] text-xs flex-1 resize-y"
                        rows={1}
                      />
                      <Select
                        value={it.priority || ""}
                        onValueChange={(v) => updatePriority(setLocalContinue, it.id, v)}
                      >
                        <SelectTrigger className="h-8 w-20 shrink-0 text-xs">
                          <SelectValue placeholder={t("workLogPriority")} />
                        </SelectTrigger>
                        <SelectContent>
                          {PRIORITIES.map((p) => (
                            <SelectItem key={p.value} value={p.value}>
                              {t(p.key)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <p className="text-xs font-bold text-muted-foreground">{t("workLogProgressHint")}</p>
                    {it.managerComment?.startsWith("⚡") && (
                      <p className="mt-1 text-[10px] text-muted-foreground">{formatManagerComment(it.managerComment)}</p>
                    )}
                    <ManagerFeedback item={it} />
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Today Work */}
          <div className="rounded-xl border bg-card shadow-sm overflow-hidden">
            <div className="flex items-center gap-2.5 border-b bg-primary/5 px-5 py-3">
              <Play className="h-4 w-4 text-primary" />
              <h3 className="text-sm font-bold text-foreground">{t("workLogTodayWork")}</h3>
            </div>
            <div className="min-h-[80px] max-h-64 overflow-y-auto p-4 space-y-2">
              {localToday.length === 0 ? (
                <p className="text-xs text-muted-foreground">{t("workLogNoToday")}</p>
              ) : (
                localToday.map((it, idx) => (
                  <div key={it.id || `new-${idx}`} className="rounded-lg border bg-background p-3">
                    <div className="flex items-start gap-2 mb-2">
                      <Textarea
                        value={it.content}
                        onChange={(e) => updateContent(setLocalToday, idx, e.target.value)}
                        placeholder={t("workLogTaskPlaceholder")}
                        className="min-h-[36px] text-xs flex-1 resize-y"
                        rows={1}
                      />
                      <Select
                        value={it.priority || ""}
                        onValueChange={(v) => updatePriority(setLocalToday, idx, v)}
                      >
                        <SelectTrigger className="h-8 w-20 shrink-0 text-xs">
                          <SelectValue placeholder={t("workLogPriority")} />
                        </SelectTrigger>
                        <SelectContent>
                          {PRIORITIES.map((p) => (
                            <SelectItem key={p.value} value={p.value}>
                              {t(p.key)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="range"
                        min={0}
                        max={100}
                        value={it.progress}
                        onChange={(e) => updateProgressByIndex(setLocalToday, idx, Number(e.target.value))}
                        className="h-2 flex-1"
                      />
                      <span className="text-xs font-bold w-8">{it.progress}%</span>
                    </div>
                    <ManagerFeedback item={it} />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { ChevronDown, ChevronRight, PenLine, Trash2, Printer, FileSpreadsheet, FileCheck } from "lucide-react"
import { cn } from "@/lib/utils"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"

export interface InboundTableRow {
  id: string
  date: string
  poDate?: string | null
  vendor: string
  inboundBatchId?: number
  poNo?: string
  invoiceNo?: string
  invoiceReceived?: boolean
  items: { name: string; spec: string; qty: number; amount: number }[]
  itemsSummary: string
  totalQty: number
  totalAmt: number
}

interface InboundTableProps {
  isOffice: boolean
  rows: InboundTableRow[]
  loading?: boolean
  /** 비본사용: 단순 { date, vendor, item, qty, amount } */
  storeRows?: { date: string; vendor: string; item: string; qty: number; amount: number }[]
  onEdit?: (row: InboundTableRow) => void
  onDelete?: (row: InboundTableRow) => void
  onInvoiceReceivedToggle?: (row: InboundTableRow) => void
  onPrint?: (row: InboundTableRow) => void
  onExcel?: (row: InboundTableRow) => void
  updatingInvoiceId?: number | null
}

export function InboundTable({
  isOffice,
  rows,
  loading = false,
  storeRows = [],
  onEdit,
  onDelete,
  onInvoiceReceivedToggle,
  onPrint,
  onExcel,
  updatingInvoiceId = null,
}: InboundTableProps) {
  const { lang } = useLang()
  const t = useT(lang)
  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set())

  const toggleExpand = (idx: number) => {
    setExpandedRows((prev) => {
      const next = new Set(prev)
      if (next.has(idx)) next.delete(idx)
      else next.add(idx)
      return next
    })
  }

  if (!isOffice) {
    return (
      <div className="overflow-x-auto rounded-lg border border-border bg-card">
        <table className="w-full text-xs">
          <thead>
            <tr className="bg-[#1E293B] text-white">
              <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("stockColDate")}</th>
              <th className="px-3 py-2.5 text-center font-semibold">{t("inVendor")}</th>
              <th className="px-3 py-2.5 text-center font-semibold">{t("outColItem")}</th>
              <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("outColQty")}</th>
              <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("inColAmount")}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {loading ? (
              <tr>
                <td colSpan={5} className="py-12 text-center">{t("loading")}</td>
              </tr>
            ) : storeRows.length === 0 ? (
              <tr>
                <td colSpan={5} className="py-12 text-center text-muted-foreground">{t("inNoData")}</td>
              </tr>
            ) : (
              storeRows.map((r, idx) => (
                <tr key={idx} className="hover:bg-primary/5 transition-colors">
                  <td className="px-3 py-2.5 text-center text-card-foreground whitespace-nowrap">{r.date}</td>
                  <td className="px-3 py-2.5 text-center text-card-foreground">{r.vendor}</td>
                  <td className="px-3 py-2.5 text-center text-card-foreground">{r.item}</td>
                  <td className="px-3 py-2.5 text-center text-card-foreground font-medium tabular-nums">{r.qty.toLocaleString()}</td>
                  <td className="px-3 py-2.5 text-right font-bold text-primary tabular-nums">{(r.amount || 0).toLocaleString()}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    )
  }

  const colCount = onEdit || onDelete || onInvoiceReceivedToggle || onPrint || onExcel ? 8 : 6

  return (
    <div className="overflow-x-auto rounded-lg border border-border bg-card">
      <table className="w-full text-xs">
        <thead>
          <tr className="bg-[#1E293B] text-white">
            <th className="px-2 py-2.5 text-center font-semibold whitespace-nowrap">{t("inPoDate")}</th>
            <th className="px-2 py-2.5 text-center font-semibold whitespace-nowrap">{t("inInboundDate")}</th>
            <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("inVendor")}</th>
            <th className="px-3 py-2.5 text-center font-semibold">{t("outColItem")}</th>
            <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("outColQty")}</th>
            <th className="px-3 py-2.5 text-center font-semibold whitespace-nowrap">{t("inColAmount")}</th>
            <th className="px-2 py-2.5 text-center font-semibold whitespace-nowrap min-w-[90px]">{t("poInvoiceNo")}</th>
            {(onEdit || onDelete || onInvoiceReceivedToggle || onPrint || onExcel) && <th className="px-2 py-2.5 text-center font-semibold min-w-[10rem] whitespace-nowrap">{t("actions")}</th>}
          </tr>
        </thead>
        <tbody className="divide-y divide-border">
          {loading ? (
            <tr>
              <td colSpan={colCount} className="py-12 text-center">{t("loading")}</td>
            </tr>
          ) : rows.length === 0 ? (
            <tr>
              <td colSpan={colCount} className="py-12 text-center text-muted-foreground">{t("inNoData")}</td>
            </tr>
          ) : (
            rows.map((row, idx) => (
              <TableRow
                key={row.id}
                row={row}
                idx={idx}
                colCount={colCount}
                isExpanded={expandedRows.has(idx)}
                onToggleExpand={() => toggleExpand(idx)}
                onEdit={onEdit}
                onDelete={onDelete}
                onInvoiceReceivedToggle={onInvoiceReceivedToggle}
                onPrint={onPrint}
                onExcel={onExcel}
                updatingInvoiceId={updatingInvoiceId}
                t={t}
              />
            ))
          )}
        </tbody>
      </table>
    </div>
  )
}

function TableRow({
  row,
  idx,
  colCount,
  isExpanded,
  onToggleExpand,
  onEdit,
  onDelete,
  onInvoiceReceivedToggle,
  onPrint,
  onExcel,
  updatingInvoiceId,
  t,
}: {
  row: InboundTableRow
  idx: number
  colCount: number
  isExpanded: boolean
  onToggleExpand: () => void
  onEdit?: (row: InboundTableRow) => void
  onDelete?: (row: InboundTableRow) => void
  onInvoiceReceivedToggle?: (row: InboundTableRow) => void
  onPrint?: (row: InboundTableRow) => void
  onExcel?: (row: InboundTableRow) => void
  updatingInvoiceId?: number | null
  t: (k: string) => string
}) {
  const hasDetails = row.items.length > 1
  const canEdit = row.inboundBatchId != null && onEdit
  const canDelete = row.inboundBatchId != null && onDelete
  const canInvoiceToggle = row.inboundBatchId != null && onInvoiceReceivedToggle
  const canPrint = row.inboundBatchId != null && onPrint
  const canExcel = row.inboundBatchId != null && onExcel

  return (
    <>
      <tr className={cn("transition-colors hover:bg-primary/5")}>
        <td className="px-2 py-2.5 text-center text-card-foreground whitespace-nowrap text-muted-foreground">{row.poDate ?? "—"}</td>
        <td className="px-2 py-2.5 text-center text-card-foreground whitespace-nowrap font-medium">{row.date}</td>
        <td className="px-3 py-2.5 text-center text-card-foreground whitespace-nowrap font-medium">{row.vendor}</td>
        <td className="px-3 py-2.5 text-card-foreground">
          <div className="flex items-center gap-1.5">
            {hasDetails && (
              <button
                type="button"
                onClick={onToggleExpand}
                className="flex-shrink-0 rounded p-0.5 hover:bg-accent transition-colors text-primary"
              >
                {isExpanded ? (
                  <ChevronDown className="h-3.5 w-3.5" />
                ) : (
                  <ChevronRight className="h-3.5 w-3.5" />
                )}
              </button>
            )}
            {!hasDetails && <span className="inline-block w-[18px]" />}
            <span className="truncate max-w-[400px]" title={row.itemsSummary}>
              {row.itemsSummary}
            </span>
          </div>
        </td>
        <td className="px-3 py-2.5 text-center text-card-foreground font-medium tabular-nums">{row.totalQty.toLocaleString()}</td>
        <td className="px-3 py-2.5 text-right font-bold text-primary tabular-nums">
          {row.totalAmt.toLocaleString()}
        </td>
        <td className="px-2 py-2.5 text-center text-muted-foreground text-xs">
          {row.invoiceNo ? (
            <span className="text-card-foreground" title={row.invoiceNo}>{row.invoiceNo}</span>
          ) : (
            "—"
          )}
        </td>
        {(canEdit || canDelete || canInvoiceToggle || canPrint || canExcel) && (
          <td className="px-2 py-2.5 min-w-[10rem]">
            <div className="flex items-center justify-center gap-1 flex-nowrap">
              {canInvoiceToggle && (
                <button
                  type="button"
                  onClick={() => onInvoiceReceivedToggle(row)}
                  disabled={updatingInvoiceId === row.inboundBatchId}
                  className={`rounded p-1.5 transition-colors ${row.invoiceReceived ? "text-green-600" : "text-muted-foreground hover:text-foreground"}`}
                  title={row.invoiceReceived ? t("poInvoiceReceived") + " ✓" : t("poInvoiceReceived")}
                >
                  <FileCheck className="h-3.5 w-3.5" />
                </button>
              )}
              {canEdit && (
                <button
                  type="button"
                  onClick={() => onEdit(row)}
                  className="rounded p-1.5 hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
                  title={t("edit")}
                >
                  <PenLine className="h-3.5 w-3.5" />
                </button>
              )}
              {canPrint && (
                <button
                  type="button"
                  onClick={() => onPrint(row)}
                  className="rounded p-1.5 hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
                  title={t("purchaseOrderPrint")}
                >
                  <Printer className="h-3.5 w-3.5" />
                </button>
              )}
              {canExcel && (
                <button
                  type="button"
                  onClick={() => onExcel(row)}
                  className="rounded p-1.5 hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
                  title={t("purchaseOrderExcel")}
                >
                  <FileSpreadsheet className="h-3.5 w-3.5" />
                </button>
              )}
              {canDelete && (
                <button
                  type="button"
                  onClick={() => onDelete(row)}
                  className="rounded p-1.5 hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors"
                  title={t("delete")}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
          </td>
        )}
      </tr>
      {isExpanded && hasDetails && (
        <tr>
          <td colSpan={colCount} className="px-0 py-0">
            <div className="mx-6 my-2 overflow-hidden rounded border border-border bg-muted/30">
              <table className="w-full text-xs">
                <thead>
                  <tr className="bg-muted/50">
                    <th className="px-4 py-2 text-center font-semibold text-card-foreground">{t("outColItem")}</th>
                    <th className="px-4 py-2 text-center font-semibold text-card-foreground">{t("spec")}</th>
                    <th className="px-4 py-2 text-center font-semibold text-card-foreground">{t("outColQty")}</th>
                    <th className="px-4 py-2 text-center font-semibold text-card-foreground">{t("inColAmount")}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {row.items.map((d, i) => (
                    <tr key={i} className="hover:bg-primary/5 transition-colors">
                      <td className="px-4 py-2 text-center text-card-foreground">{d.name}</td>
                      <td className="px-4 py-2 text-center text-muted-foreground">{d.spec}</td>
                      <td className="px-4 py-2 text-center text-card-foreground font-medium tabular-nums">{d.qty.toLocaleString()}</td>
                      <td className="px-4 py-2 text-right text-card-foreground tabular-nums">{d.amount.toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </td>
        </tr>
      )}
    </>
  )
}

"use client"

import * as React from "react"
import { flushSync } from "react-dom"
import { ChevronDown, ChevronUp, Filter, Loader2, Search } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { useLang } from "@/lib/lang-context"
import { useT } from "@/lib/i18n"
import { getMarketingCampaigns, useStoreList, type MarketingCampaign } from "@/lib/api-client"
import { cn } from "@/lib/utils"
import {
  applyMarketingCampaignListFilters,
  emptyMarketingCampaignHubLinkSets,
  marketingCampaignListFiltersActive,
  type CampaignListSearchScope,
  type MarketingCampaignHubLinkSets,
} from "@/lib/marketing-campaign-list-query"
import { fetchMarketingCampaignHubLinkSets } from "@/lib/marketing-campaign-hub-link-data"
import { CAMPAIGN_TYPE_OPTIONS, KPI_UNIT_OPTIONS } from "@/lib/marketing-campaign-type-utils"
import type { CampaignHubLinkFilterValue } from "@/lib/marketing-campaign-filters"
import { getCampaignTypeLabel } from "@/lib/marketing-campaign-type-utils"

export type MarketingCampaignFinderPanelProps = {
  value: string
  onChange: (campaignId: string) => void
  /** 주입 시 캠페인 목록 API를 다시 호출하지 않음 */
  campaigns?: MarketingCampaign[] | null
  /** 이 화면에 맞는 연동 영역 기본값 */
  defaultHubLinkFilter?: CampaignHubLinkFilterValue
  /** true면 허브 연동 필터 UI를 숨기고 조건 없이 표시(부모가 이미 범위를 한정한 경우) */
  hideHubLinkFilter?: boolean
  /** 필터·검색 적용 후 목록이 바뀔 때마다 알림(하단 카드 등과 동기화) */
  onFilteredCampaignsChange?: (rows: MarketingCampaign[]) => void
  allowEmpty?: boolean
  emptyOptionLabel?: string
  maxListHeightClass?: string
  className?: string
  /** 부모 새로고침(목록 재로드) — 검색 버튼 처리 후 캠페인 prop이 갱신될 때까지 대기하려면 Promise 반환 */
  onRefresh?: () => void | Promise<void>
  disabled?: boolean
  /** 등록 화면 등: 제목·기간·검색·필터를 한 줄(줄바꿈) 툴바로 압축 */
  toolbarLayout?: "default" | "compact"
  /** compact 툴바일 때 맨 앞 열 — 제목과 검색·기간 입력 하단선 맞춤 */
  compactToolbarTitle?: React.ReactNode
  /** compact 툴바 같은 줄 오른쪽(캠페인 허브 링크 등) */
  compactToolbarEnd?: React.ReactNode
}

export function MarketingCampaignFinderPanel({
  value,
  onChange,
  campaigns: campaignsProp,
  defaultHubLinkFilter = "",
  hideHubLinkFilter = false,
  onFilteredCampaignsChange,
  allowEmpty = false,
  emptyOptionLabel,
  maxListHeightClass = "max-h-72",
  className,
  onRefresh,
  disabled = false,
  toolbarLayout = "default",
  compactToolbarTitle,
  compactToolbarEnd,
}: MarketingCampaignFinderPanelProps) {
  const isCompactToolbar = toolbarLayout === "compact"
  const { lang } = useLang()
  const t = useT(lang)
  const { stores, loading: storesLoading } = useStoreList()

  const tr = React.useCallback(
    (ko: string, en: string, th: string) => {
      if (lang === "en") return en
      if (lang === "th") return th
      if (lang === "ko") return ko
      return en
    },
    [lang]
  )

  const statusLabel = React.useCallback(
    (s: string) => {
      switch (s) {
        case "draft":
          return tr("준비", "Draft", "เตรียมการ")
        case "ongoing":
          return tr("진행중", "Ongoing", "กำลังดำเนินการ")
        case "finish":
          return tr("완료", "Done", "เสร็จสิ้น")
        default:
          return s
      }
    },
    [tr]
  )

  const [campaignsInternal, setCampaignsInternal] = React.useState<MarketingCampaign[]>([])
  const [hubLinkSets, setHubLinkSets] = React.useState<MarketingCampaignHubLinkSets>(() =>
    emptyMarketingCampaignHubLinkSets()
  )
  const [dataLoading, setDataLoading] = React.useState(true)

  /** 입력창(초안) — 적용은 「검색」 클릭 시 listSearchQuery로 반영 */
  const [listSearchDraft, setListSearchDraft] = React.useState("")
  /** 필터에 실제로 쓰이는 검색어 */
  const [listSearchQuery, setListSearchQuery] = React.useState("")
  const [listSearchScope, setListSearchScope] = React.useState<CampaignListSearchScope>("all")
  const [listFiltersOpen, setListFiltersOpen] = React.useState(false)
  const [listPeriodFrom, setListPeriodFrom] = React.useState("")
  const [listPeriodTo, setListPeriodTo] = React.useState("")
  const [listDesignFrom, setListDesignFrom] = React.useState("")
  const [listDesignTo, setListDesignTo] = React.useState("")
  const [listCampaignTypeFilter, setListCampaignTypeFilter] = React.useState("")
  const [listStatusDraft, setListStatusDraft] = React.useState(true)
  const [listStatusOngoing, setListStatusOngoing] = React.useState(true)
  const [listStatusFinish, setListStatusFinish] = React.useState(true)
  const [listBranchFilter, setListBranchFilter] = React.useState("")
  const [listHubLinkFilter, setListHubLinkFilter] = React.useState(() => String(defaultHubLinkFilter ?? ""))
  const [listBudgetMin, setListBudgetMin] = React.useState("")
  const [listBudgetMax, setListBudgetMax] = React.useState("")
  const [listKpiMin, setListKpiMin] = React.useState("")
  const [listKpiMax, setListKpiMax] = React.useState("")
  const [listKpiUnitFilter, setListKpiUnitFilter] = React.useState("")
  const [listDiscountFilter, setListDiscountFilter] = React.useState<"any" | "none" | "percent" | "amount">("any")

  const campaignsSource = campaignsProp ?? campaignsInternal

  const reloadData = React.useCallback(async () => {
    setDataLoading(true)
    try {
      const sets = await fetchMarketingCampaignHubLinkSets()
      setHubLinkSets(sets)
      if (campaignsProp == null) {
        const c = await getMarketingCampaigns()
        setCampaignsInternal(Array.isArray(c) ? c : [])
      }
    } catch {
      setHubLinkSets(emptyMarketingCampaignHubLinkSets())
      if (campaignsProp == null) setCampaignsInternal([])
    } finally {
      setDataLoading(false)
    }
  }, [campaignsProp])

  React.useEffect(() => {
    void reloadData()
  }, [reloadData])

  React.useEffect(() => {
    if (campaignsProp != null) setCampaignsInternal(campaignsProp)
  }, [campaignsProp])

  const effectiveHubLinkFilter = hideHubLinkFilter ? "" : listHubLinkFilter

  const filterParams = React.useMemo(
    () => ({
      listSearch: listSearchQuery,
      listSearchScope,
      listPeriodFrom,
      listPeriodTo,
      listDesignFrom,
      listDesignTo,
      listCampaignTypeFilter,
      listStatusDraft,
      listStatusOngoing,
      listStatusFinish,
      listBranchFilter,
      listHubLinkFilter: effectiveHubLinkFilter,
      listBudgetMin,
      listBudgetMax,
      listKpiMin,
      listKpiMax,
      listKpiUnitFilter,
      listDiscountFilter,
      lang,
      statusLabel,
    }),
    [
      listSearchQuery,
      listSearchScope,
      listPeriodFrom,
      listPeriodTo,
      listDesignFrom,
      listDesignTo,
      listCampaignTypeFilter,
      listStatusDraft,
      listStatusOngoing,
      listStatusFinish,
      listBranchFilter,
      effectiveHubLinkFilter,
      listBudgetMin,
      listBudgetMax,
      listKpiMin,
      listKpiMax,
      listKpiUnitFilter,
      listDiscountFilter,
      lang,
      statusLabel,
    ]
  )

  const filteredList = React.useMemo(
    () => applyMarketingCampaignListFilters(campaignsSource, hubLinkSets, filterParams),
    [campaignsSource, hubLinkSets, filterParams]
  )

  React.useEffect(() => {
    onFilteredCampaignsChange?.(filteredList)
  }, [filteredList, onFilteredCampaignsChange])

  const listFiltersActive = React.useMemo(
    () =>
      marketingCampaignListFiltersActive({
        listSearchScope,
        listPeriodFrom,
        listPeriodTo,
        listDesignFrom,
        listDesignTo,
        listCampaignTypeFilter,
        listStatusDraft,
        listStatusOngoing,
        listStatusFinish,
        listBranchFilter,
        listHubLinkFilter: effectiveHubLinkFilter,
        listBudgetMin,
        listBudgetMax,
        listKpiMin,
        listKpiMax,
        listKpiUnitFilter,
        listDiscountFilter,
      }),
    [
      listSearchScope,
      listPeriodFrom,
      listPeriodTo,
      listDesignFrom,
      listDesignTo,
      listCampaignTypeFilter,
      listStatusDraft,
      listStatusOngoing,
      listStatusFinish,
      listBranchFilter,
      effectiveHubLinkFilter,
      listBudgetMin,
      listBudgetMax,
      listKpiMin,
      listKpiMax,
      listKpiUnitFilter,
      listDiscountFilter,
    ]
  )

  React.useEffect(() => {
    setListHubLinkFilter(String(defaultHubLinkFilter ?? ""))
  }, [defaultHubLinkFilter])

  const selectedCampaign = React.useMemo(() => {
    const id = value.trim()
    if (!id) return undefined
    return campaignsSource.find((c) => c.id === id)
  }, [campaignsSource, value])

  const emptyLabel =
    emptyOptionLabel ??
    tr("캠페인 미선택", "No campaign", "ไม่เลือกแคมเปญ")

  const runSearch = React.useCallback(async () => {
    const q = listSearchDraft.trim()
    // await reloadData() 전에 검색어가 반드시 반영되도록 동기 플러시 (부모 campaigns prop과 함께 쓸 때 필터가 빈 키워드로 한 번 도는 문제 방지)
    flushSync(() => {
      setListSearchQuery(q)
    })
    await reloadData()
    await Promise.resolve(onRefresh?.())
  }, [listSearchDraft, reloadData, onRefresh])

  return (
    <div className={cn("rounded-xl border bg-card", className)}>
      <div
        className={cn(
          "border-b",
          isCompactToolbar ? "px-2 py-2 sm:px-3" : "flex flex-col gap-3 px-3 py-3 sm:px-4",
        )}
      >
        {!isCompactToolbar && (
          <h3 className="text-sm font-semibold">{tr("캠페인 찾기", "Find campaign", "ค้นหาแคมเปญ")}</h3>
        )}

        <div
          className={cn(
            "flex w-full min-w-0 flex-wrap items-end gap-x-2 gap-y-2 rounded-lg border border-border/70 bg-muted/10 px-2 py-2 sm:px-3",
            isCompactToolbar &&
              "flex-nowrap gap-x-2 gap-y-0 overflow-x-auto overflow-y-visible border-dashed border-border/60 bg-muted/5 px-2 py-2 sm:gap-x-2 sm:px-3 sm:py-2",
          )}
        >
          <div className="flex shrink-0 flex-col gap-0.5">
            <span
              className={cn(
                "font-medium leading-none text-muted-foreground whitespace-nowrap text-[9px]",
                isCompactToolbar && "text-[10px] sm:text-xs",
              )}
            >
              {tr("조회 기간", "Period", "ช่วงวันที่")}
            </span>
            <div className={cn("flex min-w-0 items-center gap-1", isCompactToolbar && "gap-1")}>
              <Input
                type="date"
                title={tr("시작", "From", "เริ่ม")}
                className="h-8 w-[8.65rem] shrink-0 px-1.5 text-xs"
                disabled={disabled}
                value={listPeriodFrom}
                onChange={(e) => setListPeriodFrom(e.target.value)}
              />
              <span className="shrink-0 pb-0.5 text-[10px] text-muted-foreground sm:text-xs">~</span>
              <Input
                type="date"
                title={tr("종료", "To", "ถึง")}
                className="h-8 w-[8.65rem] shrink-0 px-1.5 text-xs"
                disabled={disabled}
                value={listPeriodTo}
                onChange={(e) => setListPeriodTo(e.target.value)}
              />
            </div>
          </div>
          <div
            className={cn(
              "flex min-w-[6.5rem] max-w-[9.5rem] flex-col gap-0.5 sm:min-w-[7.5rem]",
              isCompactToolbar && "w-[7.25rem] max-w-none shrink-0 sm:w-[8rem]",
            )}
          >
            <Label
              className={cn(
                "font-medium leading-none text-muted-foreground text-[9px]",
                isCompactToolbar && "text-[10px] sm:text-xs",
              )}
            >
              {tr("검색 범위", "Search in", "ค้นหาใน")}
            </Label>
            <select
              value={listSearchScope}
              disabled={disabled}
              onChange={(e) => setListSearchScope(e.target.value as CampaignListSearchScope)}
              className={cn(
                "h-8 w-full rounded-md border border-input bg-background px-1.5 text-[11px]",
                isCompactToolbar && "px-2 text-xs sm:text-sm",
              )}
            >
              <option value="all">{tr("전체 필드", "All fields", "ทุกฟิลด์")}</option>
              <option value="topic">{tr("제목만", "Title only", "ชื่ออย่างเดียว")}</option>
              <option value="campaignNo">{tr("캠페인 번호만", "Campaign no. only", "เฉพาะเลขแคมเปญ")}</option>
              <option value="format">{tr("채널/형식만", "Format only", "เฉพาะรูปแบบ")}</option>
              <option value="audience_promo">
                {tr("지점·대상·프로모", "Branch, audience, promo", "สาขา กลุ่มเป้า โปร")}
              </option>
            </select>
          </div>
          <div
            className={cn(
              "flex min-w-[5.5rem] max-w-[9rem] flex-col gap-0.5",
              isCompactToolbar && "w-[6.75rem] max-w-[9rem] shrink-0 sm:w-[7.25rem]",
            )}
          >
            <Label
              className={cn(
                "font-medium leading-none text-muted-foreground text-[9px]",
                isCompactToolbar && "text-[10px] sm:text-xs",
              )}
            >
              {tr("매장", "Store", "สาขา")}
            </Label>
            <select
              value={listBranchFilter || "_all"}
              disabled={disabled || storesLoading}
              onChange={(e) => setListBranchFilter(e.target.value === "_all" ? "" : e.target.value)}
              className={cn(
                "h-8 w-full rounded-md border border-input bg-background px-1.5 text-[11px] disabled:opacity-60",
                isCompactToolbar && "px-2 text-xs sm:text-sm",
              )}
            >
              <option value="_all">{tr("전체", "All", "ทั้งหมด")}</option>
              <option value="_allStoresPlan">{tr("전체 매장(기획)만", "All stores (plan) only", "เฉพาะทุกสาขา (แผน)")}</option>
              {stores.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </div>
          <div
            className={cn(
              "relative min-w-[8rem] flex-1 basis-[10rem]",
              isCompactToolbar && "min-w-[9rem] flex-1 basis-0",
            )}
          >
            <Label className="sr-only">{tr("검색", "Search", "ค้นหา")}</Label>
            <Search className="pointer-events-none absolute left-2 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground sm:left-2.5" />
            <Input
              value={listSearchDraft}
              disabled={disabled}
              onChange={(e) => setListSearchDraft(e.target.value)}
              placeholder={tr("키워드 입력 후 검색", "Enter keywords, then Search", "พิมพ์คำค้น แล้วกดค้นหา")}
              className={cn("h-8 min-w-0 pl-8 text-xs", isCompactToolbar && "pl-9 text-sm sm:pl-10")}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  void runSearch()
                }
              }}
            />
          </div>
          <Button
            type="button"
            variant="default"
            size="sm"
            className={cn(
              "h-8 shrink-0 gap-1 px-2.5 text-xs",
              isCompactToolbar && "shrink-0 px-2.5 text-xs sm:px-3",
            )}
            disabled={disabled || dataLoading}
            onClick={() => void runSearch()}
          >
            {dataLoading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Search className="h-3.5 w-3.5" />}
            {t("search")}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className={cn(
              "h-8 shrink-0 gap-1 px-2.5 text-xs",
              isCompactToolbar && "shrink-0 px-2.5 text-xs sm:px-3",
            )}
            disabled={disabled}
            onClick={() => setListFiltersOpen((o) => !o)}
          >
            <Filter className="h-3.5 w-3.5" />
            {tr("필터", "Filters", "ตัวกรอง")}
            {listFiltersOpen ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
          </Button>
          {isCompactToolbar && compactToolbarEnd != null ? (
            <div className="ms-auto flex shrink-0 flex-wrap items-center gap-2">{compactToolbarEnd}</div>
          ) : null}
        </div>

        {listFiltersOpen && (
          <div className="space-y-3 rounded-lg border border-dashed bg-muted/20 px-3 py-3">
            <div className="space-y-1.5 border-b border-border/60 pb-3">
              <p className="text-xs font-medium text-foreground">{t("marketingCampaignFinderPrepPeriodLabel")}</p>
              <p className="text-[10px] leading-relaxed text-muted-foreground">{t("marketingCampaignFinderPrepPeriodHint")}</p>
              <div className="flex flex-wrap gap-2">
                <div className="min-w-[9rem] flex-1 space-y-1">
                  <Label className="text-[10px] text-muted-foreground">{tr("시작", "From", "เริ่ม")}</Label>
                  <Input
                    type="date"
                    className="h-9"
                    disabled={disabled}
                    value={listDesignFrom}
                    onChange={(e) => setListDesignFrom(e.target.value)}
                  />
                </div>
                <div className="min-w-[9rem] flex-1 space-y-1">
                  <Label className="text-[10px] text-muted-foreground">{tr("종료", "To", "ถึง")}</Label>
                  <Input
                    type="date"
                    className="h-9"
                    disabled={disabled}
                    value={listDesignTo}
                    onChange={(e) => setListDesignTo(e.target.value)}
                  />
                </div>
              </div>
              <p className="text-[10px] leading-relaxed text-muted-foreground">
                {t("marketingCampaignFinderDesignOverlapHint")}
              </p>
            </div>

            <div
              className={cn(
                "grid gap-3 sm:grid-cols-2 lg:items-end",
                hideHubLinkFilter ? "lg:grid-cols-1" : "lg:grid-cols-2",
              )}
            >
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{tr("캠페인 유형", "Campaign type", "ประเภทแคมเปญ")}</Label>
                <select
                  value={listCampaignTypeFilter || "_all"}
                  disabled={disabled}
                  onChange={(e) => setListCampaignTypeFilter(e.target.value === "_all" ? "" : e.target.value)}
                  className="h-9 w-full rounded-md border border-input bg-background px-2 text-sm"
                >
                  <option value="_all">{tr("전체", "All", "ทั้งหมด")}</option>
                  {CAMPAIGN_TYPE_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {lang === "en" ? o.en : lang === "th" ? o.th : o.ko}
                    </option>
                  ))}
                </select>
              </div>
              {!hideHubLinkFilter && (
                <div className="space-y-1.5">
                  <Label className="text-xs text-muted-foreground">{t("marketingCampaignListHubLinkLabel")}</Label>
                  <select
                    value={listHubLinkFilter || "_all"}
                    disabled={disabled}
                    onChange={(e) => setListHubLinkFilter(e.target.value === "_all" ? "" : e.target.value)}
                    className="h-9 w-full rounded-md border border-input bg-background px-2 text-sm"
                  >
                    <option value="_all">{tr("전체", "All", "ทั้งหมด")}</option>
                    <option value="collab">{t("marketingCampaignListHubLinkCollab")}</option>
                    <option value="promo_set">{t("marketingCampaignListHubLinkPromoSet")}</option>
                    <option value="ads_roas">{t("marketingCampaignListHubLinkAdsRoas")}</option>
                    <option value="influencer">{t("marketingCampaignListHubLinkInfluencer")}</option>
                    <option value="materials">{t("marketingCampaignListHubLinkMaterials")}</option>
                  </select>
                </div>
              )}
            </div>

            <div className="flex flex-wrap gap-x-4 gap-y-2 border-t border-border/60 pt-3">
              <span className="w-full text-xs font-medium text-foreground sm:w-auto">{tr("상태", "Status", "สถานะ")}</span>
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <Checkbox
                  checked={listStatusDraft}
                  disabled={disabled}
                  onCheckedChange={(v) => setListStatusDraft(v === true)}
                />
                {statusLabel("draft")}
              </label>
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <Checkbox
                  checked={listStatusOngoing}
                  disabled={disabled}
                  onCheckedChange={(v) => setListStatusOngoing(v === true)}
                />
                {statusLabel("ongoing")}
              </label>
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <Checkbox
                  checked={listStatusFinish}
                  disabled={disabled}
                  onCheckedChange={(v) => setListStatusFinish(v === true)}
                />
                {statusLabel("finish")}
              </label>
            </div>

            <div className="grid gap-3 border-t border-border/60 pt-3 sm:grid-cols-2 lg:grid-cols-4 lg:items-end">
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{tr("예산 최소 (฿)", "Budget min (฿)", "งบขั้นต่ำ (฿)")}</Label>
                <Input
                  className="h-9"
                  inputMode="decimal"
                  disabled={disabled}
                  value={listBudgetMin}
                  onChange={(e) => setListBudgetMin(e.target.value)}
                  placeholder="0"
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{tr("예산 최대 (฿)", "Budget max (฿)", "งบสูงสุด (฿)")}</Label>
                <Input
                  className="h-9"
                  inputMode="decimal"
                  disabled={disabled}
                  value={listBudgetMax}
                  onChange={(e) => setListBudgetMax(e.target.value)}
                  placeholder="—"
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">{tr("KPI 목표 최소", "KPI target min", "KPI ขั้นต่ำ")}</Label>
                <Input
                  className="h-9"
                  inputMode="decimal"
                  disabled={disabled}
