        )}
        {!dataLoading && allowEmpty && (
          <button
            type="button"
            disabled={disabled}
            onClick={() => onChange("")}
            className={cn(
              "flex w-full flex-col items-start gap-0.5 px-3 py-2.5 text-left text-sm transition-colors hover:bg-muted/50",
              !value.trim() && "bg-muted/40"
