                                  {ev.shortLabel}
                                </div>
                              ))}
                              {overflow && (
                                <button
                                  type="button"
                                  onClick={() => openDay(ymd)}
                                  className="w-full rounded bg-muted/80 px-1 py-0.5 text-[10px] font-medium text-primary hover:underline"
                                >
                                  {t("marketingCalMoreExtra").replace("{n}", String(dayEvents.length - 3))}
