'use client'
import { appAlert, appConfirm } from "@/lib/app-message"

import { useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import type { Order } from '@/lib/pos-types'
import type { PosDeliveryApp } from '@/lib/api-client'
import { markPosOrderItemServed, updatePosOrderStatus } from '@/lib/api-client'
import { posOrderHasServerId } from '@/lib/pos-order-server-id'
import { cn } from '@/lib/utils'
import { Check, CheckCircle, Clock, XCircle } from 'lucide-react'
import { useLang } from '@/lib/lang-context'
import { formatPosOrderMonthDayTime } from '@/lib/pos-datetime-locale'

export interface DeliveryOrderPanelProps {
  orderLabel: string
  order: Order | null
  deliveryApps?: PosDeliveryApp[]
  onPackaged?: () => void
  onPay?: () => void
  /** 주문 취소 시 */
  onCancel?: () => void
  onClose?: () => void
  t?: (key: string) => string
}

function getDeliveryPlatformAndOrderNo(order: Order, deliveryApps?: PosDeliveryApp[]): { platform: string; orderNo: string } {
  const text = [order.customerName ?? '', order.orderNo ?? '', order.memo ?? ''].filter(Boolean).join(' ')
  const raw = text.toLowerCase()
  let platform = ''
  if (deliveryApps?.length) {
    for (const app of deliveryApps) {
      const keywords = app.matchKeywords || []
      if (keywords.some((k) => raw.includes(String(k).toLowerCase()))) {
        platform = app.name
        break
      }
    }
  }
  if (!platform) {
    if (raw.includes('grab') || raw.includes('그랩')) platform = 'Grab'
    else if (raw.includes('lineman') || raw.includes('line man') || raw.includes('라인맨')) platform = 'Line Man'
    else if (raw.includes('shopee') || raw.includes('쇼피')) platform = 'Shopee'
  }
  const hashMatch = text.match(/#\s*([A-Za-z0-9-]+)/)
  const orderNo = hashMatch?.[1] ?? order.orderNo ?? ''
  return { platform, orderNo }
}

export function DeliveryOrderPanel({
  orderLabel,
  order,
  deliveryApps = [],
  onPackaged,
  onPay,
  onCancel,
  onClose,
  t = (k) => k,
}: DeliveryOrderPanelProps) {
  const { lang } = useLang()
  const isCompleted = order?.status === 'completed'
  const [itemPackaged, setItemPackaged] = useState<Record<string, boolean>>({})
  const [expandedItemId, setExpandedItemId] = useState<string | null>(null)
  const [savingItemId, setSavingItemId] = useState<string | null>(null)

  useEffect(() => {
    if (!order?.items?.length) {
      setItemPackaged({})
      setExpandedItemId(null)
    } else {
      setItemPackaged((prev) => {
        const next = { ...prev }
        order.items.forEach((it) => {
          next[it.id] = Boolean(it.servedAt)
        })
        return next
      })
    }
  }, [order?.id, order?.items])

  const toggleItemPackaged = async (itemId: string) => {
    if (!order) return
    const id = Number(order.id)
    if (Number.isNaN(id)) return
    if (!posOrderHasServerId(order.id)) {
      const msg = t('posServedNeedsOrderId')
      await appAlert(
        msg && msg !== 'posServedNeedsOrderId'
          ? msg
          : '이 주문은 아직 서버에 전송되지 않았습니다. 전송이 끝난 뒤 포장 완료를 눌러 주세요.'
      )
      return
    }
    const nextPackaged = !itemPackaged[itemId]
    setSavingItemId(itemId)
    try {
      const res = await markPosOrderItemServed({
        id,
        itemId,
        served: nextPackaged,
      })
      if (!res.success) {
        await appAlert(res.message || (t('processFail') || '처리 실패'))
        return
      }
      setItemPackaged((prev) => ({ ...prev, [itemId]: nextPackaged }))
      onPackaged?.()
    } catch (e) {
      await appAlert(String(e))
    } finally {
      setSavingItemId(null)
    }
  }

  const packagedCount = order?.items?.filter((it) => itemPackaged[it.id]).length ?? 0
  const allPackaged = order?.items?.length ? packagedCount >= order.items.length : false

  const canCancel = order && !['completed', 'cancelled'].includes(order.status ?? '')
  const [cancelling, setCancelling] = useState(false)

  const handleCancelOrder = async () => {
    if (!order || !await appConfirm(t('posCancelConfirm') || '이 주문을 취소하시겠습니까?')) return
    setCancelling(true)
    try {
      await updatePosOrderStatus({ id: Number(order.id), status: 'cancelled' })
      onCancel?.()
      onClose?.()
    } catch (e) {
      await appAlert(String(e))
    } finally {
      setCancelling(false)
    }
  }

  const handlePackComplete = async () => {
    if (!order || order.status === 'completed' || order.status === 'ready') return
    const id = Number(order.id)
    if (Number.isNaN(id)) return
    try {
      await updatePosOrderStatus({ id, status: 'ready' })
      onPackaged?.()
    } catch (e) {
      console.error('updatePosOrderStatus:', e)
    }
  }

  return (
    <div className="h-full flex flex-col border-l border-border bg-card">
      <div className="px-3 py-3 border-b flex items-center justify-between">
        <h3 className="text-sm font-semibold truncate">
          {orderLabel} {t('posOrderTypeDelivery') || '배달'}
        </h3>
        <Button variant="outline" size="sm" className="h-7 text-xs" onClick={onClose}>
          {t('posBack') || '뒤로가기'}
        </Button>
      </div>

      {!order ? (
        <div className="p-3 text-sm text-muted-foreground">{t('posNoOrder') || '주문이 없습니다.'}</div>
      ) : (
        <div className="flex-1 min-h-0 p-3 flex flex-col gap-3">
          <div className="flex items-center gap-2 text-muted-foreground text-sm">
            <Clock className="w-4 h-4 shrink-0" />
            <span>{t('posOrderTime') || '주문 시각'}: {formatPosOrderMonthDayTime(order.createdAt, lang)}</span>
          </div>

          {isCompleted ? (
            <>
              <div className="flex items-center gap-2 text-emerald-600 dark:text-emerald-400 text-sm rounded-lg bg-muted/50 p-3">
                <CheckCircle className="w-4 h-4 shrink-0" />
                <span>{t('posPaymentComplete') || '결제 완료'}</span>
              </div>
              <Button className="h-11 text-base font-semibold w-full" onClick={() => onPay?.()}>
                {t('posTablePayInStore') || '매장 결제'}
              </Button>
              {canCancel && (
                <Button variant="outline" size="sm" className="w-full text-destructive border-destructive/50 hover:bg-destructive/10" disabled={cancelling} onClick={handleCancelOrder}>
                  <XCircle className="w-4 h-4 mr-1" />
                  {t('posOrderCancel') || '주문 취소'}
                </Button>
              )}
            </>
          ) : (
            <>
              <ScrollArea className="flex-1 max-h-[320px] rounded-md border">
                <ul className="p-2 space-y-2">
                  {order.items.map((item) => {
                    const packaged = itemPackaged[item.id]
                    const optMatch = item.name.match(/^(.+?)\s*\(([^)]+)\)\s*$/)
                    const mainName = optMatch ? optMatch[1].trim() : item.name
                    const optionPart = optMatch ? optMatch[2].trim() : null
                    return (
                      <li
                        key={item.id}
                        className={cn(
                          'grid grid-cols-[1fr_auto] items-start gap-2 py-2 px-2 rounded-lg border border-border/50',
                          packaged && 'bg-emerald-50 dark:bg-emerald-950/30 border-emerald-200 dark:border-emerald-800'
                        )}
                      >
                        <div className="min-w-0 flex-1">
                          <button
                            type="button"
                            className="text-sm font-medium truncate text-left w-full hover:underline"
                            onClick={() => setExpandedItemId((prev) => (prev === item.id ? null : item.id))}
                            title={item.name}
                          >
                            {mainName}
                          </button>
                          <p className="text-xs text-muted-foreground tabular-nums">
                            {optionPart && <span className="mr-1">{optionPart}</span>}
                            x{item.quantity} · {(item.price * item.quantity).toLocaleString()} ฿
                          </p>
                          {expandedItemId === item.id && (
                            <p className="text-xs text-muted-foreground mt-1 whitespace-normal break-words">
                              {item.name}
                            </p>
                          )}
                        </div>
                        <Button
                          size="sm"
                          variant={packaged ? 'default' : 'outline'}
                          className="shrink-0 h-8 min-w-[80px] self-center"
                          onClick={() => { void toggleItemPackaged(item.id) }}
                          disabled={savingItemId === item.id}
                          aria-label={
                            packaged
                              ? (t('cancel') || '취소')
                              : (t('posDeliveryPackagingComplete') || '포장 완료')
                          }
                        >
                          {packaged ? <Check className="w-4 h-4 mr-1" /> : <CheckCircle className="w-4 h-4 mr-1" />}
                          {packaged ? (t('cancel') || '취소') : (t('posDeliveryPackagingComplete') || '포장 완료')}
                        </Button>
                      </li>
                    )
                  })}
                </ul>
              </ScrollArea>

              <div className="flex justify-between text-sm font-medium">
                <span>{t('posInputTotal') || '합계'}</span>
                <span className="tabular-nums">{order.total.toLocaleString()} ฿</span>
              </div>

              <Button onClick={handlePackComplete} className="w-full h-11 text-base font-semibold" disabled={!allPackaged}>
                <CheckCircle className="w-4 h-4 mr-2" />
                {allPackaged
                  ? (t('posDeliveryPackagingComplete') || '포장 완료')
                  : `${t('posDeliveryPackagingComplete') || '포장 완료'} (${packagedCount}/${order.items.length})`}
              </Button>

              <Button className="h-11 text-base font-semibold w-full" onClick={() => onPay?.()}>
                {t('posTablePayInStore') || '매장 결제'}
              </Button>
              {canCancel && (
                <Button variant="outline" size="sm" className="w-full text-destructive border-destructive/50 hover:bg-destructive/10" disabled={cancelling} onClick={handleCancelOrder}>
                  <XCircle className="w-4 h-4 mr-1" />
                  {t('posOrderCancel') || '주문 취소'}
                </Button>
              )}
            </>
          )}
        </div>
      )}

    </div>
  )
}

'use client'
import { appAlert } from "@/lib/app-message"

import * as React from 'react'
import { ChevronDown, ChevronUp, Plus, RotateCw, Save, Truck } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { useAuth } from '@/lib/auth-context'
import { useLang } from '@/lib/lang-context'
import { useT } from '@/lib/i18n'
import {
  getPosDeliveryApps,
  savePosDeliveryApps,
  useStoreList,
  type PosDeliveryApp,
} from '@/lib/api-client'
import { isOfficeRole } from '@/lib/permissions'
import { cn } from '@/lib/utils'

const ACCENT_COLORS = [
  { value: 'lime', label: 'Lime (Grab)' },
  { value: 'sky', label: 'Sky (Line Man)' },
  { value: 'amber', label: 'Amber (Shopee)' },
  { value: 'slate', label: 'Slate (기타)' },
] as const

export function PosDeliveryAppsContent() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const { stores } = useStoreList()

  const [storeCode, setStoreCode] = React.useState('')
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [items, setItems] = React.useState<PosDeliveryApp[]>([])
  const [includeDisabled, setIncludeDisabled] = React.useState(true)

  const canSearchAll = isOfficeRole(auth?.role || '')
  const effectiveStore = canSearchAll && storeCode ? storeCode : auth?.store || ''

  const loadData = React.useCallback(() => {
    setLoading(true)
    getPosDeliveryApps({ storeCode: canSearchAll && storeCode ? storeCode : undefined, includeDisabled })
      .then((list) => setItems(Array.isArray(list) ? list : []))
      .catch(() => setItems([]))
      .finally(() => setLoading(false))
  }, [canSearchAll, storeCode, includeDisabled])

  React.useEffect(() => {
    if (canSearchAll && stores.length && !storeCode) {
      setStoreCode(stores[0])
    } else if (!canSearchAll && auth?.store) {
      setStoreCode(auth.store)
    }
  }, [canSearchAll, stores, auth?.store, storeCode])

  React.useEffect(() => {
    loadData()
  }, [loadData])

  const updateItem = (index: number, patch: Partial<PosDeliveryApp>) => {
    setItems((prev) => {
      const next = [...prev]
      next[index] = { ...next[index], ...patch }
      return next
    })
  }

  const moveItem = (index: number, dir: 'up' | 'down') => {
    const to = dir === 'up' ? index - 1 : index + 1
    if (to < 0 || to >= items.length) return
    setItems((prev) => {
      const next = [...prev]
      const tmp = next[index]
      next[index] = next[to]
      next[to] = tmp
      return next.map((it, i) => ({ ...it, displayOrder: i }))
    })
  }

  const addItem = () => {
    const maxOrder = items.length > 0 ? Math.max(...items.map((i) => i.displayOrder), 0) + 1 : 0
    setItems((prev) => [
      ...prev,
      {
        id: 0,
        code: '',
        name: '',
        matchKeywords: [],
        displayOrder: maxOrder,
        enabled: true,
        dineOutEnabled: true,
        accentColor: 'slate',
        storeCode: null,
      },
    ])
  }

  const removeItem = (index: number) => {
    const it = items[index]
    if (it.id > 0) {
      updateItem(index, { enabled: false })
    } else {
      setItems((prev) => prev.filter((_, i) => i !== index))
    }
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const payload = items
        .filter((i) => i.code.trim())
        .map((i, idx) => ({
          id: i.id,
          code: i.code.trim(),
          name: i.name.trim() || i.code.trim(),
          matchKeywords: i.matchKeywords?.length ? i.matchKeywords : [i.code.toLowerCase()],
          displayOrder: idx,
          enabled: i.enabled,
          dineOutEnabled: i.dineOutEnabled,
          accentColor: i.accentColor || null,
        }))
      const res = await savePosDeliveryApps({ storeCode: canSearchAll && storeCode ? storeCode : undefined, items: payload })
      if (res.success) {
        await appAlert(t('itemsAlertSaved') || '저장되었습니다.')
        loadData()
      } else {
        await appAlert(res.message || t('msg_save_fail_detail'))
      }
    } catch (e) {
      await appAlert(String(e))
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        {canSearchAll && (
          <Select value={storeCode || '__global__'} onValueChange={(v) => setStoreCode(v === '__global__' ? '' : v)}>
            <SelectTrigger className="h-10 w-40">
              <SelectValue placeholder={t('store') || '매장'} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__global__">{t('posDeliveryAppsGlobal') || '전역'}</SelectItem>
              {stores.map((s) => (
                <SelectItem key={s} value={s}>
                  {s}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
        <label className="flex items-center gap-2 text-sm">
          <input
            type="checkbox"
            checked={includeDisabled}
            onChange={(e) => setIncludeDisabled(e.target.checked)}
          />
          {t('posDeliveryAppsIncludeDisabled') || '비활성 포함'}
        </label>
        <Button variant="outline" size="sm" className="h-10 gap-1.5" onClick={loadData} disabled={loading}>
          <RotateCw className={cn('h-4 w-4', loading && 'animate-spin')} />
          {t('posRefresh') || '새로고침'}
        </Button>
      </div>

      <div className="rounded-xl border bg-card p-4 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 text-sm font-semibold">
            <Truck className="h-4 w-4" />
            {t('posScreenConfigTabDelivery') || '배달앱 관리'}
          </div>
          <Button size="sm" variant="outline" onClick={addItem} className="gap-1">
            <Plus className="h-4 w-4" />
            {t('posDeliveryAppsAdd') || '추가'}
          </Button>
        </div>

        {loading ? (
          <p className="text-sm text-muted-foreground py-4">{t('loading') || '불러오는 중...'}</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm border-collapse">
              <thead>
                <tr className="border-b">
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsOrder') || '순서'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsCode') || '코드'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsName') || '표시명'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsKeywords') || '인식 키워드'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsAccent') || '배지색'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsEnabled') || '활성'}</th>
                  <th className="text-left p-2 font-medium">{t('posDeliveryAppsDineOut') || 'Dine out'}</th>
                  <th className="text-left p-2 w-16"></th>
                </tr>
              </thead>
              <tbody>
                {items.map((it, idx) => (
                  <tr key={it.id || `new-${idx}`} className={cn('border-b', !it.enabled && 'opacity-60')}>
                    <td className="p-2">
                      <div className="flex gap-1">
                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => moveItem(idx, 'up')} disabled={idx === 0}>
                          <ChevronUp className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => moveItem(idx, 'down')} disabled={idx === items.length - 1}>
                          <ChevronDown className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                    <td className="p-2">
                      <Input
                        className="h-8 w-24 font-mono text-xs"
                        value={it.code}
                        onChange={(e) => updateItem(idx, { code: e.target.value })}
                        placeholder="grab"
                      />
                    </td>
                    <td className="p-2">
                      <Input
                        className="h-8 w-28"
                        value={it.name}
                        onChange={(e) => updateItem(idx, { name: e.target.value })}
                        placeholder="Grab"
                      />
                    </td>
                    <td className="p-2">
                      <Input
                        className="h-8 min-w-[120px]"
                        value={(it.matchKeywords || []).join(', ')}
                        onChange={(e) =>
                          updateItem(
                            idx,
                            { matchKeywords: e.target.value.split(',').map((k) => k.trim()).filter(Boolean) }
                          )
                        }
                        placeholder="grab, 그랩"
                      />
                    </td>
                    <td className="p-2">
                      <Select
                        value={it.accentColor || 'slate'}
                        onValueChange={(v) => updateItem(idx, { accentColor: v })}
                      >
                        <SelectTrigger className="h-8 w-28">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {ACCENT_COLORS.map((c) => (
                            <SelectItem key={c.value} value={c.value}>
                              {c.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </td>
                    <td className="p-2">
                      <input
                        type="checkbox"
                        checked={it.enabled}
                        onChange={(e) => updateItem(idx, { enabled: e.target.checked })}
                        className="h-4 w-4"
                      />
                    </td>
                    <td className="p-2">
                      <input
                        type="checkbox"
                        checked={it.dineOutEnabled}
                        onChange={(e) => updateItem(idx, { dineOutEnabled: e.target.checked })}
                        className="h-4 w-4"
                      />
                    </td>
                    <td className="p-2">
                      <Button variant="ghost" size="sm" className="h-7 text-destructive" onClick={() => removeItem(idx)}>
                        {t('delete') || '삭제'}
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <p className="text-xs text-muted-foreground">
          {t('posDeliveryAppsGuide') || '인식 키워드: 주문 라벨(customerName, orderNo, memo)에 포함되면 해당 배달앱으로 인식됩니다. Dine out: 테이블 결제 시 "배달앱 결제" 옵션에 표시됩니다.'}
        </p>

        <Button className="w-full" onClick={handleSave} disabled={saving}>
          <Save className="mr-2 h-4 w-4" />
          {saving ? '...' : t('itemsBtnSave') || '저장'}
        </Button>
      </div>
    </div>
  )
}

'use client'
import { appAlert, appConfirm } from "@/lib/app-message"

import * as React from 'react'
import { CreditCard, RotateCw, Save, Plus, Trash2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { useAuth } from '@/lib/auth-context'
import { useLang } from '@/lib/lang-context'
import { useT } from '@/lib/i18n'
import {
  getPosPaymentMethodItems,
  savePosPaymentMethodItem,
  deletePosPaymentMethodItem,
  useStoreList,
  type PosPaymentMethodItem,
} from '@/lib/api-client'
import { isOfficeRole } from '@/lib/permissions'
import { cn } from '@/lib/utils'

function isSyntheticPaymentMethodId(id: string | undefined): boolean {
  return Boolean(id?.startsWith('syn:'))
}

const CATEGORIES = [
  { value: 'card', label: '카드' },
  { value: 'qr', label: 'QR/모바일' },
  { value: 'delivery', label: '배달앱' },
  { value: 'other', label: '기타' },
] as const

export function PosPaymentSettingsContent() {
  const { auth } = useAuth()
  const { lang } = useLang()
  const t = useT(lang)
  const { stores } = useStoreList()

  const [storeCode, setStoreCode] = React.useState('')
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [deleting, setDeleting] = React.useState(false)
  const [items, setItems] = React.useState<PosPaymentMethodItem[]>([])
  const [categoryFilter, setCategoryFilter] = React.useState<string>('__all__')
  const [selected, setSelected] = React.useState<PosPaymentMethodItem | null>(null)
  const [editName, setEditName] = React.useState('')
  const [editHidden, setEditHidden] = React.useState(false)
  const [editCategory, setEditCategory] = React.useState<PosPaymentMethodItem['category']>('card')

  const canSearchAll = isOfficeRole(auth?.role || '')
  const effectiveStore = canSearchAll && storeCode ? storeCode : auth?.store || ''

  const loadData = React.useCallback(async () => {
    if (!effectiveStore) return []
    setLoading(true)
    try {
      const list = await getPosPaymentMethodItems({ storeCode: effectiveStore }) || []
      setItems(list)
      if (selected && !list.some((i) => i.id === selected.id)) {
        setSelected(null)
        setEditName('')
        setEditHidden(false)
      }
      return list
    } catch {
      setItems([])
      return []
    } finally {
      setLoading(false)
    }
  }, [effectiveStore, selected?.id])

  React.useEffect(() => {
    if (canSearchAll && stores.length && !storeCode) {
      setStoreCode(stores[0])
    } else if (!canSearchAll && auth?.store) {
      setStoreCode(auth.store)
    }
  }, [canSearchAll, stores, auth?.store, storeCode])

  React.useEffect(() => {
    loadData()
  }, [loadData])

  React.useEffect(() => {
    if (selected) {
      setEditName(selected.name)
      setEditHidden(selected.hidden)
      setEditCategory(selected.category)
    } else {
      setEditName('')
      setEditHidden(false)
      setEditCategory('card')
    }
  }, [selected])

  const filteredItems = React.useMemo(() => {
    if (!categoryFilter || categoryFilter === '__all__') return items
    return items.filter((i) => i.category === categoryFilter)
  }, [items, categoryFilter])

  const handleNew = () => {
    setSelected(null)
    setEditName('')
    setEditHidden(false)
    setEditCategory('card')
  }

  const handleSave = async () => {
    const name = editName.trim()
    if (!name) {
      await appAlert(t('posPaymentMethodNameRequired') || '이름을 입력하세요.')
      return
    }
    if (!effectiveStore) return
    setSaving(true)
    try {
      const res = await savePosPaymentMethodItem({
        id: selected?.id,
        storeCode: effectiveStore,
        category: editCategory,
        name,
        hidden: editHidden,
      })
      if (res.success) {
        await appAlert(t('itemsAlertSaved') || '저장되었습니다.')
        const list = await loadData()
        if (!selected && res.id) {
          const next = list.find((i) => i.id === res.id)
          if (next) setSelected(next)
        }
      } else {
        await appAlert(res.message || t('msg_save_fail_detail'))
      }
    } catch (e) {
      await appAlert(String(e))
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async () => {
    if (!selected) return
    if (!await appConfirm(t('posPaymentMethodDeleteConfirm') || `"${selected.name}" 항목을 삭제하시겠습니까?`)) return
    setDeleting(true)
    try {
      const res = await deletePosPaymentMethodItem({ id: selected.id })
      if (res.success) {
        setSelected(null)
        setEditName('')
        await loadData()
      } else {
        await appAlert(res.message || t('msg_save_fail_detail'))
      }
    } catch (e) {
      await appAlert(String(e))
    } finally {
      setDeleting(false)
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        <Select value={storeCode} onValueChange={setStoreCode}>
          <SelectTrigger className="h-10 w-40">
            <SelectValue placeholder={t('store') || '매장'} />
          </SelectTrigger>
          <SelectContent>
            {stores.map((s) => (
              <SelectItem key={s} value={s}>
                {s}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button variant="outline" size="sm" className="h-10 gap-1.5" onClick={loadData} disabled={loading}>
          <RotateCw className={cn('h-4 w-4', loading && 'animate-spin')} />
          {t('posRefresh') || '새로고침'}
        </Button>
      </div>

      <div className="rounded-xl border bg-card p-4">
        <div className="flex items-center gap-2 text-sm font-semibold mb-4">
          <CreditCard className="h-4 w-4" />
          {t('posScreenConfigTabPayment') || '결제 관리'} — 카드수기입력 항목관리
        </div>

        {loading ? (
          <p className="text-sm text-muted-foreground py-4">{t('loading') || '불러오는 중...'}</p>
        ) : (
          <div className="flex gap-6 flex-col sm:flex-row">
            <div className="flex-1 min-w-0 sm:max-w-xs">
              <div className="flex gap-2 mb-2">
                <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                  <SelectTrigger className="h-9 flex-1">
                    <SelectValue placeholder={t('posPaymentCategoryAll') || '전체'} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__all__">{t('posPaymentCategoryAll') || '전체'}</SelectItem>
                    {CATEGORIES.map((c) => (
                      <SelectItem key={c.value} value={c.value}>
                        {c.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="border rounded-lg overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50">
                    <tr>
                      <th className="text-left px-2 py-2 w-10">#</th>
                      <th className="text-left px-2 py-2 w-20">{t('posPaymentMethodCategory') || '분류'}</th>
                      <th className="text-left px-2 py-2">{t('name') || '이름'}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredItems.length === 0 ? (
                      <tr>
                        <td colSpan={3} className="px-3 py-6 text-center text-sm text-muted-foreground">
                          {items.length === 0 ? (
                            <span>
                              {t('posPaymentMethodListEmptyAll') ||
                                '등록된 항목이 없습니다. API/DB 오류이거나 pos_payment_method_items 테이블이 없을 수 있습니다. Supabase에서 vercel-app/scripts/pos_payment_method_items.sql 실행 후 새로고침해 보세요.'}
                            </span>
                          ) : (
                            <span>
                              {t('posPaymentMethodListEmptyCategory') ||
                                '이 분류에 해당하는 항목이 없습니다. 분류를「전체」로 바꾸거나 오른쪽에서 신규로 추가하세요.'}
                            </span>
                          )}
                        </td>
                      </tr>
                    ) : (
                      filteredItems.map((item, idx) => (
                        <tr
                          key={item.id}
                          className={cn(
                            'border-t cursor-pointer hover:bg-muted/30',
                            selected?.id === item.id && 'bg-primary/10'
                          )}
                          onClick={() => setSelected(item)}
                        >
                          <td className="px-2 py-1.5 text-muted-foreground">{idx + 1}</td>
                          <td className="px-2 py-1.5 text-muted-foreground">
                            {CATEGORIES.find((c) => c.value === item.category)?.label ?? item.category}
                          </td>
                          <td className="px-2 py-1.5">
                            {item.name}
                            {isSyntheticPaymentMethodId(item.id) && (
                              <span className="ml-1 text-xs text-muted-foreground">
                                ({t('posPaymentMethodDefaultBadge') || '기본'})
                              </span>
                            )}
                            {item.hidden && (
                              <span className="ml-1 text-xs text-muted-foreground">(숨김)</span>
                            )}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            <div className="flex-1 space-y-4 min-w-0">
              <div>
                <label className="text-sm font-medium">{t('name') || '이름'}</label>
                <Input
                  className="mt-1"
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  placeholder="Visa, Master, Grab..."
                />
              </div>
              <div>
                <label className="text-sm font-medium">{t('posPaymentMethodCategory') || '분류'}</label>
                <Select value={editCategory} onValueChange={(v) => setEditCategory(v as PosPaymentMethodItem['category'])}>
                  <SelectTrigger className="mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CATEGORIES.map((c) => (
                      <SelectItem key={c.value} value={c.value}>
                        {c.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-sm font-medium">{t('posPaymentMethodHidden') || '숨김'}</label>
                <Select value={editHidden ? 'yes' : 'no'} onValueChange={(v) => setEditHidden(v === 'yes')}>
                  <SelectTrigger className="mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="yes">{t('yes') || '예'}</SelectItem>
                    <SelectItem value="no">{t('no') || '아니오'}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex flex-wrap gap-2">
                <Button variant="outline" onClick={handleNew} className="gap-1.5">
                  <Plus className="h-4 w-4" />
                  {t('posPaymentMethodNew') || '신규'}
                </Button>
                <Button onClick={handleSave} disabled={saving || !effectiveStore} className="gap-1.5">
                  <Save className="h-4 w-4" />
                  {saving ? '...' : t('itemsBtnSave') || '저장'}
                </Button>
                {selected && !isSyntheticPaymentMethodId(selected.id) && (
                  <Button
                    variant="outline"
                    className="gap-1.5 text-destructive hover:text-destructive"
                    onClick={handleDelete}
                    disabled={deleting}
                  >
                    <Trash2 className="h-4 w-4" />
                    {deleting ? '...' : t('delete') || '삭제'}
                  </Button>
                )}
              </div>
              <p className="text-xs text-muted-foreground">
                {t('posPaymentSettingsGuide') ||
                  'POS 결제 화면「기타」세부(QR 분류)와 결산 카드·QR·배달앱 breakdown에 연동됩니다. (기본)은 DB에 행이 없을 때 결산과 같은 기본 목록입니다. 저장하면 매장 항목이 DB에 추가됩니다.'}
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'
import { appAlert } from "@/lib/app-message"

import { useEffect, useRef } from 'react'
import { getPosPrinterSettings } from '@/lib/api-client'
import { parsePosOrderMemo } from '@/lib/pos-tax-invoice'
import { escapeHtml, formatBahtNum } from '@/lib/utils'
import { translatePosMenuLineForReceipt, translateReceiptTableDisplayName } from '@/lib/pos-print-translate'
import type { PosMenu } from '@/lib/api-client'
import { useLang } from '@/lib/lang-context'
import { formatPosDateTimeMedium } from '@/lib/pos-datetime-locale'
import {
  buildKitchenSlipDocumentHtml,
  resolveKitchenSlipDesign,
} from '@/lib/pos-kitchen-slip-html'
import { formatPosReceiptOrderNoDisplay, resolvePosReceiptOrderNoRaw } from '@/lib/pos-delivery-platform'
import { posReceiptItemSkuForBarcode } from '@/lib/pos-receipt-barcode'
import { buildKitchenSlipGroupOpts, buildKitchenSlipGroups } from '@/lib/pos-kitchen-slip-routing'
import { printHtmlInHiddenIframe } from '@/lib/print-html-iframe'
import { POS_THERMAL_RECEIPT_WIDTH_MM, posThermalReceiptPageSizeRule } from '@/lib/pos-receipt-paper'

export type ReceiptModalData = {
  orderNo: string
  items: { id: string; name: string; price: number; qty: number; note?: string }[]
  subtotal: number
  discountAmt: number
  deliveryFee?: number
  packagingFee?: number
  total: number
  storeCode: string
  orderType: string
  tableName?: string
  memo?: string
  discountReason?: string
  vatFeeAmt?: number
  vatFeeMode?: 'included' | 'separate'
  serviceFeeAmt?: number
  serviceFeeMode?: 'included' | 'separate'
  cardFeeAmt?: number
  cardFeeMode?: 'included' | 'separate'
  otherFeeAmt?: number
  otherFeeMode?: 'included' | 'separate'
  /** 모달 자동 영수증 인쇄 시 어떤 설정을 따를지 (주문/추가주문/결제) */
  receiptAutoPrintContext?: 'order' | 'add_order' | 'payment'
  /** 실시간/폴링 등에서 이미 자동 인쇄된 주문이면 모달 자동 인쇄 생략 */
  suppressReceiptModalAutoPrint?: boolean
}

const POS_PAPER_SIDE_PADDING_MM = 1
function getPosPaperBaseCss(fontFamily: string, fontSizePx: number) {
  return `
    ${posThermalReceiptPageSizeRule()}
    html, body { margin: 0; padding: 0; }
    html { height: auto; }
    body {
      width: ${POS_THERMAL_RECEIPT_WIDTH_MM}mm;
      min-height: auto;
      height: auto;
      box-sizing: border-box;
      font-family: ${fontFamily};
      font-size: ${fontSizePx}px;
      padding: ${POS_PAPER_SIDE_PADDING_MM}mm;
      -webkit-print-color-adjust: economy;
      print-color-adjust: economy;
    }
  `
}

function buildCode128BarcodeUrl(raw: string): string {
  const text = String(raw || '').trim()
  if (!text) return ''
  return `https://quickchart.io/barcode?type=code128&text=${encodeURIComponent(text)}&scale=2&height=38&includetext=true`
}

interface PosReceiptModalProps {
  onOpenChange: (open: boolean) => void
  receiptData: ReceiptModalData | null
  menus: PosMenu[]
  orderTypeLabels: Record<string, string>
  t: (k: string) => string
  autoPrintReceiptOnOrder?: boolean
  autoPrintReceiptOnAddOrder?: boolean
  autoPrintReceiptOnPayment?: boolean
  autoPrintKitchenSlipOnOrder?: boolean
  receiptBizName?: string
  receiptBizTaxId?: string
  receiptBizOwner?: string
  receiptBizAddress?: string
  receiptBizPhone?: string
  receiptDesignStyle?: 'badge' | 'simple'
  receiptLogoSize?: 'sm' | 'md' | 'lg'
  receiptShowTitle?: boolean
  receiptShowPaidStamp?: boolean
  receiptShowThankYou?: boolean
  receiptShowCustomerCopy?: boolean
  receiptFooterPrimaryText?: string
  receiptFooterSecondaryText?: string
  receiptLogoImageUrl?: string
  receiptStampImageUrl?: string
  receiptShowStamp?: boolean
  receiptStampOnlyTaxInvoice?: boolean
  receiptMembershipQrImageUrl?: string
  receiptMembershipQrLinkUrl?: string
  receiptMembershipQrText?: string
  receiptShowMembershipQr?: boolean
  signatureLine?: boolean
  receiptBarcode?: boolean
  itemBarcode?: boolean
}

export function PosReceiptModal({
  onOpenChange,
  receiptData,
  menus,
  orderTypeLabels,
  t,
  autoPrintReceiptOnOrder = false,
  autoPrintReceiptOnAddOrder = false,
  autoPrintReceiptOnPayment = false,
  autoPrintKitchenSlipOnOrder = false,
  receiptBizName = '',
  receiptBizTaxId = '',
  receiptBizOwner = '',
  receiptBizAddress = '',
  receiptBizPhone = '',
  receiptDesignStyle = 'badge',
  receiptLogoSize = 'md',
  receiptShowTitle = true,
  receiptShowPaidStamp = true,
  receiptShowThankYou = true,
  receiptShowCustomerCopy = true,
  receiptFooterPrimaryText = "",
  receiptFooterSecondaryText = "",
  receiptLogoImageUrl = "",
  receiptStampImageUrl = "",
  receiptShowStamp = true,
  receiptStampOnlyTaxInvoice = true,
  receiptMembershipQrImageUrl = "",
  receiptMembershipQrLinkUrl = "",
  receiptMembershipQrText = "",
  receiptShowMembershipQr = false,
  signatureLine = false,
  receiptBarcode = false,
  itemBarcode = false,
}: PosReceiptModalProps) {
  const { lang } = useLang()
  const autoPrintedKeyRef = useRef<string>('')
  const tr = (key: string, fallback: string) => {
    const value = t(key)
    return value && value !== key ? value : fallback
  }

  const printInIframe = (fullHtml: string, title: string) =>
    new Promise<void>((resolve, reject) => {
      printHtmlInHiddenIframe(fullHtml, {
        title,
        printDelayMs: 220,
        fallbackCleanupMs: 30_000,
        focusIframeBeforePrint: false,
        onPrintUnavailable: () => reject(new Error(t('posPrintBlocked') || '인쇄를 시작할 수 없습니다.')),
        onAfterCleanup: () => resolve(),
      })
    })

  const handlePrintReceipt = async () => {
    if (!receiptData) return
    const esc = (value: string) => escapeHtml(String(value || ''))
    const tableForPrint = receiptData.tableName
      ? translateReceiptTableDisplayName(receiptData.tableName, t)
      : ''
    const parsedMemo = parsePosOrderMemo(receiptData.memo)
    const taxInvoice = parsedMemo.taxInvoice
    const logoUrl = receiptLogoImageUrl || `${window.location.origin}/company-stamp.png`
    const isPaymentReceipt =
      !receiptData.receiptAutoPrintContext || receiptData.receiptAutoPrintContext === 'payment'
    const showLogo = isPaymentReceipt
    const footerPrimaryText =
      String(receiptFooterPrimaryText || '').trim() ||
      (receiptShowThankYou ? tr('posReceiptThankYou', '감사합니다') : '')
    const footerSecondaryText =
      String(receiptFooterSecondaryText || '').trim() ||
      (receiptShowCustomerCopy ? tr('posReceiptCustomerCopy', '고객용') : '')
    const showStamp = Boolean(receiptShowStamp && receiptStampImageUrl && (!receiptStampOnlyTaxInvoice || taxInvoice))
    const membershipQrSrc = String(receiptMembershipQrLinkUrl || '').trim()
      ? `https://quickchart.io/qr?text=${encodeURIComponent(String(receiptMembershipQrLinkUrl || '').trim())}&size=180&margin=1&format=png`
      : receiptMembershipQrImageUrl
    const showMembershipQr = Boolean(receiptShowMembershipQr && membershipQrSrc)
    const membershipQrText = String(receiptMembershipQrText || '').trim()
    const receiptOrderNoRaw = resolvePosReceiptOrderNoRaw({
