"use client"

import * as React from "react"
import { Tooltip, type TooltipProps } from "recharts"
import { cn } from "@/lib/utils"

export type ChartConfig = Record<
  string,
  {
    label?: string
    icon?: React.ComponentType<{ className?: string }>
    color?: string
    theme?: { light?: string; dark?: string }
  }
>

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)
  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }
  return context
}

const ChartContainer = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    config: ChartConfig
    children: React.ReactElement
  }
>(({ id, className, config, children, ...props }, ref) => {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-chart-container
        ref={ref}
        id={chartId}
        className={cn("w-full", className)}
        {...props}
      >
        {children}
      </div>
    </ChartContext.Provider>
  )
})
ChartContainer.displayName = "ChartContainer"

const ChartTooltip = Tooltip

type ChartTooltipContentProps = {
  active?: boolean
  payload?: Array<{ name: string; value: number; dataKey?: string; color?: string; payload?: Record<string, unknown> }>
  label?: string
  formatter?: (value: unknown, name: string, item: { payload?: Record<string, unknown> }) => React.ReactNode
  className?: string
}

function ChartTooltipContent({ active, payload, label, formatter, className }: ChartTooltipContentProps) {
  if (!active || !payload?.length) return null
  const content = formatter ? (
    payload.map((item, idx) => (
      <div key={idx} className="flex items-center justify-between gap-4">
        <span className="text-muted-foreground">{item.name}</span>
        {formatter(item.value, item.name, { payload: item.payload })}
      </div>
    ))
  ) : (
    payload.map((item, idx) => (
      <div key={idx}>{`${item.name}: ${item.value}`}</div>
    ))
  )
  return (
    <div
      className={cn(
        "overflow-hidden rounded-md border bg-popover px-3 py-1.5 text-sm shadow-md",
        className
      )}
    >
      {label && <p className="mb-1.5 font-medium">{label}</p>}
      <div className="flex flex-col gap-0.5">{content}</div>
    </div>
  )
}
ChartTooltipContent.displayName = "ChartTooltipContent"

export { ChartContainer, ChartTooltip, ChartTooltipContent }

"use client"

import * as React from "react"
import { RotateCcw, RotateCw, ZoomIn, ZoomOut } from "lucide-react"
import { Button } from "./button"

/** 확대축소 3단계: 1x, 2x, 3x */
const ZOOM_LEVELS = [1, 2, 3] as const

export interface ImageViewerWithRotateProps {
  src: string
  alt?: string
  className?: string
  imgClassName?: string
  onError?: () => void
  onLoad?: () => void
  referrerPolicy?: React.ImgHTMLAttributes<HTMLImageElement>["referrerPolicy"]
  rotateLeftLabel?: string
  rotateRightLabel?: string
  zoomInLabel?: string
  zoomOutLabel?: string
}

/** 이미지 + 회전·확대축소 버튼. 사진 보기 모달 내부에서 사용 */
export function ImageViewerWithRotate({
  src,
  alt = "",
  className = "",
  imgClassName = "max-w-full max-h-[70vh] rounded-lg object-contain",
  onError,
  onLoad,
  referrerPolicy,
  rotateLeftLabel = "반시계",
  rotateRightLabel = "시계",
  zoomInLabel = "확대",
  zoomOutLabel = "축소",
}: ImageViewerWithRotateProps) {
  const [rotateDeg, setRotateDeg] = React.useState(0)
  const [zoomIdx, setZoomIdx] = React.useState(0)
  const scale = ZOOM_LEVELS[zoomIdx]

  const handleRotateLeft = () => setRotateDeg((d) => (d - 90) % 360)
  const handleRotateRight = () => setRotateDeg((d) => (d + 90) % 360)
  const handleZoomIn = () => setZoomIdx((i) => Math.min(ZOOM_LEVELS.length - 1, i + 1))
  const handleZoomOut = () => setZoomIdx((i) => Math.max(0, i - 1))

  const isZoomed = scale > 1
  return (
    <div className={`flex flex-col ${className || "relative"}`}>
      {/* 확대 시 items-start로 상단부터 보이게 하여 위아래 스크롤 모두 가능. 1x일 때는 items-center로 중앙 배치 */}
      <div
        className={`flex min-h-[120px] max-h-[55vh] flex-1 justify-center overflow-auto overflow-x-auto ${isZoomed ? "items-start" : "items-center"}`}
      >
        <div style={{ zoom: scale }} className="inline-block shrink-0">
          <img
            src={src}
            alt={alt}
            className={imgClassName}
            style={{ transform: `rotate(${rotateDeg}deg)` }}
            onError={onError}
            onLoad={onLoad}
            referrerPolicy={referrerPolicy}
          />
        </div>
      </div>
      <div className="mt-2 flex shrink-0 flex-wrap items-center justify-center gap-1">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleZoomOut}
          disabled={zoomIdx <= 0}
          className="h-8 gap-1 px-2 text-xs"
        >
          <ZoomOut className="h-3.5 w-3.5" />
          {zoomOutLabel}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleZoomIn}
          disabled={zoomIdx >= ZOOM_LEVELS.length - 1}
          className="h-8 gap-1 px-2 text-xs"
        >
          <ZoomIn className="h-3.5 w-3.5" />
          {zoomInLabel}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleRotateLeft}
          className="h-8 gap-1 px-2 text-xs"
        >
          <RotateCcw className="h-3.5 w-3.5" />
          {rotateLeftLabel}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleRotateRight}
          className="h-8 gap-1 px-2 text-xs"
        >
          <RotateCw className="h-3.5 w-3.5" />
          {rotateRightLabel}
        </Button>
      </div>
    </div>
  )
}

