    "매장미팅": "visitPurposeMeeting", "매장 미팅": "visitPurposeMeeting",
    "물건배송": "visitPurposeDelivery", "물건 배송": "visitPurposeDelivery",
    "기타": "visitPurposeEtc",
  }
  return m[p] || ""
}

