export type SyncResult = { synced: number; failed: number }
export type SyncListener = (result: SyncResult) => void

const listeners = new Set<SyncListener>()
const MAX_RETRY_COUNT = 8
const RETRY_BASE_MS = 2_000
const RETRY_MAX_MS = 5 * 60_000

export function onSyncComplete(cb: SyncListener): () => void {
  listeners.add(cb)
  return () => listeners.delete(cb)
}

function notifySyncComplete(result: SyncResult) {
  listeners.forEach((cb) => cb(result))
}

function isNetworkError(e: unknown): boolean {
  if (e instanceof TypeError && e.message?.toLowerCase().includes('fetch')) return true
  if (e instanceof Error) {
    const msg = e.message?.toLowerCase() ?? ''
    if (msg.includes('network') || msg.includes('failed') || msg.includes('load')) return true
  }
  return false
}

/**
 * 동기화 순서: 신규 주문(0) → 본문 수정·기타(1, createdAt) → 주문 상태(2) → 결산(3)
 * updatePosOrder는 1번 티어에 두어 다른 요청과 시간순으로 섞이고, status는 항상 그 뒤.
 */
function syncOrder(item: { api: string; createdAt: number }): number {
  if (item.api === '/api/savePosOrder') return 0
  if (item.api === '/api/updatePosOrderStatus') return 2
  if (item.api === '/api/savePosSettlement') return 3
  return 1 // updatePosOrder 및 그 외
}

function nextRetryDelayMs(retryCount: number): number {
  if (retryCount <= 0) return 0
  return Math.min(RETRY_MAX_MS, RETRY_BASE_MS * 2 ** Math.max(0, retryCount - 1))
}

export async function syncPending(): Promise<SyncResult> {
  if (!isOnline()) return { synced: 0, failed: 0 }
  let pending = await getAllPending()
  if (pending.length === 0) return { synced: 0, failed: 0 }

  pending = [...pending].sort(
    (a, b) => syncOrder(a) - syncOrder(b) || a.createdAt - b.createdAt
  )

  let synced = 0
  let failed = 0

  for (const item of pending) {
    if (item.retryCount >= MAX_RETRY_COUNT) {
      continue
    }
    const now = Date.now()
    const retryDelay = nextRetryDelayMs(item.retryCount)
    const lastTriedAt = item.lastTriedAt ?? item.createdAt
    if (retryDelay > 0 && now - lastTriedAt < retryDelay) {
      continue
    }
    try {
      const idempotencyKey = item.metadata?.localOrderNo || item.id
      const init: RequestInit = {
        method: item.method,
        headers: {
          'Content-Type': 'application/json',
          'X-Idempotency-Key': idempotencyKey,
          ...item.headers,
        },
        body: item.body,
      }
      const res = await apiFetch(item.api, init)

      if (res.status === 401) {
        // 토큰 만료 - 재로그인 필요, 큐 유지
        await updateQueueItem(item.id, {
          lastError: '로그인이 필요합니다.',
          retryCount: item.retryCount + 1,
          lastTriedAt: now,
        })
        failed++
        continue
      }

      if (!res.ok) {
        const text = await res.text()
        await updateQueueItem(item.id, {
          lastError: text?.slice(0, 200) || `HTTP ${res.status}`,
          retryCount: item.retryCount + 1,
          lastTriedAt: now,
        })
        if (res.status >= 500) reportNetworkFailure()
        failed++
        continue
      }

      reportNetworkSuccess()
      if (item.api === '/api/savePosOrder') {
        try {
          const data = (await res.json()) as { orderId?: unknown }
          const oid = Number(data?.orderId)
          if (Number.isFinite(oid) && oid > 0) {
            registerQueuedSavePosOrderSyncedServerId(oid)
          }
        } catch {
          /* 본문 없음·JSON 아님 무시 */
        }
      } else {
        try {
          await res.text()
        } catch {
          /* ignore */
        }
      }
      await removeFromQueue(item.id)
      synced++
    } catch (e) {
      if (isNetworkError(e)) {
        // 네트워크 문제로 다시 실패 - 큐 유지
        await updateQueueItem(item.id, {
          lastError: String(e),
          retryCount: item.retryCount + 1,
          lastTriedAt: Date.now(),
        })
        reportNetworkFailure()
      }
      failed++
    }
  }

  if (synced > 0 || failed > 0) {
    notifySyncComplete({ synced, failed })
  }
  return { synced, failed }
}

/**
 * 비밀번호 해시/검증
 * bcrypt 해시 형식: $2a$10$... (60자) → 해시된 비밀번호로 인식
 */
import { hash, compare } from 'bcryptjs'

const SALT_ROUNDS = 10

const BCRYPT_PREFIX = '$2'

/** 평문 비밀번호인지 확인 (해시는 $2로 시작) */
export function isHashed(password: string): boolean {
  const s = String(password || '').trim()
  return s.length >= 50 && (s.startsWith('$2a$') || s.startsWith('$2b$'))
}

/** 비밀번호 해시 (저장 시 사용) */
export async function hashPassword(plain: string): Promise<string> {
  const s = String(plain || '').trim()
  if (!s) return ''
  return hash(s, SALT_ROUNDS)
}

/**
 * 비밀번호 검증
 * - 해시된 DB 값과 평문 입력 비교
 * - DB가 평문(레거시)인 경우 fallback 비교
 */
export async function verifyPassword(plainInput: string, storedValue: string): Promise<boolean> {
  const input = String(plainInput || '').trim()
  const stored = String(storedValue || '').trim()
  if (!input || !stored) return false

  if (isHashed(stored)) {
    return compare(input, stored)
  }
  return input === stored
}

/**
 * POS 메뉴 대분류·소분류 프리셋
 * 메뉴 관리, 원가 분석 드롭다운에 사용
 */

import {
  PROMOTION_DEFAULT_SUBCATEGORIES,
  PROMOTION_MAIN_CATEGORY,
  LEGACY_PROMOTION_MAIN_CATEGORY,
  normalizePromotionSubcategory,
  uniqueSubcategoriesForMainMenu,
} from '@/lib/pos-promo-constants'

export type PosMenuCategoriesConfigShape = {
  mainCategories: string[]
  categoriesByMain: Record<string, string[]>
}

/** API/DB 설정에 프로모션 대분류·기본 소분류가 없으면 병합 */
export function mergePromotionIntoCategoriesConfig(cfg: PosMenuCategoriesConfigShape): PosMenuCategoriesConfigShape {
  const main = PROMOTION_MAIN_CATEGORY

  const mains = [...new Set(cfg.mainCategories.map((m) => (m === LEGACY_PROMOTION_MAIN_CATEGORY ? main : m)))]

  let categoriesByMain = { ...cfg.categoriesByMain }
  const legacySubs = categoriesByMain[LEGACY_PROMOTION_MAIN_CATEGORY]
  if (legacySubs?.length) {
    const cur = categoriesByMain[main] || []
    categoriesByMain[main] = [...new Set([...cur, ...legacySubs])]
  }
  if (LEGACY_PROMOTION_MAIN_CATEGORY in categoriesByMain) {
    const { [LEGACY_PROMOTION_MAIN_CATEGORY]: _, ...rest } = categoriesByMain
    categoriesByMain = rest
  }

  if (!mains.includes(main)) mains.push(main)
  const existingSubs = [...(categoriesByMain[main] || [])]
  let nextSubs = [...existingSubs]
  for (const d of PROMOTION_DEFAULT_SUBCATEGORIES) {
    if (!nextSubs.some((s) => normalizePromotionSubcategory(s) === d)) {
      nextSubs.push(d)
    }
  }
  nextSubs = uniqueSubcategoriesForMainMenu(main, nextSubs)
  return {
    mainCategories: mains,
    categoriesByMain: {
      ...categoriesByMain,
      [main]: nextSubs.length > 0 ? nextSubs : [...PROMOTION_DEFAULT_SUBCATEGORIES],
    },
  }
}

export const POS_MAIN_CATEGORIES = ["Chicken", "Korean", "Side", "Drinks"] as const

export type PosMainCategory = (typeof POS_MAIN_CATEGORIES)[number]

/** 대분류별 소분류 목록 */
export const POS_CATEGORIES_BY_MAIN: Record<PosMainCategory, readonly string[]> = {
  Chicken: ["Triple Chicken", "SNOW", "ORIGINAL", "Dosirak", "Bar.B.Q", "Banban", "SPECIALTIES"],
  Korean: ["Tteokbokki", "KOREAN SOUP", "KOREAN FOOD"],
  Side: ["SIDE MENU", "SIDE DISH", "salad"],
  Drinks: ["DRINKS"],
} as const

/** 전체 소분류 (평탄화) */
export const POS_ALL_SUB_CATEGORIES = POS_MAIN_CATEGORIES.flatMap(
  (main) => POS_CATEGORIES_BY_MAIN[main]
)

/** 대분류 한·영 매칭 (DB에 "치킨" 저장 시 "Chicken" 선택과 호환) */
const MAIN_CATEGORY_ALIASES: Record<string, string[]> = {
  Chicken: ["치킨"],
  Korean: ["한국"],
  Side: ["사이드", "사이드메뉴"],
  Drinks: ["음료"],
  Promotion: [LEGACY_PROMOTION_MAIN_CATEGORY],
}

/** 치킨 대분류 선택 여부 */
export function isChickenMainSelected(selected: string): boolean {
  return selected === "Chicken" || selected === "치킨"
}

/** 선택한 대분류와 row가 일치하는지 (한·영 동치, 치킨은 코드 c 시작으로도 판별) */
export function mainCategoryMatches(
  selected: string,
  rowMain: string | undefined,
  menuCode?: string
): boolean {
  if (!selected || selected === "all") return true
  const row = String(rowMain ?? "").trim()
  if (selected === row) return true
  const aliases = MAIN_CATEGORY_ALIASES[selected]
  if (aliases?.includes(row)) return true
  const engForSelected = Object.entries(MAIN_CATEGORY_ALIASES).find(([, arr]) => arr.includes(selected))?.[0]
  if (engForSelected && engForSelected === row) return true
  if (isChickenMainSelected(selected) && isChickenMenu(menuCode)) return true
  return false
}

/** 치킨 메뉴 여부 (코드가 c로 시작) */
export function isChickenMenu(code: string | undefined): boolean {
  return String(code ?? "").trim().toLowerCase().startsWith("c")
}

/** 대분류로 preset 조회 (치킨↔Chicken 등 한영 매핑) */
export function getPresetCategoriesForMain(mainCat: string): readonly string[] | null {
  if (mainCat in POS_CATEGORIES_BY_MAIN) {
    return POS_CATEGORIES_BY_MAIN[mainCat as keyof typeof POS_CATEGORIES_BY_MAIN]
  }
  const entry = Object.entries(MAIN_CATEGORY_ALIASES).find(([, aliases]) => aliases.includes(mainCat))
  return entry ? POS_CATEGORIES_BY_MAIN[entry[0] as keyof typeof POS_CATEGORIES_BY_MAIN] : null
}

/**
 * POS 영수증/인쇄용: 테이블명 끝 `번` 제거·치킨 부위 옵션명 번역 등.
 */

/** 테이블명 끝 한글 접미사 `번` 제거 (1F-2번 → 1F-2). 언어와 무관하게 표시만 정리. */
export function translateReceiptTableDisplayName(tableName: string, _t?: (key: string) => string): string {
  const s = String(tableName || '').trim()
  if (!s) return s
  if (!/\s*번\s*$/u.test(s)) return s
  return s.replace(/\s*번\s*$/u, '').trimEnd()
}

/**
 * 배치 테이블명 `4` vs 주문 `table_name` `4번` 등 매칭용 (소문자·trim·끝 `번` 제거).
 */
export function normalizePosTableNameForMatch(raw: string | undefined | null): string {
  let s = String(raw ?? '').trim().toLowerCase()
  if (!s) return ''
  s = s.replace(/\s*번\s*$/u, '').trimEnd()
  return s
}

/** 품목 줄에 포함된 순살/윙/봉 한글을 번역 키로 치환 ("M - 순살" 등) */
export function translatePosMenuLineForReceipt(name: string, t: (key: string) => string): string {
  if (!name?.trim()) return name ?? ''
  let out = String(name)
  const boneless = t('posOptionPartBoneless')
  const wing = t('posOptionPartWing')
  const drum = t('posOptionPartDrumstick')
  if (boneless && boneless !== 'posOptionPartBoneless') out = out.replace(/순살/g, boneless)
  if (wing && wing !== 'posOptionPartWing') out = out.replace(/윙/g, wing)
  if (drum && drum !== 'posOptionPartDrumstick') out = out.replace(/봉/g, drum)
  return out
}

'use client'

import { useState, useCallback, useEffect, useMemo, useRef } from 'react'
import type { Store, Table, Order } from '@/lib/pos-types'
import { useStoreList } from '@/lib/use-store-list'
import { useAuth } from '@/lib/auth-context'
import { isOfficeRole } from '@/lib/permissions'
import { getPosTableLayout, type PosTableItem, type PosOrder } from '@/lib/api-client'
import { getPosOrdersWithCache } from '@/lib/offline/receipts-offline'
import { getPosBusinessDateStr } from '@/lib/pos-business-day'
import { normalizePosTableNameForMatch } from '@/lib/pos-print-translate'

/** 관리자 테이블 배치와 동일한 픽셀 그리드 (pos-table-layout-content 기준) */
const GRID_SIZE = 24
const FLOOR_W = 720
const FLOOR_H = 480
const DEFAULT_GRID_COLS = Math.round(FLOOR_W / GRID_SIZE)
const DEFAULT_GRID_ROWS = Math.round(FLOOR_H / GRID_SIZE)

function mapOrderType(orderType: string): Order['type'] {
  const v = String(orderType || '').toLowerCase()
  if (v === 'delivery') return 'delivery'
  if (v === 'takeout') return 'takeout'
  return 'dine-in'
}

function mapOrderStatus(status: string): Order['status'] {
  const v = String(status || '').toLowerCase()
  if (v === 'completed') return 'completed'
  if (v === 'paid') return 'paid'
  if (v === 'ready') return 'ready'
  if (v === 'pending') return 'pending'
  return 'preparing'
}

function posOrderToOrder(po: PosOrder & { orderNo?: string }): Order {
  return {
    id: String(po.id),
    tableId: undefined,
    type: mapOrderType(po.orderType),
    items: (po.items || []).map((it) => ({
      id: String(it.id ?? ''),
      name: String(it.name ?? ''),
      quantity: Number(it.qty ?? 0) || 0,
      price: Number(it.price ?? 0) || 0,
      ...(typeof it.note === 'string' && String(it.note).trim()
        ? { note: String(it.note).trim() }
        : {}),
      servedAt: typeof it.servedAt === 'string' ? it.servedAt : null,
      servedBy: typeof it.servedBy === 'string' ? it.servedBy : null,
    })),
    total: Number(po.total ?? 0) || 0,
    status: mapOrderStatus(po.status),
    createdAt: new Date(po.createdAt || Date.now()),
    customerName: String(po.tableName || '').trim() || undefined,
    memo: String(po.memo || '').trim() || undefined,
    orderNo: String(po.orderNo ?? '').trim() || undefined,
    guestCount:
      mapOrderType(po.orderType) === 'dine-in'
        ? Math.max(0, Math.min(99, Math.trunc(Number(po.guestCount ?? 0) || 0)))
        : undefined,
  }
}

function layoutToTables(
  layout: PosTableItem[],
  dineInOrders: PosOrder[]
): Table[] {
  const orderByTable = new Map<string, PosOrder>()
  for (const o of dineInOrders) {
    const raw = String(o.tableName ?? '').trim()
    if (!raw) continue
    const keys = new Set<string>()
    keys.add(raw)
    const norm = normalizePosTableNameForMatch(raw)
    if (norm) keys.add(norm)
    for (const key of keys) {
      const existing = orderByTable.get(key)
      if (!existing || new Date(o.createdAt || 0) > new Date(existing.createdAt || 0)) {
        orderByTable.set(key, o)
      }
    }
  }
  return (layout || []).map((t) => {
    const gridX = Math.round((t.x ?? 0) / GRID_SIZE)
    const gridY = Math.round((t.y ?? 0) / GRID_SIZE)
    const gridW = Math.max(1, Math.round((t.w ?? 80) / GRID_SIZE))
    const gridH = Math.max(1, Math.round((t.h ?? 60) / GRID_SIZE))
    const shape = String(t.shape ?? 'rect')
    const shapeMap =
      shape === 'square'
        ? 'square'
        : shape === 'round'
          ? 'round'
          : 'rectangle'
    const name = String(t.name ?? '').trim() || String(t.id ?? '')
    const idStr = String(t.id ?? '')
    const nameNorm = normalizePosTableNameForMatch(name)
    const idNorm = normalizePosTableNameForMatch(idStr)
    const posOrder =
      orderByTable.get(name) ??
      orderByTable.get(idStr) ??
      (nameNorm ? orderByTable.get(nameNorm) : undefined) ??
      (idNorm ? orderByTable.get(idNorm) : undefined)
    const order = posOrder ? posOrderToOrder(posOrder) : undefined
    return {
      id: String(t.id ?? ''),
      name,
      seats: Number(t.seats ?? 0) || 0,
      x: Math.max(0, gridX),
      y: Math.max(0, gridY),
      width: gridW,
      height: gridH,
      shape: shapeMap as Table['shape'],
      rotation: Number(t.rotation ?? 0) || 0,
      isOccupied: !!order,
      order,
    }
  })
}

export function usePosStore() {
  const { stores: storeCodes } = useStoreList()
  const { auth } = useAuth()
  const canSearchAll = isOfficeRole(auth?.role || '')
  const effectiveStoreCodes = useMemo(() => {
    if (canSearchAll) {
      if (storeCodes.length > 0) return storeCodes
      if (auth?.store) return [auth.store]
      return storeCodes
    }
    return auth?.store ? [auth.store] : storeCodes
  }, [canSearchAll, auth?.store, storeCodes])

  const [stores, setStores] = useState<Store[]>([])
  const [layoutByStoreId, setLayoutByStoreId] = useState<Record<string, PosTableItem[]>>({})
  const layoutByStoreIdRef = useRef<Record<string, PosTableItem[]>>({})
  const [currentStoreId, setCurrentStoreId] = useState<string>('')
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    layoutByStoreIdRef.current = layoutByStoreId
  }, [layoutByStoreId])

  // API에서 테이블 배치 + 당일 매장 주문으로 사용 중 테이블 반영
  useEffect(() => {
    if (!effectiveStoreCodes?.length) {
      setStores([])
      setLoading(false)
      return
    }
    setLoading(true)
    const businessDate = getPosBusinessDateStr()
    Promise.all(
      effectiveStoreCodes.map(async (storeCode) => {
        const [layoutRes, ordersRes] = await Promise.all([
          getPosTableLayout({ storeCode }).catch(() => ({ layout: [], storeCode })),
          getPosOrdersWithCache({
            storeCode,
            startStr: businessDate,
            endStr: businessDate,
          }).catch(() => []),
        ])
        const fetchedLayout = layoutRes.layout || []
        const cachedLayout = layoutByStoreIdRef.current[storeCode] || []
        const layout = fetchedLayout.length > 0 ? fetchedLayout : cachedLayout
        const activeOrders = (ordersRes || []).filter(
          (o) => !['cancelled', 'refunded'].includes((o.status ?? '').toLowerCase())
        )
        const dineInOrders = activeOrders.filter(
          (o) =>
            o.orderType === 'dine_in' &&
            (o.tableName ?? '').trim() !== '' &&
            !['cancelled', 'refunded', 'completed'].includes((o.status ?? '').toLowerCase())
        )
        const tables = layoutToTables(layout, dineInOrders)
        return { storeCode, store: { id: storeCode, name: storeCode, gridCols: DEFAULT_GRID_COLS, gridRows: DEFAULT_GRID_ROWS, tables }, layout, activeOrders }
      })
    )
      .then((results) => {
        const storeList = results.map((r) => r.store)
        const layouts: Record<string, PosTableItem[]> = {}
        results.forEach((r) => { layouts[r.storeCode] = r.layout })
        setStores(storeList)
        setLayoutByStoreId(layouts)
        const mergedOrders = results
          .flatMap((r) => r.activeOrders || [])
          .map(posOrderToOrder)
        setOrders(mergedOrders)
        setCurrentStoreId((prev) => {
          const next = auth?.store && effectiveStoreCodes.includes(auth.store) ? auth.store : effectiveStoreCodes[0]
          return storeList.some((s) => s.id === prev) ? prev : next ?? effectiveStoreCodes[0] ?? ''
        })
      })
      .catch(() => setStores([]))
      .finally(() => setLoading(false))
  }, [effectiveStoreCodes.join(','), auth?.store])

  // effectiveStoreCodes 변경 시 currentStoreId가 목록에 없으면 첫 매장으로
  useEffect(() => {
    if (!effectiveStoreCodes.length || !currentStoreId) return
    if (effectiveStoreCodes.includes(currentStoreId)) return
    setCurrentStoreId(auth?.store && effectiveStoreCodes.includes(auth.store) ? auth.store : effectiveStoreCodes[0])
  }, [effectiveStoreCodes, currentStoreId, auth?.store])

  const currentStore = stores.find((s) => s.id === currentStoreId) || stores[0]

  const setCurrentStoreIdAndPersist = useCallback((id: string) => {
    setCurrentStoreId(id)
  }, [])

  const updateStore = useCallback((storeId: string, updates: Partial<Store>) => {
    setStores((prev) =>
      prev.map((store) => (store.id === storeId ? { ...store, ...updates } : store))
    )
  }, [])

  const updateTable = useCallback((storeId: string, tableId: string, updates: Partial<Table>) => {
    setStores((prev) =>
      prev.map((store) =>
        store.id === storeId
          ? {
              ...store,
              tables: store.tables.map((table) =>
                table.id === tableId ? { ...table, ...updates } : table
              ),
            }
          : store
      )
    )
  }, [])

  const addTable = useCallback((storeId: string, table: Table) => {
    setStores((prev) =>
      prev.map((store) =>
        store.id === storeId ? { ...store, tables: [...store.tables, table] } : store
      )
    )
  }, [])

  const removeTable = useCallback((storeId: string, tableId: string) => {
    setStores((prev) =>
      prev.map((store) =>
        store.id === storeId
          ? { ...store, tables: store.tables.filter((t) => t.id !== tableId) }
          : store
      )
    )
  }, [])

  const clearTables = useCallback((storeId: string) => {
    setStores((prev) =>
      prev.map((store) => (store.id === storeId ? { ...store, tables: [] } : store))
    )
  }, [])

  /** 결제 완료 시 테이블 주문 즉시 제거 (낙관적 업데이트) */
  const clearTableOrder = useCallback((storeId: string, tableName: string) => {
    const name = String(tableName ?? '').trim()
    if (!name) return
    const nameNorm = normalizePosTableNameForMatch(name)
    setStores((prev) =>
      prev.map((store) =>
        store.id === storeId
          ? {
              ...store,
              tables: store.tables.map((t) => {
                const tn = String(t.name ?? '').trim()
                const tid = String(t.id ?? '').trim()
                const match =
                  tn === name ||
                  tid === name ||
                  (nameNorm &&
                    (normalizePosTableNameForMatch(tn) === nameNorm ||
                      normalizePosTableNameForMatch(tid) === nameNorm))
                return match ? { ...t, order: undefined, isOccupied: false } : t
              }),
            }
          : store
      )
    )
  }, [])

  const refetchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const refetchStoresImmediate = useCallback(() => {
    if (!effectiveStoreCodes?.length) return Promise.resolve()
    setLoading(true)
    const businessDate = getPosBusinessDateStr()
    return Promise.all(
      effectiveStoreCodes.map(async (storeCode) => {
        const [layoutRes, ordersRes] = await Promise.all([
          getPosTableLayout({ storeCode }).catch(() => ({ layout: [], storeCode })),
          getPosOrdersWithCache({
            storeCode,
            startStr: businessDate,
            endStr: businessDate,
          }).catch(() => []),
        ])
        const fetchedLayout = layoutRes.layout || []
        const cachedLayout = layoutByStoreIdRef.current[storeCode] || []
        const layout = fetchedLayout.length > 0 ? fetchedLayout : cachedLayout
        const activeOrders = (ordersRes || []).filter(
          (o) => !['cancelled', 'refunded'].includes((o.status ?? '').toLowerCase())
        )
        const dineInOrders = activeOrders.filter(
          (o) =>
            o.orderType === 'dine_in' &&
            (o.tableName ?? '').trim() !== '' &&
            !['cancelled', 'refunded', 'completed'].includes((o.status ?? '').toLowerCase())
        )
        const tables = layoutToTables(layout, dineInOrders)
        return { storeCode, store: { id: storeCode, name: storeCode, gridCols: DEFAULT_GRID_COLS, gridRows: DEFAULT_GRID_ROWS, tables }, layout, activeOrders }
      })
    )
      .then((results) => {
        const storeList = results.map((r) => r.store)
        const layouts: Record<string, PosTableItem[]> = {}
        results.forEach((r) => { layouts[r.storeCode] = r.layout })
        setStores(storeList)
        setLayoutByStoreId(layouts)
        const mergedOrders = results
          .flatMap((r) => r.activeOrders || [])
          .map(posOrderToOrder)
        setOrders(mergedOrders)
      })
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [effectiveStoreCodes.join(',')])

  /** refetchStores 디바운스 (600ms) - 연속 호출 시 API 부하 감소 */
  const refetchStores = useCallback(() => {
    if (refetchTimeoutRef.current) clearTimeout(refetchTimeoutRef.current)
    refetchTimeoutRef.current = setTimeout(() => {
      refetchTimeoutRef.current = null
      refetchStoresImmediate()
    }, 600)
  }, [refetchStoresImmediate])

  const deliveryOrders = orders.filter((o) => o.type === 'delivery' && o.status !== 'ready' && o.status !== 'completed')
  const packagedDeliveryOrders = orders.filter((o) => o.type === 'delivery' && o.status === 'ready')
  const completedDeliveryOrders = orders.filter((o) => o.type === 'delivery' && o.status === 'completed')
  const takeoutOrders = orders.filter((o) => o.type === 'takeout' && o.status !== 'ready' && o.status !== 'completed')
  const packagedTakeoutOrders = orders.filter((o) => o.type === 'takeout' && o.status === 'ready')
  const completedTakeoutOrders = orders.filter((o) => o.type === 'takeout' && o.status === 'completed')

  const updateOrderStatus = useCallback((orderId: string, status: Order['status']) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status } : order))
    )
  }, [])

  const currentLayout = (currentStoreId && layoutByStoreId[currentStoreId]) || []

  return {
    stores,
    currentStore,
    currentStoreId,
    currentLayout,
    setCurrentStoreId: setCurrentStoreIdAndPersist,
    updateStore,
    updateTable,
    addTable,
    removeTable,
    clearTables,
    clearTableOrder,
    orders,
    deliveryOrders,
    packagedDeliveryOrders,
    completedDeliveryOrders,
    takeoutOrders,
    packagedTakeoutOrders,
    completedTakeoutOrders,
    updateOrderStatus,
    loadingTables: loading,
    refetchStores,
  }
}

/**
 * Supabase REST - 서버 전용 (Next.js API routes)
 *
 * SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY(권장) 또는 SUPABASE_ANON_KEY 환경 변수 필요.
 * service_role은 RLS를 우회하여 안전한 서버 전용 접근. anon은 RLS 적용됨.
 * API 라우트(app/api/*) 내부에서만 import. 클라이언트 번들에 포함되지 않도록.
 *
 * UND_ERR_HEADERS_TIMEOUT 방지: Node.js fetch(undici) 대신 https 모듈 사용.
 * 일시적 장애 대응: 5xx/429/네트워크 오류 시 최대 2회 재시도 (exponential backoff).
 */

import https from 'node:https'

const SUPABASE_RETRY_MAX = 3
const SUPABASE_RETRY_BASE_MS = 800

/** 디버그용 — 매 Supabase 요청마다 디스크 쓰기하면 로컬·다건 조회 시 병목·타임아웃 유발 */
const _log = (_msg: string, _data?: Record<string, unknown>) => {}

function httpsRequest(
  urlStr: string,
  options: { method?: string; headers?: Record<string, string>; body?: string | Buffer }
): Promise<{ status: number; headers: Record<string, string>; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr)
    // #region agent log
    _log('httpsRequest start', { hostname: url.hostname, path: url.pathname.slice(0, 80), hypothesisId: 'H2' })
    // #endregion
    const req = https.request(
      {
        hostname: url.hostname,
        port: 443,
        path: url.pathname + url.search,
        method: options.method || 'GET',
        headers: options.headers,
        timeout: 15_000,
      },
      (res) => {
        const chunks: Buffer[] = []
        res.on('data', (ch) => chunks.push(ch))
        res.on('end', () => {
          // #region agent log
          _log('httpsRequest success', { status: res.statusCode, hypothesisId: 'H2' })
          // #endregion
          const headers: Record<string, string> = {}
          Object.entries(res.headers).forEach(([k, v]) => {
            headers[k.toLowerCase()] = Array.isArray(v) ? v.join(', ') : String(v ?? '')
          })
          resolve({
            status: res.statusCode || 0,
            headers,
            body: Buffer.concat(chunks).toString('utf8'),
          })
        })
      }
    )
    req.on('error', (e) => {
      // #region agent log
      _log('httpsRequest error', { message: String(e), code: (e as NodeJS.ErrnoException).code, hypothesisId: 'H2' })
      // #endregion
      reject(e)
    })
    req.on('timeout', () => {
      // #region agent log
      _log('httpsRequest timeout', { hypothesisId: 'H2' })
      // #endregion
      req.destroy()
      reject(new Error('Supabase request timeout'))
    })
    if (options.body) req.write(options.body)
    req.end()
  })
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

/** 5xx, 429, 네트워크 오류 시 재시도 대상 */
function isRetriable(status: number | null, err: unknown): boolean {
  if (status != null) return status >= 500 || status === 429
  const msg = err instanceof Error ? err.message : String(err)
  return /timeout|ECONNRESET|ETIMEDOUT|ENOTFOUND|network|failed/i.test(msg)
}

export async function supabaseFetch(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  const urlStr =
    typeof input === 'string'
      ? input
      : input instanceof Request
        ? input.url
        : input.toString()
  const reqInit = input instanceof Request ? input : init
  const method = (reqInit?.method as string) || 'GET'
  const headers: Record<string, string> = {}
  const headersSource = input instanceof Request ? input.headers : reqInit?.headers
  if (headersSource) {
    const h = headersSource as Headers
    if (h.forEach) {
      h.forEach((v, k) => { headers[k] = v })
    } else if (typeof h === 'object') {
      Object.entries(h as unknown as Record<string, string>).forEach(([k, v]) => { headers[k] = String(v) })
    }
  }
  const bodyRaw = input instanceof Request ? input.body : reqInit?.body
  let body: string | Buffer | undefined
  if (bodyRaw) {
    if (typeof bodyRaw === 'string') body = bodyRaw
    else if (bodyRaw instanceof ArrayBuffer || ArrayBuffer.isView(bodyRaw))
      body = Buffer.from(bodyRaw as ArrayBuffer)
    else if (typeof (bodyRaw as Blob).arrayBuffer === 'function')
      body = Buffer.from(await (bodyRaw as Blob).arrayBuffer())
    else body = Buffer.from(bodyRaw as unknown as ArrayBuffer)
  }

  let lastStatus: number | null = null
  let lastErr: unknown = null
  let resHeaders: Record<string, string> = {}
  let resBody = ''

  for (let attempt = 1; attempt <= SUPABASE_RETRY_MAX; attempt++) {
    try {
      const res = await httpsRequest(urlStr, { method, headers, body })
      lastStatus = res.status
      resHeaders = res.headers
      resBody = res.body
      if (!isRetriable(res.status, null)) {
        const resHeadersObj = new Headers()
        Object.entries(resHeaders).forEach(([k, v]) => resHeadersObj.set(k, v))
        const nullBodyStatuses = [101, 204, 205, 304]
        const bodyForResponse = nullBodyStatuses.includes(res.status) ? null : resBody
        return new Response(bodyForResponse, { status: res.status, headers: resHeadersObj })
      }
      lastErr = new Error(`Supabase ${res.status}`)
    } catch (e) {
      lastErr = e
      lastStatus = null
    }
    if (attempt < SUPABASE_RETRY_MAX) {
      const delay = SUPABASE_RETRY_BASE_MS * Math.pow(2, attempt - 1)
      await sleep(delay)
    }
  }

  if (lastStatus != null) {
    const resHeadersObj = new Headers()
    Object.entries(resHeaders).forEach(([k, v]) => resHeadersObj.set(k, v))
    return new Response(lastStatus >= 500 ? resBody : null, { status: lastStatus, headers: resHeadersObj })
  }
  throw lastErr
}

let warnedMissingServiceRole = false

function getConfig() {
  const url = (process.env.SUPABASE_URL || '').trim()
  const serviceKey = (process.env.SUPABASE_SERVICE_ROLE_KEY || '').trim()
  const anonKey = (process.env.SUPABASE_ANON_KEY || '').trim()
  const key = serviceKey || anonKey
  if (!url || !key) {
    throw new Error(
      'SUPABASE_URL 및 SUPABASE_SERVICE_ROLE_KEY(권장) 또는 SUPABASE_ANON_KEY가 필요합니다. ' +
        '보안을 위해 service_role 키 사용을 권장합니다.'
    )
  }
  if (!serviceKey && anonKey && !warnedMissingServiceRole) {
    warnedMissingServiceRole = true
    console.warn(
      '[supabase-server] SUPABASE_SERVICE_ROLE_KEY가 없어 anon 키로 PostgREST를 호출합니다. ' +
        'RLS가 켜진 테이블(sauces, sauce_ingredients 등)은 0건·거부로 보일 수 있습니다. 서버(Vercel)에 service_role 키를 설정하세요.'
    )
  }
  const base = url.replace(/\/$/, '').replace(/^http:\/\//, 'https://')
  return { url: base, key }
}

/**
 * PostgREST 한 요청당 가져올 행 상한(기본값). Supabase Dashboard → Settings → API 의 max rows 와 맞추거나 env로 상향.
 * 예: SUPABASE_SELECT_PAGE_SIZE_MAX=20000
 */
export function supabaseSelectPageCap(): number {
  const raw = Number(process.env.SUPABASE_SELECT_PAGE_SIZE_MAX || '10000')
  if (!Number.isFinite(raw) || raw < 1) return 10000
  return Math.min(Math.floor(raw), 500_000)
}

/** 전 페이지 조회 루프 상한 (한 테이블당 최대 페이지 수) */
export const SUPABASE_SELECT_ALL_PAGES_MAX_PAGES = 5000
/** supabaseSelectAllPages 기본 maxRows (옵션 미지정 시) */
export const SUPABASE_SELECT_ALL_PAGES_DEFAULT_MAX_ROWS = 1_000_000
export const SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_PAGES = 5000
export const SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_ROWS_CEILING = 5_000_000
export const SUPABASE_SELECT_FILTER_ALL_PAGES_MIN_STRIDE = 500

/** 관리자 설정 화면용 — Vercel에 적용된 조회 상한(비밀값 없음) */
export function getSupabaseDataLimitDiagnostics() {
  const rawEnv = (process.env.SUPABASE_SELECT_PAGE_SIZE_MAX || '').trim()
  return {
    selectPageCap: supabaseSelectPageCap(),
    envSupabaseSelectPageSizeMax: rawEnv || null,
    selectAllPagesMaxPages: SUPABASE_SELECT_ALL_PAGES_MAX_PAGES,
    selectAllPagesDefaultMaxRows: SUPABASE_SELECT_ALL_PAGES_DEFAULT_MAX_ROWS,
    selectFilterAllPagesMaxPages: SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_PAGES,
    selectFilterAllPagesMaxRowsCeiling: SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_ROWS_CEILING,
    selectFilterAllPagesMinStride: SUPABASE_SELECT_FILTER_ALL_PAGES_MIN_STRIDE,
    fetchedAt: new Date().toISOString(),
  }
}

export async function supabaseSelect(
  table: string,
  options: { order?: string; limit?: number; offset?: number; select?: string } = {}
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}`
  const query = [options.select ? `select=${encodeURIComponent(options.select)}` : 'select=*']
  if (options.order) query.push(`order=${encodeURIComponent(options.order)}`)
  const cap = supabaseSelectPageCap()
  const limit =
    options.limit != null ? Math.max(1, Math.min(Number(options.limit), cap)) : cap
  const offset = options.offset != null ? Math.max(0, Number(options.offset)) : 0
  query.push(`limit=${limit}`)
  if (offset > 0) query.push(`offset=${offset}`)
  const rangeStart = offset
  const rangeEnd = offset + limit - 1
  const res = await supabaseFetch(pathStr + '?' + query.join('&'), {
    method: 'GET',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Accept: 'application/json',
      Range: `${rangeStart}-${Math.max(rangeStart, rangeEnd)}`,
    },
  })
  if (!res.ok) throw new Error('Supabase select failed: ' + (await res.text()))
  return res.json()
}

/**
 * PostgREST 단일 limit을 넘는 테이블 전체 로드 (offset 페이지 반복).
 * 원가 분석 등 메뉴·재료·품목 전량이 필요할 때 사용.
 */
export async function supabaseSelectAllPages(
  table: string,
  options: { order: string; select: string; pageSize?: number; maxRows?: number }
): Promise<unknown[]> {
  const cap = supabaseSelectPageCap()
  const pageSize = Math.max(1, Math.min(options.pageSize ?? cap, cap))
  const maxRows = options.maxRows ?? SUPABASE_SELECT_ALL_PAGES_DEFAULT_MAX_ROWS
  const out: unknown[] = []
  let offset = 0
  /** PostgREST/프록시가 limit=10000 요청에도 예: 1000행만 줄 수 있음. rows.length < pageSize 로 끊으면 나머지 페이지를 영원히 안 읽음 → 원가 분석 등에서 최신 BOM 누락 */
  let guard = 0
  const maxPages = SUPABASE_SELECT_ALL_PAGES_MAX_PAGES
  while (out.length < maxRows && guard++ < maxPages) {
    const batch = await supabaseSelect(table, {
      order: options.order,
      limit: pageSize,
      offset,
      select: options.select,
    })
    const rows = Array.isArray(batch) ? batch : []
    if (rows.length === 0) break
    out.push(...rows)
    if (out.length >= maxRows) break
    offset += rows.length
  }
  return out
}

export async function supabaseInsert(table: string, row: Record<string, unknown>) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}`
  const res = await supabaseFetch(pathStr, {
    method: 'POST',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
    },
    body: JSON.stringify(row),
  })
  if (!res.ok) throw new Error('Supabase insert failed: ' + (await res.text()))
  const text = await res.text()
  return text ? (JSON.parse(text) as unknown) : []
}

/**
 * PostgREST upsert — on_conflict 열이 이미 있으면 본문 필드로 병합(갱신).
 * pos_printer_settings(store_code PK) 저장 등 INSERT/UPDATE 분기 실패를 막기 위해 사용.
 */
export async function supabaseUpsertMerge(
  table: string,
  onConflictColumn: string,
  row: Record<string, unknown>
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?on_conflict=${encodeURIComponent(onConflictColumn)}`
  const res = await supabaseFetch(pathStr, {
    method: 'POST',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
      Prefer: 'resolution=merge-duplicates',
    },
    body: JSON.stringify(row),
  })
  if (!res.ok) throw new Error('Supabase upsert failed: ' + (await res.text()))
}

export async function supabaseUpdate(
  table: string,
  id: string | number,
  patch: Record<string, unknown>
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?id=eq.${encodeURIComponent(String(id))}`
  const res = await supabaseFetch(pathStr, {
    method: 'PATCH',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(patch),
  })
  if (!res.ok) throw new Error('Supabase update failed: ' + (await res.text()))
  return true
}
export async function supabaseSelectFilter(
  table: string,
  filter: string,
  options: { order?: string; limit?: number; select?: string } = {}
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}`
  const query = [options.select ? `select=${encodeURIComponent(options.select)}` : 'select=*', filter]
  if (options.order) query.push(`order=${encodeURIComponent(options.order)}`)
  const cap = supabaseSelectPageCap()
  const limit =
    options.limit != null ? Math.max(1, Math.min(Number(options.limit), cap)) : cap
  query.push(`limit=${limit}`)
  const rangeEnd = limit - 1
  const res = await supabaseFetch(pathStr + '?' + query.join('&'), {
    method: 'GET',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Accept: 'application/json',
      Range: `0-${Math.max(0, rangeEnd)}`,
    },
  })
  if (!res.ok) throw new Error('Supabase select failed: ' + (await res.text()))
  return res.json()
}

/**
 * PostgREST Range 헤더로 구간 조회 (URL의 limit와 중복 쓰지 않음)
 */
export async function supabaseSelectFilterRange(
  table: string,
  filter: string,
  options: { order?: string; select?: string; rangeStart: number; rangeEnd: number }
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}`
  const query = [options.select ? `select=${encodeURIComponent(options.select)}` : 'select=*', filter]
  if (options.order) query.push(`order=${encodeURIComponent(options.order)}`)
  const rs = Math.max(0, Math.floor(options.rangeStart))
  const re = Math.max(rs, Math.floor(options.rangeEnd))
  const res = await supabaseFetch(pathStr + '?' + query.join('&'), {
    method: 'GET',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Accept: 'application/json',
      Range: `${rs}-${re}`,
    },
  })
  if (!res.ok) throw new Error('Supabase select failed: ' + (await res.text()))
  return res.json()
}

/**
 * 필터에 맞는 행을 Range 페이지로 반복 조회해 전부 수집 (상한 도달·빈 페이지에서 중단)
 * schedules 등 행 수가 계속 늘어나도 한 번의 고정 limit에 잘리지 않게 할 때 사용
 */
export async function supabaseSelectFilterAllPages(
  table: string,
  filter: string,
  options: { order?: string; select?: string; pageSize?: number; maxRows?: number } = {}
): Promise<unknown[]> {
  const cap = supabaseSelectPageCap()
  const pageSize = Math.max(
    SUPABASE_SELECT_FILTER_ALL_PAGES_MIN_STRIDE,
    Math.min(Number(options.pageSize) || Math.min(8000, cap), cap)
  )
  const maxRows = Math.min(
    Math.max(pageSize, Number(options.maxRows) || 2_000_000),
    SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_ROWS_CEILING
  )
  const all: unknown[] = []
  let start = 0
  let guard = 0
  const maxPages = SUPABASE_SELECT_FILTER_ALL_PAGES_MAX_PAGES
  while (all.length < maxRows && guard++ < maxPages) {
    const end = start + pageSize - 1
    const batch = (await supabaseSelectFilterRange(table, filter, {
      order: options.order,
      select: options.select,
      rangeStart: start,
      rangeEnd: end,
    })) as unknown[]
    if (!Array.isArray(batch) || batch.length === 0) break
    all.push(...batch)
    if (all.length >= maxRows) break
    start += batch.length
  }
  return all
}

export async function supabaseUpdateByFilter(
  table: string,
  filter: string,
  patch: Record<string, unknown>
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?${filter}`
  const res = await supabaseFetch(pathStr, {
    method: 'PATCH',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(patch),
  })
  if (!res.ok) throw new Error('Supabase update by filter failed: ' + (await res.text()))
  return true
}

export async function supabaseDeleteByFilter(
  table: string,
  filter: string
) {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?${filter}`
  const res = await supabaseFetch(pathStr, {
    method: 'DELETE',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
    },
  })
  if (!res.ok) throw new Error('Supabase delete failed: ' + (await res.text()))
  return true
}

/**
 * count만 필요할 때 사용. PostgREST Prefer: count=exact + Range: 0-0 으로
 * 실제 row는 거의 가져오지 않고 Content-Range 헤더에서 total count 반환.
 * egress 최소화용.
 */
export async function supabaseCountFilter(table: string, filter: string): Promise<number> {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?select=id&${filter}`
  const res = await supabaseFetch(pathStr, {
    method: 'GET',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Prefer: 'count=exact',
      Range: '0-0',
    },
  })
  if (!res.ok) throw new Error('Supabase count failed: ' + (await res.text()))
  const range = res.headers.get('Content-Range')
  if (range) {
    const match = range.match(/\/(\d+)$/)
    if (match) return parseInt(match[1], 10)
  }
  return 0
}

/** 테이블 전체 행 수 (필터 없음). RLS/권한에 따라 관리 API에서만 사용 권장. */
export async function supabaseCountTable(table: string): Promise<number> {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/${encodeURIComponent(table)}?select=id`
  const res = await supabaseFetch(pathStr, {
    method: 'GET',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Prefer: 'count=exact',
      Range: '0-0',
    },
  })
  if (!res.ok) throw new Error('Supabase count failed: ' + (await res.text()))
  const range = res.headers.get('Content-Range')
  if (range) {
    const match = range.match(/\/(\d+)$/)
    if (match) return parseInt(match[1], 10)
  }
  return 0
}

/** RPC 호출. params는 함수 인자 (예: { p_location_patterns: ['a','b'], p_as_of_date: null }) */
export async function supabaseRpc<T = unknown>(
  fnName: string,
  params: Record<string, unknown>
): Promise<T> {
  const { url, key } = getConfig()
  const pathStr = `${url}/rest/v1/rpc/${encodeURIComponent(fnName)}`
  const res = await supabaseFetch(pathStr, {
    method: 'POST',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
    },
    body: JSON.stringify(params),
  })
  if (!res.ok) throw new Error('Supabase RPC failed: ' + (await res.text()))
  const text = await res.text()
  return (text ? JSON.parse(text) : []) as T
}

